window.__D("text/zohar-hebrew-translation/c027",{"p":[[9522012111,"<p>עֵד שֶׁהָיוּ הוֹלְכִים, יָשְׁבוּ בְשָׂדֶה אַחַת וְהִתְפַּלְלוּ. יָרַד עָנָן אֶחָד שֶׁל אֵשׁ וְהִקִּיף אוֹתָם. אָמַר רַבִּי שִׁמְעוֹן, הֲרֵינִי רוֹאֶה שֶׁרְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כָּאן. נֵשֵׁב. יָשְׁבוּ וְהָיוּ אוֹמְרִים דִּבְרֵי תוֹרָה. פָּתַח וְאָמַר, (משלי כה) מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק. הֲרֵי הִסְתַּכַּלְתִּי בְּדִבְרֵי שְׁלֹמֹה הַמֶּלֶךְ, וְאֶת כֻּלָּם אָמַר בְּחָכְמָה.</p>\n<p>בֹּא רְאֵה, שְׁלֹשָׁה סִפְרֵי חָכְמָה הוֹצִיא שְׁלֹמֹה לָעוֹלָם, וְכֻלָּם בְּחָכְמָה עֶלְיוֹנָה. שִׁיר הַשִּׁירִים - חָכְמָה, קֹהֶלֶת - תְּבוּנָה, וּמִשְׁלֵי - דַּעַת. כְּנֶגֶד שְׁלֹשֶׁת אֵלֶּה עָשָׂה שְׁלֹשָׁה סְפָרִים. שִׁיר הַשִּׁירִים כְּנֶגֶד חָכְמָה כָּךְ הוּא. קֹהֶלֶת כְּנֶגֶד תְּבוּנָה כָּךְ הוּא. מִשְׁלֵי כְּנֶגֶד דַּעַת. בַּמֶּה זֶה נִרְאֶה? אֶלָּא כָּל אוֹתָם הַכְּתוּבִים הֵם בִּשְׁנֵי גְוָנִים, רֹאשׁ וָסוֹף, שְׁנֵי גְוָנִים נִרְאִים. וּכְשֶׁמִּסְתַּכְּלִים בַּכְּתוּבִים, זֶה כָּלוּל בָּזֶה וְזֶה כָּלוּל בָּזֶה, מִשּׁוּם כָּךְ שָׁקוּל כְּנֶגֶד הַדַּעַת.</p>\n<p>הַפָּסוּק הַזֶּה אֵין רֹאשׁוֹ סוֹפוֹ וְאֵין סוֹפוֹ רֹאשׁוֹ, וּכְשֶׁהִסְתַּכַּלְתִּי בוֹ, הַכֹּל כָּלוּל אֶחָד עִם אֶחָד, בֵּין מִסּוֹפוֹ לְרֹאשׁוֹ, בֵּין מֵרֹאשׁוֹ לְסוֹפוֹ. שְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה. מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק, וְזֶה וָזֶה נַחַת רוּחַ. כְּמוֹ שֶׁזֶּה נַחַת רוּחַ, כָּךְ זֶה נַחַת רוּחַ.</p>\n<p>עֵד שֶׁהָיוּ יוֹשְׁבִים, בָּא אִישׁ אֶחָד וְאָמַר, אִשְׁתּוֹ שֶׁל רַבִּי שִׁמְעוֹן נִרְפְּאָה מֵחָלְיָהּ. וְהַחֲבֵרִים שָׁמְעוּ קוֹל, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מָחַל לְאוֹתָם חֲטָאֵי הַדּוֹר. אָמַר רַבִּי שִׁמְעוֹן, הֲרֵי הִתְקַיֵּם כָּאן הַפָּסוּק, וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק, כָּךְ זֶה נַחַת רוּחַ, כְּמוֹ מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה. אָמַר לָהֶם, נָקוּם וְנֵלֵךְ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַרְחִישׁ לָנוּ נִסִּים.</p>\n<p>פָּתַח וְאָמַר, מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה - זוֹ הַתּוֹרָה. שֶׁכָּל מִי שֶׁזּוֹכֶה לַעֲסֹק בַּתּוֹרָה וּמַרְוֶה מִמֶּנָּה אֶת הַנֶּפֶשׁ, מַה כָּתוּב? וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק. הַקָּדוֹשׁ בָּרוּךְ הוּא מַכְרִיז עָלָיו כַּמָּה טוֹבוֹת לְהֵיטִיב לוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. זֶהוּ שֶׁכָּתוּב וּשְׁמוּעָה טוֹבָה. מֵאֵיזֶה מָקוֹם? מֵאֶרֶץ מֶרְחָק, מִמָּקוֹם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה רָחוֹק מִמֶּנּוּ בַּתְּחִלָּה, מִמָּקוֹם שֶׁהָיָה אָדָם בְּשִׂנְאָה עִמּוֹ בַּתְּחִלָּה, שֶׁכָּתוּב (איוב כ) וְאֶרֶץ מִתְקוֹמָמָה לוֹ, מֵאוֹתוֹ מָקוֹם שֶׁמַּקְדִּימִים לוֹ שָׁלוֹם, זֶהוּ שֶׁכָּתוּב מֵאֶרֶץ מֶרְחָק. וְכָתוּב, (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי וְאַהֲבַת עוֹלָם אֲהַבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חָסֶד.</p>"],[9522012112,"<p>וְיָצָא אֶל הַמִּזְבֵּחַ אֲשֶׁר לִפְנֵי ה' וְכִפֶּר עָלָיו. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים נ) מִזְמוֹר לְאָסָף אֵל אֱלֹהִים ה' דִּבֶּר וַיִּקְרָא אָרֶץ מִמִּזְרַח שֶׁמֶשׁ עַד מְבאוֹ. לָמַדְנוּ, אֶלֶף וַחֲמֵשׁ מֵאוֹת וַחֲמִשִּׁים רִבּוֹא בַּעֲלֵי שִׁירָה מְזַמְּרִים לַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁמֵּאִיר הַיּוֹם. וְאֶלֶף וַחֲמֵשׁ מֵאוֹת וְאַרְבָּעִים וּשְׁמוֹנָה בַּצָּהֳרָיִם. וְאֶלֶף וַחֲמֵשׁ מֵאוֹת וְתִשְׁעִים אֶלֶף רִבּוֹא בְּאוֹתָהּ שָׁעָה שֶׁנִּקְרֵאת בֵּין הָעַרְבַּיִם.</p>\n<p>רַבִּי יוֹסֵי אָמַר, כְּשֶׁמֵּאִיר הַיּוֹם, כָּל אוֹתָם בַּעֲלֵי יְבָבָה מְשַׁבְּחִים בְּדִבְרֵי תִשְׁבָּחוֹת כְּנֶגֶד הַבֹּקֶר הַזֶּה. (כשמתעורר) שֶׁכְּשֶׁמִּתְעוֹרֵר הַבֹּקֶר הַזֶּה, כֻּלָּם מִתְבַּשְּׂמִים, וְהַדִּין שׁוֹכֵךְ, וְאוֹמְרִים תִּשְׁבָּחוֹת. זֶהוּ שֶׁכָּתוּב (איובלט) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. וְאוֹתוֹ זְמַן (אמונה) שִׂמְחָה וּבְרָכוֹת נִמְצָאִים בָּעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מֵעִיר אֶת אַבְרָהָם לְהַחֲיוֹתוֹ, וּמִשְׁתַּעֲשֵׁעַ עִמּוֹ וּמַשְׁלִיטוֹ בָעוֹלָם. וּמִנַּיִן לָנוּ שֶׁהַבֹּקֶר הַזֶּה הוּא שֶׁל אַבְרָהָם? שֶׁכָּתוּב (בראשית יט) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר.</p>\n<p>בְּאוֹתוֹ זְמַן שֶׁל בֵּין הָעַרְבַּיִם, כָּל אוֹתָם אֶלֶף וַחֲמֵשׁ מֵאוֹת וְתִשְׁעִים אֶלֶף רִבּוֹא בַּעֲלֵי יְלָלָה נִקְרָאִים, וּמְזַמְּרִים בְּאוֹתָהּ שָׁעָה, וְהַקְּטָטָה שׁוֹרָה בָּעוֹלָם. וְאוֹתָהּ שָׁעָה הַהִתְעוֹרְרוּת שֶׁמֵּעִיר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִצְחָק, וְעוֹמֵד וְדָן אֶת הָרְשָׁעִים שֶׁעוֹבְרִים עַל דִּבְרֵי הַתּוֹרָה, וְשִׁבְעָה נַהֲרוֹת אֵשׁ זוֹרְמִים וְיוֹצְאִים וְחָלִים עַל רָאשֵׁי הָרְשָׁעִים, וְשַׁלְהָבוֹת גֶּחָלִים שֶׁל אֵשׁ מִתְעוֹרְרוֹת מִמַּעְלָה לְמַטָּה. וְאָז שָׁב אַבְרָהָם לִמְקוֹמוֹ, כְּמוֹ שֶׁנֶּאֱמַר וְאַבְרָהָם שָׁב לִמְקוֹמוֹ. וְהַיּוֹם פּוֹנֶה, וְרִשְׁעֵי הַגֵּיהִנֹּם צוֹוְחִים וְאוֹמְרִים: (ירמיה ו) אוֹי לָנוּ כִּי פָנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב. וְאוֹתָהּ שָׁעָה צָרִיךְ אָדָם לְהִזָּהֵר בִּתְפִלַּת הַמִּנְחָה.</p>\n<p>בִּזְמַן שֶׁמַּגִּיעַ הַלַּיְלָה, אוֹתָם אֶלֶף וַחֲמֵשׁ מֵאוֹת וְאַרְבָּעִים וּשְׁמוֹנָה נִקְרָאִים מִחוּץ לַפָּרֹכֶת וְאוֹמְרִים שִׁירָה. אָז מִתְעוֹרְרִים הַדִּינִים שֶׁלְּמַטָּה, וְהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם, וְאֵלֶּה אוֹמְרִים שִׁירָה עַד שֶׁנֶּחֱלָק הַלַּיְלָה מִשְׁמֶרֶת וָחֵצִי. אַחַר שֶׁנֶּחֱלָק הַלַּיְלָה, מִזְדַּמְּנִים כָּל הָאֲחֵרִים כְּאֶחָד וְאוֹמְרִים תְּהִלּוֹת, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ס) וּתְהִלּוֹת ה' יְבַשֵּׂרוּ. רַבִּי יְהוּדָה אָמַר, כְּשֶׁנִּמְצָא רָצוֹן בַּבֹּקֶר, תְּהִלּוֹת ה' מְבַשְּׂרִים.</p>\n<p>רַבִּי יוֹסֵי אָמַר, אַחַר שֶׁרוּחַ הַצָּפוֹן הִתְעוֹרְרָה בַּחֲצוֹת הַלַּיְלָה וְהָלְכָה לָהּ, מְבַשְּׂרִים תְּהִלּוֹת עַד שֶׁיָּבֹא הַבֹּקֶר, וּמִתְעוֹרֵר הַבֹּקֶר הַזֶּה, וְאָז שִׂמְחָה וּבְרָכוֹת נִמְצָאִים בָּעוֹלָם.</p>\n<p>לָמַדְנוּ, אָמַר רַבִּי אַבָּא, כֻּלָּם כָּךְ, וּמֵעַל כֻּלָּם שְׁלֹשָׁה שָׂרִים. בְּאוֹתָהּ שָׁעָה שֶׁמִּתְעוֹרֵר הַבֹּקֶר הַזֶּה וּמְעוֹרְרִים תִּשְׁבָּחוֹת עַל כָּל אוֹתָם אֶלֶף וַחֲמֵשׁ מֵאוֹת וַחֲמִשִּׁים רִבּוֹא, מִתְמַנֶּה עֲלֵיהֶם מְמֻנֶּה אֶחָד, וּשְׁמוֹ הֵימָן, כְּנֶגֶד שֶׁלְּמַטָּה, וְתַחַת יָדוֹ שָׂרִים מְמֻנִּים עֲלֵיהֶם לְתַקֵּן שִׁיר.</p>\n<p>בְּאוֹתָהּ שָׁעָה שֶׁמִּתְעוֹרֵר זְמַן שֶׁל בֵּין הָעַרְבַּיִם וּמְזַמְּרִים כָּל אוֹתָם אֶלֶף וַחֲמֵשׁ מֵאוֹת וְתִשְׁעִים אֶלֶף רִבּוֹא בַּעֲלֵי הַיְלָלָה, מִתְמַנֶּה עֲלֵיהֶם מְמֻנֶּה אֶחָד, וּשְׁמוֹ יְדוּתוּן, כְּנֶגֶד שֶׁלְּמַטָּה, וְתַחַת יָדוֹ מְמֻנִּים עֲלֵיהֶם שָׂרִים לְתַקֵּן אוֹתוֹ הַזֶּמֶר, כְּמוֹ שֶׁנֶּאֱמַר (שם כה) זְמִיר עָרִיצִים.</p>\n<p>בְּאוֹתָהּ שָׁעָה שֶׁמַּגִּיעַ הַלַּיְלָה, מִתְעוֹרְרִים כָּל אוֹתָם שֶׁמִּחוּץ לַפָּרֹכֶת, וְאָז הַכֹּל שׁוֹכֵךְ, וּפֶתַח לֹא נִמְצָא, וְהַדִּינִים שֶׁלְּמַטָּה מִתְעוֹרְרִים, כֻּלָּם מִתְמַנִּים כְּאֶחָד אֵלֶּה עַל אֵלֶּה, עַד שֶׁנֶּחֱלָק הַלַּיְלָה. אַחַר שֶׁנֶּחֱלָק הַלַּיְלָה וְכֻלָּם מִתְכַּנְּסִים, מִתְמַנֶּה עֲלֵיהֶם מְמֻנֶּה אֶחָד וּמְכַנֵּס אֶת כָּל הַמַּחֲנוֹת, כְּמוֹ שֶׁנֶּאֱמַר (במדבר י) מְאַסֵּף לְכָל הַמַּחֲנוֹת וְגוֹ', וּשְׁמוֹ אָסָף, כְּנֶגֶד שֶׁלְּמַטָּה, וְתַחַת יָדוֹ כָּל אוֹתָם שָׂרִים מְמֻנִּים וּמְבַשְּׂרִים תְּהִלּוֹת.</p>\n<p>עֵד שֶׁבָּא הַבֹּקֶר. כֵּיוָן שֶׁבָּא הַבֹּקֶר, קָם אוֹתוֹ נַעַ\"ר וְיוֹנֵק מִשְּׁדֵי אִמּוֹ לְטַהֵר אוֹתָם, וְנִכְנָס לַשֶּׁמֶשׁ. כְּשֶׁמִּתְעוֹרֵר הַבֹּקֶר, אָז הִיא עֵת רָצוֹן שֶׁמְּדַבֶּרֶת הַגְּבִירָה עִם הַמֶּלֶךְ, וְהַמֶּלֶךְ מוֹשֵׁךְ מִמֶּנּוּ חוּט אֶחָד שֶׁל בְּרָכוֹת וּפוֹרֵס עַל הַגְּבִירָה וְעַל אוֹתָם שֶׁמִּזְדַּוְּגִים עִמָּהּ. מִי הֵם שֶׁמִּזְדַּוְּגִים עִמָּהּ? אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה בַּלַּיְלָה, כְּשֶׁנֶּחֱלָק.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁבָּא עִם הַגְּבִירָה בְּשָׁעָה שֶׁבָּאָה לְקַבֵּל אֶת פְּנֵי הַמֶּלֶךְ לְדַבֵּר עִמָּהּ, וְנִמְצָא עִמָּהּ, בְּשָׁעָה שֶׁהַמֶּלֶךְ מוֹשִׁיט אֶת יְמִינוֹ לְקַבֵּל אֶת הַגְּבִירָה. זֶהוּ שֶׁכָּתוּב (תהלים קלט) אֶשָּׂא כַנְפֵי שָׁחַר אֶשְׁכְּנָה בְּאַחֲרִית יָם. מִי אַחֲרִית הַיָּם? אוֹתָהּ שָׁעָה אַחֲרִית שֶׁל אוֹתוֹ יָם הִיא. שֶׁכְּשֶׁנֶּחֱלָק, הָיְתָה רֵאשִׁית, וְהָיָה דִין, וְעַכְשָׁו הָאַחֲרִית הוּא שֶׁלָּהּ, שֶׁמִּסְתַּלְּקִים דִּינֶיהָ, וְנִכְנֶסֶת לְכַנְפֵי הַמֶּלֶךְ הִיא וְכָל אוֹתָם שֶׁמִּזְדַּוְּגִים עִמָּהּ. זֶהוּ שֶׁכָּתוּב אֶשְׁכְּנָה בְּאַחֲרִית יָם.</p>\n<p>וְלָמַדְנוּ, כָּל אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה בְּשָׁעָה שֶׁנֶּחֱלָק הַלַּיְלָה, מִשְׁתַּתְּפִים עִם הַשְּׁכִינָה. וּכְשֶׁבָּא הַבֹּקֶר וְהַגְּבִירָה מִתְחַבֶּרֶת עִם הַמֶּלֶךְ, הוּא נִמְצָא עִמָּהּ עִם הַמֶּלֶךְ, וְהַמֶּלֶךְ פּוֹרֵס עַל כֻּלָּם אֶת כְּנָפָיו. זֶהוּ שֶׁכָּתוּב (שם מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי וְגוֹ'.</p>\n<p>לָמַדְנוּ, בְּאוֹתָהּ שָׁעָה הָאָבוֹת מִזְדַּמְּנִים עִם הַגְּבִירָה, וּמַקְדִּימִים לְדַבֵּר עִמָּהּ וּלְהִתְחַבֵּר עִמָּהּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְדַבֵּר עִמָּהּ עֲלֵיהֶם, וְהוּא קוֹרֵא לָהּ לִפְרֹס עָלֶיהָ אֶת כְּנָפָיו. זֶהוּ שֶׁכָתוּב (שם נ) מִזְמוֹר לְאָסָף אֵל אֱלֹהִים ה' דִּבֶּר וַיִּקְרָא אָרֶץ וְגוֹ'. אֵל - זֶה אוֹר הַחָכְמָה, וְנִקְרָא חֶסֶד. אֱלֹהִים - זוֹ גְבוּרָה. יֱהִֹוִה - זוֹ שְׁלֵמוּת הַכֹּל, רַחֲמִים. וְעַל זֶה - דִּבֶּר וַיִּקְרָא אָרֶץ וְגוֹ'.</p>"],[9522012113,"<p>רַבִּי אֶלְעָזָר הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן אָבִיו. אָמַר לוֹ, הֲרֵי שָׁנִינוּ אֱלֹהִים בְּכָל מָקוֹם הוּא דִּין. יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. יֵשׁ מָקוֹם שֶׁנִּקְרָא אֱלֹהִים, כְּמוֹ אֲדֹנָ\"י יְהֹוְ\"ה. לָמָּה נִקְרָא אֱלֹהִים, וַהֲרֵי אוֹתִיּוֹת הָרַחֲמִים הֵן בְּכָל מָקוֹם?</p>\n<p>אָמַר לוֹ, כָּךְ זֶה כָּתוּב בַּמִּקְרָא, שֶׁכָּתוּב (דברים ד) וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבוֹתָ אֶל לְבָבֶךְ כִּי ה' הוּא הָאֱלֹהִים, וְכָתוּב (מלכים א יח) ה' הוּא הָאֱלֹהִים. אָמַר לוֹ, דָּבָר זֶה יָדַעְתִּי, שֶׁבְּמָקוֹם שֶׁיֵּשׁ דִּין יֵשׁ רַחֲמִים, וְלִפְעָמִים בְּמָקוֹם שֶׁיֵּשׁ רַחֲמִים יֵשׁ דִּין. אָמַר לוֹ, בֹּא וּרְאֵה שֶׁכָּכָה זֶה, יְהֹוָ\"ה בְּכָל מָקוֹם רַחֲמִים. וּבְשָׁעָה שֶׁמְּהַפְּכִים הָרְשָׁעִים רַחֲמִים לְדִין, אָז כָּתוּב יִהֹוְ\"ה, וְקוֹרְאִים אוֹתוֹ אֱלֹהִים.</p>\n<p>אֲבָל בֹּא רְאֵה סוֹד הַדָּבָר, שָׁלֹשׁ דְּרָגוֹת הֵן, וְכָל דַּרְגָּה וְדַרְגָּה לְבַדָּהּ, וְאַף עַל גַּב שֶׁהַכֹּל אֶחָד וּמְקֻשָּׁרִים בְּאֶחָד, וְלֹא נִפְרָדִים זֶה מִזֶּה. בֹּא רְאֵה, כָּל הַנְּטִיעוֹת וְכָל הַמְּאוֹרוֹת (שמתלהטים) כֻּלָּם מְאִירִים וּמִתְלַהֲטִים וְנִשְׁקִים וּמִתְבָּרְכִים מֵאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא שֶׁהַכֹּל כָּלוּל בּוֹ, וּבוֹ כְּלַל הַכֹּל.</p>\n<p>וְהַנָּהָר הַזֶּה נִקְרָא אֵ\"ם לַגָּן וּמֵעַל לַגָּן, מִשּׁוּם שֶׁעֵדֶן מִשְׁתַּתֵּף עִמָּהּ וְלֹא נִפְרָד מִמֶּנָּה. וּמִשּׁוּם כָּךְ כָּל הַמַּעְיָנוֹת יוֹצְאִים וְשׁוֹפְעִים וְנִשְׁקִים לְכָל עֵבֶר וּפוֹתְחִים בָּהּ פְּתָחִים, וְעַל כֵּן רַחֲמִים נִמְצָאִים מִמֶּנָּה, וְרַחֲמִים פְּתוּחִים בָּהּ.</p>\n<p>וּמִשּׁוּם שֶׁקּוֹרְאִים לָהּ אֵם, נְקֵבָה גְּבוּרָה, וְדִין יוֹצֵא מִמֶּנָּה. נִקְרֵאת רַחֲמִים לְבַדָּהּ, הֲרֵי מִצִּדֶּיהָ מִתְעוֹרְרִים דִּינִים, וּמִשּׁוּם כָּךְ כָּתוּב בְּרַחֲמִים וְנָקוּד בְּדִין. הָאוֹתִיּוֹת בְּרַחֲמִים, וְנִשְׁפָּע דִּין מִצִּדָּהּ, כְּמוֹ כֵן יְהֶוִֹ\"ה, הִנֵּה דַּרְגָּה אַחַת.</p>\n<p>דַּרְגָּה שְׁנִיָּה - מִצַּד הָרִאשׁוֹנָה הַזּוֹ יוֹצֵאת וּמִתְעוֹרֶרֶת דַּרְגָּה אַחֶרֶת שֶׁנִּקְרֵאת גְּבוּרָה, וְזֶה נִקְרָא אֱלֹהִים בָּאוֹתִיּוֹת הַלָּלוּ מַמָּשׁ. וְהָרֵאשִׁית (אחת) הִיא מִזְּעֵיר אַנְפִּין, וּבוֹ נֶאֶחְזָה. וּמִשּׁוּם שֶׁנֶּאֶחְזָה (זה) בָּזֶה כָּתוּב ה' הָאֱלֹהִים, כִּי ה' הוּא הָאֱלֹהִים, בְּאֵלּוּ הָאוֹתִיּוֹת, וְהוּא אֶחָד, וְזוֹהִי דַּרְגָּה שְׁנִיָּה.</p>\n<p>דַּרְגָּה שְׁלִישִׁית - צֶדֶק. כֶּתֶר אַחֲרוֹן, הֲרֵי בֵּית דִּין שֶׁל הַמֶּלֶךְ. וְלָמַדְנוּ אֲדנָ\"י כָּךְ כָּתוּב וְכָךְ נִקְרָא, וּכְנֶסֶת יִשְׂרָאֵל נִקְרֵאת בַּשֵּׁם הַזֶּה, וְהַשֵּׁם הַזֶּה בַּמָּקוֹם הַזֶּה נִשְׁלָם, וְאֵלּו הֵן שָׁלֹשׁ דְּרָגוֹת שֶׁנִּקְרָאוֹת בִּשְׁמוֹת הַדִּין, וְהַכֹּל נִקְשָׁר אֶחָד עִם אֶחָד בְּלִי פֵרוּד, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>"],[9522012114,"<p>אָמַר לוֹ, אִם נוֹחַ לִפְנֵי אַבָּא, הֲרֵי שָׁמַעְתִּי עַל זֶה, שֶׁכָּתוּב (שמות ג) אֶהְיֶה אֲשֶׁר אֶהְיֶה, וְלֹא עוֹמֵד בּוֹ. אָמַר לוֹ, אֶלְעָזָר בְּנִי, הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, וְעַכְשָׁו בְּדָבָר אֶחָד הַכֹּל נִקְשָׁר.</p>\n<p>וְסוֹד הַדָּבָר כָּךְ הוּא. אֶהְיֶה, זֶה כְּלָל שֶׁל הַכֹּל. שֶׁכְּשֶׁשְּׁבִילִים סְתוּמִים וְלֹא מִתְפָּרְשִׁים, וּכְלוּלִים בְּמָקוֹם אֶחָד, אָז נִקְרָא אֶהְיֶה, הַכְּלָל שֶׁל הַכֹּל, סָתוּם וְלֹא נִגְלֶה.</p>\n<p>אַחַר שֶׁיָּצְאָה מִמֶּנּוּ רֵאשִׁית וְאוֹתוֹ נָהָר עָבַר לִמְשֹׁךְ אֶת הַכֹּל, אֲזַי נִקְרָא אֲשֶׁר אֶהְיֶה. כְּלוֹמַר, עַל כֵּן אֶהְיֶה, אֶהְיֶה מְזֻמָּן לְהַמְשִׁיךְ וּלְהוֹלִיד הַכֹּל. אֶהְיֶה - כְּלוֹמַר, עַכְשָׁו אֲנִי הוּא הַכְּלָל שֶׁל הַכֹּל, הַכְּלָל שֶׁל כָּל פְּרָט. אֲשֶׁר אֶהְיֶה - שֶׁהִתְעַבְּרָה הָאֵם, וַעֲתִידָה לְהוֹצִיא אֶת כָּל הַפְּרָטִים וּלְגַלּוֹת אֶת הַשֵּׁם הָעֶלְיוֹן.</p>\n<p>אַחַר כָּךְ רָצָה מֹשֶׁה לָדַעַת מַהוּ פְּרַט הַדָּבָר, עַד שֶׁפֵּרַשׁ וְאָמַר אֶהְיֶה (יהוה) - זֶהוּ פְּרָט. וְכָאן לֹא כָתוּב אֲשֶׁר אֶהְיֶה. וּמָצָאתִי בְּסִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ, אֲשֶׁר - בְּקֶשֶׁר שֶׁל עִדּוּן הַמֶּמְשָׁלָה נִמְצֵאת בְּחַבְרוּתָא עֶלְיוֹנָה, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ל) בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָּנוֹת, אֶהְיֶה עֲתִידָה לְהוֹלִיד.</p>\n<p>בֹּא וּרְאֵה אֵיךְ יוֹרֵד מִדַּרְגָּה לְדַרְגָּה לְהוֹדִיעַ אֶת סוֹד הַשֵּׁם הַקָּדוֹשׁ (להראות את הקדוש ברוך הוא) לְמֹשֶׁה. בָּרִאשׁוֹנָה אֶהְיֶה, הַכְּלָל שֶׁל הַכֹּל, הַנִּסְתָּר שֶׁלֹּא הִתְגַּלָּה כְּלָל, כְּמוֹ שֶׁאָמַרְנוּ. וְסִימָן - (משלי ח) וָאֶהְיֶה אֶצְלוֹ אָמוֹן וְגוֹ', וְכָתוּב (איוב כח) לֹא יָדַע אֱנוֹשׁ עֶרְכָּהּ וְגוֹ'. אַחַר כָּךְ הוֹצִיא (סוד של הראשית העליונה, תחלת הכל ו) אוֹתוֹ הַנָּהָר, הָאֵם הָעֶלְיוֹנָה שֶׁהִתְעַבְּרָה וַעֲתִידָה לְהוֹלִיד. וְאָמַר אֲשֶׁר אֶהְיֶה, עֲתִידָה לְהוֹלִיד וּלְתַקֵּן הַכֹּל. אַחַר כָּךְ הִתְחִילָה לְהוֹלִיד, וְלֹא כָתוּב אֲשֶׁר, אֶלָּא רַק אֶהְיֶה. כְּלוֹמַר, עַכְשָׁו יוֹצִיא וְיִתְתַּקֵּן הַכֹּל.</p>\n<p>אַחַר שֶׁהַכֹּל יָצָא וְכָל אֶחָד וְאֶחָד הִתְתַּקֵּן בִּמְקוֹמוֹ, עָזַב אֶת הַכֹּל וְאָמַר יְהֹוָ\"ה. זֶה פְּרָט, וְזֶה הַקִּיּוּם. וּבְאוֹתָהּ שָׁעָה יָדַע מֹשֶׁה אֶת סוֹד הַשֵּׁם הַקָּדוֹשׁ הַנִּסְתָּר וְהַנִּגְלֶה, וְנִדְבָּק בְּמַה שֶּׁלֹּא נִדְבְּקוּ שְׁאָר בְּנֵי הָעוֹלָם. אַשְׁרֵי חֶלְקוֹ. בָּא רַבִּי אֶלְעָזָר וְנָשַׁק יָדוֹ.</p>"],[9522012115,"<p>אָמַר לוֹ, אֶלְעָזָר בְּנִי, מִכָּאן וָהָלְאָה הִזָּהֵר שֶׁלֹּא לִכְתֹּב אֶת הַשֵּׁם הַקָּדוֹשׁ אֶלָּא כָּרָאוּי. שֶׁכָּל מִי שֶׁלֹּא יוֹדֵעַ לִכְתֹּב אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי וְלִקְשֹׁר אֶת קֶשֶׁר הָאֱמוּנָה קֶשֶׁר שֶׁל אֶחָד עִם אֶחָד כְּדֵי לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ, כָּתוּב עָלָיו (במדבר טו) כִּי דְבַר ה' בָּזָה וְאֶת מִצְוָתוֹ הֵפַר הִכָּרֵת תִּכָּרֵת וְגוֹ'. אֲפִלּוּ שֶׁהֶחֱסִיר דַּרְגָּה אַחַת אוֹ קֶשֶׁר אֶחָד מֵאוֹת אַחַת מֵהֶן.</p>\n<p>בֹּא רְאֵה, י' בָּרִאשׁוֹנָה - הַכְּלָל שֶׁל הַכֹּל, נִסְתַּר מִכָּל הַצְּדָדִים, הַשְּׁבִילִים לֹא נִפְתָּחִים, הַכְּלָל שֶׁל זָכָר וּנְקֵבָה. קוֹצוֹ שֶׁל יוֹ\"ד שֶׁלְּמַעְלָה רוֹמֵז לְאַיִן. אַחַר כָּךְ י' שֶׁמּוֹצִיאָה אֶת אוֹתוֹ הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מִמֶּנּוּ, וּלְהִתְעַבֵּר מִמֶּנּוּ ה', בָּזֶה כָּתוּב (בראשיתב) וְנָהָר יֹצֵא מֵעֵדֶן. יֹצֵא וְלֹא יָצָא. מִשּׁוּם כָּךְ לֹא צָרִיךְ לְהִפָּרֵד מִמֶּנּוּ. וּמִשּׁוּם כָּךְ כָּתוּב רַעְיָתִי.</p>\n<p>וְאִם תֹּאמַר, כָּתוּב נָהָר, מַשְׁמָע אֶחָד, וַהֲרֵי כָּאן שְׁלֹשָׁה? זֶה כָּךְ וַדַּאי. י' מוֹצִיאָה שְׁלֹשָׁה, וּבִשְׁלֹשָׁה הַכֹּל נִכְלָל. י' מוֹצִיאָה לְפָנֶיהָ אוֹתוֹ נָהָר, וּשְׁנֵי בָנִים שֶׁמְּנִיקָה הָאֵם, וְהִתְעַבְּרָה מֵהֶם, וּמוֹצִיאָה אוֹתָם אַחַר כָּךְ. ה' - כְּמוֹ כֵן ה', וְהֵם בָּנִים תַּחַת הָאָב וְהָאֵם.</p>\n<p>אַחַר שֶׁהוֹלִידָה, הוֹצִיאָה בֵּן זָכָר, וְשָׂמָה אוֹתוֹ לְפָנֶיהָ, וְצָרִיךְ לִכְתֹּב ו', וְזֶה יוֹרֵשׁ אֶת נַחֲלַת הָאָב וְהָאֵם, וְיוֹרֵשׁ שְׁנֵי חֲלָקִים, וּמִמֶּנּוּ נִזּוֹנֵית הַבַּת. וְעַל כֵּן צָרִיךְ לִכְתֹּב אַחַר כָּךְ ו\"ה כְּאֶחָד, כְּמוֹ שֶׁהֵ\"א רִאשׁוֹנָה י\"ה כְּאֶחָד, וְלֹא צָרִיךְ לְהַפְרִידָם. אַף כָּאן ו\"ה כְּאֶחָד, וְלֹא צָרִיךְ לְהַפְרִידָם. וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים. וְהַדְּבָרִים הַלָּלוּ עוֹלִים לְמָקוֹם אַחֵר. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁיּוֹדְעִים אֶת הַסּוֹדוֹת הָעֶלְיוֹנִים שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ וּרְאוּיִים לְהוֹדוֹת לוֹ. זֶהוּ שֶׁכָּתוּב (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ.</p>\n<p>לָמַדְנוּ, אָמַר רַבִּי יְהוּדָה, (שם נ) אֵל אֱלֹהִים דִּבֶּר וַיִּקְרָא אָרֶץ. שְׁלֵמוּת הַכֹּל, שְׁלֵמוּתָם שֶׁל הָאָבוֹת הַקְּדוֹשִׁים. דִּבֶּר וַיִּקְרָא אָרֶץ, לְהִמָּצֵא עִם כְּנֶסֶת יִשְׂרָאֵל בִּשְׁלֵמוּת וּבְשִׂמְחָה. וּמֵאֵיזֶה מָקוֹם הוּא נִמְצָא עִמָּהּ? חָזַר וְאָמַר, מִצִּיּוֹן מִכְלַל יֹפִי אֱלֹהִים הוֹפִיעַ.</p>"],[9522012116,"<p>לָמַדְנוּ, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת הָעוֹלָם שֶׁלְּמַטָּה, עָשָׂה הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה. עָשָׂה יְרוּשָׁלַיִם מֶרְכַּז כָּל הָאָרֶץ, וּמָקוֹם אֶחָד שֶׁנִּקְרָא צִיּוֹן עָלֶיהָ, וּמֵהַמָּקוֹם הַזֶּה מִתְבָּרֶכֶת. וּבַמָּקוֹם הַזֶּה שֶׁל צִיּוֹן מַתְחִיל הָעוֹלָם לְהִבָּנוֹת, וּמִמֶּנּוּ נִבְנָה. זֶהוּ שֶׁכָּתוּב, אֵל אֱלֹהִים ה' דִּבֶּר וַיִּקְרָא אָרֶץ מִמִּזְרַח שֶׁמֶשׁ עַד מְבוֹאוֹ. וּמֵאֵיזֶה מָקוֹם? מִצִּיּוֹן מִכְלַל יֹפִי אֱלֹהִים הוֹפִיעַ. כְּלוֹמַר, מִצִּיּוֹן, שֶׁהִיא שְׁלֵמוּת שֶׁל הַיֹּפִי שֶׁל הָעוֹלָם, אֱלֹהִים הוֹפִיעַ. בֹּא רְאֵה, לֹא הִתְבָּרְכָה יְרוּשָׁלַיִם אֶלָּא רַק מִצִּיּוֹן. וְצִיּוֹן מִלְמַעְלָה, וְהַכֹּל נִקְשָׁר אֶחָד עִם אֶחָד.</p>\n<p>לָמַדְנוּ, אָמַר רַבִּי יְהוּדָה, וְיָצָא אֶל הַמִּזְבֵּחַ אֲשֶׁר לִפְנֵי ה' וְכִפֶּר עָלָיו. אֶל הַמִּזְבֵּחַ סְתָם. (כביכול) כְּמוֹ שֶׁנַּעֲשֶׂה לְמַטָּה, נַעֲשֶׂה לְמַעְלָה, וְהַכֹּל נִקְשָׁר אֶחָד בְּאֶחָד. וְלָמַדְנוּ, כְּמוֹ שֶׁבַּיּוֹם הַזֶּה מְכַפֵּר הַכֹּהֵן לְמַטָּה, כָּךְ גַּם לְמַעְלָה. וּכְשֶׁהַכֹּהֵן שֶׁלְּמַטָּה מְסַדֵּר אֶת עֲבוֹדָתוֹ, כָּךְ גַּם הַכֹּהֵן שֶׁלְּמַעְלָה (כביכול) לֹא נִמְצָא לְמַעְלָה עַד שֶׁנִּמְצָא לְמַטָּה. וּמִמַּטָּה מַתְחִילָה לַעֲלוֹת קְדֻשַּׁת הַמֶּלֶךְ הָעֶלְיוֹן, וְכָל הָעוֹלָמִים נִמְצָאִים אֶחָד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אִלְמָלֵא הָיוּ יוֹדְעִים יִשְׂרָאֵל לָמָּה צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יִשְׂרָאֵל לְהוֹכִיחַ אוֹתָם יוֹתֵר מִכָּל שְׁאָר הָעַמִּים, יֵדְעוּ שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁאִיר אֶת שֶׁלּוֹ, וְלֹא גָבָה מֵהֶם אֶחָד מִמֵּאָה. לָמַדְנוּ שֶׁלַּקָּדוֹשׁ-בָּרוּךְ-הוּא יֵשׁ כַּמָּה מֶרְכָּבוֹת וְכַמָּה חֲיָלוֹת וְכַמָּה שַׁלִּיטִים מְמֻנִּים שֶׁנִּמְצָאִים בַּעֲבוֹדָתוֹ, כְּשֶׁזִּמֵּן אֶת יִשְׂרָאֵל בָּעוֹלָם הַזֶּה הִכְתִּירָם בִּכְתָרִים קְדוֹשִׁים כְּמוֹ שֶׁלְּמַעְלָה, הִשְׁרָה אוֹתָם בָּאָרֶץ הַקְּדוֹשָׁה כְּדֵי שֶׁיִּמָּצְאוּ בַעֲבוֹדָתוֹ, וְקָשַׁר אֶת כָּל הָעֶלְיוֹנִים עִם יִשְׂרָאֵל.</p>\n<p>וּשְׂמָחוֹת לֹא נִכְנָסוֹת לְפָנָיו, וַעֲבוֹדָה לֹא נַעֲשֵׂית לְפָנָיו לְמַעְלָה, עַד שֶׁיִּשְׂרָאֵל עוֹשִׂים לְמַטָּה. כָּל זְמַן שֶׁיִּשְׂרָאֵל נִמְצָאִים בַּעֲבוֹדַת רִבּוֹנָם לְמַטָּה, כָּךְ גַּם לְמַעְלָה. (כביכול) בִּזְמַן שֶׁיִּשְׂרָאֵל מְבַטְּלִים אֶת הָעֲבוֹדָה לְמַטָּה, הֵם מְבַטְּלִים לְמַעְלָה, וְהָעֲבוֹדָה לֹא נִמְצֵאת לֹא לְמַעְלָה וְלֹא לְמַטָּה. וְעַל שֶׁיִּשְׂרָאֵל בִּטְּלוּ אֶת עֲבוֹדָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁהָיוּ שְׁרוּיִים בָּאָרֶץ, כָּךְ גַּם לְמַעְלָה, כָּל שֶׁכֵּן אַחַר כָּךְ.</p>\n<p>אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: יִשְׂרָאֵל, אִם אַתֶּם יוֹדְעִים כַּמָּה אוּכְלוּסִים וְכַמָּה חֲיָלוֹת מִתְעַכְּבִים בִּשְׁבִילְכֶם, תֵּדְעוּ שֶׁאֵינְכֶם כְּדָאִים לַעֲמֹד בָּעוֹלָם אֲפִלּוּ שָׁעָה אַחַת, וְעַל כָּל זֶה מַה כָּתוּב? (ויקרא כו) וְאַף גַּם זֹּאת בִּהְיוֹתָם בְּאֶרֶץ אֹיְבֵיהֶם לֹא מְאַסְתִּים וְגוֹ'. (משום כך) וְיָצָא אֶל הַמִּזְבֵּחַ, אֶל הַמִּזְבֵּחַ סְתָם, אֲשֶׁר לִפְנֵי ה' סְתָם. וְכִפֶּר עָלָיו אַחַר כָּךְ, וְיָצָא וְעָשָׂה אֶת עֹלָתוֹ וְאֶת עֹלַת הָעָם וְגוֹ'. וְכִפֶּר עָלָיו, מַה זֶּה אוֹמֵר? אָמַר רַבִּי יוֹסֵי, לְהָעִיר חֶסֶד בָּעוֹלָם בַּתְּחִלָּה.</p>\n<p>לָמַדְנוּ, וְכִפֶּר עַל הַקֹּדֶשׁ מִטֻּמְאֹת בְּנֵי יִשְׂרָאֵל. מַה זֶּה וְכִפֶּר עַל הַקֹּדֶשׁ? אֶלָּא אָמַר רַבִּי אֶלְעָזָר, הֲרֵי שָׁנִינוּ שֶׁהָרְשָׁעִים עוֹשִׂים פְּגָם לְמַעְלָה, וּמְעוֹרְרִים דִּינִים, וְגוֹרְמִים לְטַמֵּא הַמִּקְדָּשׁ. וְהַנָּחָשׁ הַקָּשֶׁה מַתְחִיל לְהִגָּלוֹת, וְאָז מִתְעוֹרְרִים דִּינִים בָּעוֹלָם, וּבַיּוֹם הַזֶּה צָרִיךְ הַכֹּהֵן לְטַהֵר אֶת הַכֹּל וּלְהִתְעַטֵּר (ולעורר) הַכֶּתֶר הַקָּדוֹשׁ שֶׁלּוֹ, שֶׁהוּא רֹאשׁ הַמֶּלֶךְ, כְּדֵי שֶׁיָּבֹא הַמֶּלֶךְ לִשְׁרוֹת עִם הַגְּבִירָה. וּכְשֶׁרֹאשׁ הַמֶּלֶךְ נוֹסֵעַ, הַכֹּל נוֹסֵעַ, וְיָבא לְהִזְדַּוֵּג עִם הַגְּבִירָה וּלְעוֹרֵר שִׂמְחָה וּבְרָכוֹת בָּעוֹלָם. (כדי שיבא המלך להזדוג עם הגבירה ולעורר שמחה וברכות בעולם. וכשראש המלך נוסע, הכל נוסע).</p>\n<p>נִמְצָא שֶׁכָּל הַשָּׁלוֹם (השלמות) שֶׁלְּמַעְלָה וּלְמַטָּה תְּלוּיָה בַּכֹּהֵן. שֶׁאִם הוּא מְעוֹרֵר אֶת הַכֶּתֶר שֶׁלּוֹ, הַכֹּל מִתְעוֹרֵר וְהַכֹּל נִמְצָא בִּשְׁלֵמוּת, וְעַל זֶה כָּתוּב וְכִפֶּר עַל הַקֹּדֶשׁ. בָּרִאשׁוֹנָה וְכִפֶּר עַל הַקֹּדֶשׁ, לְהַרְבּוֹת שָׁלוֹם בָּעוֹלָם וּלְהַרְבּוֹת שִׂמְחָה בָּעוֹלָם. וּכְשֶׁשִּׂמְחַת הַזִּוּוּג נִמְצֵאת עִם הַמֶּלֶךְ וְהַגְּבִירָה, כָּל הַשַּׁמָּשִׁים וְכָל בְּנֵי הַהֵיכָל, כֻּלָּם נִמְצָאִים בְּשִׂמְחָה (וכל שמחת העולם). וְכָל הַחֲטָאִים שֶׁחָטְאוּ לִפְנֵי הַמֶּלֶךְ, מִתְכַּפְּרִים לָהֶם. זֶהוּ שֶׁכָּתוּב מִכֹּל חַטֹאתֵיכֶם לִפְנֵי ה' תִּטְהָרוּ. וּמִשּׁוּם כָּךְ כָּתוּב, וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד בְּבאוֹ לְכַפֵּר בַּקֹּדֶשׁ עַד צֵאתוֹ. בְּשָׁעָה שֶׁנִּכְנָס לְזַוֵּג אוֹתָם, וּבְשָׁעָה שֶׁמִּזְדַּוְּגִים הַמֶּלֶךְ עִם הַגְּבִירָה, אוֹתָהּ שָׁעָה - וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ.</p>"],[9522012117,"<p>לָמַדְנוּ, וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד. רַבִּי יִצְחָק פָּתַח, (שם) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב וְאַף אֶת בְּרִיתִי יִצְחָק וְגוֹ', וְהַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ. בּא וּרְאֵה, בְּשָׁעָה שֶׁיִּשְׂרָאֵל בַּגָּלוּת, כִּבְיָכוֹל הַקָּדוֹשׁ בָּרוּךְ הוּא עִמָּהֶם בַּגָּלוּת, שֶׁהֲרֵי הַשְּׁכִינָה לֹא זָזָה מֵהֶם לְעוֹלָמִים. בּא רְאֵה, בִּזְמַן שֶׁיִּשְׂרָאֵל נִמְצְאוּ בְּגָלוּת בָּבֶל, הַשְּׁכִינָה שָׁרְתָה בֵינֵיהֶם וְשָׁבָה עִמָּהֶם מִן הַגָּלוּת, וּבִזְכוּת אוֹתָם הַצַּדִּיקִים שֶׁנִּשְׁאֲרוּ בָאָרֶץ, שָׁרְתָה בָאָרֶץ וְלֹא זָזָה מֵהֶם לְעוֹלָמִים. אָמַר רַבִּי יְהוּדָה, שֶׁחָזְרָה הַגְּבִירָה עִם הַמֶּלֶךְ, וְחָזַר הַכֹּל בִּסְעוּדַת הַשִּׂמְחָה שֶׁל הַמֶּלֶךְ, מִשּׁוּם כָּךְ נִקְרְאוּ אַנְשֵׁי כְּנֶסֶת הַגְּדוֹלָה, כְּנֶסֶת הַגְּדוֹלָה וַדַּאי.</p>\n<p>לָמַדְנוּ, בְּכָל זְמַן שֶׁיִּשְׂרָאֵל בַּגָּלוּת, אִם הֵם צַדִּיקִים - הַקָּדוֹשׁ בָּרוּךְ הוּא מַקְדִּים לְרַחֵם עֲלֵיהֶם וּלְהוֹצִיאָם מֵהַגָּלוּת, וְאִם הֵם אֵינָם צַדִּיקִים - הוּא מְעַכֵּב אוֹתָם בַּגָּלוּת עַד אוֹתוֹ זְמַן שֶׁנִּגְזַר. וּכְשֶׁמַּגִּיעַ הַזְּמַן וְהֵם אֵינָם רְאוּיִים - הַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁגִּיחַ עַל כְּבוֹד שְׁמוֹ, וְאֵינוֹ שׁוֹכֵחַ אוֹתָם בַּגָּלוּת. זֶהוּ שֶׁכָּתוּב וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב וְגוֹ'. אֵלּוּ הָאָבוֹת שֶׁל הַכֹּל, סוֹד הַשֵּׁם הַקָּדוֹשׁ.</p>\n<p>רַבִּי חִיָּיא אָמַר, מָה הַטַּעַם יַעֲקֹב רִאשׁוֹן כָּאן? אֶלָּא מִשּׁוּם שֶׁיַּעֲקֹב הוּא כְּלַל הָאָבוֹת, וְהוּא הָעֵץ הַקָּדוֹשׁ. מִשּׁוּם כָּךְ ו' שֶׁל הַשֵּׁם הַקָּדוֹשׁ אֲחוּזָה בּוֹ, וְכָךְ קוֹרְאִים יַעֲקוֹב בְּו'. רַבִּי יִצְחָק אָמַר, וָא\"ו בְּאוֹתִיּוֹתָיו שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת, שֶׁיָּרַשׁ יְרֻשָּׁה שֶׁל שְׁלֹשָׁה עָשָׂר מַעְיָנוֹת שֶׁל הַמַּעְיָן הַנִּסְתָּר הַקָּדוֹשׁ.</p>"],[9522012118,"<p>רַבִּי אַבָּא אָמַר, וָא\"ו לָמָּה כּוֹלֶלֶת ו' א' ו'? אֶלָּא, ו' שֶׁיּוֹשֵׁב עַל הַכִּסֵּא, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל א) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. א' נִסְתֶּרֶת בְּתוֹכוֹ וְלֹא מְגֻלֶּה, וְזֶהוּ שֶׁכָּתוּב (בראשית כב) בִּי נִשְׁבַּעְתִּי נְאֻם ה', מִשּׁוּם כָּךְ כָּתוּב, וְלֹא נִקְרָא אַחֲרוֹן כְּלָל שֶׁל הָרִאשׁוֹן. הָאַחֲרוֹן, הֲרֵי בֵּאַרְנוּ (ו' אחרונה כלל של ו' ראשונה, ו' אחרונה) זֶה יה\"ו יְסוֹד, שֶׁהוּא סִיּוּם הַגּוּף וְהַכְּלָל שֶׁלּוֹ. וְעַל כֵּן כְּלוּלוֹת הָאוֹתִיּוֹת זוֹ עִם זוֹ - וָא\"ו, רֹאשׁ וְסִיּוּם, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>וְלָמַדְנוּ, שְׁתֵּי אוֹתִיּוֹת הֵן, כְּמוֹ זֶה וָא\"ו שֶׁאָמַרְנוּ, נוּ\"ן אַף כָּךְ. וְאַף עַל גַּב שֶׁבֵּאֲרוּ אֶת הַדָּבָר, נוּ\"ן כָּךְ מִתְפָּרֶשֶׁת: נ' כְּפוּפָה זוֹ הַגְּבִירָה. וּסְמוּכָה לָהּ ו', שֶׁהוּא יְסוֹד, כְּדֵי שֶׁתִּתְבָּרֵךְ מִמֶּנּוּ. ן' פְּשׁוּטָה, זוֹ הִתְפַּשְּׁטוּת הַתִּפְאֶרֶת. וְלָכֵן כְּלוּלוֹת הָאוֹתִיּוֹת וְנֶאֱחָזוֹת זוֹ בָּזוֹ. וְאִם תֹּאמַר, לָמָּה מַחֲזִיר ו' פָּנָיו מִנּוּ\"ן כְּפוּפָה, וּמַחֲזִיר פָּנָיו אֶל הַן' הַפְּשׁוּטָה. אֶלָּא בִּשְׁבִיל כְּבוֹד הַמֶּלֶךְ הוּא מַחֲזִיר פָּנָיו כְּנֶגֶד הַמֶּלֶךְ.</p>\n<p>וְלָמַדְנוּ, מֵ\"ם לֹא כוֹלֶלֶת בְּתוֹכָהּ אוֹת אַחֶרֶת, (משום) אֶלָּא מ' פְּתוּחָה, ם' סְתוּמָה. מ' פְּתוּחָה - שֶׁהוּא כְּשֶׁהַזָּכָר מִתְחַבֵּר עִמָּהּ. ם' סְתוּמָה - יוֹבֵל. שֶׁהֲרֵי נִסְתָּרִים דְּרָכֶיהָ וְאַף עַל גַּב שֶׁלִּפְעָמִים מִתְפַּשְּׁטִים, וְיֵשׁ שֶׁשּׁוֹנִים בָּזֶה, כְּמוֹ שֶׁנֶּאֱמַר (שיר ד) גַּן נָעוּל אֲחֹתִי כַלָּה גַּל נָעוּל מַעְיָן חָתוּם.</p>\n<p>אָמַר רַבִּי יִצְחָק, בְּשָׁעָה שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ זוֹכֵר אֶת יִשְׂרָאֵל בַּעֲבוּר שְׁמוֹ וְחוֹזֶרֶת הַגְּבִירָה לִמְקוֹמָהּ, (אז) כָּתוּב וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד בְּבאוֹ לְכַפֵּר בַּקֹּדֶשׁ. כָּךְ הַכֹּהֵן, בְּשָׁעָה שֶׁנִּכְנָס לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ וּלְכַפֵּר בַּקֹּדֶשׁ, לְזַוֵּג אֶת הַמֶּלֶךְ עִם הַגְּבִירָה, כָּתוּב וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד וְגוֹ'.</p>\n<p>לָמַדְנוּ, רַבִּי יְהוּדָה אָמַר, הַכֹּהֵן מְעוֹרֵר שָׁלוֹם בָּעוֹלָם, לְמַעְלָה וּלְמַטָּה. וְלָמַדְנוּ, נִכְנָס בְּדַרְגָּה אַחַת, רוֹחֵץ גּוּפוֹ. יוֹצֵא מִדַּרְגָּה זוֹ לְדַרְגָּה אַחֶרֶת, רוֹחֵץ גּוּפוֹ. אוֹחֵז שָׁלוֹם בָּזֶה וּבָזֶה. קִדֵּשׁ יָדָיו, וּמִתְבָּרְכִים כְּאֶחָד. וּבַכֹּל צָרִיךְ לְהַרְאוֹת מַעֲשֶׂה, וְצָרִיךְ לְהַרְאוֹת לְבוּשׁוֹ שֶׁיִּתְלַבֵּשׁ כְּגוֹן שֶׁהַמַּעֲשֶׂה יִתְכַּוֵּן, עַד שֶׁיְּסַדֵּר הַכֹּל כְּמוֹ שֶׁצָּרִיךְ, וְיִתְבָּרְכוּ עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>"],[9522012119,"<p>לָמַדְנוּ, רַבִּי שִׁמְעוֹן פָּתַח, (ד') יוֹ\"ד בַּחֲקִיקוֹתָיו, אוֹתִיּוֹת בַּצְּדָדִים הִתְקַשְּׁרוּ בְיוֹ\"ד. יוֹ\"ד הוֹלֵךְ לְיוֹ\"ד (לוי\"ו). יוֹ\"ד עוֹלֶה בְיוֹ\"ד. יוֹ\"ד הוֹלֵךְ לְוָי\"ו, מִתְכַּנְּסִים בְּה'. וּמְכַוֵּן אֶת הַדַּעַת, וּמִתְחַבְּרִים ה' עִם וָא\"ו.</p>\n<p>ה' עֶלְיוֹנָה אוֹחֶזֶת שְׁעָרֶיהָ (בשעריה) בְּחִקּוּקֵי תַכְסִיסִים, אוֹחֶזֶת בְּהֶאָרַת אֶלֶף וַחֲמֵשׁ מֵאוֹת וְשִׁבְעִים אַכְסַדְרוֹת נִסְתָּרוֹת. עוֹלָה ה', וּמִתְעַטֶּרֶת חֲמִשִּׁים פְּעָמִים לַחֲמִשִּׁים שְׁעָרִים עַמּוּדִים שֶׁעוֹמְדִים. כְּשֶׁמִּתְגַּלֵּף בְּעַטְרוֹתָיו, מְאִירִים פְּנֵי הַמֶּלֶךְ, וָא\"ו מִתְפַּשֶּׁטֶת לְשִׁבְעִים וּשְׁתַּיִם חֲקִיקוֹת.</p>\n<p>מְעַטֶרֶת ה' אֶת ו' (נ\"א מתעטר ביו\"ד, ה' לו') בְּשִׁבְעִים אֶלֶף וַחֲמֵשׁ מֵאוֹת כְּתָרִים שֶׁמִּתְעַטְּרִים בְּכֶתֶר אֶחָד. זֶהוּ שֶׁכָּתוּב (שם ג) בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ. ו' בִּשְׁנֵי רָאשִׁים, רֹאשׁ הַגֻּלְגֹּלֶת חָקוּק הָרֹאשׁ שֶׁלּוֹ, קוֹץ אֶחָד לְמַעְלָה וְקוֹץ אֶחָד לְמַטָּה, וְי' יוֹרֶדֶת לְו', חֲקִיקַת הַחֲקִיקוֹת בְּתוֹכָם, שִׁבְעִים פָּנִים שֶׁל עֲטָרוֹת מִמַּעְלָה לְמַטָּה. בּוֹ טָסִים גְּבִיעִים וּפְרָחִים, זֶה עוֹלֶה וְזֶה יוֹרֵד, וְנֶחְקָקִים אֶחָד עִם אֶחָד.</p>\n<p>נִקְשֶׁרֶת י' עִם ה', ה' עִם ו', ו' עִם ה' (ו' בה', ה' בו', ו' בו', ו' בה'). זֶה אָחוּז בָּזֶה, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מט) וַתֵּשֶׁב בְּאֵיתָן קַשְׁתּוֹ וַיָּפֹזּוּ זְרוֹעֵי יָדָיו מִידֵי אֲבִיר יַעֲקֹב. וְכָתוּב, (במדבר כד) אֵיתָן מוֹשָׁבֶךְ וְשִׂים בַּסֶּלַע קִנֶּךְ. אָז הַכֹּל מִתְקַשֵּׁר אֶחָד עִם אֶחָד, זֶה עִם זֶה, מְאִירִים הַמַּפְתְּחוֹת וּמְאִירִים כָּל הַפָּנִים. אָז כֻּלָּם נוֹפְלִים עַל פְּנֵיהֶם וּמִזְדַּעְזְעִים וְאוֹמְרִים: בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>"],[9522012120,"<p>הַקּוֹל נִקְשָׁר עִם הַכֹּהֵן, וְהוּא מֵשִׁיב אֲלֵיהֶם וְאוֹמֵר תִּטְהָרוּ. תִּטְהָרוּ אֵין אוֹמְרִים שְׁאָר הַכֹּהֲנִים וְהָעָם, פְּרָט לַכֹּהֵן הַגָּדוֹל, כְּשֶׁנִּקְשָׁר בּוֹ אוֹתוֹ הַקּוֹל.</p>\n<p>לָמַדְנוּ, מִכֹּל חַטֹּאתֵיכֶם לִפְנֵי ה'. כֵּיוָן שֶׁכָּתוּב מִכֹּל חַטֹּאתֵיכֶם, לָמָּה לִפְנֵי ה'? אֶלָּא אָמַר רַבִּי יִצְחָק, לִפְנֵי ה' מַמָּשׁ.</p>\n<p>שֶׁשָּׁנִינוּ, מֵרֹאשׁ חֹדֶשׁ הַסְּפָרִים פְּתוּחִים וְהַדַּיָּנִים דָּנִים. בְּכָל יוֹם וָיוֹם בָּתֵּי הַדִּין נִמְסָרִים לְהִפָּתֵחַ לְדִין, עַד אוֹתוֹ יוֹם שֶׁנִּקְרָא תִּשְׁעָה לַחֹדֶשׁ. בְּאוֹתוֹ יוֹם כָּל הַדִּינִים עוֹלִים לְבַעַל הַדִּין וּמְתַקְּנִים כִּסֵּא עֶלְיוֹן שֶׁל רַחֲמִים לַמֶּלֶךְ הַקָּדוֹשׁ. בְּאוֹתוֹ יוֹם צְרִיכִים יִשְׂרָאֵל לְמַטָּה לִשְׂמֹחַ בְּשִׂמְחָה לִפְנֵי אֲדוֹנָם שֶׁעָתִיד לְיוֹם אַחֵר לָשֶׁבֶת עֲלֵיהֶם בַּכִּסֵּא הַקָּדוֹשׁ שֶׁל רַחֲמִים, בְּכִסֵּא שֶׁל וַתְּרָנוּת.</p>\n<p>וְכָל אוֹתָם הַסְּפָרִים הַפְּתוּחִים לְפָנָיו וּכְתוּבִים לְפָנָיו אֶת כָּל אוֹתָם הַחֲטָאִים, הוּא מְזַכֶּה אוֹתָם וּמְטַהֵר אוֹתָם מִכֻּלָּם. זֶהוּ שֶׁכָּתוּב מִכֹּל חַטֹּאתֵיכֶם לִפְנֵי ה' תִּטְהָרוּ. לִפְנֵי ה' מַמָּשׁ. אוֹתָם שֶׁאוֹמְרִים אֶת הַפָּסוּק, אוֹמְרִים עַד כָּאן וְלֹא יוֹתֵר. וְאֵין רְשׁוּת לְאַחֵר לוֹמַר תִּטְהָרוּ, אֶלָּא הַכֹּהֵן הַגָּדוֹל שֶׁעוֹבֵד אֶת הָעֲבוֹדָה, וְקוֹשֵׁר אֶת הַשֵּׁם הַקָּדוֹשׁ בְּפִיו. וּכְשֶׁהָיָה נִקְשָׁר וּמִתְבָּרֵךְ בְּפִיו, אוֹתוֹ קוֹל יוֹרֵד וּמַכֶּה בּוֹ, וּמְאִירָה הַמִּלָּה בְּפִי הַכֹּהֵן, וְאוֹמֵר תִּטְהָרוּ. עָבַד עֲבוֹדָה, וּמִתְבָּרְכִים כָּל אוֹתָם הָעֶלְיוֹנִים שֶׁנִּשְׁאֲרוּ.</p>\n<p>אַחַר כָּךְ רוֹחֵץ גּוּפוֹ וּמְקַדֵּשׁ יָדָיו לְהִכָּנֵס לַעֲבוֹדָה קְדוֹשָׁה אַחֶרֶת. עַד שֶׁיִּתְכַּוֵּן לְהִכָּנֵס לְמָקוֹם אַחֵר עֶלְיוֹן קָדוֹשׁ מֵהַכֹּל. שָׁלֹשׁ שׁוּרוֹת מַקִּיפוֹת אוֹתוֹ; שֶׁל אֶחָיו הַכֹּהֲנִים, וּלְוִיִּם, וּמִכָּל שְׁאָר הָעָם. (ברכות לפניו) זוֹקְפִים יָדַיִם עָלָיו בִּתְפִלָּה, וְקֶשֶׁר שֶׁל זָהָב תָּלוּי בְּרַגְלוֹ. נוֹטֵל שָׁלֹשׁ פְּסִיעוֹת, וְכֻלָּם עוֹמְדִים בִּמְקוֹמָם וְלֹא הוֹלְכִים אַחֲרָיו. (היה מקטיר קטרת).</p>\n<p>הוֹלֵךָ שָׁלֹשׁ פְּסִיעוֹת אֲחֵרוֹת, (רשומהבלב) מַקִּיף אֶת מְקוֹמוֹ. הוֹלֵךְ שָׁלֹשׁ פְּסִיעוֹת, וְסוֹתֵם אֶת עֵינָיו וְנִקְשָׁר לְמַעְלָה. נִכְנָס לְמָקוֹם שֶׁנִּכְנָס, שׁוֹמֵעַ קוֹל כַּנְפֵי הַכְּרוּבִים שֶׁמְּזַמְּרִים וּמַקִּישִׁים בַּכְּנָפִים הַפְּרוּשׂוֹת לְמַעְלָה. הָיָה מַקְטִיר אֶת הַקְּטֹרֶת, וְשׁוֹכֵךְ קוֹל כַּנְפֵיהֶם וְנִדְבָּקִים בְּלַחַשׁ.</p>\n<p>אִם הַכֹּהֵן זוֹכֶה, שֶׁהֲרֵי לְמַעְלָה נִמְצָא בְשִׂמְחָה - אַף כָּאן בְּאוֹתָהּ שָׁעָה יוֹצֵא רְצוֹן הָאוֹר הַמִּתְבַּשֵּׂם מֵרֵיחוֹת שֶׁל הָרֵי אֲפַרְסְמוֹן טָהוֹר שֶׁלְּמַעְלָה, וְהוֹלֵךְ בְּכָל אוֹתוֹ הַמָּקוֹם. נִכְנָס הָרֵיחַ לִשְׁנֵי נִקְבֵי חָטְמוֹ, וְלִבּוֹ מִתְיַשֵּׁב. אָז הַכֹּל הוּא בְּלַחַשׁ, וְלֹא נִמְצָא שָׁם פִּתְחוֹן פֶּה. פּוֹתֵחַ הַכֹּהֵן אֶת פִּיו בִּתְפִלָּה בְּרָצוֹן, בְּשִׂמְחָה, וּמִתְפַּלֵּל אֶת תְּפִלָּתוֹ.</p>\n<p>אַחַר שֶׁסִּיֵּם, זוֹקְפִים הַכְּרוּבִים כְּמוֹ מִקֹּדֶם אֶת כַּנְפֵיהֶם וּמְזַמְּרִים. אָז יוֹדֵעַ הַכֹּהֵן שֶׁהָיָה רָצוֹן, וְעֵת שִׂמְחָה לַכֹּל, וְהָעָם יוֹדְעִים שֶׁתְּפִלָּתוֹ הִתְקַבְּלָה, כְּמוֹ שֶׁכָּתוּב (ישעיה א) אִם יִהְיֶה חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. וְהוּא שָׁב לַאֲחוֹרָיו וּמִתְפַּלֵּל תְּפִלָּתוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל הַכֹּהֵן, שֶׁהֲרֵי עַל יָדוֹ שִׂמְחָה עַל שִׂמְחָה נִמְצֵאת בְּאוֹתוֹ יוֹם לְמַעְלָה וּלְמַטָּה. עַל אוֹתָהּ שָׁעָה כָּתוּב, (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו.</p>"],[9522012121,"<p>וְהָיְתָה לָכֶם לְחֻקַּת עוֹלָם בַּחֹדֶשׁ הַשְּׁבִיעִי בֶּעָשׂוֹר לַחֹדֶשׁ תְּעַנּוּ אֶת נַפְשּתֶיכֶם וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (ישעיה כו) נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ וְגוֹ'. נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה, נַפְשִׁי אִוְּתָךְ בַּלַּיְלָה הָיָה צָרִיךְ לִהְיוֹת! מַהוּ נַפְשִׁי אִוִּיתִךְ? אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ, יְשַׁחֲרֶךָּ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא כָּךְ לָמַדְנוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא רוּחַ וְהַנֶּפֶשׁ שֶׁל הַכֹּל, וְיִשְׂרָאֵל אוֹמְרִים: נַפְשִׁי וְרוּחִי אָתָּה. מִשּׁוּם כָּךְ אִוִּיתִךְ לִדְבֹּק בְּךְ, וַאֲשַׁחֲרֶךָּ לִמְצֹא אֶת רְצוֹנְךְ.</p>\n<p>רַבִּי יוֹסֵי אָמַר, בְּשָׁעָה שֶׁאָדָם יָשֵׁן בְּמִטָּתוֹ, יוֹצֵאת נַפְשׁוֹ, עוֹלָה וּמְעִידָה בָּאָדָם עַל כָּל מַה שֶּׁעָשָׂה בְּכָל הַיּוֹם. הַגּוּף אוֹמֵר לַנֶּפֶשׁ: נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה, אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ.</p>\n<p>דָּבָר אַחֵר נַפְשִׁי אִוִּיתִךְ - אָמְרָה כְּנֶסֶת יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה, בְּעוֹד שֶׁאָנוּ בַּגָּלוּת בֵּין הָעַמִּים, וּמְנוּעָה נַפְשִׁי מִכָּל רַע (ושבעה נפשי מכל הבזיונות) שֶׁקְּשׁוּרָה בֵּין הָעַמִּים, נַפְשִׁי אִוִּיתִךְ, כְּדֵי לָשׁוּב לִמְקוֹמִי. אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ, כְּלוֹמַר, אַף עַל גַּב שֶׁהֵם מְשַׁעְבְּדִים אֶת בָּנַי בְּכָל שִׁעְבּוּד, רוּחַ הַקֹּדֶשׁ לֹא זָזָה מִמֶּנִּי כְּדֵי לְשַׁחֵר אוֹתְךְ וְלַעֲשׂוֹת מִצְווֹתֶיךְ.</p>\n<p>רַבִּי יִצְחָק אָמַר, אָמְרוּ יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: בְּעוֹד שֶׁנַּפְשִׁי בִּי, אִוִּיתִךְ בַּלַּיְלָה. מָה הַטַּעַם בַּלַּיְלָה? אֶלָּא מִשּׁוּם שֶׁהַנֶּפֶשׁ הַזּוֹ בַּשָּׁעָה הַזּוֹ צְרִיכָה לַחְמֹד אוֹתְךְ. אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ, כַּאֲשֶׁר מִתְעוֹרֶרֶת בִּי רוּחַ הַקֹּדֶשׁ, אֲשַׁחֲרֶךָּ בְּהִתְעוֹרְרוּת לַעֲשׂוֹת רְצוֹנְךְ. כִּי כַּאֲשֶׁר מִשְׁפָּטֶיךְ לָאָרֶץ, בִּזְמַן שֶׁהַמִּשְׁפָּט יוֹרֵד לָאָרֶץ לְבַשֵּׂם אֶת הָעוֹלָם, אָז צֶדֶק לָמְדוּ יֹשְׁבֵי תֵבֵל. כְּלוֹמַר, יְכוֹלִים לִסְבֹּל אֶת הַדִּין שֶׁל צֶדֶק, וְלֹא יֻשְׁמַד הָעוֹלָם מִמֶּנּוּ. מָתַי צֶדֶק לָמְדוּ יֹשְׁבֵי תֵבֵל? כַּאֲשֶׁר מִשְׁפָּטֶיךְ לָאָרֶץ. רַבִּי חִזְקִיָּה אָמַר, נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה - זוֹ כְּנֶסֶת יִשְׂרָאֵל. אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>רַבִּי אַבָּא הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן. קָם רַבִּי שִׁמְעוֹן בַּחֲצוֹת הַלַּיְלָה לַעֲסֹק בַּתּוֹרָה. קָמוּ רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא עִמּוֹ. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים מב) כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם כֵּן נַפְשִׁי תַעֲרֹג אֵלֶיךְ אֱלֹהִים. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ הַחֲבֵרִים, אַשְׁרֵיהֶם יִשְׂרָאֵל מִכָּל הָעַמִּים, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם תּוֹרָה קְדוֹשָׁה וְהוֹרִישׁ לָהֶם נְשָׁמוֹת קְדוֹשׁוֹת מִמָּקוֹם קָדוֹשׁ כְּדֵי לַעֲשׂוֹת מִצְווֹתָיו וּלְהִשְׁתַּעֲשֵׁעַ בַּתּוֹרָה. שֶׁכָּל מִי שֶׁמִּשְׁתַּעֲשֵׁעַ בַּתּוֹרָה, לֹא פוֹחֵד מִכֹּל, שֶׁכָּתוּב (תהלים קיט) לוּלֵי תוֹרָתְךְ שַׁעֲשֻׁעָי אָז אָבַדְתִּי בְעָנְיִי.</p>\n<p>מִי הֵם שַׁעֲשֻׁעָי? תּוֹרָה. שֶׁהַתּוֹרָה נִקְרֵאת שַׁעֲשׁוּעִים, שֶׁכָּתוּב (משלי ח) וָאֶהְיֶה שַׁעֲשׁוּעִים יוֹם יוֹם. וְזֶהוּ שֶׁשָּׁנִינוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן עֵדֶן. מַה זֶּה לְהִשְׁתַּעֲשֵׁעַ? כְּדֵי לִשְׂמֹחַ עִמָּהֶם, שֶׁשָּׁנִינוּ, אַשְׁרֵי הַצַּדִּיקִים, שֶׁכָּתוּב בָּהֶם (ישעיה נח) אָז תִּתְעַנַּג עַל ה', כְּדֵי לְהִתְעַנֵּג מֵאוֹתָהּ הַשְׁקָאָה שֶׁל הַנַּחַל, כְּמוֹ שֶׁנֶּאֱמַר וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ. כִּבְיָכוֹל מִשְׁתַּעֲשֵׁעַ הַקָּדוֹשׁ בָּרוּךְ הוּא בָּהֶם מֵאוֹתָהּ הַשְׁקָאַת הַנַּחַל שֶׁבָּהּ מִתְעַנְּגִים הַצַּדִּיקִים, וְעַל כֵּן בָּא לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים. וְכָל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, זוֹכֶה לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים מֵאוֹתָהּ הַשְׁקָיַת הַנַּחַל.</p>"],[9522012122,"<p>לָמַדְנוּ, כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם - זוֹ כְּנֶסֶת יִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה. תַּעֲרֹג עַל אֲפִיקֵי מָיִם, וַדַּאי כְּדֵי לְהִשָּׁקוֹת מֵהַשְׁקָיָה שֶׁל מַעַיְנוֹת הַנַּחַל עַל יְדֵי הַצַּדִּיק. תַּעֲרֹג, כְּמוֹ שֶׁנֶּאֱמַר (שיר ו) לַעֲרֻגוֹת הַבֹּשֶׂם. כֵּן נַפְשִׁי תַעֲרֹג אֵלֶיךְ אֱלֹהִים, לְקַבֵּל מִמְּךְ הַשְׁקָאָה בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>מַעַיְנוֹת הַנַּחַל מִי הֵם? מַעְיָן אֶחָד לְמַעְלָה, שֶׁכָּתוּב (בראשית ב) וְנָהָר יצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגוֹ', וּמִשָּׁם שׁוֹפֵעַ וְיוֹצֵא וּמַשְׁקֶה אֶת הַגָּן. כָּל אוֹתָם הַנְּחָלִים שׁוֹפְעִים וְיוֹצְאִים וּמִתְכַּנְּסִים לִשְׁנֵי מַעְיָנוֹת שֶׁנִּקְרָאִים נֵצַח וְהוֹד, וְאֵלּוּ נִקְרָאִים אֲפִיקֵי מַיִם, בְּאוֹתָהּ דַּרְגָּה שֶׁל צַדִּיק, שֶׁמִּמֶּנּוּ שׁוֹפֵעַ וְיוֹצֵא וְנִשְׁקָה הַגָּן. מִשּׁוּם כָּךְ אַיָּל וּצְבִי נִמְצָאִים כְּאֶחָד, (איל וצבי נקראים עטרת ויסוד) צֶדֶק וְצַדִּיק.</p>"],[9522012123,"<p>לָמַדְנוּ, כָּתוּב קוֹל ה' יְחוֹלֵל אַיָּלוֹת. אַיָּלוֹת, אַיֶּלֶת כָּתוּב חָסֵר, זוֹ אַיְלוֹת הַשָּׂדֶה (נ\"א זו אילת השחר) (ד\"א אילות השדה). אַיְלוֹת הַשָּׂדֶה, שֶׁשָּׁנִינוּ, בַּחֲצוֹת הַלַּיְלָה, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס לְגַן עֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים, הַקּוֹל הַזֶּה יוֹצֵא וּמַכְאִיב לְכָל אוֹתָן הָאַיָּלוֹת שֶׁסְּבִיב הַכִּסֵּא הַנִּכְבָּד הַקָּדוֹשׁ, זֶהוּ שֶׁכָּתוּב (שיר ג) שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ. דָּבָר אַחֵר יְחוֹלֵל אַיָּלוֹת - כְּמוֹ שֶׁנֶּאֱמַר (איובכו) חֹלְלָה יָדוֹ נָחָשׁ בָּרִחַ. וַיֶּחֱשּׁף יְעָרוֹת, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א יד) בְּיַעְרַת הַדְּבָשׁ, וְכָתוּב (שיר ה) אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי, וּמֵינִיקָה אוֹתָם כְּמוֹ אֵם שֶׁמֵּינִיקָה אֶת הַבָּנִים.</p>"],[9522012124,"<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, בְּאוֹתוֹ זְמַן בַּעֲלֵי הַמִּשְׁנָה הַלָּלוּ, בַּעֲלֵי הַחָכְמָה הָעֶלְיוֹנָה, בַּעֲלֵי קַבָּלָה, בַּעֲלֵי רָזֵי תוֹרָה, הַשָּׁעָה דְּחוּקָה לָהֶם. וְזֶהוּ שֶׁאָמַר כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם, שֶׁאוֹתָם אֲפִיקֵי מַיִם שֶׁל הַתּוֹרָה אֶל הַשְּׁכִינָה. וְאֵין תּוֹרָה אֶלָּא עַמּוּד הָאֶמְצָעִי, שֶׁיִּהְיוּ אֲפִיקֵי הַמַּיִם הַלָּלוּ בְּצַעַר, בְּיָגוֹן וּבְעֹנִי, וְאֵלּו הֵם חֲבָלִים, צִירִים שֶׁל יוֹלֵדָה, שֶׁהִיא הַשְּׁכִינָה, שֶׁבָּהּ נֶאֱמַר (משלי כג) וְתָגֵל יוֹלַדְתֶּךְ. וּבְאוֹתָם הַחֲבָלִים תִּהְיֶה בַּצַּעַר שֶׁלָּהֶם.</p>\n<p>וּבְאוֹתָם חֲבָלִים שֶׁצּוֹעֶקֶת בָּהֶם, מִתְעוֹרְרִים שִׁבְעִים סַנְהֶדְרִין שֶׁלְּמַעְלָה, עַד שֶׁיִּתְעוֹרֵר קוֹלָהּ עַד יְהֹוָ\"ה, וּמִיָּד - (תהלים כט) קוֹל ה' יְחוֹלֵל אַיָּלוֹת, שֶׁהֵם בַּעֲלֵי הַמִּשְׁנָה, בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ, לְכֻלָּם יִהְיֶה חִיל כַּיּוֹלֵדָה מַמָּשׁ בַּדְּחָקִים שֶׁהַשָּׁעָה דּוֹחֶקֶת אוֹתָם בְּכַמָּה נְשִׁיכוֹת שֶׁל יֵצֶר הָרָע, שֶׁל נָחָשׁ שֶׁנּוֹשֵׁךְ אוֹתָם בְּכַמָּה דְחָקִים.</p>\n<p>בְּאוֹתוֹ זְמַן נִפְתַּחַת לְהוֹלִיד אֶת הַמָּשִׁיחַ, מִשּׁוּם הַחֲבָלִים וְהַדְּחָקִים שֶׁל הַצַּדִּיקִים, וּבַעֲלֵי מִדּוֹת וּבַעֲלֵי רָזִים שֶׁל הַתּוֹרָה, בַּעֲלֵי בֹּשֶׁת וַעֲנָוָה, בַּעֲלֵי יִרְאָה וְאַהֲבָה, בַּעֲלֵי חֶסֶד, אַנְשֵׁי חַיִל יִרְאֵי אֱלֹהִים, אַנְשֵׁי אֱמֶת, שׂוֹנְאֵי בָצַע, שֶׁדָּחֲקָה אוֹתָם הַשָּׁעָה. וְזֶהוּ שֶׁבֵּאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה, דּוֹר שֶׁבֶּן דָּוִד בָּא, אַנְשֵׁי חַיִל יְסוֹבְבוּ מֵעִיר לְעִיר וְלֹא יְחוֹנָנוּ, וְיִרְאֵי חֵטְא יִמָּאֲסוּ, וְחָכְמַת סוֹפְרִים תִּסְרַח, וּתְהִי הָאֱמֶת נֶעְדֶּרֶת, וְהַגֶּפֶן תִּתֵּן פִּרְיָהּ, וְהַיַּיִן בְּיֹקֶר.</p>\n<p>וּמֵאוֹתָם קוֹלוֹת שֶׁהִיא נוֹתֶנֶת, שֶׁהֵם שִׁבְעִים, כְּנֶגֶד שִׁבְעִים תֵּבוֹת שֶׁל יַעַנְךְ ה' בְּיוֹם צָרָה, נִפְתַּחַת רַחְמָהּ, שֶׁהִיא שְׁתַּיִם, כְּלוּלָה מִשְּׁתֵּי בֵּיתִי\"ם, לְהוֹלִיד שְׁנֵי מְשִׁיחִים, וּמַכְנִיסָה אֶת רֹאשָׁהּ בֵּין בִּרְכֶּיהָ, שֶׁהוּא הָרֹאשׁ שֶׁלָּהּ, הָעַמּוּד הָאֶמְצָעִי. שְׁתֵּי שׁוֹקֶיהָ, נֵצַח וְהוֹד, שְׁנֵי נְבִיאִים. מִשָּׁם מוֹלִידָה שְׁנֵי מְשִׁיחִים. בְּאוֹתוֹ זְמַן וַיֶּחֱשׂף יְעָרוֹת, יָעֳבַר הַנָּחָשׁ מֵהָעוֹלָם. (עד כאן רעיא מהימנא).</p>"],[9522012125,"<p>אָמַר לוֹ רַבִּי אַבָּא, (ישעיה כו) נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ. הָיָה צָרִיךְ לִהְיוֹת נַפְשִׁי אִוְּתָךְ בַּלַּיְלָה! אֲשַׁחֲרֶךָּ?! יְשַׁחֲרֶךָּ הָיָה צָרִיךְ לִהְיוֹת! אָמַר לוֹ, הֲרֵי פֵּרְשׁוּהָ, כְּמוֹ שֶׁנֶּאֱמַר (איוב יב) אֲשֶׁר בְּיָדוֹ נֶפֶשׁ כָּל חָי וְרוּחַ כָּל בְּשַׂר אִישׁ.</p>\n<p>בֹּא רְאֵה, הַנֶּפֶשׁ וְהָרוּחַ נוֹדָעוֹת (נפגשות) (משתתפות) כְּאֶחָד לְעוֹלָמִים. לָמַדְנוּ, עֲבוֹדָה שְׁלֵמָה שֶׁצָּרִיךְ אָדָם לַעֲבֹד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁלָּמַדְנוּ וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ, שֶׁיֹּאהַב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא אַהֲבַת נֶפֶשׁ מַמָּשׁ, וְזוֹהִי אַהֲבָה שְׁלֵמָה, אַהֲבַת נַפְשׁוֹ וְרוּחוֹ. כְּמוֹ שֶׁאֵלֶּה נִדְבָּקִים בְּגוּף, וְהַגּוּף אוֹהֵב אוֹתָם, (אז) כָּךְ יִדְבַּק אָדָם לֶאֱהֹב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא אַהֲבַת נַפְשׁוֹ וְרוּחוֹ לִדְבּק בּוֹ. זֶהוּ שֶׁכָּתוּב נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה, (כלומר) נַפְשִׁי מַמָּשׁ.</p>\n<p>אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ, אֶתְדַּבֵּק בְּךְ אַהֲבָה רַבָּה בַּלַּיְלָה, שֶׁצָּרִיךְ אָדָם מֵאַהֲבָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲמֹד בְּכָל לַיְלָה לְהִשְׁתַּדֵּל בַּעֲבוֹדָתוֹ עַד שֶׁיִּתְעוֹרֵר הַבֹּקֶר, וְיִמָּשֵׁךְ עָלָיו חוּט שֶׁל חֶסֶד. שֶׁשָּׁנִינוּ, אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ אָדָם שֶׁאוֹהֵב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא אַהֲבָה כָּזוֹ, וְצַדִּיקֵי הָאֱמֶת הַלָּלוּ שֶׁאוֹהֲבִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא כָּךְ, הָעוֹלָם מִתְקַיֵּם בַּעֲבוּרָם, וְשׁוֹלְטִים עַל כָּל הַגְּזֵרוֹת הַקָּשׁוֹת שֶׁלְּמַעְלָה וּלְמַטָּה. (היא) (כדי שיתקים העולם בעבורם).</p>\n<p>לָמַדְנוּ, אוֹתוֹ צַדִּיק שֶׁנִּדְבָּק בְּרוּחוֹ וְנַפְשׁוֹ לְמַעְלָה בַּמֶּלֶךְ הַקָּדוֹשׁ בְּאַהֲבָה כָּרָאוּי, שׁוֹלֵט בָּאָרֶץ שֶׁלְּמַטָּה, וְכָל מַה שֶּׁגּוֹזֵר עַל הָעוֹלָם מִתְקַיֵּם. מִנַּיִן לָנוּ? מֵאֵלִיָּהוּ, שֶׁכָּתוּב (מלכים א יז) חַי ה' אֲשֶׁר עָמַדְתִּי לְפָנָיו אִם יִהְיֶה הַשָּׁנִים הָאֵלֶּה טַל וּמָטָר כִּי אִם לְפִי דְבָרִי.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁבָּאוֹת הַנְּשָׁמוֹת הַקְּדוֹשׁוֹת מִמַּעְלָה לְמַטָּה, וְאוֹתָם צַדִּיקֵי הָעוֹלָם שׁוֹלְפִים אוֹתָם מֵהַמֶּלֶךְ וּמֵהַגְּבִירָה, מְעַטִּים הֵם. שֶׁבְּאוֹתָהּ שָׁעָה שֶׁיּוֹרֶדֶת, עוֹמֶדֶת לִפְנֵי הַמֶּלֶךְ, וּרְצוֹנוֹ שֶׁל הַמֶּלֶךְ לְהִתְבּוֹנֵן בָּהּ, כְּמוֹ שֶׁבֵּאַרְנוּ, בְּשָׁעָה שֶׁנּוֹשֵׁב הַקָּדוֹשׁ בָּרוּךְ הוּא רוּחַ בְּכָל חַיִל וְחַיִל שֶׁל הַשָּׁמַיִם, כָּל הַחֲיָלוֹת נַעֲשִׂים, וְעוֹמְדִים בִּמְקוֹמָם. זֶהוּ שֶׁכָּתוּב וּבְרוּחַ פִּיו כָּל צְבָאָם. וּמֵהֶן מִתְעַכְּבוֹת עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹרִיד אוֹתָן לְמַטָּה.</p>\n<p>וְלָמַדְנוּ, מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם הֵן עוֹמְדוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִתְעַכְּבוֹת עַד שֶׁמַּגִּיעַ הַזְּמַן לְהוֹרִיד אוֹתָן לָאָרֶץ, וְאֵלּוּ שׁוֹלְטוֹת לְמַעְלָה וּלְמַטָּה. זֶהוּ שֶׁכָּתוּב חַי ה' אֲשֶׁר עָמַדְתִּי לְפָנָיו. אֲשֶׁר אֲנִי עוֹמֵד לֹא כָתוּב, אֶלָּא אֲשֶׁר עָמַדְתִּי. אַחַר כָּךְ חוֹזֶרֶת לִמְקוֹמָהּ וְנִכְנֶסֶת לְחַדְרָהּ, וְאוֹתָן אֲחֵרוֹת לֹא עוֹלוֹת עַד שֶׁיָּמוּתוּ, כִּי לֹא עָמְדוּ קֹדֶם כְּאוֹתָן הָאֲחֵרוֹת. וּמִשּׁוּם כָּךְ אֵלִיָּהוּ נַעֲשָׂה שָׁלִיחַ, מַלְאָךְ לְמַעְלָה, וְאֵלּו שֶׁמִּתְדַּבְּקִים יוֹתֵר לַמֶּלֶךְ.</p>\n<p>מָצָאנוּ בְּסִפְרוֹ שֶׁל אָדָם הָרִאשׁוֹן, שֶׁכָּל הָרוּחוֹת הַקְּדוֹשׁוֹת שֶׁלְּמַעְלָה עוֹשׂוֹת שְׁלִיחוּת, וְכֻלָּן בָּאוֹת מִמָּקוֹם אֶחָד. שֶׁנִּשְׁמוֹתֵיהֶם שֶׁל הַצַּדִּיקִים הֵן מִשְּׁתֵּי דְרָגוֹת שֶׁכְּלוּלוֹת בְּאַחַת, וּמִשּׁוּם כָּךְ עוֹלוֹת יוֹתֵר, וְדַרְגָּתָן יְתֵרָה, וְכָךְ זֶה. וְכָל אוֹתָן שֶׁהָיוּ טְמוּנוֹת שָׁם, יָרְדוּ וְעָלוּ בְחַיֵּיהֶן, כְּמוֹ חֲנוֹךְ שֶׁלֹּא נִמְצְאָה בּוֹ מִיתָה. וַהֲרֵי בֵּאַרְנוּ הַדָּבָר הַזֶּה בַּחֲנוֹךְ וְאֵלִיָּהוּ.</p>\n<p>וְלָמַדְנוּ, מֵאָה וְעֶשְׂרִים וַחֲמִשָּׁה אֶלֶף דְּרָגוֹת (לצדיקים) הֵן לְנִשְׁמוֹת הַצַּדִּיקִים שֶׁעָלוּ בְרָצוֹן בְּטֶרֶם שֶׁנִּבְרָא הָעוֹלָם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְזַמֵּן אוֹתָן לָעוֹלָם הַזֶּה בְּכָל דּוֹר וָדוֹר, וְעוֹלוֹת וְטָסוֹת בָּעוֹלָם, וְנִקְשָׁרוֹת לִצְרוֹר הַחַיִּים. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְחַדֵּשׁ בָּהֶן אֶת הָעוֹלָם. עֲלֵיהֶם כָּתוּב (ישעיה סו) כִּי כַאֲשֶׁר הַשָּׁמַיִם הַחֲדָשִׁים וְהָאָרֶץ הַחֲדָשָׁה וְגוֹ'.</p>\n<p>תְּעַנּוּ אֶת נַפְשּתֵיכֶם, נַפְשֹׁתֵיכֶם הוּא אָמַר, כִּי יִשְׂרָאֵל נִמְצָאִים צַדִּיקִים לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְיִהֶיה הָרָצוֹן שֶׁלָּהֶם אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהִדָּבֵק בּוֹ כְּדֵי שֶׁיִּתְכַּפֵּר לָהֶם חֶטְאָם. וְלָכֵן, מִי שֶׁאוֹכֵל וְשׁוֹתֶה בַּתְּשִׁיעִי וּמְעַנֵּג אֶת נַפְשׁוֹ בְּמַאֲכָל וּבְמִשְׁתֶּה, נִמְצָא בַּעֲשִׂירִי עִנּוּי נֶפֶשׁ בִּשְׁנֵי חֲלָקִים, וְנִמְצָא כְּאִלּוּ הִתְעַנָּה תְשִׁיעִי וַעֲשִׂירִי. אֶת נַפְשֹׁתֵיכֶם - לְהַכְלִיל אֶת הַכֹּל, גּוּף וָנֶפֶשׁ, וּלְהִכָּנַע בַּיּוֹם הַזֶּה, כְּדֵי לְכַפֵּר עַל חֶטְאָם.</p>\n<p>לָמַדְנוּ, כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם. בַּיּוֹם הַזֶּה?! הַיּוֹם הַזֶּה הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא בַּיּוֹם הַזֶּה דַּוְקָא, שֶׁבּוֹ מִתְגַּלֶּה הָעַתִּיק הַקָּדוֹשׁ לְכַפֵּר עַל חֲטָאֵי כֻּלָּם.</p>"],[9522012126,"<p>דָּבָר אַחֵר תְּעַנּוּ אֶת נַפְשּתֵיכֶם - רַבִּי אַבָּא פָּתַח וְאָמַר, (קהלת ט) עִיר קְטַנָּה וַאֲנָשִׁים בָּהּ מְעָט וְגוֹ'. עִיר קְטַנָּה, הֲרֵי פֵּרְשׁוּהָ. אֲבָל עִיר קְטַנָּה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כו) עִיר עָז לָנוּ יְשׁוּעָה יָשִׁית חוֹמוֹת וָחֵל וְגוֹ'. וְכָתוּב (הושע יא) וְלֹא אָבוֹא בְּעִיר. עִיר קְטַנָּה, קְטַנָּה הִיא, שֶׁהִיא אַחֲרוֹנָה מֵהַכֹּל וְתַחְתּוֹנָה מֵהַכֹּל. חוֹמוֹתֶיהָ גְּדוֹלוֹת, חֲזָקוֹת, קְדוֹשׁוֹת, נִקְרֵאת עִיר הַקֹּדֶשׁ. וַאֲנָשִׁים בָּהּ מְעָט, מְעַטִּים אוֹתָם שֶׁזּוֹכִים לִכָּנֵס לְתוֹכָהּ וְלִשְׁרוֹת בָּהּ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים כד) מִי יַעֲלֶה בְהַר ה' וּמִי יָקוּם בִּמְקוֹם קָדְשׁוֹ וְגוֹ'. וְעַל זֶה אֲנָשִׁים בָּהּ מְעָט.</p>\n<p>וּבָא אֵלֶיהָ מֶלֶךְ גָּדוֹל - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, לְהִזְדַּוֵּג עִמָּהּ וְלִשְׁרוֹת בָּהּ. וְסָבַב אֹתָהּ, כְּמוֹ שֶׁנֶּאֱמַר (זכריה ב) וַאֲנִי אֶהְיֶה לָּהּ נְאֻם ה' חוֹמַת אֵשׁ סָבִיב וְגוֹ'. וּבָנָה עָלֶיהָ מְצוֹדִים גְּדלִים, שֶׁבָּנָה חוֹמוֹתֶיהָ גְּדוֹלִים וַחֲזָקִים, נָאִים וְיָפִים (מכל אבנים יקרות) וּקְדוֹשִׁים. וְנִקְרֵאת עִיר הַקֹּדֶשׁ, וְאֶת כָּל כְּבוֹד הַמֶּלֶךְ הִכְנִיס לְתוֹכָהּ. וּמִשּׁוּם כָּךְ הִיא לְבַדָּהּ כְּלוּלָה מִכָּל עַטְרוֹת הַמֶּלֶךְ, וְכָל עַטְרוֹת הַמֶּלֶךְ מִתְעַטְּרִים בָּהּ. מִשּׁוּם כָּךְ כָּתוּב, וַאֲנָשִׁים בָּהּ מְעָט.</p>\n<p>וּמָצָא בָהּ אִישׁ מִסְכֵּן (ו) חָכָם, זֶהוּ שֶׁכָּתוּב נְקִי כַפַּיִם וּבַר לֵבָב. מִסְכֵּן, כְּמוֹ שֶׁנֶּאֱמַר (שמות א) וַיִּבֶן עָרֵי מִסְכְּנוֹת לְפַרְעֹה. מִתְעַטֵּר בַּעֲטָרוֹת חֲזָקוֹת, בְּעַטְרוֹת הַתּוֹרָה, בַּעֲטָרוֹת שֶׁל מִצְווֹת תּוֹרַת הַמֶּלֶךְ. וְחָכָם, שֶׁזּוֹכֶה בָּהּ בַּחָכְמָה הַזֹּאת. וְחָכָם, שֶׁהוּא יוֹתֵר חָכָם מִכֻּלָּם לְעַיֵּן בַּעֲבוֹדַת רִבּוֹנוֹ כְּדֵי לִזְכּוֹת בָּהּ וּלְהִכָּנֵס אֵלֶיהָ. זֶהוּ שֶׁכָּתוּב וּמִלַּט הוּא אֶת הָעִיר בְּחָכְמָתוֹ. וּמִלַּט, כְּמוֹ (שמואל א כ) אִמָּלְטָה נָּא וְאֶרְאֶה אֶת אֶחָי, אִמָּלְטָה נָּא שָׁמָּה. אַף כָּאן, וּמִלַּט הוּא אֶת הָעִיר בְּחָכְמָתוֹ.</p>\n<p>וְאָדָם לֹא זָכַר אֶת הָאִישׁ הַמִּסְכֵּן הַהוּא. וְאָדָם לֹא זָכַר, לַעֲשׂוֹת מִצְווֹת הַתּוֹרָה, לְהִשְׁתַּדֵּל בַּתּוֹרָה כְּאוֹתוֹ אִישׁ עָנִי שֶׁהִתְחַבֵּר בַּכֹּל כְּדֵי לִזְכּוֹת בָּהּ. (קהלת ט) וְאָמַרְתִּי אָנִי טוֹבָה חָכְמָה מִגְּבוּרָה. שֶׁהֲרֵי בְּאוֹתוֹ עוֹלָם לֹא נוֹתְנִים רְשׁוּת לְהִכָּנֵס, פְּרָט לְאוֹתָם צַדִּיקֵי אֱמֶת, אֵלּוּ שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה יָמִים וְלֵילוֹת, וּמִתְעַטְּרִים בְּמִצְווֹת הַתּוֹרָה בָּעוֹלָם הַזֶּה לְהִכָּנֵס בָּהֶם לָעוֹלָם הַבָּא.</p>\n<p>וְחָכְמַת הַמִּסְכֵּן בְּזוּיָה וּדְבָרָיו אֵינָם נִשְׁמָעִים. שֶׁהֲרֵי בְּנֵי אָדָם אֵינָם מִסְתַּכְּלִים עָלָיו, וְלֹא רוֹצִים לְהִתְחַבֵּר עִמּוֹ וּלְהַקְשִׁיב לִדְבָרָיו. שֶׁלָּמַדְנוּ, כָּל מִי שֶׁמַּקְשִׁיב לְדִבְרֵי הַתּוֹרָה, אַשְׁרָיו בָּעוֹלָם הַזֶּה, וּכְאִלּוּ קִבֵּל תּוֹרָה מִסִּינַי. וַאֲפִלּוּ מִכָּל אָדָם גַּם כֵּן צָרִיךְ לִשְׁמֹעַ דִּבְרֵי תוֹרָה. וּמִי שֶׁמַּרְכִּין אָזְנָיו כְּנֶגְדּוֹ, נוֹתֵן כָּבוֹד לַמֶּלֶךְ הַקָּדוֹשׁ וְנוֹתֵן כָּבוֹד לַתּוֹרָה. עָלָיו כָּתוּב, הַיּוֹם הַזֶּה נִהְיֵיתָ לְעָם לַה' אֱלֹהֶיךְ.</p>"],[9522012127,"<p>לָמַדְנוּ, יוֹם אֶחָד הָיוּ הוֹלְכִים הַחֲבֵרִים עִם רַבִּי שִׁמְעוֹן. אָמַר רַבִּי שִׁמְעוֹן, רָאִיתִי שֶׁהָעַמִּים הַלָּלוּ כֻּלָּם עֶלְיוֹנִים, וְיִשְׂרָאֵל תַּחְתּוֹנִים מִכֻּלָּם. מָה הַטַּעַם? מִשּׁוּם שֶׁהַמֶּלֶךְ שָׁלַח מִמֶּנּוּ אֶת הַגְּבִירָה, וְהִכְנִיס אָמָה בִּמְקוֹמָהּ (כלומר שפחה), כְּמוֹ שֶׁנֶּאֱמַר, (משלי ל) תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ וְגוֹ'. תַּחַת עֶבֶד כִּי יִמְלוֹךְ וְגוֹ'. וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ. מִי הַשִּׁפְחָה? זוֹהִי כֶּתֶר הַנָּכְרִי, שֶׁהָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא הַבְּכוֹר שֶׁלָּהֶם בְּמִצְרַיִם, שֶׁכָּתוּב (שמות יא) עַד בְּכוֹר הַשִּׁפְחָה אֲשֶׁר אַחַר הָרֵחָיִם. אַחַר הָרֵחָיִם הִיא הָיְתָה יוֹשֶׁבֶת בָּרִאשׁוֹנָה, וְעַכְשָׁו הַשִּׁפְחָה הַזּוֹ תִּירַשׁ גְּבִרְתָּהּ.</p>\n<p>בָּכָה רַבִּי שִׁמְעוֹן וְאָמַר, מֶלֶךְ בְּלִי גְבִירָה לֹא נִקְרָא מֶלֶךְ. מֶלֶךְ שֶׁנִּדְבָּק בַּשִּׁפְחָה, בָּאָמָה (שלה) שֶׁל הַגְּבִירָה, אֵיפֹה כְבוֹדוֹ? וְעָתִיד קוֹל לְבַשֵּׂר לַגְּבִירָה וְלוֹמַר: (זכריה ט) גִּילִי מְאֹד בַּת צִיּוֹן הָרִיעִי בַּת יְרוּשָׁלם הִנֵּה מַלְכֵּךְ יָבוֹא לָךְ צַדִּיק וְנוֹשָׁע הוּא. כְּלוֹמַר, צַדִּיק הוּא נוֹשָׁע, כִּי הָיָה רוֹכֵב עַד עַכְשָׁו בְּמָקוֹם שֶׁאֵינוֹ שֶׁלּוֹ, בִּמְקוֹם נָכְרִי, וּמֵינִיק אוֹתוֹ.</p>\n<p>וְעַל זֶה כָּתוּב עָנִי וְרֹכֵב עַל חֲמוֹר. עָנִי (שלא) הָיָה בָּרִאשׁוֹנָה, וְרֹכֵב עַל חֲמוֹר, כְּמוֹ שֶׁבֵּאַרְנוּ, אוֹתָם כְּתָרִים תַּחְתוֹנִים שֶׁל עַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁהָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַבְּכוֹר שֶׁלָּהֶם בְּמִצְרַיִם. זֶהוּ שֶׁכָּתוּב (שמות יא) וְכָל בְּכוֹר בְּהֵמָה, וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים. כִּבְיָכוֹל צַדִּיק וְנוֹשָׁע הוּא, הוּא וַדַּאי יוֹתֵר מֵהַכֹּל. כִּי עַד עַכְשָׁו שָׁרוּי צַדִּיק בְּלִי צֶדֶק. וְעַכְשָׁו שֶׁיִּזְדַּוְּגוּ כְאֶחָד, צַדִּיק וְנוֹשָׁע הוּא, שֶׁהֲרֵי אֵינוֹ יוֹשֵׁב בַּצַּד הָאַחֵר. לָמַדְנוּ, (ישעיה נז) הַצַּדִּיק אָבָד וְאֵין אִישׁ שָׂם עַל לֵב וְגוֹ'. פָּסוּק זֶה קָשֶׁה. הַצַּדִּיק אָבָד?! נֶאֱבַד הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אָבָד? אֶלָּא אָבַד מַמָּשׁ. וּמָה אָבַד? אָבַד לַגְּבִירָה, וְנִדְבַּק בְּמָקוֹם אַחֵר, שֶׁנִּקְרָא שִׁפְחָה.</p>\n<p>אָמַר רַבִּי יִצְחָק לְרַבִּי שִׁמְעוֹן, אִם נוֹחַ לִפְנֵי מוֹרִי, זֶה שֶׁשָּׁנִינוּ שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם, יֵשׁ מִי שֶׁאוֹמֵר שֶׁעַל שִׁבְעָה עַמּוּדִים עוֹמֵד הָעוֹלָם, וְיֵשׁ מִי שֶׁאוֹמֵר עַל עַמּוּד אֶחָד עוֹמֵד הָעוֹלָם, אֵיךְ הַדְּבָרִים מִתְיַשְּׁבִים? אָמַר לוֹ, הַכֹּל הוּא דָּבָר אֶחָד, שֶׁהֲרֵי שִׁבְעָה הֵם, וּבָהֶם יֵשׁ עַמּוּד אֶחָד שֶׁנִּקְרָא צַדִּיק, וְעוֹמְדִים עָלָיו, וְהָעוֹלָם מִתְקַיֵּם עַל זֶה. וּכְשֶׁהָעוֹלָם מִתְקַיֵּם עָלָיו, כְּאִלּוּ שֶׁהִתְקַיֵּם עַל כָּל הַשִּׁבְעָה, וְעַל כֵּן כָּתוּב וְצַדִּיק יְסוֹד עוֹלָם, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים בְּכַמָּה מְקוֹמוֹת.</p>\n<p>וְלָמַדְנוּ, הַשִּׁפְחָה הַזּוֹ עֲתִידָה לִשְׁלֹט בָּאָרֶץ הַקְּדוֹשָׁה שֶׁלְּמַטָּה, כְּמוֹ שֶׁהָיְתָה הַגְּבִירָה שׁוֹלֶטֶת בָּרִאשׁוֹנָה, שֶׁכָּתוּב צֶדֶק יָלִין בָּהּ, וְעַכְשָׁו שִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ, בַּכֹּל. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָשִׁיב אֶת הַגְּבִירָה לִמְקוֹמָהּ כְּבָרִאשׁוֹנָה, וְאָז שֶׁל מִי הִיא הַשִּׂמְחָה? הֱוֵי אוֹמֵר, שִׂמְחַת הַמֶּלֶךְ וְשִׂמְחַת הַגְּבִירָה. שִׂמְחַת הַמֶּלֶךְ, מִשּׁוּם שֶׁיָּשִׁיב אוֹתָהּ וְיִפָּרֵד מִן הַשִּׁפְחָה כְּפִי שֶׁאָמַרְנוּ. וְשִׂמְחַת הַגְּבִירָה, כִּי תָשׁוּב לְהִזְדַּוֵּג עִם הַמֶּלֶךְ. זֶהוּ שֶׁכָּתוּב גִּילִי מְאֹד בַּת צִיּוֹן וְגוֹ'.</p>\n<p>בֹּא רְאֵה, כָּתוּב וְהָיְתָה זֹּאת לָכֶם לְחֻקַּת עוֹלָם. וְהָיְתָה לָכֶם הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה זֹּאת? זֶה שֶׁאָמַרְנוּ, לְחֻקַּת עוֹלָם. בְּכָל מָקוֹם וּמָקוֹם חֻקַּת עוֹלָם נִקְרֵאת, גְּזֵרַת הַמֶּלֶךְ, שֶׁמַּכְנִיס אֶת כָּל הַנְהָגוֹתָיו בַּמָּקוֹם הַזֶּה וּמַסְתִּיר אוֹתָם, כְּמוֹ שֶׁמַּסְתִּיר הַכֹּל בְּאוֹצָר אֶחָד. חֻקַּת עוֹלָם וַדַּאי. בָּזֹּאת הַזּוֹ רָשַׁם וְחָקַק אֶת כָּל הַגְּנָזִים שֶׁלּוֹ וְאֶת כָּל הַמַּטְמוֹנִים שֶׁלּוֹ.</p>"],[9522012128,"<p>בַּחֹדֶשׁ הַשְּׁבִיעִי בֶּעָשׂוֹר לַחֹדֶשׁ. בֶּעָשׂוֹר בְּדִיִּוּק, כְּמוֹ שֶׁבֵּאַרְנוּ. תְּעַנּוּ אֶת נַפְשתֵיכֶם, וַדַּאי כָּךְ זֶה, וַהֲרֵי נֶאֱמַר נַפְשּתֵיכֶם וַדַּאי. שֶׁהֲרֵי בַּנֶּפֶשׁ תָּלוּי הַדָּבָר, וּמִשּׁוּם כָּךְ אֲכִילָה וּשְׁתִיָּה מֵהַתְּשִׁיעִי יוֹתֵר מִיּוֹם אַחֵר. וְאַף עַל גַּב שֶׁהַדָּבָר הַזֶּה נֶאֱמַר בְּגָוֶן אַחֵר, וְהַכֹּל יָפֶה, וְזֶה וָזֶה דָּבָר אֶחָד, וְכָל אֶחָד בִּמְקוֹמוֹ, וְכָךְ זֶה.</p>\n<p>וְלָמַדְנוּ, בַּיּוֹם הַזֶּה כָּל הַשִּׂמְחָה וְכָל הָאוֹר וְכָל הַסְּלִיחָה שֶׁל הָעוֹלָמוֹת, כֻּלָּם תְּלוּיִים בָּאֵם הָעֶלְיוֹנָה, שֶׁכָּל הַמַּעְיָנוֹת שׁוֹפְעִים וְיוֹצְאִים מִמֶּנָּה, וְאָז מְאִירִים כָּל אוֹתָם מְאוֹרוֹת, וּמְאִירִים בְּאוֹר וּבְשִׂמְחָה, עַד שֶׁהַכֹּל מִתְבַּשֵּׂם. וְאָז כָּל אוֹתָם הַדִּינִים נִמְצָאִים בְּאוֹר, וְהַדִּין לֹא נַעֲשֶׂה, וְעַל כֵּן תְּעַנּוּ אֶת נַפְשֹׁתֵיכֶם.</p>\n<p>אָמַר רַבִּי אַבָּא, הֲרֵי מוֹרֵנוּ בֵּאֵר אוֹתָהּ מִגּוּף הַמִּשְׁנָה - לֹא גָלוּ יִשְׂרָאֵל מֵאַרְצָם עַד שֶׁכָּפְרוּ בַּקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (שמואל ב כ) אֵין לָנוּ חֵלֶק בְּדָוִד וְלֹא נַחֲלָה (לנו) בְּבֶן יִשַׁי, וַהֲרֵי נֶאֱמַר. פָּסוּק אַחֵר מָצָאנוּ עַל זֶה, שֶׁכָּתוּב (מלכים א יא) רְאֵה בֵיתְךְ דָּוִד. אָמַר לוֹ, כָּךְ זֶה וַדַּאי, בֵּית דָּוִד נִקְרָא, כְּמוֹ שֶׁכָּתוּב (ישעיה ה) בֵּית יַעֲקֹב לְכוּ וְנֵלְכָה בְּאוֹר ה'. בֵּית יַעֲקֹב, כְּמוֹ שֶׁנֶּאֱמַר (שם ס) וּבֵית תִּפְאַרְתִּי אֲפָאֵר. לְכוּ וְנֵלְכָה בְּאוֹר ה', שֶׁכָּתוּב וְנָהָר יצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן, וְנָטַע אֶת הַגָּן הַזֶּה לְהִשְׁתַּעֲשֵׁעַ בּוֹ עִם הַצַּדִּיקִים, שֶׁבּוֹ הֵם שְׁרוּיִים.</p>\n<p>לָמַדְנוּ, כָּתוּב אַךְ בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה יוֹם הַכִּפֻּרִים הוּא וְגוֹ' וְעִנִּיתֶם אֶת נַפְשֹׁתֵיכֶם. וְכָתוּב וְהָיְתָה לָכֶם לְחֻקַּת עוֹלָם בַּחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ'. מַה שֶּׁכָּתוּב אַךְ, מַה הוּא רוֹצֶה כָּאן? אָמַר לוֹ, זֶה בָּא לְמַעֵט, שֶׁכֵּיוָן שֶׁאָמַר וְעִנִּיתֶם אֶת נַפְשּתֵיכֶם בְּתִשְׁעָה לַחֹדֶשׁ, אָמַר (אחר כך) אַךְ בֶּעָשׂוֹר, וְהָיָה צָרִיךְ לִהְיוֹת אַךְ עָשׂוֹר! שֶׁבֶּעָשׂוֹר הַדָּבָר תָּלוּי.</p>\n<p>אָמַר לוֹ, אִם כָּךְ, (שמות יב) אַךְ בַּיּוֹם הָרִאשׁוֹן תַּשְׁבִּיתוּ שְּׂאֹר מִבָּתֵיכֶם, וְשָׁנִינוּ אַךְ - חִלֵּק, חֶצְיוֹ אָסוּר בַּאֲכִילַת חָמֵץ וְחֶצְיוֹ מֻתָּר. אַף כָּאן אַךְ בֶּעָשׂוֹר לַחֹדֶשׁ, אֱמֹר שֶׁחֶצְיוֹ אָסוּר בִּמְלָאכָה (באכילה) וְחֶצְיוֹ מֻתָּר. אָמַר לוֹ, אַף כָּאן בִּוְעִנִּיתֶם אֶת נַפְשֹׁתֵיכֶם זֶה תָּלוּי, שֶׁהֲרֵי עִנּוּי לֹא נִמְצָא אֶלָּא מֵחֲצוֹת הַיּוֹם וְאֵילָךְ, וְיָפֶה הוּא אַךְ חִלֵּק בִּוְעִנִּיתֶם אֶת נַפְשּתֵיכֶם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, כָּתוּב כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם וְגוֹ'. אֲכַפֵּר עֲלֵיכֶם הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא יְכַפֵּר עֲלֵיכֶם - לְהַכְלִיל אֶת הַיּוֹבֵל שֶׁשּׁוֹפֵעַ מַעְיָנוֹת לְהַשְׁקוֹת בַּיּוֹם הַזֶּה לְכָל עֵבֶר לְרַוּוֹת אֶת הַכֹּל וּלְהַשְׁקוֹת אֶת הַכֹּל. וְזֶה עֲלֵיכֶם, כְּלוֹמַר עֲבוּרְכֶם, לְטַהֶרְכֶם בַּיּוֹם הַזֶּה, שֶׁכָּתוּב לִפְנֵי ה' תִּטְהָרוּ, וְלֹא יִשְׁלֹט עֲלֵיכֶם הַדִּין.</p>\n<p>רַבִּי יְהוּדָה אָמַר, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָּהֶם וְרוֹצֶה לְטַהֵר אוֹתָם שֶׁלֹּא יִמָּצֵא בָהֶם חֵטְא, כְּדֵי שֶׁיִּהְיוּ בְּנֵי הֵיכָלוֹ וְיָדוּרוּ בְהֵיכָלוֹ. וְלֶעָתִיד לָבא כָּתוּב, (יחזקאל לו) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וְגוֹ'.</p>"],[9522012129,"<p>רַבִּי יְהוּדָה פָּתַח, (תהלים קל) שִׁיר הַמַּעֲלוֹת מִמַּעֲמַקִּים קְרָאתִיךְ ה'. שָׁנִינוּ, בְּשָׁעָה שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, רָצָה לִבְרֹא אָדָם. נִמְלַךְ בַּתּוֹרָה. אָמְרָה לְפָנָיו: תִּרְצֶה לִבְרֹא הָאָדָם הַזֶּה?! עָתִיד הוּא לַחֲטֹא לְפָנֶיךְ וְעָתִיד הוּא לְהַרְגִּיז לְפָנֶיךְ. אִם תַּעֲשֶׂה לוֹ כְמַעֲשָׂיו, הֲרֵי הָעוֹלָם לֹא יוּכַל לַעֲמֹד לְפָנֶיךְ, כָּל שֶׁכֵּן אוֹתוֹ הָאִישׁ. אָמַר לָהּ: וְכִי לְחִנָּם נִקְרֵאתִי (שמות לד) אֵל רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם?</p>\n<p>וְטֶרֶם שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, בָּרָא תְשׁוּבָה. אָמַר לָהּ לַתְּשׁוּבָה: אֲנִי רוֹצֶה לִבְרֹא אָדָם בָּעוֹלָם, עַל מְנָת שֶׁכְּשֶׁיָּשׁוּבוּ לָךְ מֵחֲטָאֵיהֶם, שֶׁתִּהְיִי עֲתִידָה לַעֲזֹּב אֶת חֲטָאֵיהֶם וּלְכַפֵּר עֲלֵיהֶם. וּבְכָל שָׁעָה וְשָׁעָה הַתְּשׁוּבָה זְמִינָה לָאֲנָשִׁים, וּכְשֶׁאֲנָשִׁים שָׁבִים מֵחֲטָאֵיהֶם, הַתְּשׁוּבָה הַזּוֹ שָׁבָה לַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא מְכַפֵּר עַל הַכֹּל, וְהַדִּינִים נִכְנָעִים, וְכֻלָּם מִתְבַּשְּׂמִים, וְאָדָם נִטְהָר מֵחֶטְאוֹ.</p>\n<p>מָתַי נִטְהָר אָדָם מֵחֶטְאוֹ? בְּשָׁעָה שֶׁנִּכְנָס לַתְּשׁוּבָה הַזּוֹ כָּרָאוּי. רַבִּי יִצְחָק אָמַר, שֶׁשָּׁב לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן וּמִתְפַּלֵּל תְּפִלָּה מֵעֹמֶק הַלֵּב. זֶהוּ שֶׁכָּתוּב מִמַּעֲמַקִּים קְרָאתִיךְ ה'.</p>\n<p>רַבִּי אַבָּא אָמַר, מִמַּעֲמַקִּים קְרָאתִיךְ ה', מָקוֹם גָּנוּז הוּא לְמַעְלָה, וְהוּא עֹמֶק הַבְּאֵר, וּמִזֶּה יוֹצְאִים נְחָלִים וּמַעְיָנוֹת לְכָל עֵבֶר, וְאוֹתוֹ עֹמֶק הָעֳמָקִים נִקְרָא תְשׁוּבָה. וּמִי שֶׁרוֹצֶה לָשׁוּב וּלְהִטָּהֵר מֵחֲטָאָיו, מֵהָעֹמֶק הַזֶּה הוּא צָרִיךְ לִקְרֹא לַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב מִמַּעֲמַקִּים קְרָאתִיךְ ה'.</p>\n<p>לָמַדְנוּ, בְּשָׁעָה שֶׁהָיָה אָדָם חוֹטֵא לִפְנֵי רִבּוֹנוֹ וּמַקְרִיב קָרְבָּנוֹ עַל הַמִּזְבֵּחַ, וְהַכֹּהֵן מְכַפֵּר עָלָיו וּמְבַקֵּשׁ בַּקָּשָׁתוֹ עָלָיו, מִתְעוֹרְרִים רַחֲמִים, וְהַדִּינִים מִתְבַּשְּׂמִים, וְהַתְּשׁוּבָה מְרִיקָה בְרָכוֹת בְּמַעְיָנוֹת שֶׁשּׁוֹפְעִים וְיוֹצְאִים, וְכָל הַמְּאוֹרוֹת מִתְבָּרְכִים כְּאֶחָד, וְהָאָדָם נִטְהָר מֵחֶטְאוֹ.</p>\n<p>בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹצִיא עֲשָׂרָה כְתָרִים, עֲטָרוֹת קְדוֹשׁוֹת לְמַעְלָה, שֶׁהִתְעַטֵּר בָּהֶם וּמִתְלַבֵּשׁ בָּהֶם, וְהוּא זֶה הֵם, וְהֵם זֶה הוּא, כְּשַׁלְהֶבֶת הָאֲחוּזָה בְּגַחֶלֶת, וְאֵין שָׁם פֵּרוּד. כְּנֶגֶד זֶה יֵשׁ עֲשָׂרָה כְתָרִים שֶׁאֵינָם קְדוֹשִׁים לְמַטָּה, וְהֵם אֲחוּזִים בְּזֻהֲמַת הַצִּפֹּרֶן שֶׁל עֲטָרָה קְדוֹשָׁה שֶׁנִּקְרֵאת חָכְמָה, וְעַל כֵּן נִקְרְאוּ חָכְמוֹת.</p>"],[9522012130,"<p>וְלָמַדְנוּ, עֲשֶׂרֶת מִינֵי הַחָכְמוֹת הַלָּלוּ יָרְדוּ לָעוֹלָם, וְכֻלָּם נִטְמְאוּ (נשאבו) בְמִצְרַיִם, פְּרָט לְאֶחָד שֶׁהִתְפַּשֵּׁט בָּעוֹלָם, וְכֻלָּם הֵם מִינֵי כְשָׁפִים, וּמֵהֶם יָדְעוּ הַמִּצְרִים כְּשָׁפִים עַל כָּל בְּנֵי הָעוֹלָם. וּכְשֶׁהַמִּצְרִים רָצוּ לַעֲשׂוֹת כִּנּוּס בְּכִשְׁפֵיהֶם לְמַעֲשֵׂיהֶם, הָיוּ יוֹצְאִים לַשָּׂדֶה לֶהָרִים הַגְּבוֹהִים, וְזוֹבְחִים זְבָחִים, וְעוֹשִׂים גֻּמּוֹת בָּאָרֶץ, וּמְסוֹבְבִים אוֹתוֹ הַדָּם סְבִיב הַגֻּמּוֹת הַלָּלוּ, וּשְׁאָר הַדָּם מְכַנְּסִים בַּגֻּמּוֹת הַלָּלוּ, וְשָׂמִים עֲלֵיהֶם בָּשָׂר, וּמַקְרִיבִים אֶת קָרְבְּנוֹתֵיהֶם לְאוֹתָם הַמִּינִים הָרָעִים, וְאוֹתָם הַמִּינִים הָרָעִים מִתְכַּנְּסִים וּמִתְקָרְבִים כְּאֶחָד, וּמִתְפַּיְּסִים עִמָּם בְּאוֹתוֹ הָהָר.</p>\n<p>יִשְׂרָאֵל שֶׁהָיוּ מְשֻׁעְבָּדִים לָהֶם, הָיוּ מִתְקָרְבִים לָהֶם, וְלָמְדוּ מֵהֶם, וְהָיוּ טוֹעִים אַחֲרֵיהֶם. וְהַיְנוּ מַה שֶּׁכָּתוּב, כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם אֲשֶׁר יְשַׁבְתֶּם בָּהּ לֹא תַעֲשׂוּ וּכְמַעֲשֵׂה אֶרֶץ כְּנַעַן וְגוֹ'. וְכָתוּב וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם לַשְּׂעִירִים וְגוֹ'. לָמַדְנוּ, בְּשָׁעָה שֶׁהָיוּ מַקְרִיבִים לָהֶם עַל גַּבֵּי הַשָּׂדֶה וְהָיוּ מְזַמְּנִים אוֹתוֹ הַדָּם וּמַקְרִיבִים קָרְבְּנוֹתֵיהֶם, הָיוּ מִתְכַּנְּסִים כָּל אוֹתָם מִינִים רָעִים, וְרוֹאִים אוֹתָם כְּמוֹ הַשְּׂעִירִים, כֻּלָּם מְלֵאִים בְּשֵׂעָר, וּמוֹדִיעִים לָהֶם מַה שֶּׁהֵם רוֹצִים.</p>\n<p>בֹּא רְאֵה, מַה כָּתוּב בְּיִצְחָק? (בראשית כז) וַיִּגַּשׁ יַעֲקֹב אֶל יִצְחָק אָבִיו וַיְמֻשֵּׁהוּ. אָמַר, זֶה לֹא חָסֵר (כאן לא מתעורר), אֶלָּא מִטַּל הַשָּׁמַיִם שֶׁנּוֹזֵל עַל הָאָרֶץ. אָמַר רַבִּי יוֹסֵי, וּמִשְׁמַנֵּי הָאָרֶץ, בַּכֹּל הוּא בֵּרַךְ אוֹתוֹ. מָה הַטַּעַם? כִּי רָאָה אוֹתוֹ עִם שֵׂעָר. אָמַר, שֶׁכְּדֵי לְהַעֲבִיר אֶת זֶה, צָרִיךְ וּמִשְׁמַנֵּי הָאָרֶץ, וְלֹא זֻהֲמַת הָאָרֶץ, שֶׁהֲרֵי זֻהֲמָה הִיא שֶׁל הָאָרֶץ, וּכְשֶׁטַּל הַשָּׁמַיִם וּמֶגֶד הָאָרֶץ מִתְחַבְּרִים, עוֹבֶרֶת הַזֻּהֲמָה הַזּוֹ.</p>"],[9522012131,"<p>אָמַר רַבִּי חִיָּיא, הָאַחֲרוֹן שֶׁל אוֹתָם הַכְּתָרִים הַתַּחְתּוֹנִים שֶׁאֵינָם קְדוֹשִׁים, זֶהוּ הוּא מַה שֶּׁכָּתוּב (דברים י) וְדוֹרֵשׁ אֶל הַמֵּתִים, וְזֶהוּ הָעֲשִׂירִי שֶׁל הַכֹּל. שֶׁלָּמַדְנוּ, אָמַר רַבִּי יִצְחָק אָמַר רַבִּי יְהוּדָה, נַפְשׁוֹת הָרְשָׁעִים אֵלּוּ הֵם מַזִּיקֵי הָעוֹלָם.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אִם כָּךְ טוֹב לָרְשָׁעִים שֶׁנַּעֲשִׂים מַזִּיקִים בָּעוֹלָם, אֵיפֹה הוּא עֹנֶשׁ הַגֵּיהִנֹּם? אֵיפֹה הָרָע שֶׁעָתִיד לָהֶם בָּעוֹלָם הַהוּא? אָמַר רַבִּי חִיָּיא, כָּךְ שָׁנִינוּ, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים. נַפְשׁוֹת הָרְשָׁעִים בְּשָׁעָה שֶׁיּוֹצְאִים מִן הָעוֹלָם, כַּמָּה שׁוֹמְרֵי הֲחֻקִּים מִזְדַּמְּנִים כְּנֶגְדָּם וּלְהַכְנִיסָם בַּגֵּיהִנֹּם, וּמַכְנִיסִים אוֹתָם בִּשְׁלֹשָׁה דִינִים בְּכָל יוֹם בַּגֵּיהִנֹּם. אַחַר כָּךְ מִזְדַּוְּגִים עִמָּם, וְהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם, וּמַטְעִים אֶת הָרְשָׁעִים לְאוֹתָם שֶׁנִּסְתְּמָה מִלִּפְנֵיהֶם הַתְּשׁוּבָה. אַחַר כָּךְ מְשִׁיבִים אוֹתָם לַגֵּיהִנֹּם, וְנִטְמָאִים (ונדונים) שָׁם, וְכָךְ בְּכָל יוֹם.</p>\n<p>אַחַר שֶׁהוֹלְכִים עִמָּם וּמְשׁוֹטְטִים עִמָּם בָּעוֹלָם, מַחֲזִירִים לְקִבְרֵיהֶם, וְרוֹאִים אֶת הַתּוֹלַעַת שֶׁל הַגּוּף מְנַקֶּרֶת אֶת הַבָּשָׂר וּמִתְאַבְּלִים עֲלֵיהֶם, וְאוֹתָם מְכַשְּׁפִים הָיוּ הוֹלְכִים לְבֵית הַקְּבָרוֹת וּמְכַשְּׁפִים בְּכִשְׁפֵיהֶם, וְעוֹשִׂים צֶלֶם אֶחָד שֶׁל הָאָדָם, וְזוֹבְחִים לְפָנָיו שָׂעִיר אֶחָד. אַחַר כָּךְ מַכְנִיסִים אוֹתוֹ הַשָּׂעִיר לְאוֹתוֹ קֶבֶר, וְאֶת אוֹתוֹ צֶלֶם מְשַׁבְּרִים (מנהיגים) אוֹתוֹ לְאַרְבָּעָה צְדָדִים, וּמַכְנִיסִים אוֹתוֹ לְאַרְבַּע זָוִיּוֹת הַקֶּבֶר, וְאָז מְכַשְּׁפִים בְּכִשְׁפֵיהֶם, וּמְכַנְּסִים אוֹתָם כִּנּוּסִים וְאוֹתָם מִינִים רָעִים, וּמְבִיאִים אוֹתָהּ הַנֶּפֶשׁ, וּמַכְנִיסִים לַקֶּבֶר וּמְדַבְּרִים עִמָּם.</p>"],[9522012132,"<p>אָמַר רַבִּי יִצְחָק, אַשְׁרֵי הַצַּדִּיקִים בָּעולָם הַזֶּה וּבָעולָם הַבָּא, שֶׁהֲרֵי כֻּלָּם קְדוֹשִׁים. גּוּפָם קָדוֹשׁ. נַפְשָׁם קְדוֹשָׁה. רוּחָם קְדוֹשָׁה. נִשְׁמָתָם קֹדֶשׁ קָדָשִׁים. שָׁלֹשׁ דְּרָגוֹת הֵן כְּמוֹ שֶׁלְּמַעְלָה. שֶׁשָּׁנִינוּ, אָמַר רַבִּי יְהוּדָה, כָּתוּב (בראשית א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה, זוֹהִי נְשָׁמָה (עליונה) שֶׁל אָדָם הָרִאשׁוֹן (עליון). בֹּא רְאֵה, שָׁלֹשׁ דְּרָגוֹת הֵן, וְנִדְבְּקוּ כְאַחַת - נֶפֶשׁ, רוּחַ, נְשָׁמָה. וְהָעֶלְיוֹנָה מֵהֶן - נְשָׁמָה.</p>\n<p>שֶׁאָמַר רַבִּי יוֹסֵי, בְּכָל הָאֲנָשִׁים יֵשׁ נֶפֶשׁ, וְיֵשׁ נֶפֶשׁ עֶלְיוֹנָה מֵהַנֶּפֶשׁ. זָכָה אָדָם בַּנֶּפֶשׁ הַזּוֹ - מְרִיקִים עָלָיו עֲטָרָה אַחַת שֶׁנִּקְרֵאת רוּחַ. זֶהוּ שֶׁכָּתוּב (ישעיה לב) עַד יֵעָרֶה עָלֵינוּ רוּחַ מִמָּרוֹם. אָז מִתְעוֹרֵר אָדָם בְּהִתְעוֹרְרוּת אַחֶרֶת עֶלְיוֹנָה, לְהִסְתַּכֵּל בְּנִימוּסֵי הַמֶּלֶךְ הַקָּדוֹשׁ. זָכָה אָדָם בְּאוֹתָהּ הָרוּחַ - מְעַטְּרִים אוֹתוֹ בְּכֶתֶר קָדוֹשׁ עֶלְיוֹן שֶׁכּוֹלֵל הַכֹּל, שֶׁנִּקְרָא נְשָׁמָה, שֶׁנִּקְרֵאת נִשְׁמַת אֱלוֹהַּ.</p>\n<p>וְלָמַדְנוּ בְּסוֹד הַסּוֹדוֹת, בְּתוֹךְ הַסּוֹדוֹת שֶׁל סִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ, הַפָּסוּק הַזֶּה שֶׁכָּתוּב (קהלת ד) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, כֵּיוָן שֶׁכָּתוּב וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים, לָמָּה שֶׁכְּבָר מֵתוּ? אֶלָּא שֶׁכְּבָר מֵתוּ בָּעוֹלָם הַזֶּה בַּעֲבוֹדַת רִבּוֹנָם.</p>\n<p>וְשָׁם כָּתוּב, שְׁלֹשָׁה מְדוֹרִים עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיקִים, אֶחָד (שזכו אותם צדיקים שלא נאבדו מהעולם הזה, וכך צריך) לְנַפְשׁוֹת אוֹתָם הַצַּדִּיקִים שֶׁלֹּא הִסְתַּלְּקוּ מֵהָעוֹלָם הַזֶּה וּמְצוּיִים בָּעוֹלָם הַזֶּה. וּכְשֶׁהָעוֹלָם צָרִיךְ רַחֲמִים, וְאוֹתָם הַחַיִּים יוֹשְׁבִים בְּצַעַר, הֵם מִתְפַּלְלִים עֲלֵיהֶם תְּפִלָּה, וְהוֹלְכִים וּמוֹדִיעִים אֶת הַדָּבָר לְאוֹתָם יְשֵׁנֵי חֶבְרוֹן, וּמִתְעוֹרְרִים וְנִכְנָסִים לְגַן הָעֵדֶן שֶׁל הָאָרֶץ, שֶׁשָּׁם רוּחוֹת הַצַּדִּיקִים מְלֻבָּשׁוֹת בְּעַטְרוֹת אוֹר, וּמִתְיָעֲצִים עִמָּם, וְגוֹזְרִים גְּזֵרָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה אֶת רְצוֹנָם וְחָס עַל הָעוֹלָם.</p>\n<p>וְאוֹתָן נַפְשׁוֹת הַצַּדִּיקִים נִמְצָאוֹת בָּעוֹלָם הַזֶּה לְהָגֵן עַל הַחַיִּים, וְזוֹ נִקְרֵאת נֶפֶשׁ, וְזוֹ לֹא מִסְתַּלֶּקֶת (נאבדת) מִן הָעוֹלָם הַזֶּה, וּמְצוּיָה בָּעוֹלָם הַזֶּה כְּדֵי לְהִסְתַּכֵּל וְלָדַעַת וּלְהָגֵן עַל הַדּוֹר. וְזֶהוּ שֶׁאָמְרוּ הַחֲבֵרִים, שֶׁהַמֵּתִים יוֹדְעִים בְּצַעֲרוֹ שֶׁל הָעוֹלָם. וְעֹנֶשׁ הָרְשָׁעִים שֶׁבָּאָרֶץ הוּא בָּזֶה, שֶׁכָּתוּב וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא מֵעַמֶּיהָ.</p>\n<p>וְהַמָּדוֹר הַשֵּׁנִי הוּא גַּן הָעֵדֶן שֶׁבָּאָרֶץ, בּוֹ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא מְדוֹרִים עֶלְיוֹנִים נִכְבָּדִים, כְּמוֹ שֶׁהָעוֹלָם הַזֶּה וּכְמוֹ שֶׁהָעוֹלָם הָעֶלְיוֹן, וְהֵיכָלוֹת בִּשְׁנֵי גְוָנִים שֶׁאֵין לָהֶם חֶשְׁבּוֹן, וְאִילָנוֹת וַעֲשָׂבִים וְרֵיחוֹת שֶׁעוֹלִים בְּכָל יוֹם. וּבַמָּקוֹם הַזֶּה שׁוֹרֶה אוֹתוֹ שֶׁנִּקְרֵאת הָרוּחַ שֶׁל אוֹתָם הַצַּדִּיקִים, וְהַמָּדוֹר שֶׁל אוֹתָהּ רוּחַ שֶׁבּוֹ שׁוֹרָה, וְכָל רוּחַ וְרוּחַ מִתְלַבֶּשֶׁת בִּלְבוּשׁ נִכְבָּד כְּמוֹ שֶׁל הָעוֹלָם הַזֶּה, וּכְמוֹ שֶׁל אוֹתוֹ עוֹלָם עֶלְיוֹן.</p>\n<p>הַמָּדוֹר הַשְּׁלִישִׁי, אוֹתוֹ מָדוֹר קָדוֹשׁ עֶלְיוֹן שֶׁנִּקְרָא צְרוֹר הַחַיִּים, שֶׁשָּׁם מִתְעַדֶּנֶת אוֹתָהּ דַּרְגָּה עֶלְיוֹנָה קְדוֹשָׁה שֶׁנִּקְרֵאת נְשָׁמָה, וְזוֹ דְּבֵקָה לְהִתְעַנֵּג בָּעֹנֶג הָעֶלְיוֹן. עָלֶיהָ כָּתוּב, (ישעיה נח) אָז תִּתְעַנַּג עַל ה' וְהִרְכַּבְתִּיךְ וְגוֹ'.</p>\n<p>וְלָמַדְנוּ, בְּשָׁעָה שֶׁצָּרִיךְ הָעוֹלָם רַחֲמִים וְאוֹתָם צַדִּיקִים זַכָּאִים, אוֹתָהּ הַנֶּפֶשׁ שֶׁנִּמְצֵאת בָּעוֹלָם לְהָגֵן עַל הָעוֹלָם, הַנֶּפֶשׁ עוֹלֶה וְהוֹלֶכֶת וּמְשׁוֹטֶטֶת בָּעוֹלָם וּמוֹדִיעָה לָרוּחַ, וְהָרוּחַ עוֹלָה וּמִתְעַטֶּרֶת וּמוֹדִיעָה לַנְּשָׁמָה, וְהַנְּשָׁמָה לַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָז חָס הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הָעוֹלָם. אָז יוֹרֶדֶת מִמַּעְלָה לְמַטָּה, וְהַנְּשָׁמָה מוֹדִיעָה לָרוּחַ, וְהָרוּחַ מוֹדִיעָה לַנֶּפֶשׁ.</p>\n<p>וּבְכָל שַׁבָּת וְשַׁבָּת וְרֹאשׁ חֹדֶשׁ, כֻּלָּם מִתְחַבְּרוֹת וּמִתְעַטְּרוֹת כְּאֶחָד, עַד שֶׁמִּזְדַּוְּגוֹת לָבֹא לְהִשְׁתַּחֲווֹת לַמֶּלֶךְ הָעֶלְיוֹן. וְאַחַר כָּךְ חוֹזְרוֹת לִמְקוֹמָן. זֶהוּ שֶׁכָּתוּב (שם סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ יָבא כָל בָּשָׂר וְגוֹ'.</p>\n<p>וּבְשָׁעָה שֶׁהָעוֹלָם צָרִיךְ רַחֲמִים, וְהַחַיִּים הוֹלְכִים וּמוֹדִיעִים לְנַפְשׁוֹת הַצַּדִּיקִים וּבוֹכִים עַל קִבְרֵיהֶם, אוֹתָם שֶׁרְאוּיִים לְהוֹדִיעַ לָהֶם. מָה הַטַּעַם? כִּי שָׂמִים רְצוֹנָם לְהִדָּבֵק נֶפֶשׁ בְּנֶפֶשׁ, אָז מְעוֹרְרִים אֶת נַפְשׁוֹת הַצַּדִּיקִים, וּמִתְכַּנְּסִים וְהוֹלְכִים וּמְשׁוֹטְטִים לִישֵׁנֵי חֶבְרוֹן, וּמוֹדִיעִים לָהֶם אֶת צַעַר הָעוֹלָם. וְכֻלָּם נִכְנָסִים לְאוֹתוֹ פֶּתַח גַּן הָעֵדֶן וּמוֹדִיעִים לָרוּחַ. וְאוֹתָן רוּחוֹת שֶׁמִּתְעַטְּרוֹת בְּגַן עֵדֶן, הוֹלְכִים בֵּינֵיהֶן מַלְאָכִים עֶלְיוֹנִים, וְכֻלָּם מוֹדִיעִים לַנְּשָׁמָה. וְהַנְּשָׁמָה מוֹדִיעָה לַקָבָּ\"ה, וְכֻלָּם מְבַקְשִׁים רַחֲמִים עַל הַחַיִּים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל הָעוֹלָם בַּעֲבוּרָם. וְעַל זֶה אָמַר שְׁלֹמֹה, וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ וְגוֹ'.</p>\n<p>אָמַר רַבִּי חִיָּיא, תְּמֵהַנִי אִם יֵשׁ מִי שֶׁיּוֹדֵעַ לְהוֹדִיעַ לַמֵּתִים פְּרָט לָנוּ. אָמַר רַבִּי אַבָּא, הַצַּעַר מוֹדִיעַ לָהֶם, הַתּוֹרָה מוֹדִיעָה לָהֶם. שֶׁהֲרֵי בְּשָׁעָה שֶׁאֵין מִי שֶׁמַּכִּיר אֶת זֶה, מוֹצִיאִים אֶת הַתּוֹרָה סָמוּךְ לַקְּבָרִים, וְהֵם מִתְעוֹרְרִים עַל הַתּוֹרָה עַל מָה גָּלְתָה לְאוֹתוֹ מָקוֹם, וְאָז דּוּמָה מוֹדִיעַ לָהֶם.</p>\n<p>אָמַר רַבִּי יוֹסֵי, וְהֵם יוֹדְעִים שֶׁהֲרֵי הָעוֹלָם בְּצַעַר, וְהַחַיִּים לֹא רְאוּיִים וְלֹא יוֹדְעִים לְהוֹדִיעַ לָהֶם. בְּאוֹתָהּ שָׁעָה כֻּלָּם צוֹוְחִים עַל שֶׁהַתּוֹרָה נִקְלְתָה וְגָלְתָה לְאוֹתוֹ מָקוֹם. אִם בְּנֵי אָדָם שָׁבִים וּבוֹכִים בְּלֵב שָׁלֵם וְשָׁבִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, אָז כֻּלָּם מִתְכַּנְּסִים וּמְבַקְשִׁים רַחֲמִים וּמוֹדִיעִים לְאוֹתָם יְשֵׁנֵי חֶבְרוֹן, וְנִכְנָסִים וּמוֹדִיעִים לָרוּחַ שֶׁבְּגַן עֵדֶן, כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>וְאִם הֵם לֹא שָׁבִים בְּלֵב שָׁלֵם לְבַקֵּשׁ וְלִבְכּוֹת עַל צַעַר הָעוֹלָם - אוֹי לָהֶם! שֶׁכֻּלָּם מִתְכַּנְּסִים לָרִיק וְאוֹמְרִים: מִי גָרַם לַתּוֹרָה הַקְּדוֹשָׁה לִגְלוֹת עַל יְדֵיהֶם בְּלִי תְשׁוּבָה? וְכֻלָּם בָּאִים לְחַדֵּשׁ (להזכיר) חֲטָאֵיהֶם. מִשּׁוּם כָּךְ אַל יֵלְכוּ לְשָׁם בְּלִי תְשׁוּבָה וּבְלִי תַעֲנִית לְבַקֵּשׁ בַּקָּשָׁה לִפְנֵיהֶם. רַבִּי אַבָּא אָמַר, (הכל על שלש) בְּלִי שָׁלֹשׁ תַּעֲנִיּוֹת. רַבִּי יוֹסֵי אָמַר, אֲפִלּוּ אַחַת וּבְאוֹתוֹ יוֹם, וּבִלְבַד שֶׁהָעוֹלָם יֵשֵׁב בְּצַעַר יָתֵר, אָז כֻּלָּם מִזְדַּוְּגִים לְבַקֵּשׁ רַחֲמִים עַל הָעוֹלָם.</p>"],[9522012133,"<p>לָמַדְנוּ, אָמַר רַבִּי יְהוּדָה, יוֹם אֶחָד הָיוּ הוֹלְכִים רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא בַּדֶּרֶךְ. פָּגְעוּ בְּגוּשׁ חָלָב, וְהָיָה חָרֵב. יָשְׁבוּ סָמוּךְ לְבֵית הַקְּבָרוֹת, וּבִידֵי רַבִּי יֵיסָא הָיָה מַקֵּל (קשר) שֶׁל סֵפֶר תּוֹרָה שֶׁנִּקְרַע. בְּעוֹד שֶׁיָּשְׁבוּ, רָעַשׁ קֶבֶר אֶחָד לִפְנֵיהֶם וְצָוַח: אוֹי אוֹי! שֶׁהֲרֵי הָעוֹלָם מָצוּי בְּצַעַר. הֲרֵי הַתּוֹרָה גָּלְתָה לְכָאן, אוֹ שֶׁהַחַיִּים בָּאוּ לִצְחֹק עָלֵינוּ וּלְבַיֵּשׁ אוֹתָנוּ בְּבוּשָׁה בְּתוֹרָתָם! הִזְדַּעְזְעוּ רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, מִי אַתָּה? אָמַר לוֹ: אֲנִי מֵת, וַהֲרֵי הִתְעוֹרַרְתִּי לְסֵפֶר הַתּוֹרָה. שֶׁפַּעַם אַחַת הָיָה הָעוֹלָם יוֹשֵׁב בְּצַעַר, וּבָאוּ לְכָאן הַחַיִּים לְעוֹרֵר אוֹתָנוּ עִם סֵפֶר תּוֹרָה, וַאֲנִי וַחֲבֵרַי הִקְדַּמְנוּ אֶל יְשֵׁנֵי חֶבְרוֹן, וּכְשֶׁהִתְחַבְּרוּ בְּגַן עֵדֶן עִם רוּחוֹת הַצַּדִּיקִים, נִמְצָא לִפְנֵיהֶם, שֶׁאוֹתוֹ סֵפֶר תּוֹרָה שֶׁהֵבִיאוּ לְפָנֵינוּ אוֹתָם הַחַיִּים הָיָה פָּסוּל וּמְשַׁקֵּר בְּשֵׁם הַמֶּלֶךְ, עַל שֶׁנִּמְצְאָה וָא\"ו יְתֵרָה בְּאוֹתוֹ פָּסוּק שֶׁל (ויקרא יא) וְֹשסַעַת שֶׁסַע שְׁתֵּי פְרָסוֹת. וְאָמְרוּ, שֶׁהוֹאִיל וְשִׁקְּרוּ בְשֵׁם הַמֶּלֶךְ, שֶׁלֹּא יָשׁוּבוּ אֲלֵיהֶם, וְדָחוּ אוֹתִי וְאֶת הַחֲבֵרִים שֶׁלִּי מִבֵּית הַיְשִׁיבָה.</p>\n<p>עֵד שֶׁזָּקֵן אֶחָד שֶׁהָיָה בֵינֵיהֶם הָלַךְ וְהֵבִיא אֶת סִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, וְאָז הִתְעוֹרֵר רַבִּי אֶלְעָזָר בֶּן רַבִּי שִׁמְעוֹן, שֶׁהָיָה קָבוּר עִמָּנוּ, וְהָלַךְ וּבִקֵּשׁ בְּגַן עֵדֶן עֲלֵיהֶם, וְנִרְפָּא הָעוֹלָם. וְאָז הִתִּירוּ לָנוּ, וּמֵאוֹתוֹ יוֹם שֶׁהֶעֱלוּ אֶת רַבִּי אֶלְעָזָר מִבֵּית הַקְּבָרוֹת הַזֶּה וְנִתַּן לְאָבִיו, אֵין מִי שֶׁיִּתְעוֹרֵר לַעֲמֹד לִפְנֵי יְשֵׁנֵי חֶבְרוֹן, שֶׁאָנוּ פוֹחֲדִים מֵאוֹתוֹ הַיּוֹם שֶׁדָּחוּ אוֹתִי וְאֶת חֲבֵרַי. וְעַכְשָׁו בָּאתֶם אֵלֵינוּ עִם סֵפֶר תּוֹרָה עִמָּכֶם, אָמַרְנוּ שֶׁהֲרֵי הָעוֹלָם מָצוּי בְּצַעַר. וְעַל כֵּן הִזְדַּעְזַעְנוּ, שֶׁאָמַרְנוּ: מִי יַקְדִּים לְהוֹדִיעַ לְאוֹתָם צַדִּיקֵי אֱמֶת יְשֵׁנֵי חֶבְרוֹן? נִשְׁמַט רַבִּי יֵיסַא עִם אוֹתוֹ חֵלֶק שֶׁל סֵפֶר תּוֹרָה. אָמַר רַבִּי חִזְקִיָּה, חַס וְשָׁלוֹם אֵין הָעוֹלָם בְּצַעַר, וְאָנוּ לֹא בָאנוּ לְכָךְ.</p>\n<p>קָמוּ רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא וְהָלְכוּ. אָמְרוּ, וַדַּאי בְּשָׁעָה שֶׁצַּדִּיקִים לֹא נִמְצָאִים בָּעוֹלָם, הָעוֹלָם אֵינוֹ מִתְקַיֵּם אֶלָּא בִּשְׁבִיל הַמֵּתִים. אָמַר רַבִּי יֵיסָא, בְּשָׁעָה שֶׁהָעוֹלָם צָרִיךְ אֶת הַמָּטָר, לָמָּה הוֹלְכִים אֵצֶל הַמֵּתִים, וַהֲרֵי כָּתוּב (דברים יח) וְדֹרֵשׁ אֶל הַמֵּתִים, וְאָסוּר? אָמַר לוֹ, עַד כָּאן לֹא רָאִיתָ כְּנַף צִפּוֹר הָעֵדֶן. וְדֹרֵשׁ אֶל הַמֵּתִים, דַּוְקָא אֶל הַמֵּתִים. שֶׁהֵם רִשְׁעֵי הָעוֹלָם שֶׁהֵם מֵעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁנִּמְצָאִים תָּמִיד עִם הַמֵּתִים. אֲבָל יִשְׂרָאֵל, שֶׁהֵם צַדִּיקֵי אֱמֶת, עֲלֵיהֶם קָרָא שְׁלֹמֹה, (קהלתד) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, בִּזְמַן אַחֵר וְלֹא עַכְשָׁו. שֶׁכְּבָר מֵתוּ, וְעַכְשָׁו הֵם חַיִּים.</p>\n<p>וְעוֹד, שֶׁשְּׁאָר הָעַמִּים, כְּשֶׁהֵם בָּאִים לְמֵתֵיהֶם, הֵם בָּאִים עִם כְּשָׁפִים לְעוֹרֵר עֲלֵיהֶם מִינִים רָעִים. וּכְשֶׁיִּשְׂרָאֵל בָּאִים לְמֵתֵיהֶם, בָּאִים בְּכַמָּה תְשׁוּבָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, בְּשִׁבְרוֹן לֵב וּבְתַעֲנִית כְּנֶגְדּוֹ, וְהַכֹּל כְּדֵי שֶׁנִּשְׁמוֹת הַקְּדוֹשִׁים יְבַקְשׁוּ רַחֲמִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל הָעוֹלָם בַּעֲבוּרָם.</p>\n<p>וְעַל זֶה שָׁנִינוּ, צַדִּיק, אַף עַל גַּב שֶׁנִּפְטָר מֵהָעוֹלָם הַזֶּה, לֹא מִסְתַּלֵּק וְלֹא נֶאֱבָד מִכָּל הָעוֹלָמוֹת, שֶׁהֲרֵי בְּכָל הָעוֹלָמוֹת הוּא נִמְצָא יוֹתֵר מִבְּחַיָּיו, שֶׁבְּחַיָּיו נִמְצָא בָּעוֹלָם הַזֶּה בִּלְבַדּוֹ, וְאַחַר כָּךְ נִמְצָא בִּשְׁלֹשָׁה עוֹלָמוֹת וּמְזֻמָּן אֲלֵיהֶם, שֶׁכָּתוּב (שיר א) עֲלָמוֹת אֲהֵבוּךְ, אַל תִּקְרֵי עֲלָמוֹת אֶלָּא עוֹלָמוֹת. אַשְׁרֵי חֶלְקָם.</p>\n<p>לָמַדְנוּ, כָּתוּב (שמואל א כה) וְהָיְתָה נֶפֶשׁ אֲדנִי צְרוּרָה בִּצְרוֹר הַחַיִּים. וְהָיְתָה נֶפֶשׁ אֲדנִי?! נִשְׁמַת אֲדנִי הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא כְּמוֹ שֶׁאָמַרְנוּ, שֶׁאַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁהַכֹּל נִקְשָׁר זֶה עִם זֶה, נֶפֶשׁ בְּרוּחַ, וְרוּחַ בִּנְשָׁמָה, וּנְשָׁמָה בַּקָּדוֹשׁ בָּרוּךְ הוּא. נִמְצָא שֶׁהַנֶּפֶשׁ צְרוּרָה בִּצְרוֹר הַחַיִּים.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, זֶה שֶׁאָמְרוּ הַחֲבֵרִים, גָּלוּתוֹ שֶׁל סֵפֶר תּוֹרָה אֲפִלּוּ מִבֵּית כְּנֶסֶת לְבֵית כְּנֶסֶת אַחֵר אָסוּר, וְכָל שֶׁכֵּן לָרְחוֹב. לָמָּה לָרְחוֹב? אָמַר רַבִּי יְהוּדָה, כְּמוֹ שֶׁאָמַרְנוּ, כְּדֵי שֶׁיִּתְעוֹרְרוּ עָלֵינוּ וִיבַקְשׁוּ רַחֲמִים עַל הָעוֹלָם. אָמַר רַבִּי אַבָּא, כְּשֶׁשְּׁכִינָה גָּלְתָה כָּךְ גַּם מִמָּקוֹם לְמָקוֹם, עַד שֶׁאָמְרָה (ירמיה ט) מִי יִתְּנֵנִי בַמִּדְבָּר מְלוֹן אוֹרְחִים וְגוֹ', אַף כָּאן בָּרִאשׁוֹנָה מִבֵּית כְּנֶסֶת לְבֵית כְּנֶסֶת, אַחַר כָּךְ לָרְחוֹב, אַחַר כָּךְ בַּמִּדְבָּר מְלוֹן אוֹרְחִים. אָמַר רַבִּי יְהוּדָה, בְּנֵי בָּבֶל פּוֹחֲדִים וְלֹא מַעֲבִירִים אֲפִלּוּ מִבֵּית כְּנֶסֶת לְבֵית כְּנֶסֶת, כָּל שֶׁכֵּן זֶה.</p>\n<p>לָמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן לַחֲבֵרִים, בְּיָמַי לֹא יִצְטָרְכוּ בְּנֵי הָעוֹלָם אֶת זֶה. אָמַר לוֹ רַבִּי יוֹסֵי הַצַּדִּיקִים מְגִנִּים עַל הָעוֹלָם בְּחַיֵּיהֶם, וּבְמִיתָתָם יוֹתֵר מִבְּחַיֵּיהֶם. זֶהוּ שֶׁכָּתוּב (ישעיה לז) וְגַנּוֹתִי עַל הָעִיר הַזֹּאת לְהוֹשִׁיעָהּ לְמַעֲנִי וּלְמַעַן דָּוִד עַבְדִּי. וְאִלּוּ בְּחַיָּיו לֹא כָתוּב. אָמַר רַבִּי יְהוּדָה, מַה שּׁוֹנֶה כָּאן שֶׁכָּתוּב לְמַעֲנִי וּלְמַעַן דָּוִד עַבְדִּי, שֶׁשָּׁקוּל זֶה לָזֶה? אֶלָּא מִשּׁוּם שֶׁדָּוִד זָכָה לְהִקָּשֵׁר לַמֶּרְכָּבָה הַקְּדוֹשָׁה שֶׁל הָאָבוֹת, וּמִשּׁוּם כָּךְ הַכֹּל אֶחָד. בָּרוּךְ הוּא לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>"],[9522012134,"<p>כְּמַעָשֵׂה אֶרֶץ מִצְרַיִם אֲשֶׁר יְשַׁבְתֶּם בָּהּ לֹא תַעֲשׂוּ. רַבִּי יִצְחָק פָּתַח, (תהלים קב) לְסַפֵּר בְּצִיּוֹן שֵׁם ה' וּתְהִלָּתוֹ בִּיְרוּשָׁלם. שָׁם שָׁנִינוּ, הַשֵּׁם הַקָּדוֹשׁ נִסְתָּר וְנִגְלֶה. וְהַתּוֹרָה, שֶׁהִיא הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן, נִסְתֶּרֶת וְנִגְלֵית. וְכָל פָּסוּק שֶׁבַּתּוֹרָה, וְכָל פָּרָשָׁה שֶׁל הַתּוֹרָה, נִסְתָּר וְנִגְלֶה.</p>\n<p>שֶׁלָּמַדְנוּ, אָמַר רַבִּי יְהוּדָה, מֵחֻצְפָּתָהּ שֶׁל צַדִּיקָה אַחַת יָצְאוּ כַּמָּה טוֹבוֹת לָעוֹלָם, וּמִי הִיא? תָּמָר, שֶׁכָּתוּב (בראשית לח) וַתֵּשֶׁב בְּפֶתַח עֵינַיִם. אָמַר רַבִּי אַבָּא, פָּרָשָׁה זוֹ מוֹכִיחָה שֶׁהַתּוֹרָה נִסְתֶּרֶת וְנִגְלֵית. וַהֲרֵי הִסְתַּכַּלְתִּי בְּכָל הַתּוֹרָה וְלֹא מָצָאתִי מָקוֹם שֶׁנִּקְרָא פֶּתַח עֵינַיִם, אֶלָּא הַכֹּל נִסְתָּר, וְסוֹד הַסּוֹדוֹת הוּא.</p>\n<p>וְלָמַדְנוּ, מָה רָאֲתָה הַצַּדֶּקֶת הַזּוֹ לַמַּעֲשֶׂה הַזֶּה? אֶלָּא הִכִּירָה בְּבֵית חָמִיהָ אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵיךְ מַנְהִיג אֶת הָעוֹלָם עִם בְּנֵי הָאָדָם. וּמִשּׁוּם שֶׁהִיא הִכִּירָה, הַקָּדוֹשׁ בָּרוּךְ הוּא הֵקִים אֶת הַדָּבָר עַל יָדָהּ. וְזֶה הוֹלֵךְ כְּמוֹ שֶׁשָּׁנִינוּ, מְזֻמֶּנֶת הָיְתָה בַּת שֶׁבַע מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית לִהְיוֹת אִמּוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ. אַף כָּאן מְזֻמֶּנֶת הָיְתָה תָּמָר לְכָךְ מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם.</p>\n<p>וַתֵּשֶׁב בְּפֶתַח עֵינַיִם. מִי זֶה פֶּתַח עֵינַיִם? כְּמוֹ שֶׁנֶּאֱמַר, וְהוּא יֹשֵׁב פֶּתַח הָאֹהֶל. וְכָתוּב (שמות יב) וּפָסַח ה' עַל הַפֶּתַח. וְכָתוּב (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק וְגוֹ'. עֵינַיִם - שֶׁכָּל עֵינֵי הָעוֹלָם מְצַפִּים לַפֶּתַח הַזֶּה. אֲשֶׁר עַל דֶּרֶךְ תִּמְנָתָה, מַה זֶּה תִּמְנָתָה? כְּמוֹ שֶׁנֶּאֱמַר (במדבר יב) וּתְמוּנַת ה' יַבִּיט. וְכָךְ בֵּאַרְנוּ, תָּמָר הֵקִימָה הַדָּבָר לְמַטָּה, וְהִפְרִיחָה פְרָחִים וְנִצְנְצָה עֲנָפִים בְּסוֹד הָאֱמוּנָה.</p>\n<p>וִיהוֹדָה עֹד רָד עִם אֵל וְעִם קְדוֹשִׁים נֶאֱמָן (הושע יב). וַיִּרְאֶהָ יְהוּדָה וַיַּחְשְׁבֶהָ לְזוֹנָה וְגוֹ'. כְּמוֹ שֶׁנֶּאֱמַר (משלי ל) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת. כִּי כִסְּתָה פָּנֶיהָ, וּבֵאַרְנוּ כִּי כִסְּתָה פָּנֶיהָ, כְּמוֹ שֶׁנֶּאֱמַר אָכְלָה וּמָחֲתָה פִיהָ, שָׂרְפָה אֶת הָעוֹלָם בְּשַׁלְהֲבוֹתֶיהָ, וְאָמְרָה לֹא פָעַלְתִּי אָוֶן. מָה הַטַּעַם? מִשּׁוּם כִּי כִסְּתָה פָּנֶיהָ, וְאֵין מִי שֶׁיּוֹדֵעַ דְּרָכֶיהָ לְהִנָּצֵל מִמֶּנָּה. וַיֵּט אֵלֶיהָ אֶל הַדֶּרֶךְ, אֶל הַדֶּרֶךְ מַמָּשׁ, לְחַבֵּר לָבָן בְּאָדם. וַיֹּאמֶר הָבָה נָּא אָבוֹא אֵלַיִךְ וְגוֹ', הֲרֵי בֵּאַרְנוּ הָבָה בְּכָל מָקוֹם.</p>\n<p>כִּי לֹא יָדַע כִּי כַלָּתוֹ הִיא. כִּי כַלָּתוֹ הִיא שֶׁל הָעוֹלָם, מְתַרְגְּמִים: אֲשֶׁר הַשְׁמָדַת הָעוֹלָם הִיא. מָה הַטַּעַם לֹא יָדַע? מִשּׁוּם שֶׁהֵאִירוּ פָנֶיהָ לְקַבֵּל מִמֶּנּוּ, וְהִזְדַּמְּנָה לְבַשֵּׂם וּלְרַחֵם עַל הָעוֹלָם. כִּי כַלָּתוֹ הִיא - זוֹ כַּלָּה מַמָּשׁ, שֶׁכָּתוּב (שיר ד) אִתִּי מִלְּבָנוֹן כַּלָּה.</p>\n<p>וַתֹּאמֶר מַה תִּתֶּן לִי כִּי תָבוֹא אֵלָי. עַכְשָׁו הַכַּלָּה צְרִיכָה תַכְשִׁיטֶיהָ. וַיּאמֶר אָנֹכִי אֲשַׁלַּח גְּדִי עִזִּים מִן הַצּאן. לְמֶלֶךְ שֶׁהָיָה לוֹ בֵּן מִשִּׁפְחָה אַחַת שֶׁהָלַךְ בַּהֵיכָל, רָצָה הַמֶּלֶךְ לָשֵׂאת גְּבִירָה עֶלְיוֹנָה וּלְהַכְנִיסָהּ לְהֵיכָלוֹ. אָמְרָה: מִי נָתַן אֶת זֶה בְּתוֹךְ הֵיכַל הַמֶּלֶךְ? (מי נתן את זה בהיכל המלך אמר המלך:) אָמַר: מִכָּאן וָהָלְאָה אֲשַׁלַּח וַאֲגָרֵשׁ אֶת בֶּן הַשִּׁפְחָה מֵהֵיכָלִי.</p>\n<p>כָּךָ גַּם כָּאן, אָנֹכִי אֲשַׁלַּח גְּדִי עִזִּים מִן הַצֹּאן. וַהֲרֵי בֵּאַרְנוּ בְּלֹא תְבַשֵּׁל גְּדִי. וְכָל אוֹתָם שֶׁמִּצַּד בְּכוֹר הַבְּהֵמָה הֵם בָּאוּ. וְעַל כֵּן לֹא כָתוּב אָנֹכִי אֶתֵּן, אֶלָּא אָנֹכִי אֲשַׁלַּח, אֲגָרֵשׁ וַאֲשַׁלַּח אוֹתוֹ שֶׁלֹּא יִמָּצֵא בְהֵיכָלִי.</p>\n<p>וַתֹּאמֶר אִם תִּתֵּן עֵרָבוֹן עַד שָׁלְחֶךְ. אֵלּוּ הֵם סִימָנֵי הַגְּבִירָה שֶׁהִתְבָּרְכָה מֵהַמֶּלֶךְ בְּזִוּוּגָהּ. וַיֹּאמֶר מָה הָעֵרָבוֹן אֲשֶׁר אֶתֶּן לָךְ, וַתֹּאמֶר חֹתָמְךְ וּפְתִילֶךְ וּמַטְּךְ. אֵלּוּ הֵם (צדדי) הַקְּשָׁרִים הָעֶלְיוֹנִים, תַּכְשִׁיטֶיהָ שֶׁל הַכַּלָּה מִתְבָּרְכִים מִשְּׁלֹשֶׁת אֵלֶּה, נֵצַח הוֹד יְסוֹד, וְהַכֹּל נִמְצָא בִּשְׁלֹשֶׁת אֵלֶּה, וְהַכַּלָּה (מנצח הוד יסוד) מִתְבָּרֶכֶת מִכָּאן. מִיָּד - וַיִּתֶּן לָהּ וַיָּבֹא אֵלֶיהָ וַתַּהַר לוֹ. וַיְהִי כְּמִשְׁלֹשׁ חֳדָשִׁים. מַה זֶּה מִשְׁלֹשׁ חֳדָשִׁים? אַחַר שֶׁיְּשַׁלְּשׁוּ הֶחֳדָשִׁים, וַהֲרֵי שְׁלֹשָׁה חֳדָשִׁים בֵּאַרְנוּ. וְכָאן כְּמִשְׁלֹשׁ חֳדָשִׁים, שֶׁהִתְחִיל הַחֹדֶשׁ הָרְבִיעִי לְעוֹרֵר דִּינִים בָּעוֹלָם מֵחֲטָאֵי בְּנֵי אָדָם, וְהִיא יוֹנֶקֶת מִצַּד הָאַחֵר. אָז - וַיֵּגּד לִיהוּדָה לֵאמֹר זָנְתָה תָּמָר כַּלָּתֶךְ. הֲרֵי כַּלָּה בַּצַּד הָאַחֵר נִמְצֵאת. מַה כָּתוּב? הוֹצִיאוּהָ, כְּמוֹ שֶׁכָּתוּב, (איכה ב) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ תִּפְאֶרֶת יִשְׂרָאֵל. וְתִשָּׂרֵף, בְּשַׁלְהֶבֶת הַצָּהֳרַיִם בַּגָּלוּת. מַה כָּתוּב? הִיא מוּצֵאת, לְהִמָּשֵׁךְ, לַגָּלוּת. וְהִיא שָׁלְחָה אֶל חָמִיהָ לֵאמֹר לְאִישׁ אֲשֶׁר אֵלֶּה לּוֹ. לֹא כָתוּב לְאִישׁ אֲשֶׁר אֵלֶּה מִמֶּנּוּ, אֶלָּא לְאִישׁ אֲשֶׁר אֵלֶּה לּוֹ. שֶׁלּוֹ הַסִּימָנִים הַלָּלוּ הַמְּצוּיִים, אָנֹכִי הָרָה. מִיָּד - וַיַּכֵּר יְהוּדָה וַיּאמֶר צָדְקָה מִמֶּנִּי. צָדְקָה וַדַּאי, וְהַשֵּׁם גּוֹרֵם. מַה גָּרַם לָהּ? הַשֵּׁם הַזֶּה. חָזַר וְאָמַר, מִמֶּנִּי, שֶׁכָּתוּבּ כִּי צַדִּיק ה' צְדָקוֹת אָהֵב יָשָׁר יֶחֱזוּ פָנֵימוֹ. צָדְקָה - צָדַק ה', שֶׁמִּמֶּנִּי נָטְלָה אֶת הַשֵּׁם הַזֶּה. מִמֶּנִּי יָרְשָׁה, מִמֶּנִּי נִמְצֵאת.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מָה הַטַּעַם כָּתוּב חָמִיהָ בְּמָקוֹם אֶחָד, וִיהוּדָה בְּמָקוֹם אַחֵר? אָמַר לוֹ, הַכֹּל נִקְשָׁר זֶה עִם זֶה. חָמִיהָ תָּלוּי בְּמָקוֹם עֶלְיוֹן.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, הַפָּרָשָׁה הַזּוֹ בֵּאַרְנוּ בְּסוֹד עֶלְיוֹן בְּכַמָּה גְוָנִים. כְּשֶׁיִּתְבּוֹנְנוּ בַדְּבָרִים, מִמֶּנָּה יִשָּׁמְעוּ הַסּוֹדוֹת שֶׁל דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְדִינָיו בְּכָל מָקוֹם. וְהִיא יָדְעָה וְהִקְדִּימָה עַצְמָהּ לַדָּבָר הַזֶּה, לְהַשְׁלִים אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי שֶׁיֵּצְאוּ מִמֶּנָּה מְלָכִים שַׁלִּיטִים, שֶׁעֲתִידִים לִשְׁלֹט עַל הָעוֹלָם. וְרוּת עָשְׂתָה כְּגוֹן זֶה.</p>"],[9522012135,"<p>אָמַר רַבִּי אַבָּא, פָּרָשָׁה זוֹ נִקְשְׁרָה בְּסוֹד חָכְמַת הָתּוֹרָה, וְהַכֹּל נִסְתָּר וְנִגְלֶה. וְכָל הַתּוֹרָה מְצוּיָה כְּגוֹן זֶה, וְאֵין לְךְ דָּבָר בַּתּוֹרָה שֶׁלֹּא רָשׁוּם בּוֹ הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן שֶׁנִּסְתָּר וְנִגְלֶה. מִשּׁוּם כָּךְ הַנִּסְתָּרוֹת שֶׁבַּתּוֹרָה, קְדוֹשִׁים עֶלְיוֹנִים יוֹרְשִׁים אוֹתָם, וְנִגְלֵית לִשְׁאָר בְּנֵי הָעוֹלָם. כְּמוֹ כֵן כָּתוּב, (תהלים קב) לְסַפֵּר בְּצִיּוֹן שֵׁם ה' וּתְהִלָּתוֹ בִּירוּשָׁלם. שֶׁהֲרֵי בְּצִיּוֹן בַּמִּקְדָּשׁ מֻתָּר לְהַזְכִּיר אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי, וּבַחוּץ בְּכִנּוּיוֹ. וְלָכֵן הַכֹּל נִסְתָּר וְנִגְלֶה. לָמַדְנוּ, כָּל מִי שֶׁגּוֹרֵעַ אוֹת אַחַת מֵהַתּוֹרָה אוֹ מוֹסִיף אוֹת אַחַת לַתּוֹרָה, כְּמִי שֶׁמְּשַׁקֵּר בַּשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן שֶׁל הַמֶּלֶךְ.</p>\n<p>אָמַר רַבִּי יִצְחָק, מַעֲשֶׂה שֶׁל מִצְרַיִם שֶׁעוֹבְדִים לְשִׁפְחָה, כְּמוֹ שֶׁבֵּאַרְנוּ. מַעֲשֶׂה שֶׁל כְּנַעַן שֶׁעוֹבְדִים לְאוֹתוֹ שֶׁנִּקְרָא (שמות יב) שְׁבִי אֲשֶׁר בְּבֵית הַבּוֹר. וְעַל זֶה כָּתוּב, (בראשית ט) אָרוּר כְּנָעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו. מִשּׁוּם כָּךְ כֻּלָּם מַכְתִּיבִים (מברכים) (מכזבים) בִּדְבָרִים קְדוֹשִׁים, וְעוֹשִׂים מַעֲשִׂים (עריות) בַּכֹּל. מִשּׁוּם כָּךְ, כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם אֲשֶׁר יְשַׁבְתֶּם בָּהּ וְגוֹ'. רַבִּי יְהוּדָה אָמַר, שֶׁעוֹשִׂים דִּינִים (מינים) רָעִים לִשְׁלֹט (לטמא) עַל הָאָרֶץ, כְּמוֹ שֶׁנֶּאֱמַר וְלֹא תְטַמֵּא אֶת אַדְמָתְךְ. וְכָתוּב וַתִּטְמָא הָאָרֶץ.</p>\n<p>כְּמַעָשֵׂה אֶרֶץ מִצְרַיִם וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (איוב לח) לֶאֱחֹז בְּכַנְפוֹת הָאָרֶץ וְגוֹ'. לָמַדְנוּ, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְטַהֵר אֶת אַרְצוֹ מִכָּל טֻמְאַת הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁטִּמְּאוּ אוֹתָהּ, כְּמִי שֶׁאוֹחֵז בְּטַלִּיתוֹ וּמְנַעֵר אֶת הַטִּנֹּפֶת מִמֶּנָּה. וְכָל אוֹתָם שֶׁנִּקְבְּרוּ בָּאָרֶץ הַקְדוֹשָׁה, לִזְרֹק אוֹתָם הַחוּצָה, וּלְטַהֵר אֶת הָאָרֶץ מֵהַצַּד הָאַחֵר (קדוש אחר), כִּבְיָכוֹל שֶׁהָיְתָה מְזִינָה אֶת שְׁאָר גְּדוֹלֵי הָעַמִּים וּלְקַבֵּל אֶת טֻמְאָתָם וּלְהַנְהִיגָם, וְעָתִיד לְטַהֵר אוֹתָהּ וּלְהַעֲבִירָם הַחוּצָה.</p>"],[9522012136,"<p>רַבִּי שִׁמְעוֹן הָיָה מְטַהֵר אֶת (הרי) שׁוּקֵי טְבֶרְיָה, וְכָל שֶׁהָיָה שָׁם מֵת, הָיָה מַעֲלֶה אוֹתוֹ וּמְטַהֵר אֶת הָאָרֶץ. לָמַדְנוּ, כָּתוּב וַתָּבֹאוּ וַתְּטַמְּאוּ אֶת אַרְצִי וְגוֹ'. אָמַר רַבִּי יְהוּדָה, אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁזּוֹכֶה בְחַיָּיו לְהַשְׁרוֹת מְדוֹרוֹ בָּאָרֶץ הַקְּדוֹשָׁה. שֶׁכָּל מִי שֶׁזּוֹכֶה לָהּ, זוֹכֶה לְהַשְׁפִּיעַ מִטַּל הַשָּׁמַיִם שֶׁלְּמַעְלָה שֶׁיּוֹרֵד עַל הָאָרֶץ. וְכָל מִי שֶׁזּוֹכֶה לְהִקָּשֵׁר בְּחַיָּיו בָּאָרֶץ הַקְּדוֹשָׁה הַזּוֹ, זוֹכֶה לְהִקָּשֵׁר אַחַר כָּךְ לָאָרֶץ הַקְּדוֹשָׁה הָעֶלְיוֹנָה.</p>\n<p>וְכָל מִי שֶׁלֹּא זוֹכֶה בְחַיָּיו, וּמְבִיאִים אוֹתוֹ לְהִקָּבֵר שָׁם, עָלָיו כָּתוּבּ וְנַחֲלָתִי שַׂמְתֶּם לְתוֹעֵבָה. רוּחוֹ יָצְאָה בִרְשׁוּת נָכְרִיָּה אַחֶרֶת, וְגוּפוֹ בָּא תַּחַת רְשׁוּת הָאָרֶץ הַקְּדוֹשָׁה כִּבְיָכוֹל, עָשָׂה קֹדֶשׁ חֹל, וְחֹל קֹדֶשׁ. וְכָל מִי שֶׁזּוֹכֶה לְהוֹצִיא נִשְׁמָתוֹ בָּאָרֶץ הַקְּדוֹשָׁה, מִתְכַּפְּרִים חֲטָאָיו, וְזוֹכֶה לְהִקָּשֵׁר תַּחַת כַּנְפֵי הַשְּׁכִינָה, שֶׁכָּתוּב (דברים לב) וְכִפֶּר אַדְמָתוֹ עַמּוֹ. וְלֹא עוֹד, אֶלָּא אִם זוֹכֶה בְחַיָּיו, זוֹכֶה לִמְשֹׁךְ עָלָיו רוּחַ קְדֻשָּׁה תָּמִיד, וְכָל מִי שֶׁיּוֹשֵׁב בְּרָשׁוּת אַחֶרֶת, נִמְשֶׁכֶת עָלָיו רוּחַ אַחֶרֶת נָכְרִיָּה.</p>\n<p>לָמַדְנוּ, כְּשֶׁעָלָה רַב הַמְנוּנָא סָבָא לְשָׁם, הָיוּ עִמּוֹ שְׁנֵים עָשָׂר בְּנֵי הַיְשִׁיבָה שֶׁלּוֹ. אָמַר לָהֶם, אִם אֲנִי הוֹלֵךְ לַדֶּרֶךְ הַזּוֹ, לֹא עַל שֶׁלִּי אֲנִי עוֹשֶׂה, אֶלָּא כְּדֵי לְהָשִׁיב הַפִּקָּדוֹן לִבְעָלָיו. שָׁנִינוּ, כָּל אוֹתָם שֶׁלֹּא זָכוּ לָזֶה בְחַיֵּיהֶם, הֵם מְשִׁיבִים אֶת פִּקְדוֹן רִבּוֹנָם לְאַחֵר.</p>\n<p>אָמַר רַבִּי יִצְחָק, מִשּׁוּם כָּךְ, כָּל מִי שֶׁמַּעֲבִיר מֵאוֹתָם מִינִים רָעִים אוֹ רָשׁוּת אַחֶרֶת לָאָרֶץ, הָאָרֶץ נִטְמֵאת. אוֹי לְאוֹתוֹ הָאִישׁ! אוֹי לְנַפְשׁוֹ! שֶׁהֲרֵי הָאָרֶץ הַקְּדוֹשָׁה לֹא תְקַבֵּל אוֹתוֹ אַחַר כָּךְ, עָלָיו כָּתוּב (תהלים קד) יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ - בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וּרְשָׁעִים עוֹד אֵינָם - בִּתְחִיַּת הַמֵּתִים. אָז - בָּרְכִי נַפְשִׁי אֶת ה' הַלְלוּיָהּ.</p>"],[9522012137,"<p>אֶת מִשְׁפָּטַי תַּעֲשׂוּ וְאֶת חֻקֹּתַי תִּשְׁמְרוּ לָלֶכֶת בָּהֶם וְגוֹ'. רַבִּי אַבָּא אָמַר, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם מִכָּל הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, וּבִשְׁבִיל אַהֲבָתוֹ עֲלֵיהֶם נָתַן לָהֶם הַנְהָגוֹת אֱמֶת, נָטַע בָּהֶם אֶת עֵץ הַחַיִּים וְהִשְׁרָה שְׁכִינָתוֹ בֵינֵיהֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁיִּשְׂרָאֵל רְשׁוּמִים בְּרֹשֶׁם קָדוֹשׁ בִּבְשָׂרָם, וְנוֹדָעִים שֶׁהֵם שֶׁלּוֹ, (נודעים) מִבְּנֵי הֵיכָלוֹ.</p>\n<p>וּמִשּׁוּם כָּךְ, כָּל אוֹתָם שֶׁלֹּא רְשׁוּמִים בָּרֹשֶׁם הַקָּדוֹשׁ בִּבְשָׂרָם, הֵם אֵינָם שֶׁלּוֹ, וְנוֹדָעִים שֶׁכֻּלָּם מִצַּד הַטֻּמְאָה הֵם בָּאִים, וְאָסוּר לְהִתְחַבֵּר עִמָּהֶם וּלְדַבֵּר עִמָּם בְּדִבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָסוּר לְהוֹדִיעָם דִּבְרֵי תוֹרָה, כִּי הַתּוֹרָה כֻּלָּהּ שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכָל אוֹת שֶׁל הַתּוֹרָה נִקְשֶׁרֶת לַשֵּׁם הַקָּדוֹשׁ. וְכָל מִי שֶׁלֹּא רָשׁוּם בָּרֹשֶׁם הַקָּדוֹשׁ בִּבְשָׂרוֹ, אָסוּר לְהוֹדִיעוֹ דְּבַר תּוֹרָה, וְכָל שֶׁכֵּן לְהִתְעַסֵּק (להסתכל) עִמּוֹ.</p>"],[9522012138,"<p>רַבִּי שִׁמְעוֹן פָּתַח, (שמות יב) זֹּאת חֻקַּת הַפָּסַח כָּל בֶּן נֵכָר לֹא יֹאכַל בּוֹ, וְכָתוּב וְכָל עֶבֶד אִישׁ וְגוֹ', וְכָתוּב תּוֹשָׁב וְשָׂכִיר לֹא יֹאכַל בּוֹ. וּמַה פֶּסַח שֶׁהוּא בָּשָׂר לְמַאֲכָל, עַל שֶׁנִּרְמָז בְּדָבָר קָדוֹשׁ אָסוּר לְכָל אֵלֶּה לֶאֱכֹל בּוֹ וְלָתֵת לָהֶם לֶאֱכֹל עַד שֶׁיִּמּוֹלוּ - הַתּוֹרָה שֶׁהִיא קֹדֶשׁ קָדָשִׁים (של קדשים), הַשֵּׁם הָעֶלְיוֹן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>רַבִּי אֶלְעָזָר שָׁאַל אֶת רַבִּי שִׁמְעוֹן אָבִיו. אָמַר לוֹ, הֲרֵי שָׁנִינוּ שֶׁאָסוּר לְלַמֵּד תּוֹרָה לְעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, וְיָפֶה הֵעִירוּ הַחֲבֵרִים מִבָּבֶל, שֶׁכָּתוּב לֹא עָשָׂה כֵן לְכָל גּוֹי. אֲבָל כֵּיוָן שֶׁאָמַר מַגִּיד דְּבָרָיו לְיַעֲקֹב, לָמָּה חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל? אָמַר לוֹ, אֶלְעָזָר, בֹּא רְאֵה, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַחֵלֶק הָעֶלְיוֹן הַקָּדוֹשׁ הַזֶּה נָטַע בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב כִּי לֶקַח טוֹב נָתַתִּי לָכֶם, לָכֶם וְלֹא לְעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה.</p>\n<p>וּמִשּׁוּם שֶׁהִיא גְּנוּזָה עֶלְיוֹנָה נִכְבָּדָה, שְׁמוֹ מַמָּשׁ, הַתּוֹרָה כֻּלָּהּ נִסְתָּר וְנִגְלֶה בַּסּוֹד שֶׁל שְׁמוֹ, וְעַל כֵּן יִשְׂרָאֵל הֵם בִּשְׁתֵּי דְרָגוֹת, נִסְתָּר וְנִגְלֶה. שֶׁשָּׁנִינוּ, שָׁלֹשׁ דְּרָגוֹת הֵן שֶׁנִּקְשָׁרוֹת זוֹ בָּזוֹ: הַקָּדוֹשׁ בָּרוּךְ הוּא, תּוֹרָה וְיִשְׂרָאֵל. וְכָל אַחַת דַּרְגָּה עַל דַּרְגָּה, נִסְתָּר וְנִגְלֶה. הַקָּדוֹשׁ בָּרוּךְ הוּא דַּרְגָּה עַל דַּרְגָּה, נִסְתָּר וְנִגְלֶה. הַתּוֹרָה גַּם כֵּן נִסְתָּר וְנִגְלֶה. יִשְׂרָאֵל גַּם כֵּן דַּרְגָּה עַל דַּרְגָּה. זֶהוּ שֶׁכָּתוּב (תהלים קמז) מַגִּיד דְּבָרָיו לְיַעֲקֹב חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל. שְׁתֵּי דְרָגוֹת הֵן - יַעֲקֹב וְיִשְׂרָאֵל, אֶחָד גָּלוּי וְאֶחָד נִסְתָּר.</p>\n<p>מַה זֶּה אוֹמֵר? אֶלָּא כָּל מִי שֶׁנִּמּוֹל וְנִרְשָׁם בַּשֵּׁם (ברשם) הַקָּדוֹשׁ, נוֹתְנִים לוֹ בְּאוֹתָם דְּבָרִים שֶׁהִתְגַּלּוּ בַתּוֹרָה, כְּלוֹמַר, מוֹדִיעִים לוֹ בְּרָאשֵׁי אוֹתִיּוֹת וּבְרָאשֵׁי פְרָקִים, נוֹתְנִים עָלָיו חֻמְרָה שֶׁל מִצְווֹת הַתּוֹרָה, וְלֹא יוֹתֵר, עַד שֶׁיִּתְעַלֶּה לְדַרְגָּה אַחֶרֶת. זֶהוּ שֶׁכָּתוּב מַגִּיד דְּבָרָיו לְיַעֲקֹב (ליעקב יפה). אֲבָל חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל, שֶׁהוּא בְּדַרְגָּה יוֹתֵר עֶלְיוֹנָה, וְכָתוּב (בראשית לב) לֹא יִקָּרֵא שִׁמְךְ עוֹד יַעֲקֹב וְגוֹ'. חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל, אֵלּוּ סוֹדוֹת הַתּוֹרָה וְהַנְהָגוֹת הַתּוֹרָה וְסִתְרֵי תוֹרָה, שֶׁלֹּא יִצְטָרְכוּ לְגַלּוֹת אֶלָּא לְמִי שֶׁהוּא בְּדַרְגָּה יוֹתֵר עֶלְיוֹנָה כָּרָאוּי.</p>\n<p>וּמַה לְּיִשְׂרָאֵל כָּזֶה, לְעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה עַל אַחַת כַּמָּה וְכַמָּה. וְכָל מִי שֶׁלֹּא נִמּוֹל וְנוֹתְנִים לוֹ אֲפִלּוּ אוֹת קְטַנָּה שֶׁל הַתּוֹרָה, כְּאִלּוּ הֶחֱרִיב עוֹלָם וּמְשַׁקֵּר בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהַכֹּל תָּלוּי בָּזֶה, וְזֶה בָּזֶה נִקְשָׁר, שֶׁכָּתוּב (ירמיהלג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי.</p>\n<p>בֹּא רְאֵה, כָּתוּב וְזֹּאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה לִפְנֵי בְּנֵי יִשְׂרָאֵל. לִפְנֵי בְּנֵי יִשְׂרָאֵל שָׂם, אֲבָל לִשְׁאָר הָעַמִּים לֹא שָׂם. מִשּׁוּם כָּךְ דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל. (ויקרא ב) וְאֶל בְּנֵי יִשְׂרָאֵל תֹּאמַר. וְכֵן כֻּלָּם. יָנוּחוּ אֲבוֹת הָעוֹלָם, הֵם הִלֵּל וְשַׁמַּאי, שֶׁכָּךְ אָמְרוּ לְאוּנְקְלוּס, וְלֹא הוֹדִיעוּ לוֹ דְּבַר תּוֹרָה עַד שֶׁנִּמּוֹל.</p>\n<p>וּבֹא רְאֵה, הַדָּבָר הָרִאשׁוֹן שֶׁל הַתּוֹרָה שֶׁנּוֹתְנִים לַתִּינוֹקוֹת אָלֶ\"ף בֵּי\"ת, זֶה דָּבָר שֶׁאֵין בְּנֵי הָעוֹלָם יְכוֹלִים לְהַשִּׂיג בְּשִׂכְלָם וּלְהַעֲלוֹתוֹ בְרָצוֹן, וְכָל שֶׁכֵּן לְדַבֵּר אוֹתוֹ בְּפִיהֶם, וַאֲפִלּוּ מַלְאָכִים עֶלְיוֹנִים וְעֶלְיוֹנֵי הָעֶלְיוֹנִים אֵין יְכוֹלִים לְהַשִּׂיג, כִּי הֵם נִסְתְּרוֹת הַשֵּׁם הַקָּדוֹשׁ. וְאֶלֶף וְאַרְבַּע מֵאוֹת וְחָמֵשׁ רְבָבוֹת שֶׁל עוֹלָמוֹת, כֻּלָּם תְּלוּיִים בְּקוֹצוֹ שֶׁל אָלֶ\"ף, וְשִׁבְעִים וּשְׁנַיִם שֵׁמוֹת קְדוֹשִׁים חֲקוּקִים בְּאוֹתִיּוֹתָיו רְשׁוּמִים, שֶׁעָמְדוּ בָהֶם עֶלְיוֹנִים וְתַחְתּוֹנִים, שָׁמַיִם וָאָרֶץ, וְכִסֵּא הַכָּבוֹד שֶׁל הַמֶּלֶךְ, תְּלוּיִים מִצַּד אֶחָד לְצַד אֶחָד, שֶׁפְּשִׁיטוּת הָאָלֶף קִיּוּמָם שֶׁל כָּל הָעוֹלָמוֹת, וְתוֹמְכִים שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים בְּסוֹד הַחָכְמָה.</p>\n<p>וּשְׁבִילִים נִסְתָּרִים וּנְהָרוֹת עֲמֻקִּים וְעֶשֶׂר אֲמִירוֹת, כֻּלָּם יוֹצְאִים מֵאוֹתוֹ קוֹץ תַּחְתּוֹן שֶׁתַּחַת הָאָלֶף. מִכָּאן וָהָלְאָה מַתְחִיל לְהִתְפַּשֵּׁט אָלֶף בְּבֵי\"ת, וְאֵין חֶשְׁבּוֹן לַחָכְמָה שֶׁנֶּחְקְקָה כָּאן.</p>\n<p>מִשּׁוּם כָּךְ הַתּוֹרָה הִיא הַקִּיּוּם שֶׁל הַכֹּל וֶאֱמוּנַת הַכֹּל, לִקְשֹׁר קֶשֶׁר שֶׁל הָאֱמוּנָה זֶה עִם זֶה כָּרָאוּי. וּמִי שֶׁנִּמּוֹל, נִקְשָׁר בְּאוֹתוֹ קֶשֶׁר הָאֱמוּנָה. וּמִי שֶׁלֹּא נִמּוֹל וְלֹא נִקְשָׁר בּוֹ, כָּתוּב בּוֹ (ויקרא כב) וְכָל זָר לֹא יֹאכַל קֹדֶשׁ. (שמות יג) וְעָל עָרֵל לֹא יֹאכַל בּוֹ. שֶׁהֲרֵי הִתְעוֹרְרָה רוּחַ הַטֻּמְאָה שֶׁמִּצִּדּוֹ, וּבָא לְהִתְעָרֵב בַּקְּדֻשָּׁה. בָּרוּךְ הָרַחֲמָן שֶׁהִפְרִיד אֶת יִשְׂרָאֵל בָּנָיו, רְשׁוּמִים בְּרֹשֶׁם קָדוֹשׁ, מֵהֶם וּמִזֻּהַמְתָּם. עֲלֵיהֶם כָּתוּב, (ירמיה כ) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלֹּה זֶרַע אֱמֶת. וּמִשּׁוּם כָּךְ, (מיכהז) תִּתֵּן אֱמֶת לְיַעֲקֹב, וְלֹא לְאַחֵר. תּוֹרַת אֱמֶת, לְזֶרַע אֱמֶת. בָּא רַבִּי אֶלְעָזָר וּנְשָׁקוֹ עַל יָדוֹ.</p>\n<p>רַבִּי חִזְקִיָּה אָמַר, כָּתוּב (שמואל א יב) כִּי לֹא יִטֹּשׁ ה' אֶת עַמּוֹ בַּעֲבוּר שְׁמוֹ וְגוֹ'. כִּי לֹא יִטֹּשׁ ה' אֶת עַמּוֹ, מָה הַטַּעַם בַּעֲבוּר שְׁמוֹ הַגָּדוֹל? כִּי הַכֹּל נִקְשָׁר זֶה עִם זֶה. וּבַמֶּה נִקְשְׁרוּ יִשְׂרָאֵל בַּקָּדוֹשׁ בָּרוּךְ הוּא? בְּאוֹתוֹ רֹשֶׁם קָדוֹשׁ שֶׁנִּרְשָׁם בִּבְשָׂרָם, וּמִשּׁוּם כָּךְ לֹא יִטֹּשׁ ה' אֶת עַמּוֹ. וְלָמָּה? בַּעֲבוּר שְׁמוֹ הַגָּדוֹל שֶׁנִּרְשָׁם בָּהֶם.</p>\n<p>לָמַדְנוּ, הַתּוֹרָה נִקְרֵאת בְּרִית, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא בְּרִית, וְהָרֹשֶׁם הַקָּדוֹשׁ הַזֶּה נִקְרָא בְּרִית. וְלָכֵן הַכֹּל נִקְשָׁר זֶה עִם זֶה וְלֹא נִפְרָד זֶה מִזֶּה. אָמַר לוֹ רַבִּי יֵיסָא, תּוֹרָה וְיִשְׂרָאֵל - יָפֶה, אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא מִנַּיִן לָנוּ שֶׁנִּקְרָא בְּרִית? אָמַר לוֹ, שֶׁכָּתוּב (תהלים קו) וַיִּזְכֹּר לָהֶם בְּרִיתוֹ, וַהֲרֵי נוֹדָע, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>וְאֶת חֻקֹּתַי תִּשְׁמְרוּ (ויקרא יח). חֻקֹּתַי - אֵלּוּ הֵן הַנְהָגוֹת הַמֶּלֶךְ. מִשְׁפָּטַי - אֵלּוּ הֵן גְּזֵרוֹת הַתּוֹרָה. רַבִּי יְהוּדָה אָמַר, כָּל אוֹתָן הַנְהָגוֹת שֶׁנִּקְרָאוֹת צֶדֶק, נִקְרְאוּ חֻקֹּתַי, וְהֵן גְּזֵרַת הַמֶּלֶךְ. וּבְכָל מָקוֹם שֶׁנִּקְרָא מִשְׁפָּט, הֵן נִקְרָאוֹת דִּינוֹ שֶׁל הַמֶּלֶךְ, שֶׁהוּא הַמֶּלֶךְ הַקָּדוֹשׁ, הַקָּדוֹשׁ בָּרוּךְ הוּא הַמֶּלֶךְ שֶׁכָּל הַשָּׁלוֹם שֶׁלּוֹ, שֶׁהוּא הַמֶּלֶךְ הַקָּדוֹשׁ בְּמָקוֹם שֶׁשְּׁנֵי חֲלָקִים אֲחוּזִים זֶה עִם זֶה. וְעַל זֶה כָּתוּב, (תהלים פט) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךְ, וְהֵם דִּין וְרַחֲמִים. וּמִשּׁוּם כָּךְ חֹק וּמִשְׁפָּט. וְעַל זֶה כָּתוּב, (שם קמז) חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל. לְיִשְׂרָאֵל וְלֹא לִשְׁאָר הָעַמִּים.</p>\n<p>מַה כָּתוּב אַחֲרָיו? לֹא עָשָׂה כֵן לְכָל גּוֹי. וְשָׁנִינוּ, אַף עַל גַּב שֶׁנִּמּוֹל וְלֹא עָשָׂה אֶת מִצְווֹת הַתּוֹרָה, הֲרֵי הוּא כְּמוֹ גּוֹי בַּכֹּל, וְאָסוּר לְלַמְּדוֹ דִּבְרֵי תוֹרָה. וְעַל זֶה שָׁנִינוּ, (שמות כ) מִזְבַּח אֲבָנִים, זֶה מִזְבַּח אֲבָנִים מַמָּשׁ. וַהֲרֵי קְשִׁי הַלֵּב עוֹמֵד בִּמְקוֹמוֹ, וְהַזֻּהֲמָה לֹא פָסְקָה מִמֶּנּוּ. מִשּׁוּם כָּךְ לֹא עוֹלָה בְיָדוֹ אוֹתָהּ מִילָה וְלֹא מוֹעִילָה לוֹ. וְעַל זֶה כָּתוּב, כִּי חַרְבְּךְ הֵנַפְתָּ עָלֶיהָ וַתְּחַלְלֶהָ.</p>\n<p>מִשּׁוּם כָּךְ, לֹא עָשָׂה כֵן לְכָל גּוֹי סְתָם. וּמִשְׁפָּטִים בַּל יְדָעוּם, לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. דָּבָר אַחֵר (קטן), לֹא נוֹתְנִים לָהֶם כָּל שֶׁכֵּן סוֹדוֹת תּוֹרָה וְהַנְהָגוֹת הַתּוֹרָה. וְכָתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ, (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו.</p>"],[9522012139,"<p>מִשְׁנָה, בְּדַרְכֵי הָאוֹרוֹת הָעֶלְיוֹנִים. אַרְבָּעָה מַפְתְּחוֹת נַעֲשׂוּ לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וּבְזָוִיּוֹתֵיהֶם נִמְצָאִים אֶחָד לְצַד אַרְבָּעָה, וְאַרְבָּעָה לְצַד אֶחָד. נֶחְקָקִים (נחלקו) בְּגָוֶן אֶחָד. בְּאוֹתוֹ גָּוֶן, תְּכֵלֶת וְאַרְגָּמָן וְצֶבַע זוֹהֵר וְלָבָן וְאָדם. זֶה נִכְנָס לַגָּוֶן שֶׁל חֲבֵרוֹ, וְשֶׁלּוֹ רָשׁוּם בּוֹ.</p>\n<p>אַרְבָּעָה רָאשִׁים עָלוּ כְאֶחָד, וּבִדְיוֹקָן אֶחָד נִדְבָּקִים. רֹאשׁ אֶחָד עוֹלֶה מִתּוֹךְ הָרַחְצָה שֶׁרוֹחֵץ. שְׁתֵּי אַיָּלוֹת קְצוּבוֹת בְּשִׁעוּר אֶחָד עוֹלוֹת מֵאוֹתָהּ רַחְצָה, שֶׁכָּתוּב (שיר ד) כְּעֵדֶר הַקְּצוּבוֹת שֶׁעָלוּ מִן הָרַחְצָה. בַּשֵּׂעָר שֶׁלָּהֶם מַרְאֶה שֶׁל אֶבֶן טוֹבָה שֶׁל אַרְבָּעָה גְוָנִים.</p>\n<p>אַרְבַּע כְּנָפַיִם שֶׁמְּכַסּוֹת עַל הַגּוּף, וְיָדַיִם קְטַנּוֹת תַּחַת כַּנְפֵיהֶם. וְחָמֵשׁ בְּחָמֵשׁ חֲקוּקִים. טָסִים (שואפים) לְמַעְלָה לְמַעְלָה מִן הַהֵיכָל, שֶׁהוּא יְפֵה תֹאַר וְנָאֶה לְמַרְאֶה.</p>\n<p>עָלֶם אֶחָד יֶלֶד יוֹצֵא שְׁנוּן חֶרֶב, שֶׁמִּתְהַפֶּכֶת לִגְבָרִים וְלִנְקֵבוֹת. לוֹקְחִים מְדִידַת הָאֵיפָה בֵּין שָׁמַיִם וּבֵין אָרֶץ. לִפְעָמִים לוֹקְחִים (עולים) לָהּ בְּכָל הָעוֹלָם, וְכָל הַמְּדִידוֹת מוֹדְדִים בָּהּ, שֶׁכָּתוּב אֵיפַת צֶדֶק וְגוֹ'.</p>\n<p>מַרְאֶה אֶחָד שֶׁל בְּדוֹלַח עוֹמֵד עַל חֶרֶב אַחַת, בְּרֹאשׁ אוֹתוֹ יֶלֶד (חרב) מְלַהֵט אָדם מִתּוֹךְ הַבְּדוֹלַח. שְׁנֵי צְדָדִים מִצַּד זֶה וּמִצַּד זֶה, נִרְאֵית אוֹתָהּ הַחֶרֶב בִּרְשָׁמִים עֲמֻקִּים, גֶּבֶר אֶחָד תַּקִּיף, סֻלָּם שֶׁעוֹמֵד בִּשְׁלֹשָׁה עָשָׂר עוֹלָמוֹת חָגוּר אוֹתָהּ הַחֶרֶב לַעֲשׂוֹת נְקָמוֹת, וְעִמּוֹ חֲגוּרִים שִׁשִּׁים אֲחֵרִים, כֻּלָּם מֻחְלָפִים (מלמדי) (שולפי) מְנַצְּחֵי קְרָב. זֶהוּ שֶׁכָּתוּב (תהלים מה) חֲגוֹר חַרְבְּךְ עַל יָרֵךְ גִּבּוֹר הוֹדְךְ וַהֲדָרֶךְ. וְכָתוּב (שיר ג) כֻּלָּם אֲחֻזֵי חֶרֶב מְלֻמְּדֵי מִלְחָמָה וְגוֹ'. בְּכַמָּה גְוָנִים מִתְהַפְּכִים פְּנֵיהֶם, שֶׁאֵין מַכִּיר אוֹתָם פְּרָט לְתוֹלַעַת אַחַת שֶׁשָּׁטָה (ששורה) בֵּין דְּגֵי הַיָּם, כָּל הָאֲבָנִים שֶׁעוֹבְרוֹת עֲלֵיהֶם נִבְקָעוֹת.</p>\n<p>בְּאוֹתוֹ זְמַן הַקּוֹל שֶׁיּוֹצֵא מֵאוֹתָם חֲגוּרֵי הַחֶרֶב, מְבַקֵּעַ שְׁמוֹנָה עָשָׂר הָרִים גְּדוֹלִים, וְאֵין מִי שֶׁיַּרְכִּין אָזְנָיו. כָּל הָעוֹלָם סְתוּמֵי עֵינַיִם, אֲטוּמֵי לֵב, אֵין מִי שֶׁיַּשְׁגִּיחַ, שֶׁהֲרֵי הַבִּנְיָן סָתוּר כְּשֶׁעוֹשִׂים מַעֲשִׂים שֶׁאֵינָם כְּשֵׁרִים, סוֹטִים מִדֶּרֶךְ תְּקִינָה, הַיָּמִין סָרָה וְהַשְּׂמֹאל שׁוֹלֶטֶת, וְאָז מְצוּיוֹת עֲרָיוֹת. אוֹי לָרְשָׁעִים שֶׁגּוֹרְמִים אֶת זֶה בָּעוֹלָם, שֶׁהֲרֵי אֵין מִתְבָּרְכִים לְמַעְלָה עַד שֶׁיִּכְלוּ אוֹתָם לְמַטָּה. זֶהוּ שֶׁכָּתוּב (תהלים קד) וּרְשָׁעִים עוֹד אֵינָם בָּרְכִי נַפְשִׁי אֶת ה' הַלְלוּיָהּ. (עד כאן)</p>"],[9522012140,"<p>עָרְוַת אָבִיךְ וְעֶרְוַת אִמְּךְ לֹא תְגַלֵּה. רַבִּי חִיָּיא פָּתַח, (שיר ב) כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר כֵּן דּוֹדִי בֵּין הַבָּנִים וְגוֹ'. אֶת הַפָּסוּק הַזֶּה בֵּאֲרוּ הַחֲבֵרִים, אֲבָל כַּמָּה חֲבִיבָה כְּנֶסֶת יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהִיא מְשַׁבַּחַת אוֹתוֹ בָּזֶה. כָּאן יֵשׁ לְהִתְבּוֹנֵן, לָמָּה הִיא מְשַׁבַּחַת אוֹתוֹ בְּתַפּוּחַ וְלֹא בְּדָבָר אַחֵר, אוֹ בִּגְוָנִים אוֹ בְּרֵיחַ אוֹ בְּטַעַם?</p>\n<p>אֲבָל הוֹאִיל וְכָתוּב תַּפּוּחַ, בַּכֹּל הִיא מְשַׁבַּחַת אוֹתוֹ - בַּגְּוָנִים, בָּרֵיחַ, וּבַטַּעַם. מַה תַּפּוּחַ הוּא רְפוּאָה לַכֹּל - אַף הַקָּדוֹשׁ בָּרוּךְ הוּא רְפוּאָה לַכֹּל. מַה תַּפּוּחַ נִמְצָא בִּגְוָנִים, כְּמוֹ שֶׁבֵּאַרְנוּ - אַף הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בִּגְוָנִים עֶלְיוֹנִים. מַה תַּפּוּחַ יֵשׁ בּוֹ רֵיחַ דַּק מִכָּל שְׁאָר הָעֵצִים - אַף הַקָּדוֹשׁ בָּרוּךְ הוּא כָּתוּב בּוֹ וְרֵיחַ לוֹ כַּלְּבָנוֹן. מַה תַּפּוּחַ טַעֲמוֹ מָתוֹק - אַף הַקָּדוֹשׁ בָּרוּךְ הוּא כָּתוּב בּוֹ חִכּוֹ מַמְתַּקִּים.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְשַׁבֵּחַ אֶת כְּנֶסֶת יִשְׂרָאֵל כְּמוֹ שׁוֹשַׁנָּה, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים לָמָּה כְּמוֹ שׁוֹשַׁנָּה, וַהֲרֵי נִתְבָּאֵר. רַבִּי יְהוּדָה אָמַר, בְּשָׁעָה שֶׁמִּתְרַבִּים צַדִּיקִים בָּעוֹלָם, כְּנֶסֶת יִשְׂרָאֵל מַעֲלָה רֵיחוֹת טוֹבִים, וּמִתְבָּרֶכֶת מִן הַמֶּלֶךְ הַקָּדוֹשׁ, וּפָנֶיהָ מְאִירִים. וּבִזְמַן שֶׁמִּתְרַבִּים הָרְשָׁעִים בָּעוֹלָם, כִּבְיָכוֹל אֵין כְּנֶסֶת יִשְׂרָאֵל מַעֲלָה רֵיחוֹת טוֹבִים, וְטוֹעֶמֶת מֵהַצַּד הָאַחֵר הַמַּר, אָז כָּתוּב (איכה ב) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ וְגוֹ', וּפָנֶיהָ חֲשׁוּכִים.</p>\n<p>רַבִּי יוֹסֵי אָמַר, בְּשָׁעָה שֶׁמִּתְרַבִּים צַדִּיקִים בָּעוֹלָם, כָּתוּב (שם ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. וּבִזְמַן שֶׁמִּתְרַבִּים רְשָׁעִים בָּעוֹלָם, כָּתוּב הֵשִׁיב אָחוֹר יְמִינוֹ. רַבִּי חִזְקִיָּה אָמַר מִכָּאן, (משלי יז) וְנִרְגָּן מַפְרִיד אַלּוּף, כְּלוֹמַר, מַפְרִיד אֶת הַמֶּלֶךְ מֵהַגְּבִירָה. זֶהוּ שֶׁכָּתוּב עֶרְוַת אָבִיךְ וְעֶרְוַת אִמְּךְ לֹא תְגַלֵּה.</p>"],[9522012141,"<p>רַבִּי אֶלְעָזָר הָיָה יוֹשֵׁב לִפְנֵי אָבִיו. אָמַר לוֹ, אִם פְּרַקְלִיט יֵשׁ בָּעוֹלָם, הוּא נִמְצָא עִם הַגְּבִירָה. וְאִם יֵשׁ בָּעוֹלָם קָטֵגוֹר, הוּא נִמְצָא עִם הַגְּבִירָה. לָמָּה? אָמַר לוֹ, לְמֶלֶךְ שֶׁהָיָה לוֹ בֵּן מִן הַגְּבִירָה - כָּל זְמַן שֶׁאוֹתוֹ הַבֵּן עוֹשֶׂה אֶת רְצוֹן הַמֶּלֶךְ, הַמֶּלֶךְ שָׂם מְדוֹרוֹ עִם הגבירה. וכל זמן שאותו בן לא עוֹשֶׂה אֶת רְצוֹן הַמֶּלךְ, מַפְרִיד אֶת מְדוֹרוֹ מִן הַגְּבִירָה.</p>\n<p>כָּךָ הַקָּדוֹשׁ בָּרוּךְ הוּא עִם כְּנֶסֶת יִשְׂרָאֵל - כָּל זְמַן שֶׁיִּשְׂרָאֵל עוֹשִׂים אֶת רְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הַקָּדוֹשׁ בָּרוּךְ הוּא שָׂם מְדוֹרוֹ עִם כְּנֶסֶת יִשְׂרָאֵל. וְכָל זְמַן שֶׁאֵין יִשְׂרָאֵל עוֹשִׂים אֶת רְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵין הַקָּדוֹשׁ בָּרוּךְ הוּא שָׂם מְדוֹרוֹ עִם כְּנֶסֶת יִשְׂרָאֵל. מָה הַטַּעַם? כִּי יִשְׂרָאֵל הוּא בְּנוֹ הַבְּכוֹר שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב בְּנִי בְכֹרִי יִשְׂרָאֵל. הָאֵם זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁכָּתוּב (משלי א) וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ.</p>\n<p>בֹּא רְאֵה, כָּל זְמַן שֶׁיִּשְׂרָאֵל רְחוֹקִים מֵהֵיכַל הַמֶּלֶךְ, כִּבְיָכוֹל הַגְּבִירָה הִתְרַחֲקָה עִמָּהֶם. מָה הַטַּעַם? כִּי הַגְּבִירָה לֹא הִקְדִּימָה שִׁבְטָהּ לַבֵּן הַזֶּה לְהַלְקוֹתוֹ כְּדֵי לָלֶכֶת בְּדֶרֶךְ יְשָׁרָה, כִּי הַמֶּלֶךְ לֹא מַלְקֶה אֶת בְּנוֹ לְעוֹלָמִים, אֶלָּא מַשְׁאִיר הַכֹּל בְּיַד הַגְּבִירָה לְהַנְהִיג אֶת הַהֵיכָל וּלְהַלְקוֹת אֶת בְּנָהּ וּלְהַנְהִיגוֹ בְּדֶרֶךְ הָאֱמֶת כְּנֶגֶד הַמֶּלֶךְ.</p>\n<p>וְסוֹד הַדָּבָר - שֶׁכָּתוּב (משלי לא) דִּבְרֵי לְמוּאֵל מֶלֶךְ מַשָּׂא אֲשֶׁר יִסְּרַתּוּ אִמּוֹ, (אמו ודאי) זוֹ בַּת שֶׁבַע, וַהֲרֵי נֶאֱמַר הַכָּתוּב (שם י) מִשְׁלֵי שְׁלֹמֹה בֵּן חָכָם יְשַׂמַּח אָב וּבֵן כְּסִיל תּוּגַת אִמּוֹ. תּוּגַת אִמּוֹ וַדַּאי. רְאֵה מַה כָּתוּב, בֵּן חָכָם יְשַׂמַּח אָב. בְּעוֹד שֶׁהַבֵּן הַזֶּה הוֹלֵךְ בְּדֶרֶךְ יְשָׁרָה וְהוּא חָכָם - יְשַׂמַּח אָב (כלל), זֶה הַמֶּלֶךְ הַקָּדוֹשׁ לְמַעְלָה. יְשַׂמַּח אָב סְתָם. נִמְצָא הַבֵּן הַזֶּה בְּדֶרֶךְ כּוֹשֶׁלֶת - מַה כָּתוּב? וּבֵן כְּסִיל תּוּגַת אִמּוֹ. תּוּגַת אִמּוֹ וַדַּאי, זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְסוֹד הַדָּבָר כָּתוּב, (ישעיה נ) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם.</p>\n<p>בֹּא רְאֵה, לֹא נִמְצֵאת שִׂמְחָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ הַיּוֹם שֶׁעָלָה שְׁלֹמֹה לַחָכְמָה וְאָמַר שִׁיר הַשִּׁירִים. אָז הֵאִירוּ פְּנֵי הַגְּבִירָה, וּבָא הַמֶּלֶךְ לְהַשְׁרוֹת אֶת מְדוֹרוֹ עִמָּהּ. זֶהוּ שֶׁכָּתוּב (מלכים א ד) וַתֵּרֶב חָכְמַת שְׁלֹמֹה וְגוֹ'. מַה זֶּה וַתֵּרֶב? שֶׁעָלָה הַיֹּפִי שֶׁל הַגְּבִירָה וְהִתְגַּדְּלָה בְדַרְגוֹתֶיהָ עַל כָּל שְׁאָר הַדְּרָגוֹת, כִּי הַמֶּלֶךְ שָׂם אֶת מְדוֹרוֹ עִמָּהּ. וְכָל כָּךְ לָמָּה? כִּי הוֹצִיאָה אֶת הַבֵּן הֶחָכָם הַזֶּה לָעוֹלָם (למלך).</p>\n<p>וּכְשֶׁהוֹצִיאָה אֶת שְׁלֹמֹה, הִיא הוֹצִיאָה לְכָל יִשְׂרָאֵל, וְכֻלָּם הָיוּ בִּדְרָגוֹת עֶלְיוֹנוֹת צַדִּיקִים כִּשְׁלֹמֹה (בשלום), שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׂמֵחַ בָּהֶם, וְהֵם בּוֹ. וּבַיּוֹם שֶׁתִּקֵּן שְׁלֹמֹה אֶת הַבַּיִת לְמַטָּה, תִּקְּנָה הַגְּבִירָה בַּיִת לַמֶּלֶךְ, וְשָׂמוּ מְדוֹרָם יַחַד, וְהֵאִירוּ פָּנֶיהָ בְּשִׂמְחָה וּשְׁלֵמוּת. אָז נִמְצְאָה שִׂמְחָה לַכֹּל, לְמַעְלָה וּלְמַטָּה. וְכָל כָּךְ לָמָּה? כִּי כָתוּב מַשָּׂא אֲשֶׁר יִסְּרַתּוּ אִמּוֹ, שֶׁהִנְהִיגָה אוֹתוֹ לִרְצוֹן הַמֶּלֶךְ.</p>\n<p>וּכְשֶׁהַבֵּן הַזֶּה, כְּמוֹ שֶׁאָמַרְנוּ (שצריך), אֵינוֹ מִתְנַהֵג לִרְצוֹן הַמֶּלֶךְ, אָז זוֹ עֶרְוַת הַכֹּל, עֶרְוַת כָּל הַצְּדָדִים, שֶׁהֲרֵי הַמֶּלֶךְ פּוֹרֵשׁ מֵהַגְּבִירָה, וְהַגְּבִירָה הִתְרַחֲקָה מֵהֵיכָלוֹ, וּמִשּׁוּם כָּךְ זוֹהִי עֶרְוַת הַכֹּל. וְכִי אֵין זוֹ עֶרְוָה, מֶלֶךְ בְּלִי גְבִירָה, וּגְבִירָה בְּלִי מֶלֶךְ?! וְעַל זֶה כָּתוּב, עֶרְוַת אָבִיךְ וְעֶרְוַת אִמְּךְ לֹא תְגַלֵּה אִמְּךְ הִיא. אִמְּךְ הִיא וַדַּאי, וְשׁוֹרָה עִמְּךְ. מִשּׁוּם כָּךְ לֹא תְגַלֶּה עֶרְוָתָהּ.</p>"],[9522012142,"<p>רַבִּי שִׁמְעוֹן הִקִּישׁ יָדָיו וּבָכָה וְאָמַר: אוֹי אִם אֹמַר וַאֲגַלֶּה סוֹד, אוֹי אִם לֹא אֹמַר, שֶׁיֹּאבְדוּ הַחֲבֵרִים דָּבָר. (יחזקאל יא) אֲהָהּ ה' אֱלֹהִים כָּלָה אַתָּה עֹשֶׂה אֵת שְׁאֵרִית יִשְׂרָאֵל. מַה זֶּה אֲהָהּ? וּמַה זֶּה כָּלָה אַתָּה עֹשֶׂה? אֶלָּא סוֹד הַדָּבָר - בִּזְמַן שֶׁה' תַּחְתּוֹנָה הִתְגָּרְשָׁה מֵהֵיכַל הַמֶּלֶךְ, ה' אַחֶרֶת עֶלְיוֹנָה מוֹנַעַת בִּרְכָתָהּ, וְאָז כָּתוּב, אֲהָהּ כָּלָה אַתָּה עֹשֶׂה. מִשּׁוּם שֶׁכְּשֶׁהִיא (הה' הזאת) נִמְנַעַת מִבְּרָכוֹת, ה' אַחֶרֶת מוֹנַעַת אוֹתָם מֵהַכֹּל. מָה הַטַּעַם? כִּי בְרָכוֹת אֵינָן מְצוּיוֹת, אֶלָּא בְּמָקוֹם שֶׁשּׁוֹרִים זָכָר וּנְקֵבָה.</p>\n<p>וְעַל זֶה כָּתוּב, (ירמיה כה) ה' מִמָּרוֹם יִשְׁאָג וּמִמְּעוֹן קָדְשׁוֹ יִתֵּן קוֹלוֹ שָׁאֹג יִשְׁאַג עַל נָוֵהוּ. עַל נָוֵהוּ מַמָּשׁ. זוֹ הַגְּבִירָה, וְזֶהוּ וַדַּאי. וּמַהוּ אוֹמֵר? אוֹי שֶׁהֶחֱרַבְתִּי אֶת בֵּיתִי וְכוּ'. בֵּיתִי זֶהוּ זִוּוּג הַגְּבִירָה. וְזֶהוּ וַדַּאי עֶרְוַת אָבִיךְ וְעֶרְוַת אִמְּךְ לֹא תְגַלֵּה. שֶׁהֲרֵי מִכָּל הַצְּדָדִים זוֹ עֶרְוָה. וְאָז, לָבְשׁוּ שָׁמַיִם קַדְרוּת וְשַׂק הוּשַׂם כְּסוּתָם, שֶׁהֲרֵי מְקוֹם יְרֻשַּׁת הַבְּרָכוֹת שֶׁל מַעַיְנוֹת הַנְּחָלִים שֶׁהָיוּ שׁוֹפְעִים וּמַשְׁקִים כָּרָאוּי, נִמְנְעוּ.</p>\n<p>שָׁנִינוּ, כְּשֶׁנִּפְרָד הַמֶּלֶךְ מִן הַגְּבִירָה וְאֵין בְּרָכוֹת מְצוּיוֹת, אָז נִקְרָא ו\"י. מָה הַטַּעַם ו\"י? שֶׁלָּמַדְנוּ, רֹאשׁ הַיְסוֹד י', שֶׁהֲרֵי יְסוֹד הוּא ו' קְטַנָּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא ו' גְּדוֹלָה עֶלְיוֹנָה. וְלָכֵן כָּתוּב ו\"ו, שְׁתֵּי וָוִי\"ם כְּאֶחָד. וְהָרֹאשׁ שֶׁל הַיְסוֹד הַזֶה הוּא י'. וּכְשֶׁמִּתְרַחֶקֶת הַגְּבִירָה מִן הַמֶּלֶךְ וְהַבְּרָכוֹת נִמְנָעוֹת מִן הַמֶּלֶךְ, וְהַזִּוּוּג לֹא נִמְצָא בְּרֹאשׁ הַיְסוֹד, נוֹטֵל ו' הָעֶלְיוֹן אֶת הָרֹאשׁ הַזֶּה שֶׁל הַיְסוֹד, שֶׁהוּא י', וּמַשְׁפִּיעוֹ אֵלָיו, וְאָז הוּא ו\"י, ו\"י לַכֹּל, לָעֶלְיוֹנִים וְלַתַּחְתּוֹנִים.</p>\n<p>וְעַל זֶה שָׁנִינוּ, מִיּוֹם שֶׁחָרְבָה יְרוּשָׁלַיִם לֹא נִמְצְאוּ בְרָכוֹת בָּעוֹלָם, וְאֵין לְךְ יוֹם שֶׁלֹּא מְצוּיִים בּוֹ קְלָלוֹת, שֶׁהֲרֵי הַבְּרָכוֹת מְנוּעוֹת בְּכָל יוֹם. אָמַר לוֹ, אוֹ כָּךְ: אוֹ\"י, אוֹ: הוֹ\"י. (או וה') מַה הוּא?</p>\n<p>אָמַר לוֹ, כְּשֶׁהַדָּבָר תָּלוּי בִּתְשׁוּבָה וְלֹא שָׁבִים, אָז ה' הָעֶלְיוֹנָה נוֹטֶלֶת אוֹתָם וּמַשְׁפִּיעָה לְוָא\"ו וְי' אֵלֶיהָ, כִּי לֹא שָׁבִים, וְאָז נִקְרָא הוֹי. הוֹי כְּשֶׁהִסְתַּלֵּק הַמֶּלֶךְ לְמַעְלָה לְמַעְלָה, וְצוֹוְחִים בְּנֵי אָדָם וְאֵין מַשְׁגִּיחַ בָּהֶם. וְאוֹתוֹ הָעֶלְיוֹן אֶהְיֶה הוּא הַטָּמִיר, מַעֲלֶה לְו', וְי' אֵלָיו, כִּי לֹא הִתְקַבְּלָה תְפִלָּתוֹ, אָז נִקְרָא אוֹי, שֶׁהֲרֵי א' עוֹלֶה לְו' וְי', (שהיאא'עולהלה'לו'לי') וְאָז אֵין מְצוּיָה תְשׁוּבָה, וְלָכֵן הִסְתַּלְּקָה מֵהָאוֹתִיּוֹת הַלָּלוּ ה', שֶׁהֲרֵי לֹא תָלוּי בִּתְשׁוּבָה.</p>\n<p>וַדַּאי כְּשֶׁהִתְרַבּוּ יוֹתֵר חֲטָאֵי הָעוֹלָם, וּתְשׁוּבָה הָיְתָה תְלוּיָה בָּרִאשׁוֹנָה וְלֹא רָצוּ, אֲזַי הִסְתַּלְּקָה ה', וְא' הֶעֶלְתָה אֶת ו' וְיוֹ\"ד אֵלָיו, וְנִקְרָא אוֹי. וּכְשֶׁחָרַב בֵּית הַמִּקְדָּשׁ וְהַתְּשׁוּבָה הִסְתַּלְּקָה (ולאמעלה), אֲזַי צָוְחוּ וְאָמְרוּ, (ירמיה ו) אוֹי לָנוּ כִּי פָנָה הַיּוֹם. מַה זֶּה כִּי פָנָה הַיּוֹם? זֶהוּ הַיּוֹם הָעֶלְיוֹן, שֶׁנִּקְרָא תְשׁוּבָה, שֶׁהִסְתַּלֵּק וְעָבַר וְלֹא מָצוּי. אוֹתוֹ הַיּוֹם שֶׁנּוֹדָע, לִפְשֹׁט הַיָּמִין כְּנֶגֶד הָרְשָׁעִים, וַהֲרֵי הִתְפַּנָּה מֵהַכֹּל וְלֹא נִמְצָא, וְלָכֵן אָמְרוּ אוֹי וְלֹא הוֹי. כִּי יִנָּטוּ צִלְלֵי עָרֶב, שֶׁהֲרֵי נִתְּנָה רְשׁוּת לִגְדוֹלֵי הַמְמֻנִּים שֶׁל שְׁאָר הָעַמִּים לִשְׁלֹט עֲלֵיהֶם.</p>\n<p>לָמַדְנוּ, עָלְתָה ו' לְמַעְלָה לְמַעְלָה, וְהַהֵיכָל נִשְׂרַף, וְהָעָם גָּלָה, וְהַגְּבִירָה גֹּרְשָׁה, וְהַבַּיִת נֶחֱרַב. אַחַר כָּךְ שֶׁיָּרַד וָ\"ו לִמְקוֹמוֹ, הִשְׁגִּיחַ עַל בֵּיתוֹ וְהִנֵּה חָרַב, בִּקֵּשׁ אֶת הַגְּבִירָה, וְהִנֵּה הִתְרַחֲקָה וְהָלְכָה. רָאָה אֶת הֵיכָלוֹ, וְהִנֵּה נִשְׂרַף. בִּקֵּשׁ אֶת הָעָם, וְהִנֵּה גָּלָה. רָאָה אֶת בִּרְכוֹת הַנְּחָלִים הָעֲמֻקִּים שֶׁהָיוּ שׁוֹפְעִים, וְהִנֵּה נִמְנְעוּ. וְאָז כָּתוּב, (ישעיה כב) וַיִּקְרָא ה' אֱלֹהִים צְבָאוֹת בַּיּוֹם הַהוּא לִבְכִי וּלְמִסְפֵּד וּלְקָרְחָה וְלַחֲגֹר שָׂק. וְאָז לָבְשׁוּ שָׁמַיִם קַדְרוּת.</p>\n<p>אֲזַי ו' ה' (ו' י') נִמְשְׁכוּ אֶחָד כְּנֶגֶד הָאֶחָד, וְה' הָעֶלְיוֹנָה הִשְׁפִּיעָה אֶת הַמַּעְיָנוֹת לַצַּד הָאַחֵר, וְהַבְּרָכוֹת לֹא נִמְצְאוּ, שֶׁהֲרֵי לֹא נִמְצְאוּ הַזָּכָר וְהַנְּקֵבָה וְלֹא שְׁרוּיִים כְּאֶחָד. אֲזַי שָׁאֹג יִשְׁאַג עַל נָוֵהוּ. בָּכָה רַבִּי שִׁמְעוֹן, וּבָכָה רַבִּי אֶלְעָזָר. אָמַר רַבִּי אֶלְעָזָר, בְּכִיָּה תְקוּעָה בְּלִבִּי מִצַּד אֶחָד, וְשִׂמְחָה בְּלִבִּי מִצַּד אַחֵר, שֶׁהֲרֵי שָׁמַעְתִּי דְבָרִים שֶׁלֹּא שָׁמַעְתִּי עַד עַתָּה. אַשְׁרֵי חֶלְקִי!</p>"],[9522012143,"<p>עָרְוַת אֵשֶׁת אָבִיךְ לֹא תְגַלֵּה. מִי זוֹ אֵשֶׁת אָבִיךְ? אָמַר רַבִּי שִׁמְעוֹן, הֲרֵי שָׁנִינוּ, כָּל דִּבְרֵי הַתּוֹרָה נִסְתָּר וְנִגְלֶה, כְּמוֹ שֶׁהַשֵּׁם הַקָּדוֹשׁ נִסְתָּר וְנִגְלֶה, הַתּוֹרָה שֶׁהִיא שֵׁם קָדוֹשׁ, כָּךְ גַּם נִסְתָּר וְנִגְלֶה. כָּאן הַכֹּל בְּנִגְלֶה, יְדִיעָה נִסְתֶּרֶת כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>וְהַפָּסוּק הַזֶּה הוּא כָּךְ: אֵשֶׁת אָבִיךְ - לָמַדְנוּ, כָּל זְמַן שֶׁהַגְּבִירָה נִמְצֵאת עִם הַמֶּלֶךְ וְהִיא מֵינִיקָה אוֹתְךְ, נִקְרֵאת אִמְּךְ. בְּעֵת שֶׁגָּלְתָה עִמְּךְ וְהִתְרַחֲקָה מִן הַמֶּלֶךְ, הִיא נִקְרֵאת אֵשֶׁת אָבִיךְ. אֵשֶׁת הַמֶּלֶךְ הַקָּדוֹשׁ לֹא נִפְטֶרֶת בְּגֵרוּשִׁין מִמֶּנּוּ, הִיא וַדַּאי אִשְׁתּוֹ, כְּמוֹ שֶׁכָּתוּב (שם נ) כֹּה אָמַר ה' אֵי זֶה סֵפֶר כְּרִיתוּת אִמְּכֶם אֲשֶׁר שִׁלַּחְתִּיהָ. אֶלָּא וַדַּאי שֶׁהִיא אֵשֶׁת הַמֶּלֶךְ, אַף עַל גַּב שֶׁגָּלְתָה.</p>\n<p>וְלָכֵן צִוָּה עָלֶיהָ פַּעֲמַיִם - כְּשֶׁיָּשְׁבָה עִם הַמֶּלֶךְ בְּזִוּוּג אֶחָד, וְנִקְרֵאת אִמְּךְ, שֶׁכָּתוּב עֶרְוַת אִמְּךְ לֹא תְגַלֵּה, אַל תַּעֲשֶׂה שֶׁיִּתְרַחֲקוּ זֶה מִזּוֹ וְתִשָּׁלַח עַל חֶטְאֲךְ, כְּמוֹ שֶׁכָּתוּב וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם. וְאֶחָד כְּשֶׁהִיא בַּגָּלוּת עִמְּךְ וְגָלְתָה מֵהֵיכַל הַמֶּלֶךְ, וְנִקְרֵאת אֵשֶׁת הַמֶּלֶךְ. אַף עַל גַּב שֶׁהִתְרַחֲקָה מִמֶּנּוּ, אַל תַּעֲשֶׂה כְּדֵי שֶׁתָּזוּז מִבֵּינְךְ וְיִשְׁלְטוּ בְךְ שׂוֹנְאֶיךְ, וְלֹא תִשְׁמֹר עָלֶיךְ בַּגָּלוּת. זֶהוּ שֶׁכָּתוּב עֶרְוַת אֵשֶׁת אָבִיךְ לֹא תְגַלֵּה. מָה הַטַּעַם? מִשּׁוּם כִּי עֶרְוַת אָבִיךְ הוּא. אַף עַל גַּב שֶׁהִתְרַחֲקָה מִן הַמֶּלֶךְ, בָּהּ הַשְׁגָּחַת הַמֶּלֶךְ תָּמִיד, וְצָרִיךְ לְהִשָּׁמֵר כְּנֶגְדָּהּ יוֹתֵר וְלֹא תֶחֱטָא אֵלֶיהָ.</p>"],[9522012144,"<p>רַבִּי שִׁמְעוֹן פָּתַח, (דברים כג) כִּי ה' אֱלֹהֶיךְ מִתְהַלֵּךְ בְּקֶרֶב מַחֲנֶךְ לְהַצִּילְךְ וְגוֹ'. כִּי ה' אֱלֹהֶיךְ - זוֹ הַשְּׁכִינָה שֶׁנִּמְצֵאת עִם יִשְׂרָאֵל, וְכָל שֶׁכֵּן בַּגָּלוּת, לְהָגֵן עֲלֵיהֶם תָּמִיד מִכָּל הַצְּדָדִים וּמִכָּל שְׁאָר הָעַמִּים כְּדֵי שֶׁלֹּא יַשְׁמִידוּ אֶת יִשְׂרָאֵל.</p>\n<p>שֶׁלָּמַדְנוּ, לֹא יְכוֹלִים שׂוֹנְאֵיהֶם שֶׁל יִשְׂרָאֵל לְהַזִּיק לָהֶם עַד שֶׁיִּשְׂרָאֵל מַחֲלִישִׁים כֹּחַ הַשְּׁכִינָה מִלִּפְנֵי גְּדוֹלֵי הַמְמֻנִּים שֶׁל שְׁאָר הָעַמִּים, וְאָז יְכוֹלִים לָהֶם שׂוֹנְאֵי יִשְׂרָאֵל וְשׁוֹלְטִים עֲלֵיהֶם וְגוֹזְרִים עֲלֵיהֶם כַּמָּה גְזֵרוֹת רָעוֹת. וּכְשֶׁהֵם שָׁבִים אֵלֶיהָ, הִיא מְשַׁבֶּרֶת הַכֹּחַ וְהַתֹּקֶף שֶׁל שׂוֹנְאֵי יִשְׂרָאֵל וְנִפְרַעַת לָהֶם מִן הַכֹּל.</p>\n<p>וְעַל כֵּן וְהָיָה מַחֲנֶיךְ קָדוֹשׁ, שֶׁצָּרִיךְ אָדָם שֶׁלֹּא יִטְמָא בַחֲטָאָיו וְיַעֲבֹר עַל דִּבְרֵי תוֹרָה. שֶׁאִם הוּא עוֹשֶׂה כָּךְ, מְטַמְּאִים אוֹתוֹ, כְּמוֹ שֶׁכָּתוּב וְנִטְמֵתֶם בָּם, בְּלִי א'. וְלָמַדְנוּ, מָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה אֵיבָרִים בַּגּוּף, וְכֻלָּם נִטְמָאִים כְּשֶׁהוּא נִטְמָא. כְּלוֹמַר, כְּשֶׁהוּא רוֹצֶה לְהִטָּמֵא. וְעַל כֵּן וְהָיָה מַחֲנֶיךְ קָדוֹשׁ. מַה זֶּה מַחֲנֶיךְ? אֵלּוּ הֵם אֵיבְרֵי הַגּוּף. וְלֹא יִרְאֶה בְךְ עֶרְוַת דָּבָר, מַה זֶּה עֶרְוַת דָּבָר? עֶרְוָה נָכְרִיָּה שֶׁזֶּה (שהוא) דְּבַר רֶמֶז, לַדָּבָר הַזֶּה, כְּמוֹ שֶׁבֵּאַרְנוּ. שֶׁאִם כָּךְ, וְשָׁב מֵאַחֲרֶיךְ וַדַּאי. וְעַל כֵּן עֶרְוַת אֵשֶׁת אָבִיךְ לֹא תְגַלֵּה. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב עֶרְוַת אָבִיךְ הִוא, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>לָמַדְנוּ, עַל שְׁלֹשָׁה דְבָרִים מִתְעַכְּבִים יִשְׂרָאֵל בַּגָּלוּת: עַל שֶׁעוֹשִׂים קָלוֹן בַּשְּׁכִינָה בַּגָּלוּת, וּמַחֲזִירִים פְּנֵיהֶם מֵהַשְּׁכִינָה, וְעַל שֶׁמְּטַמְּאִים אֶת עַצְמָם לִפְנֵי הַשְּׁכִינָה, וְאֶת כֻּלָּם בֵּאַרְנוּ בְמִשְׁנָתֵנוּ.</p>"],[9522012145,"<p>רַבִּי אַבָּא הָיָה הוֹלֵךְ לְקַפּוּטְקִיָּא, וְהָיָה עִמּוֹ רַבִּי יוֹסֵי. עַד שֶׁהָיוּ הוֹלְכִים, רָאוּ אִישׁ אֶחָד שֶׁהָיָה בָּא עִם רֹשֶׁם אֶחָד בְּפָנָיו. אָמַר רַבִּי אַבָּא, נִסְטֶה מֵהַדֶּרֶךְ הַזּוֹ, שֶׁהֲרֵי פָּנָיו שֶׁל זֶה מְעִידִים עָלָיו שֶׁעָבַר עַל עֶרְוָה שֶׁל הַתּוֹרָה, כִּי כָּךְ רָשׁוּם בְּפָנָיו. אָמַר לוֹ רַבִּי יוֹסֵי, אִם הָרֹשֶׁם הַזֶּה הָיָה לוֹ כְּשֶׁהָיָה תִּינוֹק, אֵיזוֹ עֶרְוָה תִּמְצָא בּוֹ? אָמַר לוֹ, אֲנִי רוֹאֶה בְפָנָיו שֶׁמְּעִידִים עַל עֶרְוָה שֶׁל הַתּוֹרָה.</p>\n<p>קָרָא לוֹ רַבִּי אַבָּא, אָמַר לוֹ, אֱמֹר דְּבָרְךְ, הָרֹשֶׁם הַזֶּה שֶׁבְּפָנֶיךְ מַה זֶּה? אָמַר לָהֶם, בְּבַקָּשָׁה מִכֶּם, אַל תַּעֲנִישׁוּ יוֹתֵר אֶת אוֹתוֹ אָדָם, שֶׁהֲרֵי חֲטָאָיו גָּרְמוּ לוֹ. אָמַר רַבִּי אַבָּא, מַהוּ? אָמַר לוֹ, יוֹם אֶחָד הָיִיתִי הוֹלֵךְ בַּדֶּרֶךְ אֲנִי וַאֲחוֹתִי, וְשָׁהִינוּ בְמָלוֹן אֶחָד וְשָׁתִיתִי יַיִן, וְכָל אוֹתוֹ הַלַּיְלָה אָחַזְתִּי בַאֲחוֹתִי. בַּבֹּקֶר קַמְנוּ, וּבַעַל בֵּית הַמָּלוֹן הִתְקוֹטֵט עִם אִישׁ אֶחָד, וְנִכְנַסְתִּי בֵינֵיהֶם, וְקָשְׁרוּ אוֹתִי זֶה מִצַּד זֶה וְזֶה מִצַּד זֶה, וְהָרֹשֶׁם הַזֶּה הָיָה נִכְנָס לַמֹּחַ, וְנִצַּלְתִּי עַל יְדֵי רוֹפֵא אֶחָד שֶׁיֵּשׁ בְּתוֹכֵנוּ.</p>\n<p>אָמַר לוֹ, מִי הָרוֹפֵא? אָמַר לוֹ, זֶה רַבִּי שַׂמְלַאי. אָמַר לוֹ, אֵיזוֹ רְפוּאָה נָתַן לְךְ? אָמַר לוֹ, רְפוּאַת הַנֶּפֶשׁ. וּמֵאוֹתוֹ יוֹם חָזַרְתִּי בִתְשׁוּבָה. וּבְכָל יוֹם אֲנִי רוֹאֶה אֶת פָּנַי בְּמַרְאָה אַחַת, וַאֲנִי בּוֹכֶה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא רִבּוֹן הָעוֹלָמִים, עַל אוֹתוֹ הַחֵטְא, וּמֵאוֹתָן דְּמָעוֹת רָחַצְתִּי פָנַי. אָמַר רַבִּי אַבָּא, אִם לֹא שֶׁנִּמְנְעָה מִמְּךְ תְּשׁוּבָה, הָיִיתִי מַעֲבִיר מִפָּנֶיךְ אֶת אוֹתוֹ הָרֹשֶׁם, אֲבָל אֲנִי קוֹרֵא עָלֶיךְ, (ישעיה ו) וְסָר עֲוֹנֶךְ וְחַטָּאתְךְ תְּכֻפָּר. אָמַר לוֹ, אֱמֹר שָׁלֹשׁ פְּעָמִים. אָמַר לוֹ שָׁלֹשׁ פְּעָמִים וְהָרֹשֶׁם עָבַר.</p>\n<p>אָמַר רַבִּי אַבָּא, וַדַּאי אֲדוֹנְךְ רָצָה לְהַעֲבִירוֹ מִמְּךְ, שֶׁוַּדַּאי נִמְצֵאתָ בִּתְשׁוּבָה. אָמַר לוֹ, נָדַרְתִּי מֵהַיּוֹם הַזֶּה לַעֲסֹק בַּתּוֹרָה יוֹמָם וָלַיְלָה. אָמַר לוֹ, מַה שִּׁמְךְ? אָמַר לוֹ, אֶלְעָזָר. אָמַר לוֹ, אֵל עָזַר, וַדַּאי שֶׁהַשֵּׁם גּוֹרֵם שֶׁאֱלֹקֶיךְ סִיַּע לְךְ וְהָיָה בְעֶזְרְךְ. שָׁלַח אוֹתוֹ רַבִּי אַבָּא וּבֵרַךְ אוֹתוֹ.</p>\n<p>בְּפַעַם אַחֶרֶת הָיָה רַבִּי אַבָּא הוֹלֵךְ אֶל רַבִּי שִׁמְעוֹן, נִכְנַס לְעִירוֹ, מָצָא אוֹתוֹ שֶׁהָיָה יוֹשֵׁב וְדוֹרֵשׁ (תהלים צב) אִישׁ בַּעַר לֹא יֵדָע וּכְסִיל לֹא יָבִין אֶת זֹּאת. אִישׁ בַּעַר לֹא יֵדָע וְגוֹ', כַּמָּה טִפְּשִׁים אוֹתָם בְּנֵי הָעוֹלָם שֶׁלֹּא מַשְׁגִּיחִים וְלֹא יוֹדְעִים וְלֹא מִסְתַּכְּלִים לָדַעַת אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל מַה הֵם עוֹמְדִים בָּעוֹלָם, מִי מְעַכֵּב אוֹתָם לָדַעַת? טִפְּשׁוּתָם, כִּי לֹא עוֹסְקִים בַּתּוֹרָה. שֶׁאִלּוּ עוֹסְקִים בַּתּוֹרָה, הָיוּ יוֹדְעִים אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וּכְסִיל לֹא יָבִין אֶת זֹּאת, שֶׁלֹּא מִתְבּוֹנֵן וְלֹא יוֹדֵעַ הַהַנְהָגוֹת שֶׁל זֹּאת בָּעוֹלָם. (שאף על גב) שֶׁדָּן אֶת הָעוֹלָם בְּדִינָיו וְרוֹאִים אֶת דִּינֶיהָ שֶׁל זֹּאת הַזּוֹ שֶׁמַּגִּיעִים לִבְנֵי אָדָם שֶׁהֵם צַדִּיקִים, וְלֹא מַגִּיעִים עַל הָרְשָׁעִים הַחַיָּבִים שֶׁעוֹבְרִים עַל דִּבְרֵי הַתּוֹרָה, שֶׁכָּתוּב בִּפְרוֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב וְגוֹ'. שֶׁאֶת הָעוֹלָם הַזֶּה הֵם יוֹרְשִׁים אוֹתוֹ בְּכָל צְדָדָיו, וְהַדִּינִים לֹא מַגִּיעִים אֲלֵיהֶם בָּעוֹלָם הַזֶּה. וְאִלְמָלֵא שֶׁדָּוִד הַמֶּלֶךְ הוֹדִיעַ אוֹתוֹ בְּסוֹף הַכָּתוּב, לֹא הָיִינוּ יוֹדְעִים, שֶׁכָּתוּב לְהִשָּׁמְדָם עֲדֵי עַד, לְהַשְׁמִידָם מֵאוֹתוֹ הָעוֹלָם, וְשֶׁיִּהְיוּ עָפָר תַּחַת רַגְלֵי הַצַּדִּיקִים, שֶׁכָּתוּב (מלאכי ג) וְעַסּוֹתֶם רְשָׁעִים כִּי יִהְיוּ אֵפֶר תַּחַת כַּפּוֹת רַגְלֵיכֶם.</p>\n<p>עוֹד פָּתַח וְאָמַר, (איוב טז) וַיָּקָם בִּי כַחֲשִׁי בְּפָנַי יַעֲנֶה. בַּמֶּה מְדֻבָּר? אֶלָּא אַשְׁרֵי חֶלְקוֹ שֶׁל אָדָם שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה לָדַעַת אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, כְּאִלּוּ הִשְׁתַּדֵּל בִּשְׁמוֹ מַמָּשׁ. מַה שְּׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה הַנְהָגוֹת, אַף הַתּוֹרָה גַּם כֵּן. בּא וּרְאֵה, מִי שֶׁעוֹבֵר עַל דִּבְרֵי תוֹרָה, הַתּוֹרָה עוֹלָה וְיוֹרֶדֶת וְעוֹשָׂה בָּאָדָם רִשּׁוּמִים בְּפָנָיו, כְּדֵי שֶׁיִּסְתַּכְּלוּ בוֹ עֶלְיוֹנִים וְתַחְתּוֹנִים, וְכֻלָּם שׁוֹפְכִים קְלָלוֹת עַל רֹאשׁוֹ.</p>\n<p>וְלָמַדְנוּ, כָּל אוֹתָם עֵינֵי ה' שֶׁהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם לָדַעַת אֶת דַּרְכֵי בְּנֵי אָדָם, כֻּלָּם זוֹקְפִים עֵינַיִם וּמִסְתַּכְּלִים בִּפְנֵי אוֹתוֹ הָאִישׁ, וְרוֹאִים אוֹתָם, וְכֻלָּם פּוֹתְחִים עָלָיו: וַי וַי. אוֹי לוֹ בָּעוֹלָם הַזֶּה, וְאוֹי לוֹ בָּעוֹלָם הַבָּא. הִסְתַּלְּקוּ מִסָּבִיב לִפְלוֹנִי, שֶׁהֲרֵי עֵדוּת בְּפָנָיו, וְרוּחַ טֻמְאָה שׁוֹרָה עָלָיו. וְכָל אוֹתָם יָמִים שֶׁנִּמְצָא רֹשֶׁם בְּפָנָיו לְעֵדוּת, אִם מוֹלִיד בֵּן, הוּא שׁוֹלֵף לוֹ רוּחַ מִצַּד הַטֻּמְאָה, וְאֵלּוּ הֵם הָרְשָׁעִים שֶׁל הַדּוֹר, עַזֵּי הַפָּנִים, שֶׁרִבּוֹנָם עוֹזֵב אוֹתָם בָּעוֹלָם הַזֶּה לְהַשְׁמִידָם לָעוֹלָם הַבָּא.</p>\n<p>שָׁנִינוּ, הַצַּדִּיק הַזַּכַּאי הַזֶּה שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹשֵׁךְ עָלָיו חוּט אֶחָד שֶׁל חֶסֶד וְנִרְשָׁם לוֹ בְּפָנָיו, וּמֵאוֹתוֹ רֹשֶׁם פּוֹחֲדִים עֶלְיוֹנִים וְתַחְתּוֹנִים. כָּךְ גַּם מִי שֶׁעוֹבֵר עַל דִּבְרֵי תוֹרָה, מוֹשְׁכִים עָלָיו רוּחַ טֻמְאָה וְנִרְשָׁם לוֹ בְּפָנָיו, וּמִמֶּנּוּ בּוֹרְחִים עֶלְיוֹנִים וְתַחְתּוֹנִים. וְכֻלָּם מַכְרִיזִים עָלָיו: הִסְתַּלְּקוּ מִסָּבִיב לִפְלוֹנִי, שֶׁעָבַר עַל דִּבְרֵי תוֹרָה וְעַל מִצְווֹת רִבּוֹנוֹ. אוֹי לוֹ וְאוֹי לְנַפְשׁוֹ! הֲרֵי שָׁלַף רוּחַ טֻמְאָה שֶׁנִּמְצֵאת עִמּוֹ וְהוֹרִישָׁהּ לִבְנוֹ, וְזֶהוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אֵין לוֹ בּוֹ חֵלֶק, וְעוֹזֵב אוֹתוֹ לְהַשְׁמִידוֹ לָעוֹלָם הַבָּא.</p>\n<p>אָמַר לוֹ רַבִּי אַבָּא, יָפֶה אָמַרְתָּ, אֲבָל מִנַּיִן לְךְ אֶת זֶה? אָמַר לוֹ, כָּךְ לָמַדְתִּי, וְלָמַדְתִּי שֶׁהַיְרֻשָּׁה הָרָעָה הַזּוֹ יוֹרְשִׁים כָּל בָּנָיו, אִם לֹא שֶׁיָּשׁוּבוּ, שֶׁהֲרֵי אֵין דָּבָר שֶׁעוֹמֵד לִפְנֵי תְשׁוּבָה. וַאֲנִי כָּךְ לָמַדְתִּי, שֶׁרְפוּאָה זוֹ נָתְנוּ לִי פַּעַם אַחַת, שֶׁהָיִיתִי רָשׁוּם בְּפָנַי, וְיוֹם אֶחָד הָיִיתִי הוֹלֵךְ בַּדֶּרֶךְ וּפָגַשְׁתִּי צַדִּיק אֶחָד, וְעַל יָדוֹ עָבַר מִמֶּנּוּ אוֹתוֹ הָרֹשֶׁם. אָמַר לִי, מַה שִּׁמְךְ? אָמַרְתִּי לוֹ, אֶלְעָזָר, וְקָרָא עָלַי אֶלְעָזָר אַחֵר. אָמַר לוֹ, בָּרוּךְ הָרַחֲמָן שֶׁרָאִיתִי אוֹתְךְ וְזָכִיתִי לִרְאוֹתְךְ בָּזֶה. אַשְׁרֵי חֶלְקְךְ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. (אמר לו,) אֲנִי הוּא שֶׁפָּגַשְׁתִּי בְּךְ.</p>\n<p>הִשְׁתַּטַח לְפָנָיו וֶהֱבִיאוֹ לְבֵיתוֹ. הִתְקִין לְפָנָיו חַלַּת (טרכוסא) לֶחֶם וּבָשָׂר שֶׁל עֶגְלָה מְשֻׁלֶּשֶׁת. אַחַר שֶׁאָכְלוּ, אָמַר לוֹ אוֹתוֹ הָאִישׁ: רַבִּי, אֱמֹר לִי דָּבָר אֶחָד, פָּרָה אֲדֻמָּה יֵשׁ לִי, אִמּוֹ שֶׁל הָעֵגֶל שֶׁאֶת בְּשָׂרוֹ זֶה עַתָּה אָכַלְנוּ, וְיוֹם אֶחָד טֶרֶם שֶׁהִתְעַבְּרָה וְהוֹלִידָה, הָלַכְתִּי אַחֲרֶיהָ לַמִּרְעֶה בַּמִּדְבָּר, בְּעוֹד שֶׁאֲנִי מַנְהִיג אוֹתָהּ עָבַר לְפָנַי אִישׁ אֶחָד, אָמַר לִי, מַה שְּׁמָהּ שֶׁל הַפָּרָה הַזּוֹ? אָמַרְתִּי, מִיּוֹם שֶׁנּוֹלְדָה לֹא קְרָאתִיהָ בְשֵׁם. אָמַר לִי, הִיא נִקְרֵאת בַּת שֶׁבַע אֵם שְׁלֹמֹה, אִם תִּזְכֶּה לְכַפָּרָה. וַאֲנִי, בְּעוֹד שֶׁהֶחֱזַרְתִּי אֶת רֹאשִׁי, לֹא רָאִיתִי אוֹתוֹ, וְצָחַקְתִּי מֵאוֹתוֹ הַדָּבָר.</p>\n<p>וְעַכְשָׁו שֶׁזָּכִיתִי בַּתּוֹרָה, הִתְעוֹרַרְתִּי עַל הַדָּבָר הַהוּא, ף וּמִיּוֹם שֶׁנִּפְטַר מִכָּאן רַבִּי שַׂמְלַאי, לֹא הָיָה אִישׁ שֶׁיָּאִיר לָנוּ בַּתּוֹרָה כְּמוֹתוֹ, וַאֲנִי פָחַדְתִּי לוֹמַר דְּבַר תּוֹרָה שֶׁלֹּא לָמַדְתִּי. וְהַדָּבָר הַזֶּה שֶׁהִסְתַּכַּלְתִּי שֶׁדְּבַר חָכְמָה הוּא, וְלֹא יָדַעְתִּי. אָמַר לוֹ, וַדַּאי שֶׁזֶּהוּ דְּבַר חָכְמָה, וְרֶמֶז עֶלְיוֹן הוּא לְמַעְלָה וּלְמַטָּה.</p>"],[9522012146,"<p>אֲבָל בֹּא רְאֵה, בַּת שֶׁבַע נִקְרֵאת מַמָּשׁ בְּסוֹד הַחָכְמָה, מִשּׁוּם כָּךְ כָּתוּב בָּהּ הַכֹּל בְּשֶׁבַע: שֶׁבַע פָּרוֹת, שֶׁבַע שְׂרֵפוֹת, שֶׁבַע הַזָּאוֹת, שִׁבְעָה כִבּוּסִים, שִׁבְעָה טְמֵאִים, שִׁבְעָה טְהוֹרִים, שִׁבְעָה כֹהֲנִים. וּמֹשֶׁה וְאַהֲרֹן בַּחֶשְׁבּוֹן, שֶׁכָּתוּב וַיְדַבֵּר ה' אֶל מֹשֶׁה וְאַהֲרֹן וְגוֹ'. וְיָפֶה אָמַר אוֹתוֹ הָאִישׁ שֶׁאָמַר בַּת שֶׁבַע, וְהַכֹּל הוּא סוֹד שֶׁל חָכְמָה.</p>\n<p>אָמַר לוֹ, בָּרוּךְ הָרַחֲמָן שֶׁשָּׁמַעְתִּי דָּבָר זֶה, בָּרוּךְ הוּא, שֶׁהֲרֵי הִקְדִּים לִי שָׁלוֹם בָּרִאשׁוֹנָה לִזְכּוֹת לָזֶה, שֶׁכָּתוּב (ישעיה נז) שָׁלוֹם שָׁלוֹם לָרָחוֹק וְלַקָּרוֹב אָמַר ה'. כְּשֶׁאֲנִי הָיִיתִי רָחוֹק, הִקְדִּים לִי הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלוֹם לִהְיוֹת קָרוֹב. קָרָא עָלָיו רַבִּי אַבָּא, (שמואל א כה) אַתָּה שָׁלוֹם וּבֵיתְךְ שָׁלוֹם וְכֹל אֲשֶׁר לְךְ שָׁלוֹם.</p>"],[9522012147,"<p>עָרְוַת אֲחוֹת אָבִיךְ לֹא תְגַלֵּה. רַבִּי חִיָּיא פָּתַח, וְאִישׁ אֲשֶׁר יִקַּח אֶת אֲחֹתוֹ בַּת אָבִיו אוֹ בַת אִמּוֹ וְרָאָה אֶת עֶרְוָתָהּ וְגוֹ'. שָׁם שָׁנִינוּ, מֵאָה וּשְׁלֹשִׁים שָׁנָה פָּרַשׁ אָדָם מֵאִשְׁתּוֹ וְלֹא הָיָה מוֹלִיד. מִשֶּׁהָרַג קַיִן אֶת הֶבֶל לֹא רָצָה אָדָם לְהִזְדַּוֵּג עִם אִשְׁתּוֹ. רַבִּי יוֹסֵי אָמַר, מִשָּׁעָה שֶׁנִּגְזְרָה עָלָיו וְעַל כָּל הָעוֹלָם מִיתָה. אָמַר, לָמָּה אֲנִי אוֹלִיד לַבֶּהָלָה? מִיָּד פָּרַשׁ מֵאִשְׁתּוֹ.</p>\n<p>וּשְׁתֵּי רוּחוֹת נְקֵבוֹת הָיוּ בָאוֹת וּמִזְדַּוְּגוֹת עִמּוֹ וְהוֹלִידוּ. וְאוֹתָם שֶׁהוֹלִידוּ הָיוּ הַמַּזִּיקִים שֶׁל הָעוֹלָם, וְנִקְרָאִים נִגְעֵי בְּנֵי אָדָם, וְאֵלֶּה מְסִיתִים בְּנֵי אָדָם וְשׁוֹרִים בְּפֶתַח הַבַּיִת וּבְבוֹרוֹת וּבְבָתֵּי הַכִּסֵּא. וְעַל כֵּן בֶּן אָדָם שֶׁנִּמְצָא בְּפֶתַח בֵּיתוֹ הַשֵּׁם הַקָּדוֹשׁ שַׁדַּי בִּכְתָרִים עֶלְיוֹנִים, כֻּלָּם בּוֹרְחִים וּמִתְרַחֲקִים מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב (תהלים צא) וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךְ. מַה זֶּה וְנֶגַע לֹא יִקְרַב? אֵלּוּ נִגְעֵי בְּנֵי אָדָם.</p>\n<p>וְלָמַדְנוּ, בְּשָׁעָה שֶׁיָּרַד אָדָם בִּדְיוֹקָן עֶלְיוֹן, בִּדְיוֹקָן קָדוֹשׁ, וְרָאוּ אוֹתוֹ עֶלְיוֹנִים וְתַחְתּוֹנִים, כֻּלָּם קָרְבוּ אֵלָיו וְהִמְלִיכוּהוּ עַל הָעוֹלָם הַזֶּה. לְאַחַר שֶׁבָּא הַנָּחָשׁ עַל חַוָּה וְהִטִּיל בָּהּ זֻהֲמָה, אַחַר כָּךְ הוֹלִידָה אֶת קַיִן, וּמִשָּׁם (נתיחסו) נִתְחַיְּבוּ כָּל דּוֹרוֹת הָרְשָׁעִים בָּעוֹלָם. וּמְדוֹר הַשֵּׁדִים וְהָרוּחוֹת מִשָּׁם נִמְצְאוּ, וּמִצִּדּוֹ. וּמִשּׁוּם כָּךְ כָּל הַשֵּׁדִים וְהָרוּחוֹת, חֲצִי יֵשׁ בָּהֶם מִבְּנֵי אָדָם שֶׁלְּמַטָּה, וַחֲצִי מִמַּלְאָכִים עֶלְיוֹנִים שֶׁלְּמַעְלָה. וְכֵן כְּשֶׁנּוֹלְדוּ מֵאָדָם אוֹתָם אֲחֵרִים, כֻּלָּם נִמְצְאוּ כְּגוֹן זֶה - חֲצִי מֵהַתַּחְתּוֹנִים, וַחֲצִי מֵהָעֶלְיוֹנִים.</p>\n<p>אַחַר שֶׁנּוֹלְדוּ מֵאָדָם, (חזרו לו קצת מאותן רוחות שיצאו מתשוקתו בחלום) הוֹלִיד מֵאוֹתָן רוּחוֹת בָּנוֹת שֶׁדּוֹמוֹת לִיפִי הָעֶלְיוֹנִים וְלִיפִי הַתַּחְתּוֹנִים, וְעַל זֶה כָּתוּב, (בראשית ו) וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם כִּי טֹבֹת הֵנָּה וְגוֹ', וְטָעוּ כֻלָּם אַחֲרֵיהֶן. וְזָכָר אֶחָד נִמְצָא שֶׁבָּא לָעוֹלָם מֵרוּחוֹ שֶׁל צַד קַיִן, וְקָרְאוּ לוֹ תּוּבַל קַיִן, וּנְקֵבָה אַחַת יָצְאָה עִמּוֹ, וְהָיוּ הַבְּרִיּוֹת טוֹעִים אַחֲרֶיהָ, וְנִקְרֵאת נַעֲמָ\"ה. מִמֶּנָּה יָצְאוּ רוּחוֹת וְשֵׁדִים אֲחֵרִים, וְהֵם תְּלוּיִים בָּאֲוִיר וּמוֹדִיעִים דְּבָרִים לְאוֹתָם אֲחֵרִים שֶׁמְּצוּיִים לְמַטָּה.</p>\n<p>וְתוּבַל קַיִן הַזֶּה הוֹצִיא כְּלֵי זַיִן לַהֲרֹג לָעוֹלָם, וְנַעֲמָה הַזּוֹ הִתְרַעֲשָׁה בְּרִגְשָׁהּ, וְנִדְבְּקָה בְצִדָּהּ. וְעַד עַכְשָׁו הִיא קַיֶּמֶת, וּמְדוֹרָהּ בֵּין שְׁאוֹן הַיָּם הַגָּדוֹל, וְיוֹצֵאת וְצוֹחֶקֶת עִם בְּנֵי אָדָם, וּמִתְחַמֶּמֶת מֵהֶם בַּחֲלוֹם בְּאוֹתָהּ הַתְּשׁוּקָה שֶׁל אָדָם, וְנִדְבֶּקֶת בּוֹ. תְּשׁוּקָה הִיא נוֹטֶלֶת, וְלֹא יוֹתֵר. וּמֵאוֹתָהּ תְּשׁוּקָה הִיא מִתְעַבֶּרֶת, וּמוֹצִיאָה מִינִים אֲחֵרִים לָעוֹלָם.</p>\n<p>וְהַבָּנִים הַלָּלוּ שֶׁמּוֹלִידָה מִבְּנֵי אָדָם נִמְצָאִים כְּנֶגֶד נְקֵבוֹת בְּנֵי הָאָדָם, וּמִתְעַבְּרוֹת מֵהֶם וּמוֹלִידוֹת רוּחוֹת, וְכֻלָּם הוֹלְכִים אֶל לִילִית הָרִאשׁוֹנָה, וְהִיא מְגַדֶּלֶת אוֹתָם. וְהִיא יוֹצֵאת לָעוֹלָם וְרוֹצָה תִינוֹקוֹתֶיהָ. וְרוֹאָה תִינוֹקוֹת שֶׁל בְּנֵי אָדָם וְנִדְבֶּקֶת לָהֶם לַהֲרֹג אוֹתָם, וּלְהִשָּׁאֵב לְרוּחוֹת תִּינוֹקוֹת בְּנֵי הָאָדָם, וְהוֹלֶכֶת עִם אוֹתָהּ הָרוּחַ (תינוק), וּמִזְדַּמְּנִים שָׁם שָׁלֹשׁ רוּחוֹת קְדוֹשׁוֹת, וְטָסִים לְפָנֶיהָ, וְנוֹטְלִים מִמֶּנָּה אוֹתָהּ הָרוּחַ (תינוק), וּמַנִּיחִים אוֹתָהּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְשָׁם נֶחְקָקִים (לומדים) לְפָנָיו.</p>"],[9522012148,"<p>מִשּׁוּם כָּךְ הַתּוֹרָה מַזְהִירָה אֶת בְּנֵי הָאָדָם, וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדֹשִׁים, וַדַּאי. אִם נִמְצָא אָדָם קָדוֹשׁ, לֹא פוֹחֵד מִמֶּנָּה, שֶׁאָז מַזְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אוֹתָם שְׁלֹשֶׁת הַמַּלְאָכִים הַקְּדוֹשִׁים שֶׁאָמַרְנוּ, וְשׁוֹמְרִים אֶת אוֹתוֹ הַתִּינוֹק, וְהִיא לֹא יְכוֹלָה לְהָרַע לוֹ. זֶהוּ שֶׁכָּתוּב לֹא תְאֻנֶּה אֵלֶיךְ רָעָה וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךְ. מָה הַטַּעַם לֹא תְאֻנֶּה אֵלֶיךְ רָעָה? מִשּׁוּם שֶׁכִּי מַלְאָכָיו יְצַוֶּה לָּךְ. וְכָתוּב כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ.</p>\n<p>שֶׁאִם אָדָם לֹא נִמְצָא קָדוֹשׁ, וְשׁוֹלֵף רוּחַ מִצַּד הַטֻּמְאָה, אֲזַי הִיא בָּאָה וְצוֹחֶקֶת עִם אוֹתוֹ תִינוֹק. וְאִם הִיא הוֹרֶגֶת אוֹתוֹ, הִיא נִשְׁאֶבֶת לְאוֹתָהּ הָרוּחַ וְלֹא זָזָה מִמֶּנָּה לְעוֹלָמִים. וְאִם תֹּאמַר, אוֹתָם הָאֲחֵרִים שֶׁהָרְגָה אוֹתָם וְהִזְדַּמְּנוּ לְפָנֶיהָ הֵם אוֹתָם שְׁלֹשָׁה קְדוֹשִׁים, וְנוֹטְלִים מִמֶּנָּה אוֹתָהּ הָרוּחַ, הֲרֵי לֹא נִמְצְאוּ בְּצַד הַטֻּמְאָה, לָמָּה הִיא שׁוֹלֶטֶת לַהֲרֹג אוֹתָם? אֶלָּא זֶה כְּשֶׁהָאִישׁ הַזֶּה אֵינוֹ מִתְקַדֵּשׁ, אֲבָל לֹא מִתְכַּוֵּן לְהִטָּמֵא וְלֹא נִטְמָא, כִּי כָּךְ הִיא יְכוֹלָה לִשְׁלֹט בַּגּוּף וְלֹא בָרוּחַ.</p>\n<p>וְלִפְעָמִים נִמְצָא שֶׁיּוֹצֵאת נַעֲמָה לָעוֹלָם לְהִתְחַמֵּם עִם בְּנֵי אָדָם, וְנִמְצָא אָדָם בְּקֶשֶׁר (בקשוי) שֶׁל תְּשׁוּקָה עִמָּהּ, וּמִתְעוֹרֵר מִשְּׁנָתוֹ, וְאוֹחֵז בְּאִשְׁתּוֹ וְשׁוֹכֵב עִמָּהּ, וְהָרָצוֹן שֶׁלּוֹ בְּאוֹתָהּ תְּשׁוּקָה שֶׁהָיְתָה לוֹ בַּחֲלוֹמוֹ, אָז אוֹתוֹ הַבֵּן שֶׁמּוֹלִיד בָּא מִצִּדָּהּ שֶׁל נַעֲמָה, שֶׁהֲרֵי בַּתְּשׁוּקָה שֶׁלָּהּ זֶה נִמְצָא. כְּשֶׁיּוֹצֵאת לִילִי\"ת וְרוֹאָה אוֹתוֹ, הִיא יוֹדַעַת הַדָּבָר וְנִקְשֶׁרֶת בּוֹ, וּמְגַדֶּלֶת אוֹתוֹ כְּמוֹ הָאֲחֵרִים בְּנֵי נַעֲמָה, וְנִמְצֵאת עִמּוֹ זְמַנִּים רַבִּים וְלֹא הוֹרֶגֶת אוֹתוֹ.</p>\n<p>זֶהוּ אִישׁ, שֶׁבְּכָל לְבָנָה וּלְבָנָה נֶחְסָר, וְלֹא מִתְיָאֶשֶׁת מִמֶּנּוּ לְעוֹלָמִים, שֶׁהֲרֵי בְּכָל לְבָנָה וּלְבָנָה כְּשֶׁהִיא מִתְחַדֶּשֶׁת בָּעוֹלָם, לִילִי\"ת יוֹצֵאת, וּפוֹקֶדֶת עַל כָּל אֵלֶּה שֶׁהִיא מְגַדֶּלֶת וְצוֹחֶקֶת בָּהֶם, וְאָז אוֹתוֹ הָאִישׁ פָּגוּם בְּאוֹתוֹ זְמַן. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁמִּתְקַדְּשִׁים בִּקְדֻשַּׁת הַמֶּלֶךְ, עֲלֵיהֶם כָּתוּב, (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ וְגוֹ'.</p>\n<p>אֶת הַדְּבָרִים הַלָּלוּ גִּלָּה שְׁלֹמֹה הַמֶּלֶךְ בְּסִפְרוֹ שֶׁל אַשְׁמְדַאי הַמֶּלֶךְ, וּמָצָאנוּ בוֹ אֶלֶף וְאַרְבַּע מֵאוֹת וַחֲמִשָּׁה מִינֵי טֻמְאָה שֶׁנִּטְמָאִים בָּהֶם בְּנֵי אָדָם. אֶת זֶה גִּלָּה אַשְׁמְדַאי לַמֶּלֶךְ שְׁלֹמֹה.</p>\n<p>אוֹי לָהֶם לִבְנֵי אָדָם, שֶׁכֻּלָּם אֲטוּמִים וּסְתוּמֵי עֵינַיִם, וְלֹא יוֹדְעִים וְלֹא שׁוֹמְעִים וְלֹא מַשְׁגִּיחִים אֵיךְ הֵם עוֹמְדִים בָּעוֹלָם. וְהִנֵּה עֵצָה וּרְפוּאָה לִפְנֵיהֶם, וְאֵינָם מִסְתַּכְּלִים. שֶׁהֲרֵי אֵין אֲנָשִׁים יְכוֹלִים לְהִנָּצֵל אֶלָּא בָּעֵצָה שֶׁל הַתּוֹרָה, שֶׁכָּתוּב (דברים כג) כִּי יִהְיֶה בְךְ אִישׁ אֲשֶׁר לֹא טָהוֹר מִקְּרֵה לָיְלָה. אֲשֶׁר לֹא יִהְיֶה טָהוֹר דַּוְקָא, מִקְּרֵה לָיְלָה דַּוְקָא, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים בַּעֲצַת הַתּוֹרָה הַקְּדוֹשָׁה. שֶׁכָּךְ כָּתוּב בַּתּוֹרָה הַקְּדוֹשָׁה, וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים כִּי אֲנִי ה' אֱלֹהֵיכֶם.</p>"],[9522012149,"<p>לָמַדְנוּ, אַחַר שֶׁהִסְתַּלְּקוּ קַיִן וְהֶבֶל, חָזַר אָדָם לְאִשְׁתּוֹ, וְהִתְלַבֵּשׁ בְּרוּחַ אַחֶרֶת, וְהוֹלִיד אֶת שֵׁת. מִכָּאן הִתְיַחֲסוּ דוֹרוֹת הַצַּדִּיקִים בָּעוֹלָם, וְהִגְדִּיל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַחֶסֶד בָּעוֹלָם, וּלְכָל אֶחָד נוֹלְדָה עִמּוֹ נְקֵבָה, שֶׁיִּתְיַשֵּׁב הָעוֹלָם כְּמוֹ שֶׁלְּמַעְלָה. וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים בִּסְתַם מִשְׁנָה, שֶׁכָּתוּב וְאִישׁ אֲשֶׁר יִקַּח אֶת אֲחֹתוֹ בַּת אָבִיו אוֹ בַת אִמּוֹ וְגוֹ', חֶסֶד הוּא. חֶסֶד הוּא וַדַּאי. וְאַחַר שֶׁשָּׁרָה הַחֶסֶד, יָצְאוּ גְזָעִים וְשָׁרָשִׁים מִתַּחַת לְמַעְלָה, וְנִפְרְדוּ הָעֲנָפִים, וְהַקָּרוֹב הִתְרַחֵק. אָז גָּדֵל הֶעָנָף וּבָא לְהִתְחַבֵּר בְּזִוּוּג אֶחָד עִם הָאִילָן. זֶה בָּרִאשׁוֹנָה, וְזֶה בְּסֵתֶר הָעוֹלָם, מִשּׁוּם שֶׁכָּתוּב (תהלים פב) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה. אֲבָל מִכָּאן וָהָלְאָה, אֲנָשִׁים שֶׁיִּמָּצְאוּ בוֹ - וְנִכְרְתוּ לְעֵינֵי בְּנֵי עַמָּם.</p>"],[9522012150,"<p>לָמַדְנוּ, עֶרְוַת אֲחוֹת אָבִיךְ, כְּמוֹ שֶׁנִּתְגַּלָּה בְנִסְתָּר. כָּתוּב (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְצַדִּיקִים יֵלְכוּ בָם וְגוֹ'. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁיּוֹדְעִים דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְהוֹלְכִים בָּהֶם וְנוֹדָעִים אֲלֵיהֶם. אַשְׁרֵי חֶלְקָם.</p>\n<p>לָמַדְנוּ, הִתְעַבְּרָה ה' עֶלְיוֹנָה בְּאַהֲבָה וַחֲבִיבוּת שֶׁאֵין נִפְרָד מִמֶּנָּה יוֹ\"ד לְעוֹלָמִים. הִתְעַבְּרָה וְהוֹצִיאָה וָא\"ו, אַחַר כָּךְ עָמַד לְפָנֶיהָ וְהֵינִיקָה אוֹתוֹ, וְזוֹ (ודן בעולם) הַוָּא\"ו כְּשֶׁיָּצְאָה, בַּת זוּגוֹ יָצְאָה עִמּוֹ. בָּא הַחֶסֶד וְהִתְעוֹרֵר אֵלָיו, וְהִפְרִיד אוֹתָם, וְיָצְאוּ גְזָעִים מִתַּחַת לְמַעְלָה, וְהִתְפַּשְּׁטוּ עֲנָפִים וְהִתְרַבּוּ, וְנֶעֶשְׂתָה הֵ\"א תַּחְתּוֹנָה. וְהִתְרַבְּתָה בַּעֲנָפֶיהָ לְמַעְלָה לְמַעְלָה, עַד שֶׁהִזְדַּוְּגָה בָּאִילָן הָעֶלְיוֹן, וְהִתְחַבְּרוּ וָא\"ו עִם הֵ\"א. מִי גָרַם לָהֶם? חֶסֶד הוּא. חֶסֶד הוּא וַדַּאי. שֶׁחִבְּרָם כְּאֶחָד.</p>\n<p>יוֹ\"ד עִם הֵ\"א עֶלְיוֹנָה, אֵין תָּלוּי חִבּוּרָן בְּחֶסֶד, אֶלָּא חִבּוּרָן תָּלוּי בְּמַזָּל, וַחֲבִיבוּתָן, שֶׁלֹּא נִפְרָדוֹת לְעוֹלָמִים. יוֹ\"ד נִקְשֶׁרֶת לְהֵ\"א, וְהֵ\"א נִקְשֶׁרֶת לְוָא\"ו, וָא\"ו נִקְשֶׁרֶת בְּהֵ\"א, וְהֵ\"א נִקְשֶׁרֶת בַּכֹּל. וְהַכֹּל הוּא קֶשֶׁר אֶחָד וְדָבָר אֶחָד. לֹא נִפְרָדוֹת זוֹ מִזּוֹ לְעוֹלָמִים. כִּבְיָכוֹל מִי שֶׁגּוֹרֵם אֶת הַפֵּרוּד כְּאִלּוּ הֶחֱרִיב עוֹלָם, וְנִקְרָא עֶרְוַת הַכֹּל.</p>"],[9522012151,"<p>וְלֶעָתִיד לָבֹא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָשִׁיב שְׁכִינָה לִמְקוֹמָהּ, וְשֶׁיִּמָּצֵא הַכֹּל בְּזִוּוּג אֶחָד, שֶׁכָּתוּב (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד וְגוֹ'. וְאִם תֹּאמַר, עַכְשָׁו אֵינוֹ אֶחָד?! לֹא, שֶׁהֲרֵי עַכְשָׁו הָרְשָׁעִים שֶׁל הָעוֹלָם גָּרְמוּ שֶׁלֹּא יִמָּצֵא אֶחָד, שֶׁהֲרֵי הַגְּבִירָה הִתְרַחֲקָה מִן הַמֶּלֶךְ, וְלֹא נִמְצָאִים בְּזִוּוּג. הָאֵם הָעֶלְיוֹנָה הִתְרַחֲקָה מֵהַמֶּלֶךְ וְלֹא מֵינִיקָה אוֹתוֹ.</p>\n<p>כִּי מֶלֶךְ בְּלִי גְבִירָה לֹא מִתְעַטֵּר בְּעַטְרוֹתָיו עִמָּהּ (של האם) כְּמוֹ בָּרִאשׁוֹנָה כְּשֶׁהִתְחַבֵּר עִם הַגְּבִירָה, שֶׁעִטְּרָה אוֹתוֹ בְּכַמָּה עֲטָרוֹת, בְּכַמָּה זְהָרִים בַּעֲטָרוֹת קְדוֹשׁוֹת עֶלְיוֹנוֹת, שֶׁכָּתוּב (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה וְגוֹ', שֶׁהִזְדַּוֵּג עִם הַגְּבִירָה, אָז עִטְּרָה אוֹתוֹ הָאֵם הָעֶלְיוֹנָה כָּרָאוּי. וְכָעֵת שֶׁאֵין נִמְצָא הַמֶּלֶךְ עִם הַגְּבִירָה, אֲזַי הָאֵם הָעֶלְיוֹנָה נוֹטֶלֶת אֶת כִּתְרָהּ (עטרתה) וּמוֹנַעַת מִמֶּנּוּ אֶת מַעַיְנוֹת הַנְּחָלִים, וְלֹא נִמְצָא בְקֶשֶׁר אֶחָד. כִּבְיָכוֹל אֵינוֹ בַּנִּמְצָא אֶחָד.</p>\n<p>וּבִזְמַן שֶׁתָּשׁוּב הַגְּבִירָה לִמְקוֹם הֵיכָלָהּ וְהַמֶּלֶךְ יִזְדַּוֵּג עִמָּהּ בְּזִוּוּג אֶחָד, אָז יִתְחַבֵּר הַכֹּל כְּאֶחָד בְּלִי פֵרוּד. וְעַל זֶה כָּתוּב, בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. בַּיּוֹם הַהוּא, בִּזְמַן שֶׁתָּשׁוּב הַגְּבִירָה לַהֵיכָל, אָז הַכֹּל יִמָּצֵא אֶחָד בְּלִי פֵרוּד. וְאָז - (עובדיה א) וְעָלוּ מוֹשִׁיעִים בְּהַר צִיּוֹן לִשְׁפֹּט וְגוֹ'.</p>\n<p>שֶׁלָּמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן, לֹא תִכָּנֵס הַגְּבִירָה בְּשִׂמְחָה לְהֵיכָלוֹ עַד שֶׁתִּדּוֹן מַלְכוּת עֵשָׂו וְתִקַּח מִמֶּנּוּ נְקָמוֹת שֶׁגָּרְמָה כָּל זֶה. אַחַר כָּךְ תִּזְדַּוֵּג עִם הַמֶּלֶךְ וְתִהְיֶה שִׂמְחָה שְׁלֵמָה. זֶהוּ שֶׁכָּתוּב וְעָלוּ מוֹשִׁיעִים בְּהַר צִיּוֹן לִשְׁפֹּט אֶת הַר עֵשָׂו - בָּרִאשׁוֹנָה, וְאַחַר כָּךְ - וְהָיְתָה לַה' הַמְּלוּכָה. מִי הַמְּלוּכָה? זוֹ הַגְּבִירָה. זֶהוּ שֶׁכָּתוּב וְהָיְתָה לַה' הַמְּלוּכָה. וְאַחַר שֶׁיִּזְדַּוְּגוּ כְאֶחָד מַה כָּתוּב? וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>"],[9522012152,"<p>עָרְוַת אֲחִי אָבִיךְ לֹא תְגַלֵּה, שָׁנָה רַבִּי יְהוּדָה - זֶהוּ יִשְׂרָאֵל לְמַטָּה. וַאֲחוֹת אִמְּךְ - זוֹ יְרוּשָׁלַיִם שֶׁלְּמַטָּה. בַּחֲטָאִים הַלָּלוּ יִגְלוּ יִשְׂרָאֵל לְבֵין הָעַמִּים וְתֶחֱרַב יְרוּשָׁלַיִם לְמַטָּה. וְעַל זֶה שָׁנִינוּ, אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁקָּרָא לְיִשְׂרָאֵל אַחִים, שֶׁנֶּאֱמַר (תהלים קכב) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָא וְגוֹ'. (ובארנו הדברים, ושם (דּבָרים שָם) בת בנה ובת בתה. ואף על גב שהם בנגלה ובנסתר וכן אחריו. שהרי העולם צריך להם, והם ישוב העולם, כמו שכתוב (משלי כז) רעך ורע אביך) וְזֶה סוֹד הַדָּבָר. שֶׁאָמַר רַבִּי שִׁמְעוֹן.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אִם אַחַי, לָמָּה רֵעָי? וְאִם רֵעָי, לָמָּה אַחַי? אֶלָּא לָמַדְנוּ, אוֹתוֹ דָבָר שֶׁלֹּא סָר לְעוֹלָמִים נִקְרָא רֵעַ, כְּמוֹ שֶׁנֶּאֱמַר רֵעֲךְ וְרֵעַ אָבִיךְ אַל תַּעֲזֹּב. וְזֶהוּ סוֹד הַדָּבָר שֶׁאָמַר רַבִּי שִׁמְעוֹן, הָאֵם הָעֶלְיוֹנָה נִקְרֵאת רַעְיָה, כִּי לֹא זָזָה אַהֲבַת הָאָב מִמֶּנָּה לְעוֹלָמִים. וְהָאֵם הַתַּחְתּוֹנָה נִקְרֵאת כַּלָּה, וְנִקְרֵאת אָחוֹת, כְּמוֹ שֶׁבֵּאַרְנוּ (שיר ח) אָחוֹת לָנוּ קְטַנָּה.</p>\n<p>וְהַיְנוּ סְתַם מִשְׁנָה שֶׁלָּנוּ, שֶׁכָּתוּב כָּאן עֶרְוַת אֲחוֹתְךְ בַת אָבִיךְ אוֹ בַת אִמֶּךְ. כֵּיוָן שֶׁאָמַר בַת אָבִיךְ, מַה זֶּה אוֹ בַת אִמֶּךְ? אֶלָּא, אִם הִיא נִמְצֵאת מִצַּד הָאָב, נִקְרֵאת חָכְמָה. וְאִם מִצַּד הָאֵם, נִקְרֵאת בִּינָה. וְעַל כָּל פָּנִים, בֵּין כָּךְ וּבֵין כָּךְ, הִיא נִמְצֵאת מֵהָאָב וְהָאֵם. שֶׁהֲרֵי יוֹ\"ד אֵינָהּ זָזָה מֵה' לְעוֹלָמִים. וְזֶהוּ סוֹד הַדָּבָר, מוֹלֶדֶת בַּיִת - מִצַּד הָאָב. אוֹ מוֹלֶדֶת חוּץ - מִצַּד הָאֵם.</p>"],[9522012153,"<p>רַבִּי אַבָּא אָמַר, (משלי כד) בְּחָכְמָה יִבָּנֶה בָּיִת. מִי הַבַּיִת שֶׁנִּבְנֶה בְחָכְמָה? הֱוֵי אוֹמֵר זֶה הַנָּהָר שֶׁיּוֹצֵא מֵעֵדֶן. מִשּׁוּם כָּךְ מוֹלֶדֶת בַּיִת אוֹ מוֹלֶדֶת חוּץ, כְּשֶׁיָּצְאָה מִו', כְּמוֹ שֶׁכָּתוּב (בראשית ב) עֶצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי. וְכָתוּב וַיִּקַּח אַחַת מִצַּלְעֹתָיו, וְזֶהוּ מוֹלֶדֶת חוּץ, מִמָּקוֹם שֶׁל זְעֵיר אַנְפִּין נִמְצָא, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וְעַל זֶה אָמַר רַבִּי יְהוּדָה, יִשְׂרָאֵל נִקְרָאִים אַחִים לַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁלֹּא סָרָה אַהֲבָתָם לְעוֹלָמִים. יְרוּשָׁלַיִם שֶׁלְּמַטָּה נִקְרֵאת אֲחוֹת אִמֶּךְ, כְּמוֹ שֶׁכָּתוּב (תהלים קכב) יְרוּשָׁלַיִם הַבְּנוּיָה כְּעִיר שֶׁחֻבְּרָה לָּהּ יַחְדָּו וְגוֹ'. מַה זֶּה שֶׁחֻבְּרָה לָּהּ יַחְדָּו? כְּדֵי שֶׁיִּזְדַּוֵּג עִמָּהּ הַמֶּלֶךְ מִשִּׁשָּׁה צְדָדִים, בְּכָל צִדְדֵי הַמֶּלֶךְ, בְּדַרְגַּת הַצַּדִּיק, וְכָל כִּתְרֵי הַמֶּלֶךְ שֶׁכְּלוּלִים בּוֹ. וְהַיְנוּ שֶׁחֻבְּרָה לָּהּ יַחְדָּו.</p>\n<p>רַבִּי יִצְחָק אָמַר, שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ. מִי הַשְּׁבָטִים? אֵלּוּ שְׁנֵים עָשָׂר תְּחוּמִים שֶׁנִּפְרָדִים מֵאוֹתוֹ אִילָן גָּדוֹל וְחָזָק שֶׁיָּרַשׁ אוֹתָם מִצַּד הָאָב וְהָאֵם. זֶהוּ שֶׁכָּתוּב שִׁבְטֵי יָהּ, מִיפִי הָעֵדוּת שֶׁמֵּעִיד הַבֵּן הַקָּדוֹשׁ, (שמעיד אבא ואמא בבן הקדוש) שֶׁכָּתוּב שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל, וְהֵם נְהָרוֹת עֲמֻקִּים שֶׁשּׁוֹפְעִים וְנִמְשָׁכִים מִן יָ\"הּ. וְהַכֹּל (וכל כך למה,,) לְהוֹדוֹת לְשֵׁם ה'. כִּי שָׁמָּה יָשְׁבוּ כִסְאוֹת לְמִשְׁפָּט כִּסְאוֹת לְבֵית דָּוִד, לָרֶשֶׁת אֶת הַמַּלְכוּת הַקְּדוֹשָׁה הוּא וּבָנָיו לְדוֹרֵי דוֹרוֹת, וְזוֹהִי הַשִּׁירָה שֶׁאָמַר דָּוִד עַל הַמַּלְכוּת הָעֶלְיוֹנָה הַקְּדוֹשָׁה.</p>\n<p>רַבִּי חִזְקִיָּה אָמַר, הַכֹּל בְּסוֹד עֶלְיוֹן הוּא, לְהַרְאוֹת שֶׁמִּי שֶׁפּוֹגֵם לְמַטָּה - פּוֹגֵם לְמַעְלָה. עֶרְוַת כַּלָּתְךְ לֹא תְגַלֵּה, שֶׁשָּׁנִינוּ, עוֹנָתָן שֶׁל תַּלְמִידֵי חֲכָמִים מִשַּׁבָּת לְשַׁבָּת. מִכֵּיוָן שֶׁיּוֹדְעִים אֶת סוֹד הַדָּבָר וִיכַוְּנוּ אֶת הַלֵּב, וְיִמָּצֵא רְצוֹנָם שָׁלֵם, וְהַבָּנִים שֶׁמּוֹלִידִים נִקְרָאִים הַבָּנִים שֶׁל הַמֶּלֶךְ. וְאִם אֵלֶּה פּוֹגְמִים דָּבָר לְמַטָּה, כִּבְיָכוֹל הֵם פּוֹגְמִים בְּכַלָּה שֶׁלְּמַעְלָה, וְאָז כָּתוּב עֶרְוַת כַּלָּתְךְ לֹא תְגַלֵּה. זֶה בִּשְׁבִיל אֵלּוּ שֶׁיּוֹדְעִים אֶת דִּינֵי הַתּוֹרָה. שְׁאָר הָעָם אוֹתוֹ שֶׁבַּנִּגְלֶה, כַּלָּתְךְ מַמָּשׁ, וּבַחֵטְא הַזֶּה הַשְּׁכִינָה מִסְתַּלֶּקֶת מִבֵּינֵיהֶם.</p>"],[9522012154,"<p>לָמַדְנוּ, נֶחְקָק הַשֵּׁם הַקָּדוֹשׁ בִּצְדָדִים יְדוּעִים, בְּאוֹתִיּוֹת רְשׁוּמוֹת שֶׁל עֶשְׂרִים וּשְׁתַּיִם (י' בא', א' בי', י' בב', ב' בי', י' בא', ב' בה', ו' בג', י' בה', י' בג', ה' בי', ג' בה', ה' בד') י' בְּא', א' בְּי'. י' בְּב', ב' בְּי'. י' בְּא' ה' בְּג', יו\"ד בְּה\"א, יו\"ד בְּגימ\"ל, ה\"א בְיו\"ד גימ\"ל בְּה\"א, ה\"א בְּדל\"ת. כֻּלָּן נֶחְקָקוֹת בְּיוֹ\"ד, יוֹ\"ד מַעֲלֶה אוֹתָן.</p>\n<p>הֵ\"א כְּלוּלָה בְּיוֹ\"ד, מִמֶּנּוּ יוֹצֵאת, אָז מְעַטְּרִים אֶת הָאָבוֹת. נִפְתַּחַת הֵ\"א בַּנְּחָלִים שֶׁלָּהּ, וּמְעַטֶּרֶת אֶת רֹאשׁ הַו', שֶׁשָּׁם שְׁרוּיִים הָאָבוֹת.</p>\n<p>ו' כּוֹלֶלֶת שֵׁשׁ אוֹתִיּוֹת, וְאֶת כֻּלָּם כּוֹלֶלֶת יוֹ\"ד. יוֹ\"ד נֶחְקֶקֶת בְּגִלּוּפֶיהָ, וְעוֹלֶה לְהִתְעַטֵּר בִּשְׁתֵּים עֶשְׂרֵה אוֹתִיּוֹת אֲחֵרוֹת, מִמֶּנּוּ יוֹצְאוֹת עֶשֶׂר אֲמִירוֹת בַּגִּלּוּפִים שֶׁלּוֹ, וְכֻלָּם שְׁבִילִים שֶׁל הַדֶּרֶךְ הָעֶלְיוֹנָה, (של דרכי התורה) הַנִּכְבָּדָה מֵהַכֹּל. אֲזַי הֵ\"א אַחֶרֶת נִכְלֶלֶת מִכֻּלָּם, חֲקוּקָה מִצַּד מָתוּחַ (מתיחדת) טָמִיר לְהוֹלִיד לְמַטָּה.</p>\n<p>נֶחְקְקוּ (נחלקו) כֻלָּם בְּאַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת, וְאֶת כֻּלָּם פֵּרַשְׁנוּ בְמִשְׁנָתֵנוּ, וְכֻלָּם עוֹלִים לְרֹאשׁ הַמֶּלֶךְ.</p>\n<p>שֶׁבַע שַׁבָּתוֹת שְׁלֵמוֹת מִתְפָּרְשׁוֹת בְּשִׁבְעִים אוֹתִיּוֹת. שִׁבְעִים וּשְׁתַּיִם עָלוּ, וְהֵן עָלוּ בָּאוֹת ו' (יו\"ד), רְשׁוּמוֹת בְּפָרָשַׁת וַיְהִי בְּשַׁלַּח פַּרְעֹה בְּפָסוּק וַיִּסַּע וַיָּבא וַיֵּט. כְּשֶׁהַשְּׁכִינָה נוֹטֶלֶת וְשִׁבְעָה רִשּׁוּמִים נִרְשְׁמוּ בָהּ, מִתְעַלּוֹת שֶׁבַע מִמֶּנָּה בְּמַעֲשִׂים רְשׁוּמִים. לָמַדְנוּ שֶׁהִתְעַלּוּ הָאוֹתִיּוֹת בִּרְשָׁמִים יְדוּעִים וּדְרָכִים סְתוּמוֹת, פְּרָט לְצַדִּיקֵי אֱמֶת, עַמּוּדֵי הָעוֹלָם.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אֶלְעָזָר, בֹּא רְאֵה, עֶשְׂרִים וּשְׁתַּיִם הָאוֹתִיּוֹת שֶׁחֲקוּקוֹת בַּתּוֹרָה, כֻּלָּן מִתְפָּרְשׁוֹת (מאלו) בְּעֶשֶׂר הָאֲמִירוֹת הַלָּלוּ, כָּל אֲמִירָה וַאֲמִירָה מֵאוֹתָן הָעֶשֶׂר, שֶׁהֵן כִּתְרֵי הַמֶּלֶךְ, כֻּלָּן חֲקוּקוֹת בְּאוֹתִיּוֹת יְדוּעוֹת (אחרות). מִשּׁוּם כָּךְ הַשֵּׁם הַקָּדוֹשׁ מִתְכַּסֶּה בְּאוֹתִיּוֹת אֲחֵרוֹת, וְכָל אֲמִירָה מַלְוָה לַאֲמִירָה יוֹתֵר עֶלְיוֹנָה אֶת אוֹתִיּוֹתֶיהָ, מִשּׁוּם שֶׁנִּכְלָלוֹת זוֹ עִם זוֹ. וְלָכֵן אֶת הַשֵּׁם הַקָּדוֹשׁ חָקַקְנוּ אוֹתוֹ בְּאוֹתִיּוֹת אֲחֵרוֹת, מִשּׁוּם שֶׁהִתְכַּסּוּ זוֹ בְּזוֹ וְזוֹ בָּזוֹ, עַד שֶׁכֻּלָּן נִקְשָׁרוֹת כְּאַחַת.</p>\n<p>וּמִי שֶׁרוֹצֶה לָדַעַת אֶת צֵרוּפֵי הַשֵּׁמוֹת הַקְּדוֹשִׁים, שֶׁיֵּדַע אֶת אוֹתָן הָאוֹתִיּוֹת הָרְשׁוּמוֹת בְּכָל כֶּתֶר וְכֶתֶר, וְאָז יֵדַע וְיִתְקַיֵּם בַּכֹּל. וַהֲרֵי חָקַקְנוּ אוֹתָם בְּכָל אוֹתָן הָאוֹתִיּוֹת שֶׁרְשׁוּמוֹת וִידוּעוֹת בְּכָל כֶּתֶר וְכֶתֶר מֵהַסֵּפֶר הָעֶלְיוֹן שֶׁל שְׁלֹמֹה. וְכָךְ עָלָה בְיָדֵינוּ, וְהַחֲבֵרִים חָקְקוּ אוֹתָם, (ולחברים גלינו אותם) וְיָפֶה הוּא. שֶׁהֲרֵי כָּל כֶּתֶר וְכֶתֶר מַלְוֶה לַחֲבֵרוֹ אֶת אוֹתִיּוֹתָיו, כְּמוֹ שֶׁבֵּאַרְנוּ, וְלִפְעָמִים שֶׁלֹּא צָרִיךְ אֶלָּא בָּאוֹתִיּוֹת אוֹתָם שֶׁרְשׁוּמִים בּוֹ. וְכֻלָּם יְדוּעִים לַחֲבֵרִים, וַהֲרֵי בֵּאַרְנוּ אוֹתָם.</p>\n<p>אַשְׁרֵי הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּכְבוֹדָם וּמְגַלֶּה לָהֶם סוֹדוֹת עֶלְיוֹנִים שֶׁל שְׁמוֹ הַקָּדוֹשׁ, שֶׁלֹּא גִלָּה לְעֶלְיוֹנִים קְדוֹשִׁים, וְעַל זֶה יָכֹל מֹשֶׁה לְהִתְעַטֵּר בֵּין קְדוֹשִׁים, וְכֻלָּם לֹא יָכְלוּ לְהִתְקָרֵב אֵלָיו, כְּאֵשׁ יוֹקֶדֶת וְגַחֲלֵי אֵשׁ. שֶׁאִם לֹא כָּךְ, מִי הָיָה לוֹ לְמֹשֶׁה לַעֲמֹד בֵּינֵיהֶם? אֶלָּא אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁהֲרֵי כְּשֶׁהִתְחִיל לְדַבֵּר עִמּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, רָצָה לָדַעַת אֶת שְׁמוֹ הַקָּדוֹשׁ (שמותיו הקדושים), נִסְתָּר וְנִגְלֶה, בְּכָל אֶחָד וְאֶחָד כָּרָאוּי, וְאָז נִדְבַּק וְיָדַע יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁעָלָה מֹשֶׁה לְתוֹךְ הֶעָנָן הַנִּכְבָּד, נִכְנַס לְבֵין קְדוֹשִׁים. פָּגַע בּוֹ מַלְאָךְ אֶחָד בְּשַׁלְהֲבוֹת אֵשׁ, בְּעֵינַיִם לוֹהֲטוֹת, וּכְנָפָיו שׂוֹרְפוֹת. רָצָה לִשְׁאֹף אוֹתוֹ לְתוֹכוֹ. וְשֵׁם אוֹתוֹ מַלְאָךְ גַּבְרִיאֵל (גזריא\"ל) (גזרנא\"ל). אָז הִזְכִּיר מֹשֶׁה שֵׁם קָדוֹשׁ אֶחָד שֶׁהָיָה חָקוּק עִם שְׁתֵּים עֶשְׂרֵה אוֹתִיּוֹת, וְהִזְדַּעֲזַע וְהִתְרַגֵּשׁ, עַד שֶׁעָלָה מֹשֶׁה בֵּינֵיהֶם, וְכֵן לְכָל אֶחָד וְאֶחָד. אַשְׁרֵי חֶלְקוֹ, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים.</p>"],[9522012155,"<p>עָרְוַת אִשָּׁה וּבִתָּהּ לֹא תְגַלֵּה. לָמַדְנוּ, בְּתִקּוּנֵי הַגְּבִירָה בֵּאַרְנוּ אֶת הָעֲרָיוֹת הַלָּלוּ, אַף עַל גַּב שֶׁהֵם (עריות הם) בַּנִּגְלֶה וּבַנִּסְתָּר, וְשָׁם בַּת בְּנָהּ וּבַת בִּתָּהּ. שֶׁהֲרֵי הָעוֹלָם צָרִיךְ אוֹתָם, וְהֵם יִשּׁוּבוֹ שֶׁל עוֹלָם, כְּמוֹ שֶׁבֵּאַרְנוּ. וּמִי שֶׁמְּגַלֶּה עֶרְוָה אַחַת מֵהֶן, אוֹי לוֹ וְאוֹי לְנַפְשׁוֹ, שֶׁהֲרֵי גִּלָּה בִּשְׁבִיל זֶה עֲרָיוֹת אֲחֵרוֹת.</p>\n<p>וְלָמַדְנוּ, הַדִּבּוּר הָאַחֲרוֹן שֶׁל עֶשֶׂר הָאֲמִירוֹת שֶׁל הַתּוֹרָה - (שמות כ) לֹא תַחְמֹד אֵשֶׁת רֵעֶךְ, כִּי זֶהוּ הַכְּלָל שֶׁל כֻּלָּם. וּמִי שֶׁחוֹמֵד אִשָּׁה אַחֶרֶת כְּאִלּוּ עָבַר עַל כָּל הַתּוֹרָה. בְּרַם, אֵין דָּבָר שֶׁעוֹמֵד לִפְנֵי תְשׁוּבָה, וְכָל שֶׁכֵּן אִם קִבֵּל עָנְשׁוֹ כְּמוֹ דָּוִד הַמֶּלֶךְ. אָמַר רַבִּי יוֹסֵי, שָׁנִינוּ, כָּל מִי שֶׁחָטָא וּפָרַשׁ מֵאוֹתוֹ חֵטְא, הַתְּשׁוּבָה מוֹעִילָה לוֹ יוֹתֵר. וְאִם לֹא, לֹא עוֹלָה בְיָדוֹ תְּשׁוּבָה וְלֹא מוֹעִילָה לוֹ. אִם כָּךְ, אָז אֵיךְ דָּוִד לֹא פָרַשׁ מִבַּת שֶׁבַע לְאַחַר מִכֵּן? אָמַר לוֹ, בַּת שֶׁבַע הָיְתָה שֶׁלּוֹ, וְאֶת שֶׁלּוֹ הוּא לָקַח, שֶׁהֲרֵי מֵת בַּעְלָהּ.</p>\n<p>שֶׁלָּמַדְנוּ, מְזֻמֶּנֶת הָיְתָה בַּת שֶׁבַע לְדָוִד מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, וּמָה עִכֵּב אוֹתוֹ? שֶׁנָּשָׂא אֶת בִּתּוֹ שֶׁל שָׁאוּל הַמֶּלֶךְ, וְאוֹתוֹ יוֹם נָשָׂא אוֹתָהּ אוּרִיָּה בְּרַחֲמִים, אַף עַל גַּב שֶׁלֹּא הָיְתָה שֶׁלּוֹ. אַחַר כָּךְ בָּא דָוִד וְנָטַל אֶת שֶׁלּוֹ. וְעַל שֶׁדָּוִד דָּחַק אֶת הַשָּׁעָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לַהֲרֹג אֶת אוּרִיָּה וְלַעֲשׂוֹת כָּךְ, הֵרַע לְפָנָיו, וְהֶעֱנִישׁ אֶת דָּוִד, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה לַהֲשִׁיבָהּ לְדָוִד, לְקַיֵּם לוֹ אֶת הַמַּלְכוּת הַקְּדוֹשָׁה הָעֶלְיוֹנָה. וּכְשֶׁהִשְׁתּוֹקֵק, לְשֶׁלּוֹ הִשְׁתּוֹקֵק.</p>\n<p>לָמַדְנוּ, אָמַר רַבִּי יוֹסֵי, מַהוּ שֶׁכָּתוּב אֲנִי ה' - אֲנִי ה' עָתִיד לִתֵּן שָׂכָר טוֹב לַצַּדִּיקִים לֶעָתִיד לָבא. אֲנִי ה' עָתִיד לְהִפָּרַע מִן הָרְשָׁעִים לֶעָתִיד לָבֹא, אוֹתָם שֶׁכָּתוב בָּהֶם הַפֹּשְׁעִים בִּי. כָּתוּב אֲנִי ה', וְכָתוּב (דברים לב) אֲנִי אָמִית וַאֲחַיֶּה. אַף עַל פִּי שֶׁאֲנִי בְּמִדַּת הָרַחֲמִים, הָרְשָׁעִים הוֹפְכִים אוֹתִי לְמִדַּת הַדִּין. שֶׁלָּמַדְנוּ, שֵׁם מָלֵא - ה' אֱלֹהִים. זָכוּ - ה', וְאִם לֹא - אֱלֹהִים. אָמַר רַבִּי שִׁמְעוֹן, הָרְשָׁעִים עוֹשִׂים פְּגָם לְמַעְלָה. אֵיזֶה פְּגָם? כְּמוֹ שֶׁבֵּאַרְנוּ פְּגָם מַמָּשׁ, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522012156,"<p>לָמַדְנוּ, כָּתוּב וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לֹא תִקְרַב לְגַלּוֹת עֶרְוָתָהּ. שָׁנָה רַבִּי יְהוּדָה, דּוֹר שֶׁרַבִּי שִׁמְעוֹן בַּר יוֹחַאי שָׁרוּי בְּתוֹכוֹ, כֻּלָּם צַדִּיקִים, חֲסִידִים, כֻּלָּם הֵם יִרְאֵי חֵטְא, וּשְׁכִינָה שׁוֹרָה בֵינֵיהֶם, מַה שֶּׁאֵין כֵּן בְּדוֹרוֹת אֲחֵרִים. מִשּׁוּם כָּךְ הַדְּבָרִים הַלָּלוּ מִתְפָּרְשִׁים וְלֹא נִטְמָנִים. בְּדוֹרוֹת אֲחֵרִים לֹא כֵן, וּדְבָרִים שֶׁל סוֹדוֹת עֶלְיוֹנִים לֹא יְכוֹלִים לְגַלּוֹת, וְאוֹתָם שֶׁיּוֹדְעִים פּוֹחֲדִים. שֶׁכַּאֲשֶׁר הָיָה רַבִּי שִׁמְעוֹן אוֹמֵר סוֹד הַפָּסוּק הַזֶּה, עֵינֵי כָּל הַחֲבֵרִים נָבְעוּ דְמָעוֹת, וְכָל הַדְּבָרִים שֶׁאָמַר הָיוּ בְעֵינֵיהֶם גְּלוּיִים, כְּמוֹ שֶׁכָּתוּב (במדבר יב) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה וְלֹא בְחִידת.</p>"],[9522012157,"<p>שֶׁיּוֹם אֶחָד שָׁאַל רַבִּי יֵיסָא, אָמַר, בֵּיצָה שֶׁל אֱמֶת (מדה) שֶׁיָּצְאָה מֵעוֹף שֶׁשָּׁרוּי (שנזרק) בְּאוּר, וְהִתְבַּקְּעָה לְאַרְבָּעָה צְדָדִים, שְׁנַיִם עוֹלִים מֵהֶם, וְאֶחָד מִתְנַמֵּךְ, וְאֶחָד רוֹבֵץ בְּמִרְבָּץ (מבועי המעין) שֶׁל הַיָּם הַגָּדוֹל. אָמַר רַבִּי אַבָּא, עָשִׂיתָ לִפְנֵי רַבִּי שִׁמְעוֹן קֹדֶשׁ חֹל, שֶׁהֲרֵי כָּתוּב פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ. אָמַר לוֹ רַבִּי שִׁמְעוֹן, טֶרֶם שֶׁתִּתְבַּקַּע הַבֵּיצָה, תִּסְתַּלֵּק מִן הָעוֹלָם. וְכָךְ הָיָה בָּאִדְּרָא שֶׁל רַבִּי שִׁמְעוֹן.</p>\n<p>לָמַדְנוּ, בִּימֵי רַבִּי שִׁמְעון הָיָה אומֵר אָדָם לַחֲבֵרוֹ: פְּתַח פִּיךְ וְיָאִירוּ דְבָרֶיךְ. אַחַר שֶׁנִּפְטַר רַבִּי שִׁמְעוֹן, הָיוּ אוֹמְרִים: (קהלת ה) אַל תִּתֵּן אֶת פִּיךְ לַחֲטִיא אֶת בְּשָׂרֶךְ.</p>"],[9522012158,"<p>לָמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן, אִם בְּנֵי הָעוֹלָם מִסְתַּכְּלִים בְּמַה שֶּׁכָּתוּב בַּתּוֹרָה, לֹא יָבוֹאוּ לְהַרְגִּיז לִפְנֵי רִבּוֹנָם. לָמַדְנוּ, כְּשֶׁמִּתְעוֹרְרִים הַדִּינִים הַקָּשִׁים לָרֶדֶת לָעוֹלָם, וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ וְגוֹ'. כָּאן כָּתוּב (תהלים כה) סוֹד ה' לִירֵאָיו, וּבָאִדְּרָא (ובדור הזה) הַקְּדוֹשָׁה נֶאֱמַר, כָּאן הִצְטָרַכְנוּ לְגַלּוֹת, שֶׁהֲרֵי לַמָּקוֹם הַזֶּה הִסְתַּלֵּק.</p>\n<p>שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁהַנָּחָשׁ הַתַּקִּיף שֶׁל מַעְלָה הִתְעוֹרֵר בִּשְׁבִיל חֲטָאֵי בְּנֵי הָאָדָם, הִתְחִיל לְהִתְחַבֵּר עִם נְקֵבָה וְהִטִּיל בָּהּ זֻהֲמָה, נִפְרָד מִמֶּנָּה הַזָּכָר, מִשּׁוּם שֶׁהֲרֵי נִטְמְאָה וְנִקְרֵאת טְמֵאָה, וְאֵין רָאוּי לַזָּכָר לִקְרַב אֵלֶיהָ. שֶׁאוֹי אִם הוּא נִטְמָא עִמָּהּ בִּזְמַן שֶׁהִיא טְמֵאָה.</p>"],[9522012159,"<p>וְלָמַדְנוּ, מֵאָה עֶשְׂרִים וַחֲמִשָּׁה מִינֵי טֻמְאָה יָרְדוּ לָעוֹלָם שֶׁאֲחוּזִים מִצִּדּוֹ שֶׁל הַנָּחָשׁ הֶחָזָק, וְשִׁבְעָה וְעֶשְׂרִים גְּדוֹלִים מֵהֶם נֶאֱחָזִים בַּנְּקֵבוֹת וְנִדְבָּקִים בָּהֶם. אוֹי לְמִי שֶׁיִּקְרַב אֵלֶיהָ בְּאוֹתוֹ זְמַן, שֶׁמִּי שֶׁיִּקְרַב עִמָּהּ, מַרְאֶה פְגָם לְמַעְלָה, שֶׁהֲרֵי בַּחֵטְא הַזֶּה מִתְעוֹרֵר הַנָּחָשׁ הַקָּשֶׁה לְמַעְלָה וּמַטִּיל זֻהֲמָה בְּמָקוֹם שֶׁלֹּא צָרִיךְ, וּמִתְחַבֵּר עִם הַנְּקֵבָה, וּגְדֵלוֹת שַׂעֲרוֹתָיו שֶׁל הַזָּכָר, וְהַנְּקֵבָה נִטְמֵאת, וּשְׂעָרָהּ גָּדוֹל וְצִפָּרְנֶיהָ גְּדוֹלוֹת, וְאָז הַדִּינִים שׁוֹרִים לְהִתְעוֹרֵר בָּעוֹלָם וְנִטְמָאִים הַכֹּל. זֶהוּ שֶׁכָּתוּב (במדבריט) כִּי אֶת מִקְדַּשׁ ה' טִמֵּא, מִקְדַּשׁ ה' נִטְמָא בַּחֲטָאֵי בְּנֵי הָאָדָם.</p>\n<p>לָמַדְנוּ, מַה שֶּׁכָּתוּב (בראשית ג) וְאֵיבָה אָשִׁית בֵּינְךְ וּבֵין הָאִשָּׁה, אַרְבָּעָה וְעֶשְׂרִים מִינֵי טֻמְאָה הִטִּיל הַנָּחָשׁ בַּנְּקֵבָה כְּשֶׁהִתְחַבֵּר עִמָּהּ, כְּחֶשְׁבּוֹן וְאֵיבָה, וְעֶשְׂרִים וְאַרְבָּעָה מִינִים (דינים) מִתְעוֹרְרִים לְמַעְלָה, וְעֶשְׂרִים וְאַרְבָּעָה לְמַטָּה. וְשֵׂעָר גָּדוֹל וְצִפָּרְנַיִם גְּדוֹלוֹת, וְאָז מִתְעוֹרְרִים הַדִּינִים בַּכֹּל. וְלָמַדְנוּ, כְּשֶׁרוֹצָה אִשָּׁה לְהִטָּהֵר, צְרִיכָה לְסַפֵּר אוֹתוֹ שֵׂעָר שֶׁגָּדַל בַּיּוֹם שֶׁהִיא טְמֵאָה, וּלְסַפֵּר אֶת צִפָּרְנֶיהָ, וְכָל אוֹתָהּ זֻהֲמָה שֶׁבָּהֶן.</p>"],[9522012160,"<p>שֶׁלָּמַדְנוּ בְּסוֹדוֹת הַטֻּמְאָה, שֶׁזֻּהֲמַת הַצִּפָּרְנַיִם מְעוֹרֶרֶת זֻהֲמָה אַחֶרֶת, וּמִשּׁוּם כָּךְ צְרִיכִים גְּנִיזָה, וּמִי שֶׁמַּעֲבִירָם לְגַמְרֵי, כְּאִלּוּ הֵעִיר חֶסֶד בָּעוֹלָם. שֶׁלָּמַדְנוּ, אֵין צָרִיךְ אָדָם לָתֵת זֵכֶר לְמִינִים רָעִים. שֶׁשָּׁנִינוּ, אֶלֶף וְאַרְבַּע מֵאוֹת וַחֲמִשָּׁה מִינִים רָעִים נֶאֱחָזִים בְּאוֹתָהּ הַזֻּהֲמָה שֶׁהִטִּיל הַנָּחָשׁ הֶחָזָק, וְכֻלָּם מִתְעוֹרְרִים בְּאוֹתָהּ זֻהֲמַת הַצִּפָּרְנַיִם.</p>\n<p>וַאֲפִלּוּ מִי שֶׁרוֹצֶה, יַעֲשֶׂה בָהֶם כְּשָׁפִים לִבְנֵי אָדָם, מִשּׁוּם אוֹתָם שֶׁתְּלוּיִים בָּהֶם. וּמִי שֶׁמַּעֲבִירָם, כְּאִלּוּ הִרְבָּה חֶסֶד בָּעוֹלָם, וְדִינִים רָעִים לֹא נִמְצָאִים, וְתַעֲבֹר אוֹתָהּ זֻהֲמָה וְצִפָּרְנֶיהָ שֶׁרְשׁוּמוֹת בָּהּ. שֶׁלָּמַדְנוּ, מִי שֶׁדּוֹרֵךְ בְּרַגְלוֹ אוֹ בְּנַעֲלוֹ עֲלֵיהֶן, יָכוֹל לְהִנָּזֵק. וּמַה בְּשִׁיּוּרֵי הַשִּׁירַיִם שֶׁל הַזֻּהֲמָה שֶׁלְּמַעְלָה כָּךְ - אִשָּׁה שֶׁמְּקַבֶּלֶת וּמִתְחַבֶּרֶת עִם הַנָּחָשׁ וְהִטִּיל בָּהּ זֻהֲמָה עַל אַחַת כַּמָּה וְכַמָּה. אוֹי לָעוֹלָם שֶׁמְּקַבֵּל מִמֶּנָּה אוֹתָהּ זֻהֲמָה. מִשּׁוּם כָּךְ, וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לֹא תִקְרַב.</p>"],[9522012161,"<p>אָמַר רַבִּי שִׁמְעוֹן, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: הָבִיאוּ עָלַי כַּפָּרָה בְּרֹאשׁ חֹדֶשׁ. עָלַי וַדַּאי, כְּדֵי שֶׁיָּעֳבַר אוֹתוֹ הַנָּחָשׁ וְיִתְבַּשֵּׂם מִי שֶׁצָּרִיךְ. עָלַי, כְּמוֹ שֶׁכָּתוּב (ישעיה ו) שְׂרָפִים עֹמְדִים מִמַּעַל לוֹ. וְעַל זֶה כָּתוּב בְּקֹרַח, (במדבר טז) הַנֹּעָדִים עַל ה', שֶׁבִּגְלָלָם מִתְעוֹרֵר מִי שֶׁמִּתְעוֹרֵר שֶׁבָּא מִצִּדָּם. אַף כָּאן הָבִיאוּ עָלַי כַּפָּרָה, עָלַי מַמָּשׁ, כְּדֵי שֶׁיִּתְבַּשֵּׂם וְיָעֳבַר וְלֹא יִמָּצֵא הַנָּחָשׁ בְּמָקוֹם שֶׁשּׁוֹרֶה. וְכָל כָּךְ לָמָּה? עַל שֶׁמִּעַטְתִּי אֶת הַיָּרֵחַ וְשׁוֹלֵט בָּהּ מִי שֶׁלֹּא צָרִיךְ. וּמִשּׁוּם כָּךְ כָּתוּב, וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לֹא תִקְרַב.</p>\n<p>אַשְׁרֵי הַדּוֹר שֶׁרַבִּי שִׁמְעוֹן בֶּן יוֹחַאי שָׁרוּי בְּתוֹכוֹ. אַשְׁרֵי גּוֹרָלוֹ בֵּין עֶלְיוֹנִים וְתַחְתּוֹנִים. עָלָיו כָּתוּב (קהלת י) אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִים. מַהוּ בֶּן חוֹרִים? שֶׁזּוֹקֵף רֹאשׁ לְגַלּוֹת וּלְפָרֵשׁ דְּבָרִים וְאֵינוֹ פּוֹחֵד. כָּזֶה שֶׁהוּא בֶּן חוֹרִין, וְיֹאמַר מַה שֶּׁהוּא רוֹצֶה וְלֹא פוֹחֵד. מִי זֶה מַלְכֵּךְ? זֶה הוּא רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי, בַּעַל הַתּוֹרָה, בַּעַל הַחָכְמָה. שֶׁכְּשֶׁהָיָה רַבִּי אַבָּא וְהַחֲבֵרִים רוֹאִים אֶת רַבִּי שִׁמְעוֹן, הָיוּ רָצִים אַחֲרָיו וְאוֹמְרִים: (הושע יא) אַחֲרֵי ה' יֵלְכוּ כְּאַרְיֵה יִשְׁאָג.</p>"],[9522012162,"<p>אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ. לָמָּה שָׁקוּל זֶה בָּזֶה? אֶלָּא הַכֹּל בְּדַרְגָּה אַחַת עוֹלֶה. זֶה מִזְדַּוֵּג עִם זֶה, וְשִׂמְחָה שֶׁל זֶה עִם זֶה לֹא נִמְצֵאת, אֶלָּא כְּשֶׁמִּתְגַּלֶּה הָעַתִּיק הַקָּדוֹשׁ, אָז זוֹהִי חֶדְוַת הַכֹּל. וְשָׁנִינוּ, כָּתוּב (תהלים צב) מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת, לְיוֹם הַשַּׁבָּת מַמָּשׁ. הַשֶּׁבַח שֶׁמְּשַׁבֵּחַ הַקָּדוֹשׁ בָּרוּךְ הוּא, אֲזַי נִמְצֵאת שִׂמְחָה, וּנְשָׁמָה מִתּוֹסֶפֶת. שֶׁהֲרֵי הָעַתִּיק הִתְגַּלָּה, וְהַזִּוּוּג יִזְדַּמֵּן.</p>\n<p>אַף כָּךְ בְּחִדּוּשׁ הַלְּבָנָה, שֶׁהֲרֵי מֵאִיר הַשֶּׁמֶשׁ בְּשִׂמְחַת הָאוֹר שֶׁל הָעַתִּיק לְמַעְלָה. מִשּׁוּם כָּךְ הַקָּרְבָּן הַזֶּה הוּא לְמַעְלָה, כְּדֵי שֶׁהַכֹּל יִתְבַּשֵּׂם וְתִמָּצֵא שִׂמְחָה בָּעוֹלָם, וְעַל כֵּן הָבִיאוּ עָלַי כַּפָּרָה, דָּבָר מְדֻיָּק.</p>\n<p>לָמַדְנוּ, כָּתוּב (במדבר כח) עֹלַת שַׁבַּת בְּשַׁבַּתּוֹ עַל עֹלַת הַתָּמִיד, שֶׁצָּרִיךְ לְכַוֵּן אֶת הַלֵּב לְמַעְלָה לְמַעְלָה יוֹתֵר מִבִּשְׁאָר הַיָּמִים. וְעַל זֶה עַל עֹלַת הַתָּמִיד דַּוְקָא. לָמַדְנוּ, כָּתוּב בְּחַנָּה (שמואל א א) וַתִּתְפַּלֵּל חַנָּה עַל ה', עַל דַּוְקָא, מִשּׁוּם שֶׁהַבָּנִים תְּלוּיִים בַּמַּזָּל הַקָּדוֹשׁ, כְּמוֹ שֶׁבֵּאַרְנוּ. וְאֵין לְךְ דָּבָר בַּתּוֹרָה אוֹ אוֹת קְטַנָּה בַּתוֹרָה שֶׁלֹּא רְמוּזָה בַּחָכְמָה הָעֶלְיוֹנָה, וּתְלוּיִים מִמֶּנָּה תִּלֵּי תִלִּים שֶׁל סוֹדוֹת הַחָכְמָה הָעֶלְיוֹנָה. זֶהוּ שֶׁכָּתוּב (שיר ה) ק1ְוֵצּוֹתָיו תַּלְתַּלִּים, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522012163,"<p>רַבִּי יוֹסֵי מָצָא אֶת רַבִּי אַבָּא שֶׁהָיָה יוֹשֵׁב וְקוֹרֵא אֶת הַפָּסוּק שֶׁכָּתוּב, (תהלים נה) הַשְׁלֵךְ עַל ה' יְהָבְךְ, עַל דַּוְקָא. שֶׁהֲרֵי מְזוֹנוֹת תְּלוּיִים בְּמַזָּל. רַבִּי יְהוּדָה הָיָה קוֹרֵא, (שם לב) על זאת יתפלל כל חסיד אליך לְעֵת מְצֹא. עַל זֹּאת וַדַּאי. לְעֵת מְצֹא, הֲרֵי בֵּאַרְנוּ. אֲבָל לְעֵת מְצֹא, כְּמוֹ שֶׁכָּתוּב (ישעיה נה) דִּרְשׁוּ ה' בְּהִמָּצְאוֹ קְרָאֻהוּ בִּהְיוֹתוֹ קָרוֹב. דָּבָר אַחֵר לְעֵת מְצֹא - בְּשָׁעָה שֶׁנְּהָרוֹת שׁוֹפְעִים וְנִמְשָׁכִים, וְהָאָבוֹת נֶהֱנִים, וְהַכֹּל מִתְבָּרְכִים. רַק לְשֵׁטֶף מַיִם רַבִּים, מִי זֶה הַשֵּׁטֶף מַיִם רַבִּים? זֶהוּ עֹמֶק הַנְּחָלִים וְהַנְּהָרוֹת, שֶׁמִּי יִזְכֶּה לוֹ וּמִי יִזְכֶּה לְהִתְקָרֵב וְלַעֲלוֹת לְשָׁם. זֶהוּ שֶׁכָּתוּב בּוֹ, (תהלים לה) רַק לְשֵׁטֶף מַיִם רַבִּים אֵלָיו לֹא יַגִּיעוּ, שֶׁהֲרֵי לֹא זוֹכִים וְלֹא יְכוֹלִים.</p>\n<p>רַבִּי יִצְחָק אָמַר, כָּתוּב (שם כז) אַחַת שָׁאַלְתִּי מֵאֵת ה' אוֹתָהּ אֲבַקֵּשׁ וְגוֹ'. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁכַּמָּה גְנָזִים עֶלְיוֹנִים שְׁמוּרִים לָהֶם בְּאוֹתוֹ הָעוֹלָם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ עִמָּם בְּאוֹתָם הָעוֹלָמוֹת, כְּמוֹ שֶׁבֵּאַרְנוּ בְּנֹעַם ה', וַהֲרֵי נִתְבָּאֵר. רַבִּי חִזְקִיָּה אָמַר, מִכָּאן (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ. יַעֲשֶׂה?! תַּעֲשֶׂה הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא יַעֲשֶׂה וַדַּאי. הַיְנוּ (שם לח) יוֹסִף עַל יָמֶיךְ חֲמֵשׁ עֶשְׂרֵה שָׁנָה. וְהַיְנוּ הַשְׁלֵךְ עַל ה' יְהָבְךְ. וְכָתוּב וַתִּתְפַּלֵּל עַל ה'. וְהַכֹּל אֶחָד.</p>\n<p>אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. עֲלֵיהֶם כָּתוּב (תהלים ה) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנֵּנוּ וְתָסֵךְ עָלֵימוֹ וְיַעְלְצוּ בְךְ אֹהֲבֵי שְׁמֶךְ. וְכָתוּב (שם קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ. וְכָתוּב (שם ט) וְיִבְטְחוּ בְךְ יוֹדְעֵי שְׁמֶךְ כִּי לֹא עָזַבְתָּ דֹּרְשֶׁיךְ ה'. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן. יִמְלֹךְ יְיָ לְעוֹלָם אָמֵן וִאָמֵן.</p>"],[9522012164,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵּאמֹר דַּבֵּר אֶל כָּל עֲדַת בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵהֶם קְדשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי ה' אֱלֹהֵיכֶם. רַבִּי אֶלְעָזָר פָּתַח, (תהלים לב) אַל תִּהְיוּ כְּסוּס כְּפֶרֶד אֵין הָבִין וְגוֹ'. בְּכַמָּה פְעָמִים הַתּוֹרָה מְעִידָה בִּבְנֵי אָדָם, כַּמָּה פְעָמִים הִיא מְרִימָה קוֹלוֹת לְכָל הַצְּדָדִים לְהָעִיר אוֹתָם, וְכֻלָּם רְדוּמִים בְּשֵׁנָה בַּחֲטָאֵיהֶם (בחוריהם), אֵינָם מִסְתָּכְּלִים וְאֵינָם מַשְׁגִּיחִים בְּאֵיזֶה פָנִים יַעַמְדוּ לְיוֹם הַדִּין הָעֶלְיוֹן, כְּשֶׁיִּתְבַּע אוֹתָם הַמֶּלֶךְ הָעֶלְיוֹן עַל עֶלְבּוֹן הַתּוֹרָה שֶׁצּוֹעֶקֶת כְּנֶגְדָּם, וְאֵינָם מַחֲזִירִים פְּנֵיהֶם מוּלָהּ, שֶׁכֻּלָּם פְּגוּמִים בַּכֹּל, שֶׁאֵינָם יוֹדְעִים אֶת אֱמוּנַת הַמֶּלֶךְ הָעֶלְיוֹן, אוֹי לָהֶם וְאוֹי לְנַפְשָׁם!</p>\n<p>שֶׁהֲרֵי הַתּוֹרָה מְעִידָה בּוֹ וְאוֹמֶרֶת, (משלי ט) מִי פֶתִי יָסֻר הֵנָּה חֲסַר לֵב (ואמרה) אָמְרָה לּוֹ. מַה זֶּה חֲסַר לֵב? שֶׁאֵין בּוֹ אֱמוּנָה. שֶׁמִּי שֶׁאֵינוֹ עוֹסֵק בַּתּוֹרָה, אֵין בּוֹ אֱמוּנָה וּפָגוּם הוּא מֵהַכֹּל. (ואמרה) אָמְרָה לּוֹ?! אוֹמְרָה לוֹ הָיָה צָרִיךְ לִהְיוֹת, כְּמוֹ שֶׁנֶּאֱמַר (תהלים מב) אוֹמְרָה לְאֵל סַלְעִי. מַה זֶּה אָמְרָה? אֶלָּא לְהַכְלִיל וּלְהוֹסִיף אֶת הַתּוֹרָה שֶׁלְּמַעְלָה, שֶׁהִיא קוֹרֵאת לוֹ חֲסַר לֵב, פָּגוּם מֵהָאֱמוּנָה.</p>\n<p>שֶׁכָּךָ שָׁנִינוּ, שֶׁכָּל מִי שֶׁלֹּא מִשְׁתַּדֵּל בַּתּוֹרָה, אָסוּר לוֹ לְהִתְקָרֵב אֵלָיו, לְהִשְׁתַּתֵּף עִמּוֹ וְלַעֲשׂוֹת עִמּוֹ סְחוֹרָה, וְכָל שֶׁכֵּן לָלֶכֶת עִמּוֹ בַּדֶּרֶךְ, שֶׁהֲרֵי אֵין בּוֹ אֱמוּנָה. (ועל זה) שָׁנִינוּ, כָּל אָדָם שֶׁהוֹלֵךְ בַּדֶּרֶךְ וְאֵין עִמּוֹ דִּבְרֵי תוֹרָה, מִתְחַיֵּב בְּנַפְשׁוֹ. כָּל שֶׁכֵּן מִי מִתְחַבֵּר בַּדֶּרֶךְ עִם מִי שֶׁאֵין בּוֹ אֱמוּנָה, שֶׁלֹּא מַחֲשִׁיב אֶת כְּבוֹד אֲדוֹנוֹ וְאֶת שֶׁלּוֹ, שֶׁלֹּא חָס עַל נַפְשׁוֹ.</p>\n<p>רַבִּי יְהוּדָה אוֹמֵר, מִי שֶׁלֹּא חָס עַל נַפְשׁוֹ, אֵיךְ יִשְׁלֹף נֶפֶשׁ כְּשֵׁרָה לִבְנוֹ? אָמַר רַבִּי אֶלְעָזָר, תְּמֵהַנִי עַל הַדּוֹר, וַהֲרֵי הַדָּבָר נֶאֱמַר וְכוּ'. וְעַל זֶה כָּתוּב אַל תִּהְיוּ כְּסוּס כְּפֶרֶד אֵין הָבִין. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וְיוֹדְעִים אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמְקַדְּשִׁים אֶת עַצְמָם בִּקְדֻשַּׁת הַמֶּלֶךְ, וְנִמְצָאִים קְדוֹשִׁים בַּכֹּל, וּמִשּׁוּם כָּךְ שׁוֹלְפִים רוּחַ שֶׁל קֹדֶשׁ מִלְמַעְלָה, וְכָל בְּנֵיהֶם הֵם צַדִּיקֵי אֱמֶת, וְנִקְרָאִים בְּנֵי הַמֶּלֶךְ, בָּנִים קְדוֹשִׁים.</p>\n<p>אוֹי לָהֶם לָרְשָׁעִים, שֶׁכֻּלָּם חֲצוּפִים וּמַעֲשֵׂיהֶם חֲצוּפִים, וּמִשּׁוּם כָּךְ יוֹרְשִׁים בְּנֵיהֶם נֶפֶשׁ חֲצוּפָה מִצַּד הַטֻּמְאָה, כְּמוֹ שֶׁכָּתוּב וְנִטְמֵתֶם בָּם. בָּא לְהִטָּמֵא - מְטַמְּאִים אוֹתוֹ. אַל תִּהְיוּ כְּסוּס כְּפֶרֶד, שֶׁהֵם בַּעֲלֵי זְנוּת (של טמאה) עַל הַכֹּל. אֵין הָבִין, שֶׁלֹּא יִשְׁתַּדְּלוּ אֲנָשִׁים בַּדֶּרֶךְ הַזּוֹ. שֶׁאִם כָּךְ, כָּתוּב כָּאן אֵין הָבִין, וְכָתוּב שָׁם (ישעיה נו) וְהַכְּלָבִים עַזֵּי נֶפֶשׁ לֹא יָדְעוּ שָׂבְעָה וְהֵמָּה רֹעִים לֹא יָדְעוּ הָבִין. כְּלומַר, יִהְיוּ מִזְדַּמְּנִים אותָם שֶׁנִּקְרָאִים עַזֵּי נֶפֶשׁ. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא יָדְעוּ הָבִין.</p>\n<p>וְהֵמָּה רֹעִים, מַה זֶּה רֹעִים? אֵלּוּ אוֹתָם הַמּוֹבִילִים וְהַמַּנְהִיגִים אֶת הָאָדָם לַגֵּיהִנֹּם. לֹא יָדְעוּ שָׂבְעָה, כְּמוֹ שֶׁנֶּאֱמַר (משלי ל) לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב. מִשּׁוּם כָּךְ שֶׁהֵם הַב הַב, לֹא יָדְעוּ שָׂבְעָה. כֻּלָּם לְדַרְכָּם פָּנוּ אִישׁ לְבִצְעוֹ מִקָּצֵהוּ. שֶׁהֲרֵי הֵם תַּיָּרֵי הַגֵּיהִנֹּם. וְכָל זֶה מִי גָרַם לָהֶם? מִשּׁוּם שֶׁלֹּא הִתְקַדְּשׁוּ בְּאוֹתוֹ זִוּוּג כְּמוֹ שֶׁצָּרִיךְ. וְעַל זֶה כָּתוּב, קְדשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי ה'. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מִכָּל שְׁאָר הָעַמִּים לֹא רָצִיתִי לְהַדְבִּיק בִּי אֶלָּא רַק יִשְׂרָאֵל, שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה'. אַתֶּם, וְלֹא שְׁאָר הָעַמִּים. (ועל כן כתוב כאן קדוש) מִשּׁוּם כָּךְ (קדשים תהיו דוקא).</p>"],[9522012165,"<p>קְדֹשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי ה'. רַבִּי יִצְחָק פָּתַח, (ישעיה יח) הוֹי אֶרֶץ צִלְצַל כְּנָפָיִם וְגוֹ'. וְכִי מִשּׁוּם שֶׁהִיא אֶרֶץ צִלְצַל כְּנָפָיִם נִמְצָא בָּהּ קִנְטוּר, שֶׁכָּתוּב הוֹי אֶרֶץ? אֶלָּא אָמַר רַבִּי יִצְחָק, בְּשָׁעָה שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם וְרָצָה לְגַלּוֹת עֲמֻקּוֹת מִתּוֹךְ הַהֶסְתֵּר, וְאוֹר מִתּוֹךְ הַחֲשֵׁכָה, הָיוּ כְלוּלִים זֶה עִם זֶה. וּמִשּׁוּם כָּךְ מִתּוֹךְ הַחֲשֵׁכָה יָצָא אוֹר, וּמִתּוֹךְ הַהֶסְתֵּר יָצָא וְהִתְגַּלָּה הֶעָמֹק, וְזֶה יָצָא מִזֶּה. שֶׁמִּתּוֹךְ הַטּוֹב יוֹצֵא הָרָע, וּמִתּוֹךְ הָרַחֲמִים יוֹצֵא דִין, וְהַכֹּל נִכְלָל זֶה בָּזֶה - יֵצֶר טוֹב וְיֵצֶר הָרָע, יָמִין וּשְׂמֹאל, יִשְׂרָאֵל וּשְׁאָר הָעַמִּים, לָבָן וְשָׁחֹר, וְהַכֹּל תָּלוּי הָאֶחָד בָּאֶחָד.</p>\n<p>לָמַדְנוּ, אָמַר רַבִּי יִצְחָק אָמַר רַבִּי יְהוּדָה, כָּל הָעוֹלָם כֻּלּוֹ לֹא נִרְאֶה, אֶלָּא בַּעֲטָרָה אַחַת הַמֻּדְבֶּקֶת (הזוהרת) בִּקְשָׁרָיו. כְּשֶׁנִּדּוֹן הָעוֹלָם בְּדִין, הוּא נִדּוֹן כָּלוּל בְּרַחֲמִים. וְאִם לֹא, אֵין הָעוֹלָם יָכוֹל לַעֲמֹד רֶגַע אֶחָד, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים, כְּמוֹ שֶׁכָּתוּב (שם כו) כִּי כַּאֲשֶׁר מִשְׁפָּטֶיךְ לָאָרֶץ צֶדֶק לָמְדוּ יֹשְׁבֵי תֵבֵל.</p>\n<p>וְלָמַדְנוּ, בְּאוֹתוֹ זְמַן שֶׁהַדִּין תָּלוּי בָּעוֹלָם וְצֶדֶק מִתְעַטֵּר בְּדִינָיו, כַּמָּה בַּעֲלֵי כְנָפַיִם מִתְעוֹרְרִים כְּנֶגֶד בַּעֲלֵי הַדִּין הַקָּשֶׁה לִשְׁלֹט בָּעוֹלָם. פּוֹרְשִׂים כְּנָפַיִם מֵהַצַּד הַזֶּה וּמֵהַצַּד הַזֶּה לְהִשְׁתַּטֵּחַ (להשגיח) בָּעוֹלָם. אָז מִתְעוֹרְרוֹת הַכְּנָפַיִם לִפְרֹשׂ אוֹתָן וּלְהִשָּׁאֵב (ולהשתתף) בַּדִּין הַקָּשֶׁה, וּמְשׁוֹטְטוֹת בָּעוֹלָם לְהָרַע. אָז כָּתוּב, הוֹי אֶרֶץ צִלְצַל כְּנָפָיִם. אָמַר רַבִּי יְהוּדָה, רָאִיתִי בְּנֵי הָעוֹלָם בְּחֻצְפָּה, פְּרָט לְאוֹתָם צַדִּיקֵי הָאֱמֶת. וּמִשּׁוּם כָּךְ, כִּבְיָכוֹל, הַכֹּל כָּךְ נִמְצָא. בָּא לְהִטָּהֵר - מְסַיְּעִין אוֹתוֹ. בָּא לְהִטָּמֵא - כְּמוֹ שֶׁבֵּאַרְנוּ וְנִטְמֵתֶם בָּם.</p>"],[9522012166,"<p>רַבִּי יוֹסֵי הָיָה הוֹלֵךְ בַּדֶּרֶךְ, פָּגַשׁ בּוֹ רַבִּי חִיָּיא. אָמַר לוֹ, זֶה שֶׁבֵּאֲרוּ הַחֲבֵרִים, שֶׁכָּתוּב בְּעֵלִי (שמואל א ג) וְלָכֵן נִשְׁבַּעְתִּי לְבֵית עֵלִי אִם יִתְכַּפֵּר עֲון בֵּית עֵלִי בְּזֶבַח וּבְמִנְחָה עַד עוֹלָם, בְּזֶבַח וּמִנְחָה אֵינוֹ מִתְכַּפֵּר, אֲבָל מִתְכַּפֵּר הוּא בְּדִבְרֵי תוֹרָה. לָמָּה? מִשּׁוּם שֶׁדִּבְרֵי תוֹרָה עוֹלִים עַל כָּל הַקָּרְבָּנוֹת שֶׁבָּעוֹלָם, כְּמוֹ שֶׁבֵּאֲרוּהָ שֶׁכָּתוּב, (ויקראז) זֹּאת הַתּוֹרָה לָעֹלָה לַמִּנְחָה וְלַחַטָּאת וְלָאָשָׁם וְלַמִּלּוּאִים, שְׁקוּלָה הַתּוֹרָה כְּנֶגֶד כָּל הַקָּרְבָּנוֹת שֶׁל הָעוֹלָם. אָמַר לוֹ, כָּךְ זֶה וַדַּאי, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, אַף עַל גַּב שֶׁנִּגְזַר עָלָיו עֹנֶשׁ מִלְמַעְלָה, נוֹחַ לוֹ מִכָּל הַקָּרְבָּנוֹת וְהָעוֹלוֹת, וְאוֹתוֹ הָעֹנֶשׁ נִקְרָע. (ומשום שעוסק בה לשמה, הקדוש ברוך הוא מתפיס עמו).</p>\n<p>וּבֹא רְאֵה, הָאָדָם לֹא נִטְהָר לְעוֹלָמִים, אֶלָּא בְּדִבְרֵי תוֹרָה. מִשּׁוּם כָּךְ דִּבְרֵי תוֹרָה לֹא מְקַבְּלִים טֻמְאָה, מִשּׁוּם שֶׁהִיא עוֹמֶדֶת לְטַהֵר אֶת אֵלּוּ הַטְּמֵאִים, וְהָרְפוּאָה נִמְצֵאת בַּתּוֹרָה, שֶׁכָּתוּב (משלי ג) רִפְאוּת תְּהִי לְשָׁרֶךְ וְשִׁקּוּי לְעַצְמוֹתֶיךְ. וְהַטָּהֳרָה נִמְצֵאת בַּתּוֹרָה, שֶׁכָּתוּב (תהלים יט) יִרְאַת ה' טְהוֹרָה עוֹמֶדֶת לָעַד. מַה זֶּה עוֹמֶדֶת לָעַד? שֶׁעוֹמֶדֶת תָּמִיד בְּאוֹתָהּ טָהֳרָה, וְלֹא זָזָה מִמֶּנָּה לְעוֹלָמִים.</p>\n<p>אָמַר לוֹ, יִרְאַת ה' כָּתוּב, וְלֹא תוֹרָה. אָמַר לוֹ, כָּךְ הוּא וַדַּאי, שֶׁהֲרֵי הַתּוֹרָה בָּאָה מִצַּד הַגְּבוּרָה. אָמַר לוֹ, וּמִשָּׁם יָצְאָה?! מִכָּאן יָצְאָה! שֶׁכָּתוּב רֵאשִׁית חָכְמָה יִרְאַת ה', וְכָתוּב יִרְאַת ה' טְהוֹרָה.</p>\n<p>וְתוֹרָה נִקְרֵאת קְדֻשָּׁה, שֶׁכָּתוּב כִּי קָדוֹשׁ אֲנִי ה', וְזוֹ הַתּוֹרָה שֶׁהִיא הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן. וְעַל כֵּן, מִי שֶׁמִּשְׁתַּדֵּל בָּהּ נִטְהָר, וְאַחַר כָּךְ מִתְקַדֵּשׁ, שֶׁכָּתוּב קְדשִׁים תִּהְיוּ. לֹא כָתוּב קְדשִׁים הֱיוּ, אֶלָּא תִּהְיוּ, תִּהְיוּ וַדַּאי. אָמַר לוֹ, כָּךְ הוּא, וּמִקְרָא כָּתוּב, (שמות יט) וְאַתֶּם תִּהְיוּ לִי מַמְלֶכֶת כֹּהֲנִים וְגוֹי קָדוֹשׁ, וְכָתוּב אֵלֶּה הַדְּבָרִים וְגוֹ'.</p>\n<p>לָמַדְנוּ, קְדֻשַּׁת הַתּוֹרָה קְדֻשָּׁה שֶׁעוֹלָה עַל כָּל הַקְּדֻשּׁוֹת. וְהַקְּדֻשָּׁה שֶׁל הַחָכְמָה הַנִּסְתֶּרֶת עוֹלָה עַל הַכֹּל. אָמַר לוֹ, אֵין תּוֹרָה בְּלִי חָכְמָה, וְאֵין חָכְמָה בְּלִי תוֹרָה, וְהַכֹּל הוּא בְּדַרְגָּה אַחַת וְהַכֹּל אֶחָד. אֶלָּא תּוֹרָה נִמְצֵאת עִם הַחָכְמָה הָעֶלְיוֹנָה, וּבָהּ הִיא עוֹמֶדֶת, וּבָהּ נִטְּעוּ שָׁרָשֶׁיהָ מִכָּל הַצְּדָדִים.</p>\n<p>בְּעוֹד שֶׁהָיוּ הוֹלְכִים מָצְאוּ אִישׁ אֶחָד בִּלְקִיטַת עֵצִים (בלקיטת זרעים) רָכוּב עַל סוּסוֹ. הִשְׁמִיט יָדוֹ לְעָנָף אֶחָד שֶׁל הָאִילָן. אָמַר רַבִּי יוֹסֵי, זֶהוּ שֶׁכָּתוּב וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים. אָדָם מְקַדֵּשׁ עַצְמוֹ מִלְּמַטָּה - מְקַדְּשִׁים אוֹתוֹ מִלְמַעְלָה. זֶהוּ שֶׁכָּתוּב קְדֹשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי ה'.</p>\n<p>שָׁנָה רַבִּי אַבָּא, הַפָּרָשָׁה הַזּוֹ הִיא כְּלָלָהּ שֶׁל תּוֹרָה, וְחוֹתַם הָאֱמֶת שֶׁל הַחוֹתֶמֶת הִיא. בְּפָרָשָׁה זוֹ הִתְחַדְּשׁוּ סוֹדוֹת עֶלְיוֹנִים שֶׁל הַתּוֹרָה בְּעֶשֶׂר אֲמִירוֹת, וּגְזֵרוֹת וָעֳנָשִׁים, וּמִצְווֹת עֶלְיוֹנוֹת, שֶׁכְּשֶׁמַּגִּיעִים לַפָּרָשָׁה הַזּוֹ הָיוּ שְׂמֵחִים.</p>\n<p>אָמַר רַבִּי אַבָּא, מָה הַטַּעַם שֶׁפָּרָשַׁת עֲרָיוֹת וּפָרָשַׁת קְדֹשִׁים תִּהְיוּ סְמוּכוֹת זוֹ לָזוֹ? אֶלָּא כָּךְ לָמַדְנוּ, כָּל מִי שֶׁנִּשְׁמָר מִן הָעֲרָיוֹת הַלָּלוּ, וַדַּאי שֶׁנַּעֲשָׂה בִּקְדֻשָּׁה. וְכָל שֶׁכֵּן אִם מִתְקַדֵּשׁ בִּקְדֻשַּׁת רִבּוֹנוֹ, וַהֲרֵי הֵעִירוּ הַחֲבֵרִים.</p>\n<p>מָתַי הִיא עוֹנָתָם שֶׁל כֻּלָּם שֶׁיִּתְקַדֵּשׁ אָדָם? בּא רְאֵה, מִי שֶׁרוֹצֶה לְהִתְקַדֵּשׁ בִּרְצוֹן רִבּוֹנוֹ, אַל יְשַׁמֵּשׁ אֶלָּא מֵחֲצוֹת הַלַּיְלָה וְאֵילָךְ, אוֹ בַּחֲצוֹת הַלַּיְלָה. שֶׁהֲרֵי בְּאוֹתָהּ הַשָּׁעָה הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בְּגַן עֵדֶן, וְהַקְּדֻשָּׁה הָעֶלְיוֹנָה מִתְעוֹרֶרֶת, וְאָז הַשָּׁעָה לְהִתְקַדֵּשׁ. זֶה לִשְׁאָר בְּנֵי הָאָדָם, תַּלְמִידֵי חֲכָמִים שֶׁיּוֹדְעִים אֶת דַּרְכֵי הַתּוֹרָה, בַּחֲצוֹת הַלַּיְלָה שְׁעָתָם לַעֲמֹד וְלַעֲסֹק בַּתּוֹרָה, לְהִזְדַּוֵּג עִם כְּנֶסֶת יִשְׂרָאֵל, לְשַׁבֵּחַ אֶת הַשֵּׁם הַקָּדוֹשׁ, אֶת הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>בְּלֵיל שַׁבָּת, שֶׁנִּמְצָא הָרָצוֹן שֶׁל הַכֹּל, הַזִּוּוּג שֶׁלָּהֶם בְּאוֹתָהּ שָׁעָה לְהוֹצִיא אֶת רְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר שֶׁכָּתוּב, (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. וְאֵלֶּה נִקְרָאִים קְדוֹשִׁים, שֶׁכָּתוּב קְדשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי ה'. וְכָתוּב (תהלים א) וְהָיָה כְּעֵץ שָׁתוּל עַל פַּלְגֵי מָיִם אֲשֶׁר פִּרְיוֹ יִתֵּן בְּעִתּוֹ וְגוֹ'.</p>\n<p>קְדֹשִׁים תִּהְיוּ. רַבִּי אַבָּא פָּתַח, (שמואל ב ז) וּמִי כְעַמְּךְ כְּיִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ. בֹּא רְאֵה, בְּכָל עַמֵּי הָעוֹלָם לֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּהֶם, פְּרָט לְיִשְׂרָאֵל בִּלְבַדָּם, וְעָשָׂה אוֹתָם עַם יָחִיד בָּעוֹלָם, וְקָרָא לָהֶם גּוֹי אֶחָד כִּשְׁמוֹ, וְעִטֵּר אוֹתָם בְּכַמָּה עֲטָרוֹת וְכַמָּה מִצְווֹת לְהִתְעַטֵּר בָּהֶן. וְעַל כֵּן תְּפִלִּין שֶׁל רֹאשׁ וּתְפִלִּין שֶׁל זְרוֹעַ שֶׁיִּתְעַטֵּר בָּהֶן בֶּן אָדָם כְּמוֹ שֶׁלְּמַעְלָה, וּלְהִמָּצֵא אֶחָד שָׁלֵם בַּכֹּל.</p>\n<p>וּבְאוֹתָהּ שָׁעָה שֶׁמִּתְעַטֵּר בָּהֶן אָדָם וּמִתְקַדֵּשׁ בָּהֶן, נַעֲשֶׂה שָׁלֵם וְנִקְרָא אֶחָד, שֶׁלֹּא נִקְרָא אֶחָד אֶלָּא כְּשֶׁהוּא שָׁלֵם. וּמִי שֶׁפָּגוּם, לֹא נִקְרָא אֶחָד. וְעַל כֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא אֶחָד - בִּשְׁלֵמוּת הַכֹּל, בִּשְׁלֵמוּת הָאָבוֹת, בַּשְּׁלֵמוּת שֶׁל כְּנֶסֶת יִשְׂרָאֵל. מִשּׁוּם כָּךְ יִשְׂרָאֵל לְמַטָּה נִקְרָאִים אֶחָד. שֶׁכַּאֲשֶׁר מֵנִיחַ אָדָם תְּפִלִּין וּמִתְכַּסֶּה בְּכִסּוּי שֶׁל מִצְוָה, אֲזַי הוּא מִתְעַטֵּר בַּעֲטָרוֹת קְדוֹשׁוֹת כְּמוֹ שֶׁלְּמַעְלָה, וְנִקְרָא אֶחָד.</p>\n<p>וּמִשּׁוּם כָּךְ, יָבֹא אֶחָד וְיִשְׁתַּדֵּל עִם אֶחָד. הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא אֶחָד יִשְׁתַּדֵּל עִם אֶחָד, שֶׁהֲרֵי אֵין מֶלֶךְ מִשְׁתַּדֵּל אֶלָּא בְּמַה שֶּׁרָאוּי לוֹ. וּמִשּׁוּם כָּךְ כָּתוּב, וְהוּא בְאֶחָד וּמִי יְשִׁיבֶנּוּ, אֵין הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹרֶה וְלֹא נִמְצָא אֶלָּא בְּאֶחָד. בְּאֶחָד?! אֶחָד צָרִיךְ לִהְיוֹת! אֶלָּא בְּמִי שֶׁמִּתְתַּקֵּן בִּקְדֻשָּׁה עֶלְיוֹנָה לִהְיוֹת אֶחָד, אָז הוּא שׁוֹרֶה בְאֶחָד, וְלֹא בְמָקוֹם אַחֵר.</p>\n<p>וּמָתַי נִקְרָא אָדָם אֶחָד? בְּשָׁעָה שֶׁנִּמְצָא זָכָר וּנְקֵבָה, וּמִתְקַדֵּשׁ בִּקְדֻשָּׁה (בעטרה) עֶלְיוֹנָה, וּמִתְכַּוֵּן לְהִתְקַדֵּשׁ. וּבֹא רְאֵה, בִּזְמַן שֶׁנִּמְצָא אָדָם בְּזִוּוּג אֶחָד זָכָר וּנְקֵבָה וּמִתְכַּוֵּן לְהִתְקַדֵּשׁ כָּרָאוּי, אָז הוּא שָׁלֵם, וְנִקְרָא אֶחָד בְּלִי פְגָם.</p>\n<p>מִשּׁוּם כָּךְ צָרִיךְ אָדָם לְשַׂמֵּחַ אֶת אִשְׁתּוֹ בְּאוֹתָהּ שָׁעָה, לְזַמֵּן אוֹתָהּ בְּרָצוֹן אֶחָד עִמּוֹ. וְיִתְכַּוְּנוּ שְׁנֵיהֶם כְּאֶחָד לְאוֹתוֹ הַדָּבָר. וּכְשֶׁנִּמְצָאִים שְׁנֵיהֶם כְּאֶחָד, אֲזַי הַכֹּל אֶחָד בַּנֶּפֶשׁ וּבַגּוּף. בַּנֶּפֶשׁ - לְהִדָּבֵק זֶה בָּזֶה בְּרָצוֹן אֶחָד. וּבַגּוּף - כְּמוֹ שֶׁלָּמַדְנוּ שֶׁאָדָם שֶׁלֹּא נִשָּׂא הוּא כְּמִי שֶׁנֶּחֱלָק, וּכְשֶׁמִּתְחַבְּרִים זָכָר וּנְקֵבָה, אָז נַעֲשִׂים גּוּף אֶחָד. נִמְצָא שֶׁהֵם נֶפֶשׁ אַחַת וְגוּף אֶחָד, וְנִקְרָא אָדָם אֶחָד. אָז הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹרֶה בְאֶחָד, וּמַפְקִיד רוּחַ שֶׁל קְדֻשָּׁה בְּאוֹתוֹ אֶחָד.</p>\n<p>וְאֵלּוּ נִקְרָאִים בָּנִים שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר. וּמִשּׁוּם כָּךְ קְדשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי ה'. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁלֹּא בֵאֵר הַדָּבָר הַזֶּה בְּמָקוֹם אַחֵר, אֶלָּא בּוֹ מַמָּשׁ, שֶׁכָּתוּב כִּי קָדוֹשׁ אֲנִי ה', כְּדֵי לְהִדָּבֵק בּוֹ וְלֹא בְאַחֵר. וְעַל כֵּן קְדשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי ה' אֱלֹהֵיכֶם.</p>"],[9522012167,"<p>אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ וְגוֹ'. הֲרֵי שָׁנִינוּ שֶׁפָּרָשָׁה זוֹ הִיא הַכְּלָל שֶׁל הַתּוֹרָה. מַקִּישׁ יִרְאַת אָב וָאֵם לְשַׁבְּתוֹתַי. אֶלָּא אָמַר רַבִּי יוֹסֵי, הַכֹּל אֶחָד. מִי שֶׁיָּרֵא מִזֶּה, שׁוֹמֵר אֶת זֶה.</p>\n<p>אִישׁ אִמּוֹ, מָה הַטַּעַם הִקְדִּים אִמּוֹ לְאָבִיו בַּיִּרְאָה? כְּמוֹ שֶׁבֵּאֲרוּהָ. אֲבָל הָאֵם שֶׁאֵין רְשׁוּת בְּיָדֶיהָ כָּל כָּךְ כְּמוֹ אָבִיו, (אבל בא ראה, אמו זו כנסת ישראל, ומשום שבה שורה היראה והיא נקראת יראת ה') הִקְדִּים אֶת יִרְאָתָהּ.</p>\n<p>רַבִּי יִצְחָק אָמַר, מַה כָּתוּב לְמַעְלָה? קְדֹשִׁים תִּהְיוּ. בָּא אָדָם לְהִתְקַדֵּשׁ עִם אִשְׁתּוֹ כְּאֶחָד, מִמִּי הוּא יוֹתֵר שֶׁבַח בְּאוֹתָהּ קְדֻשָּׁה? הֱוֵה אוֹמֵר מֵהַנְּקֵבָה. מִשּׁוּם כָּךְ אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ.</p>\n<p>רַבִּי יְהוּדָה אָמַר, אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ, כְּגוֹן זֶה (בראשית ב) בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמָיִם. וּבְמָקוֹם אַחֵר הִקְדִּים שָׁמַיִם לָאָרֶץ. אֶלָּא לְהַרְאוֹת שֶׁשְּׁנֵיהֶם כְּאֶחָד נַעֲשׂוּ. אַף כָּאן הִקְדִּים אֵם לְאָב, וּבְמָקוֹם אַחֵר הִקְדִּים אָב לְאֵם, לְהַרְאוֹת שֶׁשְּׁנֵיהֶם כְּאֶחָד הִשְׁתַּדְּלוּ בוֹ.</p>\n<p>וְאֶת שַׁבְּתוֹתַי תִּשְׁמֹרוּ. זֶה שָׁקוּל לָזֶה, וְהַכֹּל כְּאֶחָד נִשְׁקָל בְּמִשְׁקָל אֶחָד, שֶׁכָּתוּב (שמות לה) וּשְׁמַרְתֶּם אֶת הַשַּׁבָּת כִּי קֹדֶשׁ הִיא לָכֶם, וְכָתוּב (ויקראכו) זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ. אֶלָּא אֶחָד לָאָב, וְאֶחָד לָאֵם. כָּתוּב כָּאן, אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ וְאֶת שַׁבְּתוֹתַי תִּשְׁמֹרוּ. וְכָתוּב שָׁם, אֶת שַׁבְּתוֹתַי תִּשְׁמֹרוּ וּמִקְדָּשִׁי תִּירָאוּ. מַהוּ מִקְדָּשִׁי? כְּמַשְׁמָעוֹ. עוֹד מִקְדָּשִׁי - אֵלּוּ אוֹתָם שֶׁמְּקַדְּשִׁים עַצְמָם בְּאוֹתָהּ שָׁעָה. כְּמוֹ זֶה, (יחזקאל ט) וּמִמִּקְדָּשִׁי תָּחֵלּוּ. אַל תִּקְרֵי מִמִּקְדָּשִׁי אֶלָּא מִמְּקֻדָּשַׁי. מַה לְמַעְלָה מִמְּקֻדָּשַׁי, אַף כָּאן מִמְּקֻדָּשַׁי, שֶׁהֵם הָאָב וְהָאֵם.</p>\n<p>אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ. רַבִּי שִׁמְעוֹן אָמַר, כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' וְגוֹ'. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁנִּדְבָּקִים בּוֹ בַּקָּדוֹשׁ בָּרוּךְ הוּא, (הם ולא אמות עובדי כוכבים ומזלות) וּמִשּׁוּם שֶׁנִּדְבָּקִים בּוֹ בַּקָּדוֹשׁ בָּרוּךְ הוּא, כֻּלָּם נִדְבָּקִים כְּאֶחָד זֶה עִם זֶה.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁאָדָם מְקַדֵּשׁ לְמַטָּה, כְּמוֹ הַחֲבֵרִים שֶׁמְּקַדְּשִׁים אֶת עַצְמָם מִשַּׁבָּת לְשַׁבָּת, בְּשָׁעָה שֶׁהַזִּוּוּג הָעֶלְיוֹן נִמְצָא, שֶׁהֲרֵי בְּאוֹתָהּ הַשָּׁעָה נִמְצָא הָרָצוֹן וְהַבְּרָכָה מִזְדַּמֶּנֶת, אָז כֻּלָּם נִדְבָּקִים כְּאֶחָד - הַנֶּפֶשׁ שֶׁל שַׁבָּת, וְהַגּוּף שֶׁמִּזְדַּמֵּן בְּשַׁבָּת. וְעַל זֶה כָּתוּב אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ, שֶׁהֵם זִוּוּג אֶחָד בְּגוּף בְּאוֹתָהּ הַשָּׁעָה לְהִתְקַדֵּשׁ. וְאֶת שַׁבְּתוֹתַי תִּשְׁמֹרוּ - זוֹ שַׁבָּת הָעֶלְיוֹנָה וְשַׁבָּת הַתַּחְתּוֹנָה, שֶׁהֵן מְזַמְּנוֹת אֶת הַנֶּפֶשׁ לְאוֹתוֹ הַגּוּף מֵאוֹתוֹ הַזִּוּוּג הָעֶלְיוֹן. וְעַל כֵּן, וְאֶת שַׁבְּתוֹתַי תִּשְׁמֹרוּ - שְׁנַיִם, וְהַכֹּל נִדְבָּק זֶה עִם זֶה. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל.</p>\n<p>דָּבָר אַחֵר וְאֶת שַׁבְּתוֹתַי תִּשְׁמֹרוּ - לְהַזְהִיר אֶת אוֹתָם שֶׁמְּחַכִּים לְזִוּוּגָם מִשַּׁבָּת לְשַׁבָּת, וַהֲרֵי בֵּאַרְנוּ, כְּמוֹ שֶׁכָּתוּב, (ישעיה נו) לַסָּרִיסִים אֲשֶׁר יִשְׁמְרוּ אֶת שַׁבְּתוֹתַי. מִי הֵם הַסָּרִיסִים? אֵלּוּ אוֹתָם הַחֲבֵרִים שֶׁמְּסָרְסִים אֶת עַצְמָם כָּל שְׁאָר הַיָּמִים כְּדֵי לַעֲסֹק בַּתּוֹרָה, וְהֵם מְחַכִּים מִשַּׁבָּת לְשַׁבָּת. זֶהוּ שֶׁכָּתוּב אֲשֶׁר יִשְׁמְרוּ אֶת שַׁבְּתוֹתַי, כְּמוֹ שֶׁנֶּאֱמַר (בראשית לו) וְאָבִיו שָׁמַר אֶת הַדָּבָר, וּמִשּׁוּם כָּךְ - וְאֶת שַׁבְּתוֹתַי תִּשְׁמֹרוּ. אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ - זֶה הַגּוּף. וְאֶת שַׁבְּתוֹתַי תִּשְׁמֹרוּ - זוֹ הַנֶּפֶשׁ. וְהַכֹּל נִדְבָּק זֶה עִם זֶה. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל.</p>\n<p>אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ וְאֶת שַׁבְּתוֹתַי תִּשְׁמֹרוּ. מִצְוָה זוֹ שְׁקוּלָה זוֹ לָזוֹ. שָׁקוּל כִּבּוּד אָב וָאֵם לִכְבוֹד הַשַּׁבָּת. לָאָב הִקְדִּים כָּבוֹד, וְזֶהוּ שֶׁאָמַר הַכָּתוּב (מלאכי א) וְאִם אָב אָנִי אַיֵּה כְבוֹדִי וְאִם אֲדוֹנִים אָנִי אַיֵּה מוֹרָאִי. כְּבוֹדִי עוֹלֶה בְחֶשְׁבּוֹן עֶשֶׂר אֲמִירוֹת, וְל\"ב אֱלֹהִים שֶׁל מַעֲשֵׂה בְרֵאשִׁית.</p>\n<p>וּבְכָל מָקוֹם (משלי ג) כָּבוֹד חֲכָמִים יִנְחָלוּ, וּפֵרְשׁוּהָ רַבּוֹתֵינוּ, אֵין כָּבוֹד אֶלָּא תּוֹרָה. מִשּׁוּם שֶׁהֵם ל\"ב אֱלֹהִים שֶׁל תּוֹרָה, הַכָּבוֹד שֶׁלּוֹ. וְאֵלּוּ (הם) הַחֲכָמִים שֶׁל הַתּוֹרָה, חֲכָמִים בְּחָכְמָה יוֹרְשִׁים אֶת הַכָּבוֹד הַזֶּה וְלֹא טִפְּשִׁים, שֶׁעֲלֵיהֶם נֶאֱמַר וּכְסִילִים מֵרִים קָלוֹן. וּמִנַּיִן לָנוּ שֶׁמִּי שֶׁאֵינוֹ מַכִּיר אֶת הַתּוֹרָה נִקְרָא כְּסִיל? שֶׁכָּתוּב (תהלים צב) וּכְסִיל לֹא יָבִין אֶת זֹּאת. וְאֵין זֹּאת אֶלָּא תּוֹרָה, שֶׁכָּתוּב (דברים ד) וְזֹּאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה.</p>\n<p>רוֹעָה הַנֶּאֱמָן, מִשּׁוּם שֶׁחָלוּשׁ אַתָּה פָּתַחְתִּי אֶת הַפָּרָשָׁה בַּמִּצְווֹת הַלָּלוּ, לִהְיוֹת לְךְ מְעַט לְעֵזֶר. הִתְחַזֵּק בְּךְ, שֶׁהֲרֵי הַמַּחֲנוֹת שֶׁל הַיְשִׁיבוֹת בָּאִים אֵלֶיךְ, בְּמִצְוָה אַחַר זוֹ, שֶׁהִיא מִצְוָה לְהַעֲמִיד עָלֶיךְ מֶלֶךְ לְמַעְלָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא יַעֲמִיד אוֹתְךְ מֶלֶךְ בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים בִּדְיוֹקְנוֹ, מִשּׁוּם שֶׁרַבּוֹתֵינוּ מֵהַיְשִׁיבָה, עֲלֵיהֶם שְׁכִינָה וְתַחְתּוֹנָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מֶלֶךְ בָּאֶמְצַע, אוֹחֵז בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים. כָּךְ אַתָּה תִּהְיֶה בִדְיוֹקְנוֹ, הַבֵּן שֶׁלּוֹ, עֲמֹד לִכְבוֹד הַמֶּלֶךְ.</p>\n<p>עָמַד הָרוֹעֶה הַנֶּאֱמָן, וְהֵרִים יָדָיו לְמַעְלָה וְאָמַר: יְהִי רְצוֹנְךְ, עִלַּת הָעִלּוֹת, שֶׁאַתָּה מִתְעַלֶּה מֵעִלּוּי לְעִלּוּי, עַד אֵין עִלּוּי, אֶלָּא שֶׁאַתָּה מֵעַל לְכָל עִלּוּי, (, לתת) לִי כֹּחַ לַעֲשׂוֹת אֶת רְצוֹנְךְ בְּדַרְגוֹתֶיךְ, שֶׁהֵן אָב וָאֵם, וַאֲנִי הַבֵּן שֶׁלָּהֶם, וּבַיִּחוּד שֶׁלְּךְ שְׁנֵיהֶם אֶחָד. וְאַתָּה הִשְׁוֵיתָ אֶת יִרְאַת אָב וָאֵם לְיִרְאָתְךְ, אַחַר שֶׁאַתָּה בָּאֶמְצַע, אֶחָד וְלֹא שְׁנַיִם, בְּלִי שֻׁתָּפוּת, אַף עַל גַּב שֶׁהֵם בַּשֻּׁתָּפוּת שֶׁלְּךְ, אֲבָל אַתָּה אֶחָד בְּלִי שֻׁתָּפוּת שֶׁל שֵׁנִי. וּמִשּׁוּם זֶה נֶאֱמַר בְּךְ, וְאֵין אֱלֹהִים עִמָּדִי.</p>\n<p>תֵּן לִי כֹּחַ לְהִתְעוֹרֵר בִּכְבוֹדְךְ בָּרִאשׁוֹנָה, וְאַחַר כָּךְ בִּכְבוֹד אָבִי וְאִמִּי שֶׁבַּשָּׁמַיִם, שֶׁעֲלֵיהֶם בֵּאֲרוּ, גּוֹזֵל אָבִיו וְאִמּוֹ וְאוֹמֵר אֵין פָּשַׁע חָבֵר הוּא לְאִישׁ מַשְׁחִית. וּפֵרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, אֵין אָבִיו אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאֵין אִמּוֹ אֶלָּא כְּנֶסֶת יִשְׂרָאֵל. וְהַכָּבוֹד שֶׁלְּךְ, אַבָּא, חָכְמָה, שֶׁכּוֹלֶלֶת עֶשֶׂר סְפִירוֹת מִמַּטָּה שֶׁלּוֹ לְמַעְלָה, וּשְׁנֵיהֶם הֵם כִּסֵּא סַפְסָל תַּחְתֶּיךְ לִכְבוֹדְךְ.</p>\n<p>וְכָךָ תִּקְּנוּ, שֶׁיִּהְיֶה קָטָן מְכַבֵּד אֶת הַגָּדוֹל שֶׁלְּמַעְלָה מִמֶּנּוּ. אָב הוּא חָכְמָה, הֲלֹא אָב אֶחָד לְכֻלָּנוּ, לִהְיוֹת מְשַׁמֵּשׁ תַּחְתֶּיךְ, וְאַתָּה כֶּתֶר עֶלְיוֹן עַל רֹאשׁוֹ. וְאֵין עָלֶיךְ כֶּתֶר, וְאֵין אֱלוֹהַּ אַחֵר. וְהָאֵם לְשַׁמֵּשׁ אֶת הָאָב, שֶׁהִיא תַּחְתָּיו, לִהְיוֹת כִּסֵּא תַּחְתָּיו.</p>\n<p>וַיֹּאמֶר הוּא בְּכָל מַאֲמָר עַד שְׁלֹשִׁים וּשְׁניִם, יְהִי כֵן, וַיְהִי כֵן. וְהִיא עָשְׂתָה מַאֲמָרוֹ מִיָּד. וּמִשּׁוּם שֶׁעָשְׂתָה מַאֲמָרוֹ וְצִוּוּיוֹ בְּלִי עִכּוּב כְּלָל בְּל\"ב שְׁבִילִים שֶׁבָּהֶם נִבְרָא כָּל מַעֲשֵׂה בְרֵאשִׁית, נִקְרֵאת כָּבוֹד, (תהלים כט) וּבְהֵיכָלוֹ כֻּלּוֹ אוֹמֵר כָּבוֹד. (יחזקאל ג) בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. אַיֵּה מְקוֹם כְּבוֹדוֹ לְהַעֲרִיצוֹ.</p>\n<p>וְתַרְגּוּם כְּבוֹד אָבִיו - יְקָרָא דַּאֲבוּהִי. וְזֶה (תהלים יט) תּוֹרַת ה' תְּמִימָה, עָלֶיהָ נֶאֱמַר (משלי ו) יְקָרָה הִיא מִפְּנִינִים. וְיִשְׂרָאֵל שֶׁנִּקְרְאוּ בָנִים, בִּכְלַל בֵּן וּבַת, מִצַּד שֶׁל תִּפְאֶרֶת וּמַלְכוּת, שֶׁהֵם בֵּן וּבַת, הַכָּבוֹד שֶׁל אָבִיו וְאִמּוֹ לַעֲשׂוֹת אֶת הַצִּוּוּי שֶׁלּוֹ, וְהַצִּוּוּי שֶׁלּוֹ אוֹתָן מִצְווֹת עֲשֵׂה. וַהֲרֵי פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, יֵשׁ מְצֻוֶּה וְעוֹשֶׂה. וּמִשּׁוּם כָּךְ הוּא נַעֲשֶׂה וְנִשְׁמָע. וְזֶהוּ כִּבּוּד אָב וָאֵם, שֶׁיְּצַוֶּה אֶת בְּנוֹ שֶׁיַּעֲשֶׂה כָּךְ, וְהוּא עוֹשֶׂה מִיָּד בְּלִי עִכּוּב כְּלָל.</p>\n<p>וְעִלַּת עַל הַכֹּל, אֲנִי רוֹצֶה לְהִשְׁתַּדֵּל בִּכְבודְךְ, לְתַקֵּן אֶת הַמִּדּות שֶׁל אַבָּא וְאִמָּא לִכְבודְךְ. תִּהְיֶה בְעֶזְרִי לְסַדֵּר הַכֹּל כָּרָאוּי. וְאַתָּה תְּסַדֵּר אוֹתִי וְאֶת כָּל רָאשֵׁי הַיְשִׁיבוֹת מַעְלָה וּמַטָּה, וּמַחֲנוֹת הַמַּלְאָכִים הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים, לִהְיוֹת מְתַקְּנִים וּמְסַדְּרִים לִכְבוֹדְךְ וְלִכְבוֹד אַבָּא וְאִמָּא, לִהְיוֹת סַפְסָל תַּחַת רַגְלָיו, וְלַעֲשׂוֹת צִוּוּיָיו בְּכָל מִצְווֹתָיו, וְלִירָא מִמֶּנּוּ בְּכָל הַמִּצְווֹת שֶׁל לֹא תַעֲשֶׂה.</p>\n<p>וְזְהִוּ אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ, וְסָמַךְ לוֹ וְאֶת שַׁבְּתוֹתַי תִשְׁמֹרוּ. וּבְפָסוּק אַחֵר וְאֶת מִצְותַי תַּעֲשׂוּ. מִצַּד שֶׁל מִצְווֹת עֲשֵׂה שֶׁהֵם כָּבוֹד, הִקְדִּים אָב לָאֵם, וְזֶה י\"ה. מִצַּד שֶׁל לֹא תַעֲשֶׂה הִקְדִּים אֵם לָאָב, וְזֶה ה\"י, וְהַיְנוּ (משלי כה) כְּבוֹד אֱלֹהִים הַסְתֵּר דָּבָר. לְאֵלּוּ שֶׁאֵינָם מִשְׁתַּדְּלִים בַּכָּבוֹד הַזֶּה, הַסְתֵּר דָּבָר מֵהֶם.</p>\n<p>וַעָלֵיהֶם נֶאֱמַר, (משלי ג) וּכְסִילִים מֵרִים קָלוֹן. אֵלּוּ הֵם עַמֵּי הָאָרֶץ, מֵאַחַר שֶׁאֵינָם מִשְׁתַּדְּלִים בַּכָּבוֹד הַזֶה שֶׁל הַתּוֹרָה, וְאֵיךְ אוֹמְרִים, אָבִינוּ שֶׁבַּשָּׁמַיִם שְׁמַע קוֹלֵנוּ חוּס וְרַחֵם עָלֵינוּ וְקַבֵּל תְּפִלָּתֵנוּ? הֲרֵי הוּא יֹאמַר לָהֶם: וְאִם אָב אָנִי אַיֵּה כְבוֹדִי? אַיֵּה הִשְׁתַּדְּלוּתְכֶם בַּתּוֹרָה וּבְמִצְווֹתַי לַעֲשׂוֹת אֶת הַצִּוּוּיִים שֶׁלִּי? שֶׁמִּי שֶׁאֵינוֹ מַכִּיר אֶת הַצִּוּוּי שֶׁל אֲדוֹנוֹ, אֵיךְ יַעֲשֶׂה אוֹתוֹ?</p>\n<p>פְּרָט לְמִי שֶׁשּׁוֹמֵעַ מֵחֲכָמִים וְעוֹשֶׂה, וְזֶהוּ שֶׁקִּבֵּל נַעֲשֶׂה וְנִשְׁמָע. וְעִם כָּל זֶה, מִי שֶׁלֹּא קִבֵּל מֵאֲדוֹנוֹ, אֶלָּא מִשְּׁלוּחוֹ, יֵשׁ הֶבְדֵּל. וְאֵיזֶה הֶבְדֵּל יֵשׁ בֵּין זֶה לָזֶה? שֶׁהֲרֵי כָּתוּב, מֹשֶׁה קִבֵּל תּוֹרָה מִסִּינַי, וְאַחַר כָּךְ מְסָרָהּ לִיהוֹשֻׁעַ. אֲנִי קִבַּלְתִּי, וְאַחַר כָּךְ מָסַרְתִּי לְכֻלָּם. וְכָךְ מִי שֶׁמְּקַבֵּל מֵאַחֵר, כְּקַבָּלַת הַלְּבָנָה וְהַכּוֹכָבִים מִן הַשֶּׁמֶשׁ, וּבַקִּבּוּל הַזּה הוּא מִתְמַלֵּא. וּמִי שֶׁמְּקַבֵּל, יְכוֹלָה לְהִסְתַּלֵּק מִמֶּנּוּ הַנְּבִיעָה, כְּמוֹ שֶׁרָאִיתִי בַּשֶּׁמֶשׁ וּבַלְּבָנָה, שֶׁמִּסְתַּלֵּק הָאוֹר שֶׁלָּהֶם בַּלַּיְלָה, שֶׁאֵין הַשֶּׁמֶשׁ מֵאִיר, אֶלָּא בַּיּוֹם. וְהַלְּבָנָה בַּלַּיְלָה.</p>\n<p>וְאִם תּאמַר שֶׁאותו אור שֶׁל הַלְּבָנָה הוּא מִן הַשֶּׁמֶשׁ, שֶׁאַף עַל גַּב שֶׁהִתְכַּנֵּס, הוּא מֵאִיר בַּלְּבָנָה וּבַכּוֹכָבִים, הֲרֵי רָאִינוּ מִצַּד אַחֵר בְּלִקּוּי הַלְּבָנָה וְהַשֶּׁמֶשׁ שֶׁמִּסְתַּלֵּק אוֹרָם, וְנִשְׁאָרִים כְּמוֹ גוּף בְּלִי נְשָׁמָה, שֶׁיֵּשׁ עֲלֵיהֶם אָדוֹן שֶׁמַּחֲשִׁיךְ אֶת מְאוֹרֵיהֶם. אֲבָל עִקַּר הָאוֹר אוֹתוֹ מָקוֹם שֶׁנּוֹבֵעַ, שֶׁאֵין הֶפְסֵק לָאוֹר שֶׁלּוֹ, וְאֵין עָלָיו אֱלוֹהַּ אַחֵר לְהַפְסִיק מִמֶּנּוּ אֶת מְאוֹרוֹ.</p>\n<p>וְעִלַּת הָעִלּוֹת, מֵאַחַר שֶׁאַתָּה שָׁם, אֵין הֶפְסֵק לִנְבִיעַת אוֹר הַתּוֹרָה. יְהִי רְצוֹנְךְ שֶׁלֹּא תָזוּז מֵאַבָּא וְאִמָּא שֶׁלִּי וְלֹא מִבָּנָיו. וְכָךְ מִי שֶׁמֵּמִית עַצְמוֹ עַל הַתּוֹרָה, שֶׁהִיא יְקָרָה, מִתְקַיֶּמֶת בּוֹ וְאֵינָהּ מַפְסִיקָה מִמֶּנּוּ. מַה שֶּׁאֵין כֵּן מִי שֶׁאֵינוֹ מִשְׁתַּדֵּל בָּהּ, אֶלָּא אַף עַל גַּב שֶׁעוֹשֶׂה צִוּוּי חֲכָמִים, הוּא שַׁמָּשׁ שֶׁלָּהֶם, עֶבֶד וְלֹא בֵן. אֲבָל אִם הוּא נֶאֱמָן, אֲדוֹנוֹ מַשְׁלִיט אוֹתוֹ בְּכָל אֲשֶׁר לוֹ.</p>\n<p>אֲבָל מִי שֶׁלֹּא מִשְׁתַּדֵּל בַּתּוֹרָה וְלֹא מְשַׁמֵּשׁ חֲכָמִים לִשְׁמֹעַ מֵהֶם מִצְווֹת, לְקַיֵּם נַעֲשֶׂה וְנִשְׁמָע, אֶלָּא שֶׁסָּרַח וְעָבַר עַל לֹא תַעֲשֶׂה, הוּא שָׁקוּל לְאֻמּוֹת הָעוֹלָם עוֹבְדֵי עֲבוֹדָה זָרָה, בְּנֵי סָמָאֵ\"ל וְנָחָשׁ, שֶׁנֶּאֱמַר בָּהֶם (משלי ג) וּכְסִילִים מֵרִים קָלוֹן, שֶׁלֹּא רָצוּ לְקַבֵּל אֶת הַתּוֹרָה, שֶׁכֹּל שֶׁאֵין בּוֹ תּוֹרָה, אֵין בּוֹ כָּבוֹד, שֶׁנֶּאֱמַר בָּהֶם (שם) כָּבוֹד חֲכָמִים יִנְחָלוּ.</p>"],[9522012168,"<p>וְעִם כָּל זֶה, רָאשֵׁי הַיְשִׁיבָה, לֹא כָּל כָּבוֹד שָׁוֶה, שֶׁהֲרֵי בֵּן יְכַבֵּד אָב וְעֶבֶד אֲדוֹנָיו. בֵּן יְכַבֵּד, עַל מְנָת שֶׁלֹּא לְקַבֵּל שָׂכָר, אֲבָל הוּא מְצֻוֶּה בְּכִבּוּד אָב וָאֵם. וְאִם לֹא רוֹצֶה לַעֲשׂוֹת צִוּוּיוֹ, יַכּוּ אוֹתוֹ הָאָב וְהָאֵם עַד שֶׁיַּעֲשֶׂה בְּעַל כָּרְחוֹ. וְאִם הָיָה בֵּן גָּדוֹל, בֵּית דִּין כּוֹפִים אוֹתוֹ. שֶׁאִם אֵינוֹ רוֹצֶה לַעֲשׂוֹת, מַה כָּתוּב בּוֹ? (דברים כא) בְּנֵנוּ זֶה סוֹרֵר וּמֹרֶה אֵינֶנּוּ שֹׁמֵעַ בְּקֹלֵנוּ, וְדָנִים אוֹתוֹ בִּסְקִילָה. אֲבָל עֶבֶד שֶׁמְּשַׁמֵּשׁ עַל מְנָת לְקַבֵּל פְּרָס, אִם אֵינוֹ עוֹשֶׂה אֶת צִוּוּי רַבּוֹ, אֲדוֹנוֹ מַעֲבִיר אוֹתוֹ מִתּוֹךְ בֵּיתוֹ וְיִקַּח אַחֵר, מַה שֶּׁלֹּא הָיָה יָכוֹל לַעֲשׂוֹת כָּךְ לִבְנוֹ, אֶלָּא אוֹ שֶׁיַּעֲשֶׂה אֶת הַצִּוּוּי שֶׁלּוֹ, אוֹ שֶׁיַּהֲרֹג אוֹתוֹ.</p>\n<p>אָמַר לוֹ הַמְּנוֹרָה הַקְּדוֹשָׁה, מִי גָרַם שֶׁלֹּא יַעֲשֶׂה אֶת צִוּוּיוֹ, הוֹאִיל וּבְנוֹ הוּא? אָמַר הָרוֹעֶה הַנֶּאֱמָן, וַדַּאי תַּעֲרֹבֶת שֶׁל רַע, וְסוֹד זֶה גָּרַם לְיִשְׂרָאֵל לַחֲטֹא לַאֲבִיהֶם שֶׁבַּשָּׁמַיִם. וְסוֹד זֶה - (תהלים קו) וַיִּתְעָרְבוּ בַגּוֹיִם. וְזֶה גָרַם הֶרֶג לְיִשְׂרָאֵל, וְהֶחֱרִיב אֶת בֵּית הַמִּקְדָּשׁ. וּמִשּׁוּם זֶה אֵין מְקַבְּלִים גֵּרִים לִימוֹת הַמָּשִׁיחַ, אֶלָּא - (דברים לב) ה' בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר.</p>\n<p>שֶׁיִּשְׂרָאֵל הֵם מֵעֵץ הַחַיִּים, עֶבֶד טוֹב וְעֶבֶד רַע. מִצַּד שֶׁל מְטַטְרוֹ\"ן עֶבֶד טוֹב, עֶבֶד נֶאֱמָן לְרַבּוֹ. עֶבֶד רַע - סָמָאֵ\"ל. מִי שֶׁהוּא מֵעֵץ הַחַיִּים, הוּא בֶּן הָעוֹלָם הַבָּא, בֵּן מִצַּד שֶׁל בֶּן יָ\"הּ, בִּינָה. וְיוֹרֵשׁ אֶת הַמַּלְכוּת שֶׁהִיא ה'. וְאֵיךְ יוֹרֵשׁ אוֹתָהּ? אִם עוֹשֶׂה אֶת הַצִּוּוּי שֶׁל אַבָּא וְאִמָּא, מִשּׁוּם שֶׁהִיא מַלְכוּת מִצְוַת הַמֶּלֶךְ, וְעָלָיו נֶאֱמַר (אסתר ג) מַדּוּעַ אַתָּה עוֹבֵר אֵת מִצְוַת הַמֶּלֶךְ. הִיא מִצְוָה, וְצִוּוּיוֹ שֶׁל הַמֶּלֶךְ עַל עֲשֵׂה וְלֹא תַעֲשֶׂה.</p>\n<p>מִצְוָה מִן הַתּוֹרָה, שֶׁהִיא תִּפְאֶרֶת. וְכָאן אֵין שָׁם פֵּרוּד, הַקָּדוֹשׁ בָּרוּךְ הוּא אֱמֶת, תּוֹרָתוֹ תּוֹרַת אֱמֶת, הוּא תּוֹרָתוֹ וּמִצְוָתוֹ. כְּמוֹ שֶׁבִּינָה, תּוֹרָתוֹ וּמִצְוָתוֹ שֶׁל חָכְמָה. שֶׁיֵּשׁ תּוֹרָה שֶׁל בְּרִיאָה, וְחָכְמָה שֶׁל בְּרִיאָה, וּבִינָה שֶׁל בְּרִיאָה, וְכָךְ בְּכָל הַמִּדּוֹת. בָּזֶה יָכוֹל בֵּן בַּתּוֹרָה הַזּוֹ לִהְיוֹת בְּלִי מִצְוָה, וּמִצְוָה בְּלִי תוֹרָה בְּפֵרוּד. וּמִכָּאן בֵּן סוֹרֵר וּמוֹרֶה. אֲבָל מִצַּד שֶׁל אֲצִילוּת אֵין הֶבְדֵּל שָׁם, וְכֵן מִשָּׁם אֵין חֵטְא בָּא עַל יָדוֹ, וְאֵין בּוֹ עֹנֶשׁ וְלֹא שָׂכָר וְלֹא מִיתָה.</p>\n<p>וּמִשּׁוּם כָּךְ, הַתּוֹרָה זֶה עֵץ הַחַיִּים, שְׂכַר הָעוֹלָם הַבָּא, וְהָאִילָן הַזֶּה נִקְרָא עֵץ הַחַיִּים, וְנִקְרָא הָעוֹלָם הַבָּא, וְלֹא נִקְרָא בּוֹ שָׂכָר, מִשּׁוּם שֶׁהוּא בֵּן. מִשָּׁם לֹא מִשְׁתַּדֵּל בַּתּוֹרָה לְקַבֵּל שָׂכָר, לֹא בְמַעֲשֶׂה וְלֹא בְדִבּוּר וְלֹא בְמַחֲשָׁבָה.</p>"],[9522012169,"<p>בָּא הַמְּנוֹרָה הַקְּדוֹשָׁה לְנַשֵּׁק אֶת יָדוֹ. אָמַר, וַדַּאי אַתָּה הוּא בֵּן מִשָּׁם, בַּדְּיוֹקָן שֶׁל בְּנוֹ בְּכוֹרוֹ, תִּפְאֶרֶת בֵּן שֶׁל אַבָּא וְאִמָּא הָעֶלְיוֹנִים, הָאֲצִילוּת שֶׁלּוֹ בְּלִי הַפְסָקָה, לֹא קָדַם אוֹתְךְ בֵּן אַחֵר, לֹא בְמַחֲשָׁבָה, וְלֹא בְדִבּוּר, וְלֹא בְמַעֲשֶׂה. אָמַר הָרוֹעֶה הַנֶּאֱמָן, וְאַתָּה וְהַחֲבֵרִים, וְרָאשֵׁי מוֹרֵי הַיְשִׁיבוֹת, שֶׁמְּזֻמָּנִים לְכָאן עִמִּי בְּלִי הַפְסָקָה כְּלָל וּבְלִי תַעֲרֹבֶת. נָשְׁקוּ כֻלָּם זֶה לָזֶה, וְהִכִּירוּ בָאַחֲוָה וּבָכוּ.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, עִם כָּל זֶה, בֵּן בְּכוֹר חַיָּבִים כָּל אֶחָיו בִּכְבוֹדוֹ, שֶׁהֲרֵי כָּתוּב (שמות כ) כַּבֵּד אֶת אָבִיךְ, וּפֵרְשׁוּהָ רַבּוֹתֵינוּ, אֶת - לְרַבּוֹת אָחִיךְ הַגָּדוֹל. וַאֲפִלּוּ מִכָּל צַד הוּא מְפֹרָשׁ עָלֶיךְ בַּתּוֹרָה, בְּשַׁגַּ\"ם - זֶה הֶבֶל. וְלֹא הָיָה לְאָדָם הָרִאשׁוֹן בֵּן קַדְמוֹן מִמֶּנּוּ, וּפֵרְשׁוּהָ רַבּוֹתֵינוּ, בְּשַׁגַּ\"ם - זֶה מֹשֶׁה. שֶׁבֶּן הַמֶּלֶךְ בְּכָל מָקוֹם, אַתָּה הַבְּכוֹר מִצַּד שֶׁל עֵץ הַחַיִּים שֶׁל טוֹב וָרָע, אַתָּה הוּא טוֹב. זֶהוּ שֶׁכָּתוּב (בראשית א) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, (שמות ב) וַתֵּרֶא אֹתוֹ כִּי טוֹב הוּא.</p>\n<p>וּמִשָּׁם קָרָא אוֹתְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עֶבֶד נֶאֱמָן. אַחַר כָּךְ עָלִיתָ לִהְיוֹת מֶלֶךְ. זֶהוּ שֶׁכָּתוּב (דברים לג) וַיְהִי בִישֻׁרוּן מֶלֶךְ. אַחַר כָּךְ בֶּן בַּיִת לְמַעְלָה. מֶלֶךְ מִצַּד שֶׁל מַלְכוּת שֶׁל בְּרִיאָה, בֶּן בַּיִת מִצַּד שֶׁל בִּינָה שֶׁל בְּרִיאָה. כָּעֵת אַתָּה מֶלֶךְ מִצַּד שֶׁל עֵץ הַמַּלְכוּת שֶׁל אֲצִילוּת. בֶּן בַּיִת מִצַּד שֶׁל בֶּ\"ן יָ\"הּ. תִּפְאֶרֶת שֶׁל אֲצִילוּת, אַשְׁרֵי חֶלְקְךְ. וּמִי גָרַם לְךְ אֶת זֶה? מִשּׁוּם הִשְׁתַּדְּלוּתְךְ בַּתּוֹרָה וּבַמִּצְוָה, לְיַחֵד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, לְהַעֲלוֹת אֶת הַמֶּלֶךְ עַל מְקוֹמוֹ וְעַל מַחֲנוֹתָיו לְמַעְלָה וְעַל יִשְׂרָאֵל לְמַטָּה.</p>\n<p>וּמִשּׁוּם כָּךְ (ובגללך) כֻּלָּם יוֹרְשִׁים נְשָׁמוֹת שֶׁל אֲצִילוּת מִמֶּנּוּ, וְנִקְרָאִים בָּנִים שֶׁלּוֹ, מִשּׁוּם יְהֹוָ\"ה שֶׁל אֲצִילוּת שֶׁאֵין שָׁם פֵּרוּד וְקִצּוּץ. שֶׁבָּרִאשׁוֹנָה נֶאֱמַר בָּהֶם בָּנִים לַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, מִצַּד יְהֹוָ\"ה שֶׁל בְּרִיאָה, שֶׁנֶּאֱמַר בּוֹ בְּרָאתִיו יְצַרְתִּיו אַף עֲשִׂיתִיו, כְּגוֹן בָּנִים לַיהֹוָ\"ה שֶׁל אֲצִילוּת.</p>"],[9522012170,"<p>וּבְךָ הִתְקַיְּמָה הַמִּצְוָה, שֶׁהִיא מִצְוָה עַל יִשְׂרָאֵל לְהַעֲמִיד לָהֶם מֶלֶךְ. זֶהוּ שֶׁכָּתוּב, (שם י) שׂוֹם תָּשִׂים עָלֶיךְ מֶלֶךְ. וְהִתְקַיֵּם בְּךְ (שם לג) וַיְהִי בִישֻׁרוּן מֶלֶךְ, כְּבָרִאשׁוֹנָה. וְכֻלָּם מִתְנַהֲגִים אַחֲרֶיךְ, כְּמוֹ אֵיבָרִים שֶׁכֻּלָּם מִתְנַהֲגִים בִּתְנוּעַת הַנְּשָׁמָה שֶׁמִּתְפַּשֶּׁטֶת עַל כָּל אֵיבָר. מִשּׁוּם שֶׁכֶּתֶר עֶלְיוֹן אַתָּה תִּהְיֶה מְעֻטָּר בּוֹ, שֶׁבּוֹ עִלַּת הָעִלּוֹת הוּא כֶּתֶר עַל הַכֹּל, טָמִיר וְגָנוּז מִבִּפְנִים מִמֶּנּוּ. וּמִמֶּנּוּ מִתְפַּשֵּׁט עַל כָּל הַסְּפִירוֹת, וּמְסַדֵּר אוֹתָם לִהְיוֹת זֶה גָּדוֹל, וְזֶה קָטָן, וְזֶה בֵּינוֹנִי, וּמַנְהִיג אוֹתָם לִרְצוֹנוֹ וּמֵאִיר בָּהֶם, וּמְקַשֵּׁר אוֹתָם וּמְיַחֵד אוֹתָם.</p>\n<p>כָּכָה אַתָּה תִּהְיֶה מַנְהִיג לְיִשְׂרָאֵל בְּכָל הַמִּדּוֹת הַטּוֹבוֹת שֶׁלּוֹ, וּתְסַדֵּר כָּל אֶחָד כָּרָאוּי לוֹ - הַבְּכוֹר כִּבְכוֹרָתוֹ, וְהַצָּעִיר כִּצְעִירוּתוֹ, וְהַבֵּינוֹנִי כְּפִי דַרְגָּתוֹ. וּתְקַשֵּׁר אוֹתָם קֶשֶׁר אֶחָד לַאֲבִיהֶם שֶׁבַּשָּׁמַיִם, לִהְיוֹת כֻּלָּם בְּשָׂפָה בְרוּרָה, לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וּלְקַדְּשׁוֹ וּלְיַחֲדוֹ בַּדַּרְגָּה שֶׁלְּךְ, בַּמַּחֲשָׁבָה שֶׁלְּךְ, בָּאֲצִילוּת שֶׁלְּךְ, שֶׁהִתְקַיֵּם בְּךְ (במדבר יא) וְאָצַלְתִּי מִן הָרוּחַ אֲשֶׁר עָלֶיךְ וְשַׂמְתִּי עֲלֵיהֶם. קוּם הִתְעוֹרֵר בַּמִּצְוָה, לְהַכְרִית זַרְעוֹ שֶׁל עֲמָלֵק.</p>\n<p>אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ וְגוֹ'. מִצְוָה זוֹ לְכַבֵּד אָב וָאֵם, שֶׁצָּרִיךְ בֶּן אָדָם לִירָא מֵאָבִיו וּמֵאִמּוֹ וּלְכַבֵּד אוֹתָם. כְּמוֹ שֶׁצָּרִיךְ בֶּן אָדָם לְכַבֵּד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא מִצַּד הָרוּחַ שֶׁנָּתַן בְּתוֹכוֹ וְלִירָא מִמֶּנּוּ, כָּךְ צָרִיךְ לְכַבֵּד אֶת אָבִיו וְאֶת אִמּוֹ מִצַּד שֶׁל הַגּוּף שֶׁלּוֹ וְלִירָא מֵהֶם, שֶׁהֲרֵי הֵם מִשְׁתַּתְּפִים עִם הַקָּדוֹשׁ בָּרוּךְ הוּא וְעוֹשִׂים לוֹ גּוּף. וְהוֹאִיל וְהֵם שֻׁתָּפִים בַּמַּעֲשֶׂה, יִהְיוּ שֻׁתָּפִים בְּיִרְאָה וְכָבוֹד.</p>\n<p>כְּמוֹ כֵן, שְׁלֹשָׁה שֻׁתָּפִים נִמְצְאוּ לוֹ לְמַעְלָה בְּסוֹד שֶׁל אָדָם. אָדָם הָרִאשׁוֹן, אַף עַל גַּב שֶׁגּוּפוֹ הָיָה מֵעָפָר, לֹא מֵעָפָר שֶׁל כָּאן הָיָה, אֶלָּא מֵעָפָר שֶׁל בֵּית הַמִּקְדָּשׁ שֶׁל מַעְלָה. הָאָב וְהָאֵם נִמְצְאוּ, וְהַמֶּלֶךְ הָעֶלְיוֹן הִשְׁתַּתֵּף עִמָּם, וְשָׁלַח בּוֹ רוּחַ שֶׁל חַיִּים וְנִבְרָא. וּכְמוֹ זֶה נִמְצָא הַכֹּל לְמַעְלָה וּלְמַטָּה. וְעַל כֵּן צָרִיךְ אָדָם לִירָא מֵהַקָּדוֹשׁ בָּרוּךְ הוּא וְלִירָא מֵאָבִיו וְאִמּוֹ.</p>"],[9522012171,"<p>בְּסִתְרֵי תוֹרָה, אָדָם הָרִאשׁוֹן לֹא הָיָה לוֹ מֵהָעוֹלָם הַזֶּה כְּלוּם. צַדִּיק אֶחָד עָשָׂה שִׁמּוּשׁ עִם נְקֵבָתוֹ, וְנַעֲשָׂה מֵאוֹתוֹ הַשִּׁמּוּשׁ גּוּף אֶחָד, שֶׁאוֹרוֹ יוֹתֵר מִכָּל אוֹתָם הַמַּלְאָכִים הַשְּׁלוּחִים לְמַעְלָה. וּכְשֶׁנִּבְרָא אוֹתוֹ הַגּוּף, הַמֶּלֶךְ הָעֶלְיוֹן שָׁלַח בְּאוֹתוֹ הַצַּדִּיק עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת, וְהִשְׁתַּתֵּף עִמָּם וְיָצָא לָעוֹלָם.</p>\n<p>כֵּיוָן שֶׁיָּצָא, רָאוּ אוֹתוֹ הַשֶּׁמֶשׁ וְהַלְּבָנָה וְהִסְתִּירוּ אֶת אוֹרָם, שֶׁתַּפּוּחַ רַגְלוֹ הֶחְשִׁיךְ אֶת הָאוֹר שֶׁלָּהֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁמִּמַּעֲשֵׂה הַשֶּׁמֶשׁ וְהַלְּבָנָה יָצָא. כֵּיוָן שֶׁחָטָא, נֶחְשַׁךְ, וְהִקְטִין עַצְמוֹ, וְהִצְטָרֵךְ לְגוּף אַחֵר בְּעוֹר וּבְבָשָׂר, שֶׁכָּתוּב (בראשיתב) וַיַּעַשׂ ה' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּשֵׁם. כְּמוֹ אוֹתוֹ הַשִּׁמּוּשׁ שֶׁעָשָׂה אוֹתוֹ צַדִּיק עִם נְקֵבָתוֹ, לֹא נִמְצָא מִקֹּדֶם לָכֵן וּלְאַחַר מִכֵּן, שֶׁהֲרֵי טֶרֶם יָצָא לְצוֹרֵף אֻמָּן.</p>\n<p>עֵד שֶׁבָּא חֲנוֹךְ, וְנָטַל אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מִן הָאָרֶץ, וְנִבְרְרָה הַפְּסֹלֶת וְהַזֻּהֲמָה מִן הַכֶּסֶף, וְכֵן בְּכָל אוֹתָם הַצַּדִּיקִים שֶׁבָּאָרֶץ. אַחַר כָּךְ הִתְתַּקֵּן אוֹתוֹ הַמָּקוֹם, וְנַעֲשׂוּ רוּחוֹת וּנְשָׁמוֹת בְּשִׁמּוּשֵׁיהֶם וְהַגּוּף מִלְּמַטָּה בָּאָרֶץ. וְעַל כֵּן, בְּשֻׁתָּפוּת שֶׁלְּמַעְלָה וּלְמַטָּה בָּא הָאָדָם לָעוֹלָם, וְצָרִיךְ לִירָא מֵאוֹתָם הַשֻּׁתָּפִים וּלְכַבֵּד אוֹתָם, כְּמוֹ שֶׁנִּתְבָּאֵר. (עד כאן רעיא מהימנא).</p>\n<p>אַל תִּפְנוּ אֶל הָאֱלִילִים וֵאלֹהֵי מַסֵּכָה לֹא תַעֲשׂוּ לָכֶם. רַבִּי חִיָּיא פָּתַח, (דברים ט) אַל תֵּפֶן אֶל קְשִׁי הָעָם הַזֶּה וְגוֹ'. אַל תֵּפֶן, וְכִי מִי שֶׁיֹּאמַר לַמֶּלֶךְ אַל תֵּפֶן? וַהֲרֵי כָּתוּב (איוב לד) כִּי עֵינָיו עַל דַּרְכֵי אִישׁ. וְכָתוּב (ירמיה כד) אִם יִסָּתֵר אִישׁ בְּמִסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ נְאֻם ה', וַהֲרֵי בַּכֹּל מַשְׁגִּיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא וּמִסְתַּכֵּל עַל כָּל הַמַּעֲשִׂים, וּמַכְנִיס בְּדִין עַל כֻּלָּם, אִם טוֹב וְאִם רָע, כְּמוֹ שֶׁנֶּאֱמַר (קהלת יב) הָאֱלֹהִים יָבִא בְמִשְׁפָּט עַל כָּל נֶעְלָם אִם טוֹב וְאִם רָע, וּמֹשֶׁה אוֹמֵר אַל תֵּפֶן?!</p>\n<p>אֶלָּא כַּמָּה צָרִיךְ אָדָם לְהִשָּׁמֵר מֵחֶטְאוֹ כְּדֵי שֶׁלֹּא יֶחֱטָא לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. בּא רְאֵה, בֶּן אָדָם שֶׁעוֹשֶׂה מִצְוָה, אוֹתָהּ מִצְוָה עוֹלָה וְעוֹמֶדֶת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְאוֹמֶרֶת: אֲנִי מִפְּלוֹנִי שֶׁעָשָׂה אוֹתִי. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹנֶה אוֹתָהּ לְפָנָיו, לְהַשְׁגִּיחַ בָּהּ כָּל יוֹם, לְהֵיטִיב לוֹ בִּשְׁבִילָהּ. עָבַר עַל דִּבְרֵי תוֹרָה - אוֹתָהּ עֲבֵרָה עוֹלָה לְפָנָיו וְאוֹמֶרֶת: אֲנִי מִפְּלוֹנִי שֶׁעָשָׂה אוֹתִי. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹנֶה אוֹתָהּ, וְעוֹמֶדֶת שָׁם לְהַשְׁגִּיחַ בָּהּ, לְכַלּוֹת אוֹתוֹ. זֶהוּ שֶׁכָּתוּב (דברים לב) וַיַּרְא ה' וַיִּנְאָץ מִכַּעַס בָּנָיו וּבְנֹתָיו. מַה זֶּה וַיַּרְא? אוֹתוֹ שֶׁעוֹמֵד לְפָנָיו.</p>\n<p>שָׁב בִּתְשׁוּבָה - מַה כָּתוּב? (שמואל ב יב) גַּם ה' הֶעֱבִיר חַטָּאתְךְ לֹא תָמוּת. שֶׁהֶעֱבִיר אוֹתוֹ הַחֵטְא מִלְּפָנָיו כְּדֵי שֶׁלֹּא יִסְתַּכֵּל בּוֹ, לְהֵיטִיב לוֹ. וְעַל כֵּן, אַל תֵּפֶן אֶל קְשִׁי הָעָם הַזֶּה וְאֶל רִשְׁעוֹ וְאֶל חַטָּאתוֹ. אָמַר רַבִּי יוֹסֵי, וְכֵן מִכָּאן מַשְׁמָע, שֶׁכָּתוּב (ירמיה ב) נִכְתָּם עֲוֹנֵךְ לְפָנַי.</p>"],[9522012172,"<p>רַבִּי יוֹסֵי הַקָּטָן נִכְנַס לִפְנֵי רַבִּי שִׁמְעוֹן יוֹם אֶחָד, מָצָא אוֹתוֹ שֶׁהָיָה יוֹשֵׁב וְקוֹרֵא, כָּתוּב (בראשית ב) וַיֹּאמֶר הָאָדָם הָאִשָּׁה אֲשֶׁר נָתַתָּה עִמָּדִי הִיא נָתְנָה לִּי מִן הָעֵץ וָאֹכֵל. מַשְׁמָע שֶׁאָדָם וְחַוָּה נִבְרְאוּ כְאֶחָד וּבְגוּף אֶחָד, שֶׁכָּתוּב אֲשֶׁר נָתַתָּה עִמָּדִי, וְלֹא כָתוּב אֲשֶׁר נָתַתָּ לִי. אָמַר לוֹ, אִם כָּךְ, וַהֲרֵי כָּתוּב (שמואל א א) אֲנִי הָאִשָּׁה הַנִּצֶּבֶת עִמְּכָה בָּזֶה, וְלֹא כָתוּב הַנִּצֶּבֶת לְפָנֶיךְ. אָמַר לוֹ, אִם כָּתוּב הַנִּתֶּנֶת עִמְּךְ - הָיִיתִי אוֹמֵר כָּךְ, כְּמוֹ שֶׁכָּתוּב אֲשֶׁר נָתַתָּה עִמָּדִי, אֲבָל הַנִּצֶּבֶת כָּתוּב.</p>\n<p>אָמַר לוֹ, וַהֲרֵי כָּתוּב (בראשית ב) וַיֹּאמֶר ה' אֱלֹהִים לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ אֶעֱשֶׂה לּוֹ עֵזֶר כְּנֶגְדּוֹ. אֶעֱשֶׂה לּוֹ עַכְשָׁו. אָמַר לוֹ, כָּךְ הוּא וַדַּאי, שֶׁאָדָם הָיָה לְבַדּוֹ, שֶׁלֹּא הָיָה לוֹ סֶמֶךְ מִנְּקֵבָתוֹ, מִשּׁוּם שֶׁהָיְתָה בְּצִדּוֹ כְּפִי שֶׁבֵּאַרְנוּ. וּמַה שֶּׁאָמַר אֶעֱשֶׂה לּוֹ עֵזֶר - כָּךְ הוּא, שֶׁלֹּא כָתוּב אֶבְרָא לוֹ עֵזֶר, מִשּׁוּם שֶׁכָּתוּב (שם ה) זָכָר וּנְקֵבָה בְּרָאָם. אֲבָל כָּתוּב אֶעֱשֶׂה. וּמַה הוּא אֶעֱשֶׂה? אֲתַקֵּן. מַשְׁמָע שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָטַל אוֹתָהּ מִצִּדּוֹ, וְתִקֵּן אוֹתָהּ בְּתִקּוּן, וְהֵבִיא אוֹתָהּ לְפָנָיו. וְאָז הִשְׁתַּמֵּשׁ אָדָם בְּאִשְׁתּוֹ, וְהָיָה לוֹ סֶמֶךְ.</p>\n<p>וְשָׁנִינוּ, יָפְיוֹ שֶׁל אָדָם כִּסֵּא שֶׁל הַקֶּשֶׁר הָעֶלְיוֹן, מֵהַזֹּהַר הַמֵּאִיר. יָפְיָהּ שֶׁל חַוָּה, שֶׁלֹּא הָיוּ יְכוֹלִים כָּל הַבְּרִיּוֹת לְהִסְתַּכֵּל בָּהּ. וַאֲפִלּוּ אָדָם הָרִאשׁוֹן לֹא הָיָה מִסְתַּכֵּל בָּהּ, עַד אוֹתוֹ הַזְּמַן שֶׁחָטְאוּ, וְהוּסַר (והקטן) הַיֹּפִי שֶׁלָּהֶם. אָז הִסְתַּכֵּל בָּהּ אָדָם וְהִכִּיר בָּהּ לְשַׁמֵּשׁ עִמָּהּ. זֶהוּ שֶׁכָּתוּב (שם ד) וַיֵּדַע אָדָם עוֹד אֶת אִשְׁתּוֹ. וַיֵּדַע - בַּכֹּל. וַיֵּדַע - בְּתַשְׁמִישׁ. וַיֵּדַע - שֶׁהִכִּיר בָּהּ וְהִסְתַּכֵּל בָּהּ.</p>"],[9522012173,"<p>וְשָׁנִינוּ, אָסוּר לוֹ לָאָדָם לְהִסְתַּכֵּל בְּיָפְיָהּ שֶׁל אִשָּׁה, כְּדֵי שֶׁלֹּא יָבֹא לְהִרְהוּר רַע, וְיֵעָקֵר לְדָבָר אַחֵר. וְכָךְ הָיָה רַבִּי שִׁמְעוֹן עוֹשֶׂה - כְּשֶׁהָיָה הוֹלֵךְ בָּעִיר וְהָיוּ הַחֲבֵרִים הוֹלְכִים אַחֲרָיו וְרָאָה נָשִׁים יָפוֹת, הִשְׁפִּיל אֶת עֵינָיו, וְהָיָה אוֹמֵר לַחֲבֵרִים: אַל תִּפְנוּ.</p>\n<p>וְכָל מִי שֶׁמִּסְתַּכֵּל בְּיֹפִי שֶׁל אִשָּׁה בַּיּוֹם, בָּא לְהִרְהוּר בַּלַּיְלָה. וְאִם עוֹלֶה אוֹתוֹ הִרְהוּר רַע עָלָיו, עוֹבֵר מִשּׁוּם וֵאלֹהֵי מַסֵּכָה לֹא תַעֲשׂוּ לָכֶם. וְעוֹד, אִם שִׁמֵּשׁ עִם אִשְׁתּוֹ בִּזְמַן שֶׁעוֹלֶה בּוֹ אוֹתוֹ הַהִרְהוּר הָרָע, אוֹתָם בָּנִים שֶׁמּוֹלִידִים נִקְרָאִים אֱלֹהֵי מַסֵּכָה. וְעַל זֶה כָּתוּב אַל תִּפְנוּ אֶל הָאֱלִילִים וֵאלֹהֵי מַסֵּכָה לֹא תַעֲשׂוּ לָכֶם. רַבִּי אַבָּא אָמַר, אָסוּר לוֹ לָאָדָם לְהִסְתַּכֵּל בֶּאֱלִילֵי עֲבוֹדָה זָרָה, וּבִנְשׁוֹת הָעַמִּים, וְלֹא לֵהָנוֹת מֵהֶן, וְלֹא לְהִתְרַפֵּא בָהֶן. שֶׁאָסוּר לוֹ לָאָדָם לְהִסְתַּכֵּל בְּמָקוֹם שֶׁלֹּא צָרִיךְ.</p>"],[9522012174,"<p>רַבִּי אַבָּא פָּתַח, (תהלים פו) פְּנֵה אֵלַי וְחָנֵּנִי תְּנָה עֻזְּךְ לְעַבְדֶּךְ. פְּנֵה אֵלַי וְחָנֵּנִי, וְכִי לֹא הָיָה לוֹ לַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם יָפֶה כְּדָוִד, שֶׁהוּא אוֹמֵר פְּנֵה אֵלַי וְחָנֵּנִי? אֶלָּא כָּךְ שָׁנִינוּ, דָּוִד אַחֵר יֵשׁ לַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא מְמֻנֶּה עַל כַּמָּה אוּכְלוּסִים עֶלְיוֹנִים וּמַחֲנוֹת. וּכְשֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְרַחֵם עַל הָעוֹלָם, מִסְתַּכֵּל בַּדָּוִד הַזֶּה, וּמֵאִיר לוֹ פָּנִים, וְהוּא מֵאִיר לָעוֹלָמוֹת וְחָס עַל הָעוֹלָם.</p>\n<p>וְיָפְיוֹ שֶׁל הַדָּוִד הַזֶּה מֵאִיר לְכָל הָעוֹלָמוֹת, רֹאשׁוֹ גֻּלְגֹּלֶת זָהָב שֶׁנִּרְקְמָה בְּשִׁבְעָה תַכְשִׁיטֵי מִינִים שֶׁל זָהָב, וַהֲרֵי פֵּרְשׁוּהָ. וַחֲבִיבוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כְּנֶגְדּוֹ, וּמֵרֹב אַהֲבָתוֹ אֵלָיו אָמַר לַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיַּחֲזִיר עֵינָיו כְּנֶגְדּוֹ וְיִסְתַּכֵּל בּוֹ, מִשּׁוּם שֶׁהֵם יָפִים בַּכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (שיר ו) הָסֵבִּי עֵינַיִךְ מִנֶּגְדִּי וְגוֹ'. הָסֵבִּי עֵינַיִךְ מִנֶּגְדִּי, שֶׁבְּשָׁעָה שֶׁהָעֵינַיִם הַלָּלוּ מִסְתַּכְּלוֹת בּוֹ בַּקָּדוֹשׁ בָּרוּךְ הוּא, אָז מִתְעוֹרְרִים בְּלִבּוֹ חִצֵּי בַּלִּיסְטְרָאוֹת בְּאַהֲבָה עֶלְיוֹנָה, וּמִגֹּדֶל הַשַּׁלְהֶבֶת שֶׁל הָאַהֲבָה הָעֶלְיוֹנָה אֵלָיו, אָמַר הָסֵבִּי עֵינַיִךְ מִנֶּגְדִּי, סוֹבְבִי עֵינַיִךְ לְצַד אַחֵר מִמֶּנִּי, שֶׁהֵם שׂוֹרְפִים אוֹתִי בְּשַׁלְהֲבוֹת אַהֲבָה. וְעַל כֵּן כָּתוּב בְּדָוִד, (שמואל א טז) וְהוּא אַדְמֹנִי עִם יְפֵה עֵינָיִם וְטוֹב רֹאִי. וּבִשְׁבִיל אוֹתוֹ דָּוִד עֶלְיוֹן הַנָּאֶה, אַהֲבָתוֹ וּתְשׁוּקָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִדָּבֵק עִמּוֹ, אָמַר דָּוִד פְּנֵה אֵלַי וְחָנֵּנִי.</p>\n<p>כְּמוֹ זֶה, (בראשית כז) וַיֹּאמֶר רְאֵה רֵיחַ בְּנִי כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה'. מַשְׁמָע שֶׁנִּכְנַס עִם יַעֲקֹב גַּן עֵדֶן, שֶׁהוּא שְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים. וְכִי אֵיךְ יָכוֹל גַּן עֵדֶן לְהִכָּנֵס עִמּוֹ, שֶׁהֲרֵי גַּן עֵדֶן כַּמָּה הוּא גָּדוֹל בָּרֹחַב וּבָאֹרֶךְ, כַּמָּה מִינִים שֶׁל בָּתִּים עֶלְיוֹנִים קְדוֹשִׁים, דְּרָגוֹת עַל דְּרָגוֹת, מְדוֹרִים עַל מְדוֹרִים יֵשׁ שָׁם?</p>\n<p>אֶלָּא גַּן אַחֵר עֶלְיוֹן קָדוֹשׁ יֵשׁ לַקָּדוֹשׁ בָּרוּךְ הוּא, וְאוֹתוֹ הַגָּן הוּא אַהֲבָתוֹ, וְנִדְבָּק בּוֹ, וְאֵינוֹ שָׁמוּר אֶלָּא לַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, שֶׁהוּא נִכְנָס בּוֹ. וְזֶה הוֹרִישׁ הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִמָּצֵא תָמִיד עִם הַצַּדִּיקִים, וְכָל שֶׁכֵּן לְהִמָּצֵא בּוֹ עִם יַעֲקֹב, וְזֶה מַה שֶּׁזִּמֵּן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִכָּנֵס עִמּוֹ לְסַיֵּעַ לוֹ.</p>\n<p>כְּמוֹ כֵן, (שם כח) אֲנִי ה' אֱלֹהֵי אַבְרָהָם אָבִיךְ וֵאלֹהֵי יִצְחָק הָאָרֶץ וְגוֹ'. שָׁנִינוּ, מְלַמֵּד שֶׁנִּתְקַפְּלָה לוֹ אֶרֶץ יִשְׂרָאֵל. וְכִי אֶרֶץ יִשְׂרָאֵל, שֶׁהִיא אַרְבַּע מֵאוֹת פַּרְסָה עַל אַרְבַּע מֵאוֹת פַּרְסָה, אֵיךְ נֶעֶקְרָה מִמְּקוֹמָה וְיָשְׁבָה תַחְתָּיו? אֶלָּא אֶרֶץ אַחֶרֶת עֶלְיוֹנָה קְדוֹשָׁה יֵשׁ לַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִקְרֵאת אֶרֶץ יִשְׂרָאֵל. וְהִיא תַּחַת דַּרְגַּת יַעֲקֹב שֶׁעוֹמֵד עָלֶיהָ, וְהוֹרִישׁ אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל בִּשְׁבִיל אַהֲבָתָם, לָדוּר עִמָּם וּלְהַנְהִיג אוֹתָם וּלְהָגֵן עֲלֵיהֶם מֵהַכֹּל, וְנִקְרֵאת אֶרֶץ חַיִּים.</p>"],[9522012175,"<p>בֹּא רְאֵה, אָסוּר לוֹ לָאָדָם לְהִסְתַּכֵּל בְּמָקוֹם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹאֵס בּוֹ וְנַפְשׁוֹ רְחוֹקָה מִמֶּנּוּ. וּמַה בְּמַה שֶּׁאוֹהֵב הַקָּדוֹשׁ בָּרוּךְ הוּא אָסוּר לְהִסְתַּכֵּל בּוֹ - בְּמַה שֶּׁרָחוֹק עַל אַחַת כַּמָּה וְכַמָּה. שֶׁבֹּא רְאֵה, אָסוּר לוֹ לָאָדָם לְהִסְתַּכֵּל בַּקֶּשֶׁת, מִשּׁוּם שֶׁהִיא מַרְאֶה שֶׁל דְּיוֹקָן עֶלְיוֹן. אָסוּר לוֹ לָאָדָם לְהִסְתַּכֵּל בְּאוֹת הַבְּרִית שֶׁלּוֹ, מִשּׁוּם שֶׁהוּא רוֹמֵז לְצַדִּיק שֶׁל עוֹלָם. אָסוּר לוֹ לָאָדָם לְהִסְתַּכֵּל בְּאֶצְבְּעוֹת הַכֹּהֲנִים בְּשָׁעָה שֶׁפּוֹרְשִׂים יְדֵיהֶם, מִשּׁוּם שֶׁשָּׁם שָׁרוּי כְּבוֹד הַמֶּלֶךְ הָעֶלְיוֹן. וּמַה בְּמָקוֹם קָדוֹשׁ עֶלְיוֹן אָסוּר לְהִסְתַּכֵּל - בְּמָקוֹם טָמֵא רָחוֹק לֹא כָּל שֶׁכֵּן. מִשּׁוּם כָּךְ, אַל תִּפְנוּ אֶל הָאֱלִילִים. רַבִּי יִצְחָק אָמַר, וּמַה לְּהִסְתַּכֵּל בָּהֶם אָסוּר - לַעֲבֹד אוֹתָם אוֹ לַעֲשׂוֹת אוֹתָם עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>וּמִשּׁוּם כָּךְ, אַל תִּפְנוּ אֶל הָאֱלִילִים. כָּאן בָּא לְהַזְהִיר אֶת יִשְׂרָאֵל כְּבָרִאשׁוֹנָה, כְּנֶגֶד (שמות כ) לֹא יִהְיֶה לְךְ אֱלֹהִים אֲחֵרִים עַל פָּנָי. וֵאלֹהֵי מַסֵּכָה לֹא תַעֲשׂוּ לָכֶם, כְּנֶגֶד לֹא תַעֲשֶׂה לְךְ פֶסֶל אֲנִי ה' אֱלֹהֵיכֶם. כְּנֶגֶד אָנֹכִי ה' אֱלֹהֶיךְ - אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ. כְּנֶגֶד כַּבֵּד אֶת אָבִיךְ וְאֶת אִמֶּךְ - וְאֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ, זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ. לֹא תִשָּׁבְעוּ בִשְׁמִי לַשָּׁקֶר - לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךְ לַשָּׁוְא. לֹא תִגְנֹבוּ - לֹא תִגְנֹב. וְלֹא תְכַחֲשׁוּ - וְלֹא תְשַׁקְּרוּ אִישׁ בַּעֲמִיתוֹ, לֹא תַעֲנֶה בְרֵעֲךְ עֵד שָׁקֶר. מוֹת יוּמַת הַנֹּאֵף וְהַנֹּאָפֶת - לֹא תִנְאָף. לֹא תַעֲמֹד עַל דַּם רֵעֶךְ - לֹא תִרְצַח. וַהֲרֵי פֵּרְשׁוּהָ, וְעַל כֵּן כְּלַל הַתּוֹרָה בַּפָּרָשָׁה הַזּוֹ.</p>"],[9522012176,"<p>אָמַר רַבִּי חִיָּיא, בָּרִאשׁוֹנָה - אָנֹכִי ה' אֱלֹהֶיךְ. זָכוֹר אֶת יוֹם הַשַּׁבָּת. לֹא תִשָּׂא. לֹא תִרְצַח. לֹא תִנְאָף. לֹא תִגְנֹב. בִּלְשׁוֹן יָחִיד. וְכָאן - אֲנִי ה' אֱלֹהֵיכֶם. אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ, וְאֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ. אַל תִּפְנוּ אֶל הָאֱלִילִים. בִּלְשׁוֹן רַבִּים. אֶלָּא בֹּא רְאֵה, מִיּוֹם שֶׁהָיוּ יִשְׂרָאֵל מְצוּיִים בָּעוֹלָם, לֹא נִמְצְאוּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּלֵב אֶחָד וּבְרָצוֹן אֶחָד כְּמוֹ בְאוֹתוֹ יוֹם שֶׁעָמְדוּ בְּהַר סִינַי, וְעַל כֵּן הַכֹּל נֶאֱמַר בִּלְשׁוֹן יָחִיד. אַחַר בִּלְשׁוֹן רַבִּים, שֶׁהֲרֵי לֹא נִמְצְאוּ כָּל כָּךְ בְּאוֹתוֹ הָרָצוֹן.</p>\n<p>רַבִּי אֶלְעָזָר הָיָה הוֹלֵךְ לִרְאוֹת אֶת רַבִּי יוֹסֵי בֶּן רַבִּי שִׁמְעוֹן בֶּן לָקוּנְיָא חָמִיו, וְהָיוּ עִמּוֹ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי. כְּשֶׁהִגִּיעוּ לְשָׂדֶה אַחַת, יָשְׁבוּ תַחַת אִילָן אֶחָד. אָמַר רַבִּי אֶלְעָזָר, כָּל אֶחָד יֹאמַר דְּבַר תּוֹרָה. פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (הושע יג) וְאָנֹכִי ה' אֱלֹהֶיךְ מֵאֶרֶץ מִצְרָיִם וֵאלֹהִים זוּלָתִי לֹא תֵדָע. לֹא כָתוּב אֲשֶׁר הוֹצֵאתִיךְ מֵאֶרֶץ מִצְרַיִם, אֶלָּא אָנֹכִי ה' אֱלֹהֶיךְ מֵאֶרֶץ מִצְרָיִם. וְכִי מֵאֶרֶץ מִצְרַיִם הָיָה לָהֶם לְמֶלֶךְ, וְלֹא מִקֹּדֶם לָכֵן? וַהֲרֵי כָּתוּב (בראשית לה) וַיֹּאמֶר יַעֲקֹב אֶל בָּנָיו הָסִרוּ אֶת אֱלֹהֵי הַנֵּכָר אֲשֶׁר בְּתֹכֲכֶם, וְכָתוּב וְנָקוּמָה וְנַעֲלֶה בֵּית אֵל, וְאַתָּה אָמַרְתָּ מֵאֶרֶץ מִצְרַיִם?!</p>\n<p>אֶלָּא, מִיּוֹם שֶׁהָיוּ יִשְׂרָאֵל בָּעוֹלָם, לֹא הִכִּירוּ אֶת כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא, רַק בְּאֶרֶץ מִצְרַיִם, שֶׁהָיוּ בְּאוֹתָהּ עֲבוֹדָה קָשָׁה וְצָוְחוּ כְנֶגְדּוֹ, וְלֹא שִׁנּוּ מִנִּימוּסֵיהֶם לְעוֹלָמִים. וְשָׁם נִבְחֲנוּ הָאָבוֹת, כְּזָהָב מִתּוֹךְ הַפְּסֹלֶת (כהתוך הזהב מתוך השלהבת). וְעוֹד, שֶׁהָיוּ רוֹאִים בְּכָל יוֹם כַּמָּה כְשָׁפִים, כַּמָּה מִינִים רָעִים, לְהַטְעוֹת אֶת בְּנֵי הָאָדָם, וְלֹא סָטוּ מִן הַדֶּרֶךְ לְיָמִין וְלִשְׂמֹאל. וְאַף עַל גַּב שֶׁלֹּא הָיוּ מַכִּירִים כָּל כָּךְ בִּכְבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, אֶלָּא הָיוּ הוֹלְכִים אַחַר מִנְהֲגֵי אֲבוֹתֵיהֶם.</p>\n<p>וְאַחַר כָּךְ רָאוּ כַּמָּה נִסִּים וְכַמָּה גְבוּרוֹת, וְלָקַח אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲבוֹדָתוֹ. וּמִשּׁוּם שֶׁכֻּלָּם רָאוּ כַּמָּה נִסִּים וְאוֹתוֹת בְּעֵינֵיהֶם, וְכָל אוֹתָם נִסִּים וּגְבוּרוֹת, אָמַר וְאָנֹכִי ה' אֱלֹהֶיךְ מֵאֶרֶץ מִצְרָיִם. שֶׁשָּׁם הָיָה כְבוֹדוֹ בְּהִתְגַּלּוּת. וְהִתְגַּלָּה עֲלֵיהֶם עַל הַיָּם, וְרָאוּ אֶת זִיו הַכָּבוֹד הָעֶלְיוֹן פָּנִים בְּפָנִים. שֶׁלֹּא תֹאמְרוּ שֶׁאֱלוֹהַּ אַחֵר הוּא שֶׁדִּבֵּר עִמָּנוּ, אֶלָּא אֲנִי הוּא שֶׁרְאִיתֶם בְּאֶרֶץ מִצְרַיִם, אֲנִי הוּא שֶׁהָרַגְתִּי אֶת שׂוֹנְאֵיכֶם בְּאֶרֶץ מִצְרַיִם, אֲנִי הוּא שֶׁעָשִׂיתִי כָּל אוֹתָן עֶשֶׂר מַכּוֹת בְּאֶרֶץ מִצְרַיִם. וּמִשּׁוּם כָּךְ, וֵאלֹהִים זוּלָתִי לֹא תֵדָע, שֶׁלֹּא תֹאמַר שֶׁאַחֵר הָיָה, אֶלָּא אֲנִי הוּא הַכֹּל.</p>"],[9522012177,"<p>עוֹד פָּתַח, לֹא תַעֲשֹׁק אֶת רֵעֲךְ וְלֹא תִגְזֹל וְלֹא תָלִין פְּעֻלַּת שָׂכִיר עַד בֹּקֶר. לָמָּה לֹא תָלִין פְּעֻלַּת שָׂכִיר? אֶלָּא מִכָּתוּב אַחֵר נִשְׁמָע, שֶׁכָּתוּב (דברים כד) בְּיוֹמוֹ תִתֵּן שְׂכָרוֹ וְלֹא תָבוֹא עָלָיו הַשֶּׁמֶשׁ כִּי עָנִי הוּא וְאֵלָיו הוּא נֹשֵׂא אֶת נַפְשׁוֹ. לֹא תָבוֹא עָלָיו הַשֶּׁמֶשׁ, הִזָּהֵר שֶׁלֹּא תִתְכַּנֵּס בִּגְלָלוֹ מִן הָעוֹלָם טֶרֶם יַגִּיעַ זְמַנְּךְ לְהִתְכַּנֵּס, כְּמוֹ שֶׁנֶּאֱמַר (קהלת יב) עַד אֲשֶׁר לֹא תֶחְשַׁךְ הַשֶּׁמֶשׁ וְגוֹ'. מִכָּאן לָמַדְנוּ דָּבָר אַחֵר - מִי שֶׁמַּשְׁלִים לְנֶפֶשׁ הֶעָנִי, אֲפִלּוּ שֶׁהִגִּיעוּ יָמָיו לְהִסְתַּלֵּק מִן הָעוֹלָם, הַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁלִים לְנַפְשׁוֹ וְנוֹתֵן לוֹ יוֹתֵר חַיִּים.</p>\n<p>לֹא תָלִין פְּעֻלַּת שָׂכִיר. בּא רְאֵה, מִי שֶׁנּוֹטֵל אֶת שְׂכַר הֶעָנִי, כְּאִלּוּ נָטַל אֶת נַפְשׁוֹ וְאֶת שֶׁל אַנְשֵׁי בֵיתוֹ. הוּא הִקְטִין אֶת נַפְשָׁם - הַקָּדוֹשׁ בָּרוּךְ הוּא מַקְטִין אֶת יָמָיו וּמַקְטִין אֶת נַפְשׁוֹ מֵאוֹתוֹ הָעוֹלָם. שֶׁהֲרֵי כָּל אוֹתָם הַהֲבָלִים שֶׁיּוֹצְאִים מִפִּיו כָּל אוֹתוֹ הַיּוֹם, כֻּלָּם עוֹלִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְעוֹמְדִים לְפָנָיו, אַחַר כָּךְ עוֹלָה נַפְשׁוֹ וְנַפְשׁוֹת בְּנֵי בֵיתוֹ, וְעוֹמְדִים עִם אוֹתָם הַהֲבָלִים שֶׁל פִּיו. וְאָז, אֲפִלּוּ נִגְזַר עַל אוֹתוֹ הָאִישׁ כַּמָּה יָמִים וְכַמָּה טוֹבוֹת, כֻּלָּם נֶעֱקָרִים מִמֶּנּוּ וּמִסְתַּלְּקִים מִמֶּנּוּ.</p>\n<p>וְלֹא עוֹד, אֶלָּא שֶׁנַּפְשׁוֹ אֵינָהּ עוֹלָה לְמַעְלָה, וְהַיְנוּ מַה שֶּׁאָמַר רַבִּי אַבָּא: הָרַחֲמָן יַצִּילֵנוּ מֵהֶם וּמֵעֶלְבּוֹנָם. וּפֵרְשׁוּהָ, אֲפִלּוּ שֶׁהוּא עָשִׁיר, וְאֵלָיו הוּא נֹשֵׂא אֶת נַפְשׁוֹ דַּוְקָא, אֲפִלּוּ מִכָּל אָדָם גַּם כֵּן, וְכָל שֶׁכֵּן עָנִי. וְהַיְנוּ מַה שֶּׁהָיָה עוֹשֶׂה רַב הַמְנוּנָא, כְּשֶׁהָיָה אוֹתוֹ שָׂכִיר מִסְתַּלֵּק מֵעֲבוֹדָתוֹ, הָיָה נוֹתֵן לוֹ שְׂכָרוֹ וְאוֹמֵר לוֹ: טֹל אֶת נַפְשְׁךְ שֶׁהִפְקַדְתָּ בְּיָדִי, טֹל אֶת פִּקְדוֹנְךְ.</p>\n<p>וַאֲפִלּוּ אָמַר יְהִי בְיָדְךְ, שֶׁאֲנִי (לא) רוֹצֶה לְוַתֵּר עַל שְׂכָרִי - לֹא הָיָה רוֹצֶה. אָמַר: פִּקָּדוֹן שֶׁל גּוּפְךְ לֹא רָאוּי לִהְיוֹת מֻפְקָד בְּיָדִי, כָּל שֶׁכֵּן פִּקְדוֹן הַנֶּפֶשׁ, שֶׁהֲרֵי פִּקְדוֹן הַנֶּפֶשׁ לֹא נִתָּן אֶלָּא לַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (תהלים לא) בְּיָדְךְ אַפְקִיד רוּחִי. אָמַר רַבִּי חִיָּיא, וּבְיַד אַחֵר מֻתָּר. אָמַר לוֹ, אֲפִלּוּ בְּיָדוֹ, אַחַר שֶׁנָּתַן.</p>\n<p>כָּתוּב לֹא תָלִין פְּעֻלַּת שָׂכִיר, וְכָתוּב וְלֹא תָבוֹא עָלָיו הַשֶּׁמֶשׁ. אֶלָּא הֲרֵי פֵּרְשׁוּהָ, אֲבָל בּא רְאֵה, אֵין לְךְ יוֹם וָיוֹם שֶׁלֹּא שׁוֹלֵט בּוֹ יוֹם אַחֵר עֶלְיוֹן. וְאִם הוּא אֵינוֹ נוֹתֵן לוֹ אֶת נַפְשׁוֹ בְּאוֹתוֹ יוֹם, כְּמִי שֶׁפּוֹגֵם אֶת אוֹתוֹ יוֹם עֶלְיוֹן. וּמִשּׁוּם כָּךְ בְּיוֹמוֹ תִּתֵּן שְׂכָרוֹ וְלֹא תָבוֹא עָלָיו הַשֶּׁמֶשׁ. וְזֶה שֶׁנֶּאֱמַר לֹא תָלִין, מִשּׁוּם שֶׁנַּפְשׁוֹ לֹא עוֹלָה, וְעוֹלָה אוֹתָהּ נֶפֶשׁ הֶעָנִי וְשֶׁל אַנְשֵׁי בֵיתוֹ, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>"]]});
